// Nuvemath — 8-sinf, II qism (Geometriya 8) nazariyasi, t1–t10. Format: js/theory/GUIDE.md
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-2';

  // ---------- t1. Ko‘pburchaklar. Ichki va tashqi burchaklar yig‘indisi ----------
  T.add(P, 't1', { sections: [
    { kind: 'intro', h: L('Uchburchakdan ko‘pburchakka', 'От треугольника к многоугольнику', 'From triangles to polygons'), p: [
      L('7-sinfda biz uchburchak bilan yaqindan tanishdik va uning burchaklari yig‘indisi doim 180° ekanini isbotladik. Endi savol tug‘iladi: to‘rtburchak, beshburchak yoki o‘nburchakning burchaklari yig‘indisi qancha? Har safar burchaklarni transportir bilan o‘lchab chiqish shartmi yoki hammasi uchun bitta umumiy qoida bormi?', 'В 7 классе мы подробно изучили треугольник и доказали, что сумма его углов всегда 180°. Теперь возникает вопрос: чему равна сумма углов четырёхугольника, пятиугольника или десятиугольника? Нужно ли каждый раз мерить углы транспортиром, или есть одно общее правило?', 'In grade 7 we studied the triangle closely and proved that its angles always add up to 180°. Now a new question appears: what is the angle sum of a quadrilateral, a pentagon or a decagon? Do we have to measure every angle with a protractor, or is there one general rule for all of them?'),
      L('Javob juda chiroyli: har qanday qavariq ko‘pburchakni bitta uchidan chiqqan diagonallar yordamida uchburchaklarga bo‘lish mumkin. Uchburchak haqida bilganimiz esa butun ko‘pburchak haqida xulosa chiqarishga imkon beradi. Matematikada ko‘pincha shunday bo‘ladi: murakkab shaklni oddiy bo‘laklarga ajratamiz va eski bilim yangi masalani yechadi.', 'Ответ очень красивый: любой выпуклый многоугольник можно разрезать на треугольники диагоналями, выходящими из одной вершины. А то, что мы знаем о треугольнике, позволяет сделать вывод обо всём многоугольнике. В математике так бывает часто: сложную фигуру делим на простые части, и старое знание решает новую задачу.', 'The answer is beautiful: any convex polygon can be cut into triangles by the diagonals that leave one vertex. What we already know about triangles then tells us about the whole polygon. This happens a lot in mathematics: we split a complicated figure into simple pieces, and old knowledge solves a new problem.'),
      L('Bu mavzuda biz ko‘pburchak, uning uchlari, tomonlari, diagonallari va burchaklarini aniq ta’riflaymiz, ichki burchaklar yig‘indisi (n − 2) · 180° ekanini, tashqi burchaklar yig‘indisi esa har doim 360° ekanini isbotlaymiz, hamda diagonallar sonini topishni o‘rganamiz. Asalari uyalari, futbol to‘pi va Samarqand peshtoqlaridagi naqshlar ham shu qoidalarga bo‘ysunadi.', 'В этой теме мы точно определим многоугольник, его вершины, стороны, диагонали и углы, докажем, что сумма внутренних углов равна (n − 2) · 180°, а сумма внешних всегда 360°, и научимся находить число диагоналей. Пчелиные соты, футбольный мяч и узоры на порталах Самарканда тоже подчиняются этим правилам.', 'In this topic we define a polygon and its vertices, sides, diagonals and angles precisely, prove that the interior angles add up to (n − 2) · 180° while the exterior angles always add up to 360°, and learn to count diagonals. Honeycombs, footballs and the patterns on the portals of Samarkand all obey these rules.')
    ] },
    { kind: 'def', h: L('Ko‘pburchak va uning elementlari', 'Многоугольник и его элементы', 'A polygon and its parts'), p: [
      L('<b>Ko‘pburchak</b> — bu o‘zini o‘zi kesmaydigan yopiq siniq chiziq va u chegaralagan tekislik qismi. Siniq chiziqning bo‘g‘inlari ko‘pburchakning <b>tomonlari</b>, bo‘g‘inlar tutashgan nuqtalar esa <b>uchlari</b> deyiladi. n ta uchi bor ko‘pburchak <b>n-burchak</b> deb ataladi: uchburchak (n = 3), to‘rtburchak (n = 4), beshburchak (n = 5) va hokazo. Ko‘pburchakning uchlari soni, tomonlari soni va burchaklari soni har doim bir xil.', '<b>Многоугольник</b> — это замкнутая ломаная без самопересечений вместе с частью плоскости, которую она ограничивает. Звенья ломаной — <b>стороны</b> многоугольника, точки соединения звеньев — <b>вершины</b>. Многоугольник с n вершинами называют <b>n-угольником</b>: треугольник (n = 3), четырёхугольник (n = 4), пятиугольник (n = 5) и так далее. Число вершин, сторон и углов у многоугольника всегда одинаково.', 'A <b>polygon</b> is a closed broken line that does not cross itself, together with the part of the plane it encloses. The links of the broken line are the <b>sides</b>, and the points where they meet are the <b>vertices</b>. A polygon with n vertices is an <b>n-gon</b>: triangle (n = 3), quadrilateral (n = 4), pentagon (n = 5) and so on. A polygon always has the same number of vertices, sides and angles.')
    ], list: [
      L('<b>Qo‘shni uchlar</b> — bitta tomonning ikki uchi; qo‘shni bo‘lmagan uchlarni tutashtiruvchi kesma — <b>diagonal</b>.', '<b>Соседние вершины</b> — концы одной стороны; отрезок, соединяющий несоседние вершины, — <b>диагональ</b>.', '<b>Neighbouring vertices</b> are the two ends of one side; a segment joining two non-neighbouring vertices is a <b>diagonal</b>.'),
      L('<b>Perimetr</b> — barcha tomonlar uzunliklarining yig‘indisi.', '<b>Периметр</b> — сумма длин всех сторон.', 'The <b>perimeter</b> is the sum of the lengths of all sides.'),
      L('<b>Qavariq ko‘pburchak</b> — istalgan tomonini o‘z ichiga olgan to‘g‘ri chiziqning bir tomonida yotadigan ko‘pburchak. Unda har bir ichki burchak 180° dan kichik.', '<b>Выпуклый многоугольник</b> лежит по одну сторону от прямой, содержащей любую его сторону. Каждый его внутренний угол меньше 180°.', 'A <b>convex polygon</b> lies on one side of the line through any of its sides. Every interior angle of it is less than 180°.'),
      L('<b>Tashqi burchak</b> — ichki burchakka qo‘shni burchak: bir tomonni uchdan tashqariga davom ettirsak hosil bo‘ladi. Ichki va tashqi burchak yig‘indisi 180°.', '<b>Внешний угол</b> — угол, смежный с внутренним: получается, если продолжить сторону за вершину. Внутренний и внешний углы в сумме дают 180°.', 'An <b>exterior angle</b> is the angle next to an interior one, formed by extending a side past the vertex. An interior and its exterior angle add up to 180°.'),
      L('<b>Muntazam ko‘pburchak</b> — barcha tomonlari teng va barcha burchaklari teng bo‘lgan qavariq ko‘pburchak.', '<b>Правильный многоугольник</b> — выпуклый многоугольник, у которого все стороны и все углы равны.', 'A <b>regular polygon</b> is a convex polygon with all sides equal and all angles equal.')
    ] },
    { kind: 'history', h: L('Ko‘pburchaklar tarixi: Yevklid va girih naqshlari', 'История: Евклид и узоры гирих', 'History: Euclid and girih patterns'), p: [
      L('Taxminan miloddan avvalgi 300-yilda Iskandariyada yashagan yunon olimi <b>Yevklid</b> o‘sha davrgacha to‘plangan geometrik bilimlarni «Negizlar» («Elementlar») nomli 13 kitobga jamladi. Unda uchburchak burchaklari yig‘indisi 180° ekani isbotlangan, keyin esa bu fakt ko‘pburchaklarga tatbiq qilingan. «Negizlar» ikki ming yildan ortiq vaqt davomida dunyodagi asosiy geometriya darsligi bo‘lib keldi.', 'Около 300 года до н. э. греческий учёный <b>Евклид</b>, живший в Александрии, собрал накопленные геометрические знания в 13 книгах «Начал». Там доказано, что сумма углов треугольника равна 180°, а затем этот факт применён к многоугольникам. «Начала» более двух тысяч лет оставались главным учебником геометрии в мире.', 'Around 300 BC the Greek scholar <b>Euclid</b>, who lived in Alexandria, gathered the geometry known in his day into the 13 books of the <b>Elements</b>. There he proves that a triangle’s angles add up to 180° and then applies this to polygons. For more than two thousand years the Elements remained the world’s main geometry textbook.'),
      L('Ko‘pburchaklar Sharq me’morchiligida ayniqsa go‘zal namoyon bo‘ldi. Samarqanddagi Registon, Buxorodagi Minorai Kalon va Shohi Zinda maqbaralarida <b>girih</b> deb ataladigan naqshlar bor: ular besh, olti, sakkiz va o‘n burchakli yulduzlar hamda ko‘pburchaklardan tuzilgan. Usta naqqoshlar tekislikni bo‘shliqsiz to‘ldirish uchun har bir uchda burchaklar yig‘indisi aniq 360° bo‘lishini bilishgan. Al-Xorazmiy va Abu Rayhon Beruniy asarlarida ham ko‘pburchaklar va ularning burchaklari bilan bog‘liq hisoblar uchraydi.', 'Многоугольники особенно красиво проявились в архитектуре Востока. На Регистане в Самарканде, на минарете Калян в Бухаре и в ансамбле Шахи-Зинда есть узоры <b>гирих</b>: они составлены из пяти-, шести-, восьми- и десятиугольных звёзд и многоугольников. Мастера знали, что для заполнения плоскости без щелей сумма углов в каждой вершине должна быть ровно 360°. Вычисления с многоугольниками и их углами встречаются и в трудах аль-Хорезми и Абу Райхана Беруни.', 'Polygons appear especially beautifully in the architecture of Central Asia. The Registan in Samarkand, the Kalyan minaret in Bukhara and the Shah-i-Zinda tombs carry <b>girih</b> patterns built from five-, six-, eight- and ten-pointed stars and polygons. The craftsmen knew that to fill a surface without gaps, the angles meeting at each point must add up to exactly 360°. Calculations with polygons and their angles also appear in the works of al-Khwarizmi and Abu Rayhan al-Biruni.')
    ] },
    { kind: 'rule', h: L('Ichki burchaklar yig‘indisi: (n − 2) · 180°', 'Сумма внутренних углов: (n − 2) · 180°', 'Interior angle sum: (n − 2) · 180°'), p: [
      L('<b>Teorema.</b> Qavariq n-burchakning ichki burchaklari yig‘indisi <b>(n − 2) · 180°</b> ga teng.', '<b>Теорема.</b> Сумма внутренних углов выпуклого n-угольника равна <b>(n − 2) · 180°</b>.', '<b>Theorem.</b> The interior angles of a convex n-gon add up to <b>(n − 2) · 180°</b>.'),
      L('<b>Isbot g‘oyasi.</b> Bitta uchni, masalan A₁ ni tanlaymiz va undan barcha diagonallarni o‘tkazamiz. A₁ uchi o‘zi bilan ham, ikkita qo‘shni uchi bilan ham diagonal hosil qilmaydi, shuning uchun undan (n − 3) ta diagonal chiqadi. Bu diagonallar ko‘pburchakni (n − 2) ta uchburchakka bo‘ladi. Har bir uchburchak burchaklari yig‘indisi 180°, va bu uchburchaklarning barcha burchaklari birgalikda ko‘pburchakning ichki burchaklarini aynan to‘ldiradi. Demak, yig‘indi (n − 2) · 180°.', '<b>Идея доказательства.</b> Выберем одну вершину, например A₁, и проведём из неё все диагонали. Вершина A₁ не образует диагонали ни сама с собой, ни с двумя соседними, поэтому из неё выходит (n − 3) диагонали. Они делят многоугольник на (n − 2) треугольника. Сумма углов каждого треугольника 180°, а все их углы вместе в точности составляют внутренние углы многоугольника. Значит, сумма равна (n − 2) · 180°.', '<b>Proof idea.</b> Pick one vertex, say A₁, and draw every diagonal from it. A₁ makes no diagonal with itself or with its two neighbours, so (n − 3) diagonals leave it. They cut the polygon into (n − 2) triangles. Each triangle’s angles add up to 180°, and together all their angles make up exactly the interior angles of the polygon. So the sum is (n − 2) · 180°.'),
      L('<b>Muntazam n-burchakning</b> barcha burchaklari teng, shuning uchun bitta burchak <b>(n − 2) · 180° : n</b>. Masalan, muntazam oltiburchakda 4 · 180° : 6 = 120°.', 'У <b>правильного n-угольника</b> все углы равны, поэтому один угол равен <b>(n − 2) · 180° : n</b>. Например, у правильного шестиугольника 4 · 180° : 6 = 120°.', 'All angles of a <b>regular n-gon</b> are equal, so one angle is <b>(n − 2) · 180° ÷ n</b>. For a regular hexagon, for example, 4 · 180° ÷ 6 = 120°.'),
      L('<b>Diagonallar soni.</b> Har bir uchdan (n − 3) ta diagonal chiqadi, uchlar n ta, lekin har bir diagonal ikki uchga tegishli bo‘lgani uchun ikki marta sanaladi: d = <b>n(n − 3) / 2</b>.', '<b>Число диагоналей.</b> Из каждой вершины выходит (n − 3) диагонали, вершин n, но каждая диагональ посчитана дважды (у неё два конца): d = <b>n(n − 3) / 2</b>.', '<b>Number of diagonals.</b> Each of the n vertices sends out (n − 3) diagonals, but every diagonal has two ends and is counted twice: d = <b>n(n − 3) / 2</b>.')
    ] },
    { kind: 'rule', h: L('Tashqi burchaklar yig‘indisi har doim 360°', 'Сумма внешних углов всегда 360°', 'Exterior angles always add to 360°'), p: [
      L('<b>Teorema.</b> Qavariq ko‘pburchakning har bir uchida bittadan olingan tashqi burchaklari yig‘indisi <b>360°</b> ga teng — tomonlar soniga bog‘liq emas!', '<b>Теорема.</b> Сумма внешних углов выпуклого многоугольника, взятых по одному при каждой вершине, равна <b>360°</b> — независимо от числа сторон!', '<b>Theorem.</b> The exterior angles of a convex polygon, one taken at each vertex, add up to <b>360°</b> — whatever the number of sides!'),
      L('<b>Isbot.</b> Har bir uchda ichki va tashqi burchak yig‘indisi 180°. n ta uch bo‘lgani uchun barcha ichki va tashqi burchaklar yig‘indisi n · 180°. Undan ichki burchaklar yig‘indisini ayiramiz: n · 180° − (n − 2) · 180° = 2 · 180° = 360°.', '<b>Доказательство.</b> При каждой вершине внутренний и внешний углы дают 180°. Вершин n, значит, все внутренние и внешние углы вместе дают n · 180°. Вычтем сумму внутренних: n · 180° − (n − 2) · 180° = 2 · 180° = 360°.', '<b>Proof.</b> At each vertex the interior and exterior angles add up to 180°. With n vertices, all interior and exterior angles together give n · 180°. Subtract the interior sum: n · 180° − (n − 2) · 180° = 2 · 180° = 360°.'),
      L('<b>Tasavvur qiling:</b> siz ko‘pburchak shaklidagi yo‘lak bo‘ylab yuryapsiz. Har bir burchakda tashqi burchak qadar buriliysiz. Boshlang‘ich joyga qaytganingizda siz roppa-rosa bir marta to‘liq aylangan bo‘lasiz, ya’ni 360° ga burilgansiz. Shuning uchun muntazam n-burchakning bitta tashqi burchagi 360° : n.', '<b>Представьте:</b> вы идёте по дорожке в форме многоугольника. В каждой вершине поворачиваете на внешний угол. Вернувшись в начальную точку, вы сделали ровно один полный оборот, то есть повернулись на 360°. Поэтому внешний угол правильного n-угольника равен 360° : n.', '<b>Imagine</b> walking along a path shaped like a polygon. At every corner you turn through the exterior angle. When you are back at the start you have made exactly one full turn, that is 360°. That is why one exterior angle of a regular n-gon is 360° ÷ n.')
    ] },
    { kind: 'steps', h: L('Burchaklarga oid masalani yechish tartibi', 'Порядок решения задач на углы', 'How to solve an angle problem'), list: [
      L('1. Ko‘pburchak qavariqmi, tomonlari soni n nechta — aniqlang.', '1. Определите, выпуклый ли многоугольник и сколько у него сторон n.', '1. Check that the polygon is convex and find its number of sides n.'),
      L('2. Ichki burchaklar yig‘indisini hisoblang: S = (n − 2) · 180°.', '2. Вычислите сумму внутренних углов: S = (n − 2) · 180°.', '2. Work out the interior sum: S = (n − 2) · 180°.'),
      L('3. Agar ko‘pburchak muntazam bo‘lsa, bitta burchak S : n; tashqi burchak 360° : n.', '3. Если многоугольник правильный, один угол S : n; внешний угол 360° : n.', '3. If it is regular, one angle is S ÷ n and one exterior angle is 360° ÷ n.'),
      L('4. Agar n noma’lum bo‘lsa, tenglama tuzing: (n − 2) · 180° = berilgan yig‘indi yoki 360° : n = berilgan tashqi burchak.', '4. Если n неизвестно, составьте уравнение: (n − 2) · 180° = данная сумма или 360° : n = данный внешний угол.', '4. If n is unknown, set up an equation: (n − 2) · 180° = the given sum, or 360° ÷ n = the given exterior angle.'),
      L('5. Javob natural son ekanini va n ≥ 3 ekanini tekshiring. Kasr chiqsa, bunday ko‘pburchak mavjud emas.', '5. Проверьте, что ответ натуральный и n ≥ 3. Если получилась дробь, такого многоугольника не существует.', '5. Check that the answer is a whole number with n ≥ 3. If you get a fraction, no such polygon exists.')
    ], after: [
      L('Maslahat: tashqi burchak orqali ishlash ko‘pincha tezroq, chunki 360° soni n ga bog‘liq emas.', 'Совет: работать через внешний угол часто быстрее, потому что 360° не зависит от n.', 'Tip: working through the exterior angle is often faster, because 360° does not depend on n.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Qavariq sakkizburchakning ichki burchaklari yig‘indisini toping. Muntazam sakkizburchakning bitta burchagi nechaga teng?', 'Найдите сумму внутренних углов выпуклого восьмиугольника. Чему равен один угол правильного восьмиугольника?', 'Find the interior angle sum of a convex octagon. What is one angle of a regular octagon?'),
        s: L('n = 8. S = (8 − 2) · 180° = 6 · 180° = 1080°. Muntazam bo‘lsa, bitta burchak 1080° : 8 = 135°. Tekshirish: tashqi burchak 180° − 135° = 45°, va 8 · 45° = 360°. To‘g‘ri.', 'n = 8. S = (8 − 2) · 180° = 6 · 180° = 1080°. Для правильного: один угол 1080° : 8 = 135°. Проверка: внешний угол 180° − 135° = 45°, и 8 · 45° = 360°. Верно.', 'n = 8. S = (8 − 2) · 180° = 6 · 180° = 1080°. If regular, one angle is 1080° ÷ 8 = 135°. Check: the exterior angle is 180° − 135° = 45°, and 8 · 45° = 360°. Correct.') },
      { q: L('Ko‘pburchakning ichki burchaklari yig‘indisi 1980°. Uning nechta tomoni bor?', 'Сумма внутренних углов многоугольника 1980°. Сколько у него сторон?', 'A polygon’s interior angles add up to 1980°. How many sides does it have?'),
        s: L('(n − 2) · 180° = 1980°, n − 2 = 11, n = 13. Javob: 13 ta tomon. Agar yig‘indi, masalan, 1000° bo‘lganida, 1000 : 180 butun chiqmasdi — bunday ko‘pburchak bo‘lmasdi.', '(n − 2) · 180° = 1980°, n − 2 = 11, n = 13. Ответ: 13 сторон. Если бы сумма была, например, 1000°, то 1000 : 180 не было бы целым — такого многоугольника нет.', '(n − 2) · 180° = 1980°, so n − 2 = 11 and n = 13. Answer: 13 sides. If the sum were, say, 1000°, then 1000 ÷ 180 would not be whole — no such polygon would exist.') },
      { q: L('Muntazam ko‘pburchakning tashqi burchagi 24°. Uning tomonlari sonini va diagonallari sonini toping.', 'Внешний угол правильного многоугольника 24°. Найдите число сторон и число диагоналей.', 'A regular polygon has an exterior angle of 24°. Find its number of sides and its number of diagonals.'),
        s: L('n = 360° : 24° = 15. Diagonallar: d = 15 · (15 − 3) : 2 = 15 · 12 : 2 = 90. Ichki burchak esa 180° − 24° = 156°.', 'n = 360° : 24° = 15. Диагоналей: d = 15 · (15 − 3) : 2 = 15 · 12 : 2 = 90. Внутренний угол 180° − 24° = 156°.', 'n = 360° ÷ 24° = 15. Diagonals: d = 15 · (15 − 3) ÷ 2 = 15 · 12 ÷ 2 = 90. Each interior angle is 180° − 24° = 156°.') },
      { q: L('Beshburchakning burchaklari 2 : 3 : 3 : 4 : 6 nisbatda. Eng katta burchakni toping.', 'Углы пятиугольника относятся как 2 : 3 : 3 : 4 : 6. Найдите наибольший угол.', 'The angles of a pentagon are in the ratio 2 : 3 : 3 : 4 : 6. Find the largest angle.'),
        s: L('Yig‘indi (5 − 2) · 180° = 540°. Qismlar soni 2 + 3 + 3 + 4 + 6 = 18, bitta qism 540° : 18 = 30°. Eng katta burchak 6 · 30° = 180°. Lekin qavariq ko‘pburchakda burchak 180° bo‘lolmaydi — bunday qavariq beshburchak yo‘q! Bu tekshiruv nega muhimligini ko‘rsatadi.', 'Сумма (5 − 2) · 180° = 540°. Частей 2 + 3 + 3 + 4 + 6 = 18, одна часть 540° : 18 = 30°. Наибольший угол 6 · 30° = 180°. Но в выпуклом многоугольнике угол не может быть 180° — такого выпуклого пятиугольника нет! Вот почему проверка важна.', 'The sum is (5 − 2) · 180° = 540°. There are 2 + 3 + 3 + 4 + 6 = 18 parts, so one part is 540° ÷ 18 = 30°. The largest angle is 6 · 30° = 180°. But a convex polygon cannot have a 180° angle — no such convex pentagon exists! This shows why checking matters.') }
    ] },
    { kind: 'table', h: L('Muntazam ko‘pburchaklar jadvali', 'Таблица правильных многоугольников', 'Table of regular polygons'), table: {
      head: [L('n', 'n', 'n'), L('Nomi', 'Название', 'Name'), L('Ichki yig‘indi', 'Сумма внутр.', 'Interior sum'), L('Bitta burchak', 'Один угол', 'One angle'), L('Diagonallar', 'Диагонали', 'Diagonals')],
      rows: [
        ['3', L('uchburchak', 'треугольник', 'triangle'), '180°', '60°', '0'],
        ['4', L('kvadrat', 'квадрат', 'square'), '360°', '90°', '2'],
        ['5', L('beshburchak', 'пятиугольник', 'pentagon'), '540°', '108°', '5'],
        ['6', L('oltiburchak', 'шестиугольник', 'hexagon'), '720°', '120°', '9'],
        ['8', L('sakkizburchak', 'восьмиугольник', 'octagon'), '1080°', '135°', '20'],
        ['10', L('o‘nburchak', 'десятиугольник', 'decagon'), '1440°', '144°', '35'],
        ['12', L('o‘n ikkiburchak', 'двенадцатиугольник', 'dodecagon'), '1800°', '150°', '54']
      ] }, after: [
      L('Jadvalga qarang: n oshgan sari bitta burchak 180° ga yaqinlashadi, lekin hech qachon unga yetmaydi. Juda ko‘p tomonli muntazam ko‘pburchak deyarli aylanaga o‘xshab qoladi.', 'Посмотрите на таблицу: с ростом n один угол приближается к 180°, но никогда его не достигает. Правильный многоугольник с очень большим числом сторон почти похож на окружность.', 'Look at the table: as n grows, one angle gets closer to 180° but never reaches it. A regular polygon with very many sides looks almost like a circle.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>n · 180° deb yozish.</b> Ichki yig‘indi (n − 2) · 180°, chunki uchburchaklar soni tomonlar sonidan 2 ta kam. Tekshiring: uchburchak uchun n · 180° = 540° bo‘lardi — bu noto‘g‘ri.', '<b>Писать n · 180°.</b> Сумма внутренних углов (n − 2) · 180°, ведь треугольников на 2 меньше, чем сторон. Проверьте: для треугольника вышло бы 540° — неверно.', '<b>Writing n · 180°.</b> The interior sum is (n − 2) · 180°, because there are 2 fewer triangles than sides. Test it: a triangle would give 540° — wrong.'),
      L('<b>Tashqi burchaklar yig‘indisini n ga bog‘lash.</b> U har doim 360°, uchburchakda ham, yuzburchakda ham.', '<b>Связывать сумму внешних углов с n.</b> Она всегда 360° — и у треугольника, и у стоугольника.', '<b>Making the exterior sum depend on n.</b> It is always 360°, for a triangle and for a 100-gon alike.'),
      L('<b>Diagonallarni n(n − 3) deb sanash.</b> Har bir diagonal ikki marta sanaladi, shuning uchun 2 ga bo‘lish shart.', '<b>Считать диагонали как n(n − 3).</b> Каждая диагональ посчитана дважды, поэтому надо делить на 2.', '<b>Counting diagonals as n(n − 3).</b> Each diagonal is counted twice, so you must divide by 2.'),
      L('<b>Har qanday ko‘pburchakni muntazam deb hisoblash.</b> Burchakni S : n deb faqat barcha burchaklar teng bo‘lganda topish mumkin.', '<b>Считать любой многоугольник правильным.</b> Делить сумму на n можно только тогда, когда все углы равны.', '<b>Treating every polygon as regular.</b> You may divide the sum by n only when all angles are equal.'),
      L('<b>Javobni tekshirmaslik.</b> Tomonlar soni butun bo‘lishi, qavariq ko‘pburchak burchaklari esa 0° dan katta va 180° dan kichik bo‘lishi kerak.', '<b>Не проверять ответ.</b> Число сторон должно быть целым, а углы выпуклого многоугольника — больше 0° и меньше 180°.', '<b>Not checking the answer.</b> The number of sides must be whole, and the angles of a convex polygon must lie between 0° and 180°.')
    ] },
    { kind: 'life', h: L('Hayotda ko‘pburchaklar', 'Многоугольники в жизни', 'Polygons in real life'), p: [
      L('<b>Asalari uyalari</b> muntazam oltiburchaklardan iborat. Nega aynan oltiburchak? Uning burchagi 120°, uchtasi bir nuqtada uchrashsa 3 · 120° = 360° bo‘ladi va bo‘shliq qolmaydi. Bundan tashqari, bir xil perimetrda oltiburchak uchburchak va kvadratga qaraganda ko‘proq yuzani o‘raydi, ya’ni asalarilar mumdan tejab foydalanadi.', '<b>Пчелиные соты</b> состоят из правильных шестиугольников. Почему именно шестиугольник? Его угол 120°, три угла в одной точке дают 3 · 120° = 360°, и щелей нет. К тому же при том же периметре шестиугольник охватывает больше площади, чем треугольник и квадрат, — пчёлы экономят воск.', '<b>Honeycombs</b> are made of regular hexagons. Why hexagons? Each angle is 120°, so three meeting at a point give 3 · 120° = 360° with no gaps. Also, for the same perimeter a hexagon encloses more area than a triangle or a square, so the bees save wax.'),
      L('<b>Plitka va parket</b> ustalari ham shu qoidadan foydalanadi: pol yoki devorni bir xil muntazam ko‘pburchaklar bilan faqat uch turda qoplash mumkin — uchburchak (6 · 60°), kvadrat (4 · 90°) va oltiburchak (3 · 120°). Muntazam beshburchak bunga yaramaydi, chunki 108° ni butun songa ko‘paytirib 360° hosil qilib bo‘lmaydi. Aynan shu sababli girih ustalari beshburchaklarni yulduzlar va romblar bilan aralashtirgan.', '<b>Плиточники и паркетчики</b> пользуются тем же правилом: замостить пол одинаковыми правильными многоугольниками можно только тремя способами — треугольниками (6 · 60°), квадратами (4 · 90°) и шестиугольниками (3 · 120°). Правильный пятиугольник не подходит: 108°, умноженное на целое число, не даёт 360°. Поэтому мастера гирих сочетали пятиугольники со звёздами и ромбами.', '<b>Tilers and parquet makers</b> use the same rule: a floor can be covered with identical regular polygons in only three ways — triangles (6 · 60°), squares (4 · 90°) and hexagons (3 · 120°). A regular pentagon will not work, because no whole number times 108° equals 360°. That is why girih masters mixed pentagons with stars and rhombuses.'),
      L('<b>Futbol to‘pi</b> 12 ta beshburchak va 20 ta oltiburchakdan tikiladi, <b>STOP</b> yo‘l belgisi esa muntazam sakkizburchak (har bir burchagi 135°). Robotlar va dronlar ko‘pburchak bo‘ylab harakatlanganda dasturchilar har bir burilish burchagini 360° : n deb hisoblaydi.', '<b>Футбольный мяч</b> сшит из 12 пятиугольников и 20 шестиугольников, а знак <b>STOP</b> — правильный восьмиугольник (каждый угол 135°). Когда робот или дрон облетает многоугольник, программисты задают угол поворота 360° : n.', 'A <b>football</b> is stitched from 12 pentagons and 20 hexagons, and a <b>STOP</b> sign is a regular octagon (each angle 135°). When a robot or drone travels round a polygon, programmers set each turn to 360° ÷ n.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Ichki burchagi butun gradus bo‘lgan muntazam ko‘pburchaklar faqat n soni 360 ning bo‘luvchisi bo‘lganda hosil bo‘ladi: n = 3, 4, 5, 6, 8, 9, 10, 12, 15, 18, 20, 24, 30, 36, 40, 45, 60, 72, 90, 120, 180, 360.', 'Правильные многоугольники с целым числом градусов во внешнем угле бывают только тогда, когда n делит 360: n = 3, 4, 5, 6, 8, 9, 10, 12, 15, 18, 20, 24, 30, 36, 40, 45, 60, 72, 90, 120, 180, 360.', 'A regular polygon has a whole-degree exterior angle only when n divides 360: n = 3, 4, 5, 6, 8, 9, 10, 12, 15, 18, 20, 24, 30, 36, 40, 45, 60, 72, 90, 120, 180, 360.'),
      L('Yigirmaburchakda 170 ta diagonal bor, yuzburchakda esa 4850 ta!', 'У двадцатиугольника 170 диагоналей, а у стоугольника — 4850!', 'A 20-gon has 170 diagonals, and a 100-gon has 4850!'),
      L('Arximed aylana uzunligini baholash uchun 96 burchakli muntazam ko‘pburchakdan foydalanib, π soni 3,1408 bilan 3,1429 orasida ekanini ko‘rsatgan.', 'Архимед, чтобы оценить длину окружности, использовал правильный 96-угольник и показал, что π лежит между 3,1408 и 3,1429.', 'Archimedes used a regular 96-gon to estimate the circumference of a circle and showed that π lies between 3.1408 and 3.1429.'),
      L('Botiq (qavariq bo‘lmagan) ko‘pburchakda ham ichki burchaklar yig‘indisi (n − 2) · 180°, ammo unda 180° dan katta burchak bo‘ladi.', 'И у невыпуклого многоугольника сумма внутренних углов (n − 2) · 180°, но там есть угол больше 180°.', 'Even a non-convex polygon has interior sum (n − 2) · 180°, but it contains an angle larger than 180°.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. To‘qqizburchakning ichki burchaklari yig‘indisi qancha?', '1. Чему равна сумма внутренних углов девятиугольника?', '1. What is the interior angle sum of a nonagon?'),
      L('2. Muntazam ko‘pburchakning ichki burchagi 150°. Nechta tomoni bor?', '2. Внутренний угол правильного многоугольника 150°. Сколько у него сторон?', '2. A regular polygon has interior angle 150°. How many sides does it have?'),
      L('3. Ichki burchagi 100° bo‘lgan muntazam ko‘pburchak mavjudmi?', '3. Существует ли правильный многоугольник с внутренним углом 100°?', '3. Is there a regular polygon with interior angle 100°?'),
      L('4. Diagonallari 14 ta bo‘lgan ko‘pburchakning nechta tomoni bor?', '4. Сколько сторон у многоугольника с 14 диагоналями?', '4. How many sides has a polygon with 14 diagonals?')
    ], after: [
      L('Javoblar: 1) 7 · 180° = 1260°; 2) tashqi burchak 30°, n = 12; 3) tashqi burchak 80°, 360 : 80 = 4,5 — yo‘q; 4) n(n − 3) = 28, n = 7.', 'Ответы: 1) 7 · 180° = 1260°; 2) внешний угол 30°, n = 12; 3) внешний угол 80°, 360 : 80 = 4,5 — нет; 4) n(n − 3) = 28, n = 7.', 'Answers: 1) 7 · 180° = 1260°; 2) exterior angle 30°, n = 12; 3) exterior angle 80°, 360 ÷ 80 = 4.5 — no; 4) n(n − 3) = 28, n = 7.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Ko‘pburchak — o‘zini kesmaydigan yopiq siniq chiziq bilan chegaralangan shakl; uchlari, tomonlari va burchaklari soni teng.', 'Многоугольник — фигура, ограниченная замкнутой ломаной без самопересечений; вершин, сторон и углов у него поровну.', 'A polygon is bounded by a closed broken line that does not cross itself; it has as many vertices as sides and angles.'),
      L('Qavariq n-burchak ichki burchaklari yig‘indisi (n − 2) · 180°.', 'Сумма внутренних углов выпуклого n-угольника (n − 2) · 180°.', 'A convex n-gon has interior angle sum (n − 2) · 180°.'),
      L('Tashqi burchaklar yig‘indisi har doim 360°.', 'Сумма внешних углов всегда 360°.', 'The exterior angles always add up to 360°.'),
      L('Muntazam n-burchakda: ichki burchak (n − 2) · 180° : n, tashqi burchak 360° : n.', 'У правильного n-угольника внутренний угол (n − 2) · 180° : n, внешний 360° : n.', 'In a regular n-gon the interior angle is (n − 2) · 180° ÷ n and the exterior angle is 360° ÷ n.'),
      L('Diagonallar soni n(n − 3) / 2.', 'Число диагоналей n(n − 3) / 2.', 'The number of diagonals is n(n − 3) / 2.'),
      L('Isbot g‘oyasi: ko‘pburchakni bitta uchdan chiqqan diagonallar bilan (n − 2) ta uchburchakka bo‘lish.', 'Идея доказательства: разрезать многоугольник диагоналями из одной вершины на (n − 2) треугольника.', 'Proof idea: cut the polygon into (n − 2) triangles with the diagonals from one vertex.')
    ] }
  ] });

  // ---------- t2. Parallelogramm, uning xossalari va alomatlari ----------
  T.add(P, 't2', { sections: [
    { kind: 'intro', h: L('Qarama-qarshi tomonlari parallel to‘rtburchak', 'Четырёхугольник с параллельными сторонами', 'A quadrilateral with parallel sides'), p: [
      L('Daftaringizdagi katakchalarni, eshik ramkasini yoki temir yo‘l relslarini eslang. Ularda bir-biriga parallel chiziqlar juft-juft bo‘lib keladi. Ikki juft parallel to‘g‘ri chiziq kesishganda hosil bo‘ladigan to‘rtburchak <b>parallelogramm</b> deyiladi. Bu nom yunoncha «parallel chiziqlar bilan chegaralangan» degan ma’noni beradi.', 'Вспомните клеточки в тетради, дверную раму или рельсы. В них параллельные линии идут парами. Четырёхугольник, который получается при пересечении двух пар параллельных прямых, называется <b>параллелограммом</b>. Это греческое слово означает «ограниченный параллельными линиями».', 'Think of the squares in your exercise book, a door frame or railway tracks. In them, parallel lines come in pairs. The quadrilateral formed where two pairs of parallel lines cross is called a <b>parallelogram</b>. The Greek name means “bounded by parallel lines”.'),
      L('Parallelogramm geometriyaning eng muhim shakllaridan biri: to‘g‘ri to‘rtburchak, romb va kvadrat uning xususiy hollari. Uning xossalarini bilsak, ko‘plab masalalar bir zumda yechiladi. Bu mavzuda ikki narsani farqlashni o‘rganamiz: <b>xossa</b> — parallelogramm bo‘lsa, unda nima bajariladi; <b>alomat</b> — qanday shartlar bajarilsa, to‘rtburchak parallelogramm bo‘ladi.', 'Параллелограмм — одна из важнейших фигур геометрии: прямоугольник, ромб и квадрат — его частные случаи. Зная его свойства, многие задачи решаем мгновенно. В этой теме научимся различать две вещи: <b>свойство</b> — что выполняется, если фигура параллелограмм; <b>признак</b> — при каких условиях четырёхугольник является параллелограммом.', 'The parallelogram is one of the most important figures in geometry: rectangles, rhombuses and squares are special cases of it. If we know its properties, many problems are solved in a moment. In this topic we learn to tell two things apart: a <b>property</b> — what is true if the figure is a parallelogram; a <b>test</b> — which conditions make a quadrilateral a parallelogram.'),
      L('Isbotlarda bizga 7-sinfdagi ikki asosiy vosita yordam beradi: parallel to‘g‘ri chiziqlar va kesuvchi hosil qilgan burchaklar hamda uchburchaklar tengligi alomatlari.', 'В доказательствах нам помогут два инструмента из 7 класса: углы при параллельных прямых и секущей и признаки равенства треугольников.', 'Two tools from grade 7 will help in the proofs: the angles formed by parallel lines and a transversal, and the tests for congruent triangles.')
    ] },
    { kind: 'def', h: L('Ta’rif va belgilashlar', 'Определение и обозначения', 'Definition and notation'), p: [
      L('<b>Parallelogramm</b> — qarama-qarshi tomonlari juft-jufti bilan parallel bo‘lgan to‘rtburchak. ABCD parallelogrammda AB ∥ CD va BC ∥ AD. Uchlar ketma-ket, aylanib chiqish tartibida yoziladi; A va C, B va D — qarama-qarshi uchlar; AC va BD — diagonallar.', '<b>Параллелограмм</b> — четырёхугольник, у которого противоположные стороны попарно параллельны. В параллелограмме ABCD AB ∥ CD и BC ∥ AD. Вершины записывают по порядку обхода; A и C, B и D — противоположные вершины; AC и BD — диагонали.', 'A <b>parallelogram</b> is a quadrilateral whose opposite sides are parallel in pairs. In parallelogram ABCD, AB ∥ CD and BC ∥ AD. The vertices are written in order round the figure; A and C, B and D are opposite vertices; AC and BD are the diagonals.'),
      L('Parallelogrammning <b>balandligi</b> — bir tomonning istalgan nuqtasidan qarama-qarshi tomon yotgan to‘g‘ri chiziqqa tushirilgan perpendikulyar. Har bir parallelogrammda ikki xil balandlik bor: biri AD tomonga, ikkinchisi AB tomonga tushiriladi. Ular odatda turli uzunlikda bo‘ladi.', '<b>Высота</b> параллелограмма — перпендикуляр, опущенный из любой точки одной стороны на прямую, содержащую противоположную сторону. У параллелограмма два вида высот: к стороне AD и к стороне AB. Обычно они разной длины.', 'A <b>height</b> of a parallelogram is a perpendicular dropped from any point of one side onto the line containing the opposite side. Every parallelogram has two kinds of height: one to side AD and one to side AB. Usually they have different lengths.'),
      L('Qisqa yozuv: ▱ABCD. Qo‘shni burchaklar — bitta tomonga yopishgan burchaklar, masalan ∠A va ∠B.', 'Краткая запись: ▱ABCD. Соседние углы — углы, прилежащие к одной стороне, например ∠A и ∠B.', 'Short notation: ▱ABCD. Neighbouring angles are the angles on one side, for example ∠A and ∠B.')
    ] },
    { kind: 'history', h: L('Tarixdan: Yevklid va parallellar', 'Из истории: Евклид и параллельные', 'History: Euclid and parallels'), p: [
      L('Yevklidning «Negizlar» asarining birinchi kitobida parallelogrammning asosiy xossasi isbotlangan: uning qarama-qarshi tomonlari va burchaklari teng, diagonal esa uni teng ikkiga bo‘ladi. Yevklid bu xossalarni o‘zining mashhur beshinchi postulatiga — parallellar haqidagi aksiomaga tayanib isbotlagan. Keyinchalik minglab olimlar bu postulatni boshqa aksiomalardan keltirib chiqarishga urinishgan.', 'В первой книге «Начал» Евклида доказано основное свойство параллелограмма: противоположные стороны и углы равны, а диагональ делит его пополам. Евклид опирался на свой знаменитый пятый постулат — аксиому о параллельных. Позже тысячи учёных пытались вывести этот постулат из других аксиом.', 'In Book I of Euclid’s Elements the main property of the parallelogram is proved: opposite sides and angles are equal, and a diagonal halves it. Euclid relied on his famous fifth postulate — the axiom of parallels. Later, thousands of scholars tried to derive this postulate from the other axioms.'),
      L('Bunday urinishlar orasida O‘rta Osiyo va Sharq olimlarining ishlari alohida o‘rin tutadi. Umar Xayyom XI asrda to‘rtburchaklarni o‘rganib, parallellar nazariyasiga sharh yozgan; XIII asrda Nasiriddin Tusiy bu ishni davom ettirgan. Ular postulatni isbotlay olmagan bo‘lsa-da, ularning g‘oyalari XIX asrda Lobachevskiy va Gauss kashf etgan noyevklid geometriyaga yo‘l ochdi. Demak, oddiy parallelogramm ortida ming yillik ilmiy bahs yotadi.', 'Среди этих попыток особое место занимают работы учёных Востока. Омар Хайям в XI веке, изучая четырёхугольники, написал комментарий к теории параллельных; в XIII веке эту работу продолжил Насир ад-Дин Туси. Доказать постулат они не смогли, но их идеи подготовили открытие неевклидовой геометрии Лобачевским и Гауссом в XIX веке. За простым параллелограммом стоит тысячелетний научный спор.', 'Among these attempts, the work of scholars of the Islamic East stands out. In the 11th century Omar Khayyam studied quadrilaterals and wrote a commentary on the theory of parallels; in the 13th century Nasir al-Din al-Tusi continued the work. They could not prove the postulate, but their ideas paved the way for the non-Euclidean geometry discovered by Lobachevsky and Gauss in the 19th century. Behind the humble parallelogram lies a thousand-year scientific debate.')
    ] },
    { kind: 'rule', h: L('Parallelogramm xossalari', 'Свойства параллелограмма', 'Properties of a parallelogram'), list: [
      L('<b>1-xossa.</b> Qarama-qarshi tomonlar teng: AB = CD, BC = AD.', '<b>Свойство 1.</b> Противоположные стороны равны: AB = CD, BC = AD.', '<b>Property 1.</b> Opposite sides are equal: AB = CD, BC = AD.'),
      L('<b>2-xossa.</b> Qarama-qarshi burchaklar teng: ∠A = ∠C, ∠B = ∠D.', '<b>Свойство 2.</b> Противоположные углы равны: ∠A = ∠C, ∠B = ∠D.', '<b>Property 2.</b> Opposite angles are equal: ∠A = ∠C, ∠B = ∠D.'),
      L('<b>3-xossa.</b> Bitta tomonga yopishgan burchaklar yig‘indisi 180°: ∠A + ∠B = 180°.', '<b>Свойство 3.</b> Сумма углов, прилежащих к одной стороне, равна 180°: ∠A + ∠B = 180°.', '<b>Property 3.</b> Angles on the same side add up to 180°: ∠A + ∠B = 180°.'),
      L('<b>4-xossa.</b> Diagonallar kesishish nuqtasida teng ikkiga bo‘linadi: AO = OC, BO = OD.', '<b>Свойство 4.</b> Диагонали точкой пересечения делятся пополам: AO = OC, BO = OD.', '<b>Property 4.</b> The diagonals bisect each other: AO = OC, BO = OD.')
    ], after: [
      L('<b>Isbot g‘oyasi.</b> AC diagonalni o‘tkazamiz. AB ∥ CD bo‘lgani uchun ∠BAC = ∠DCA (ichki almashinuvchi burchaklar), BC ∥ AD bo‘lgani uchun ∠BCA = ∠DAC. AC — umumiy tomon. Demak, △ABC = △CDA (tomon va unga yopishgan ikki burchak bo‘yicha). Bundan AB = CD, BC = AD va ∠B = ∠D kelib chiqadi. 3-xossa esa parallel chiziqlarda ichki bir tomonli burchaklar yig‘indisi 180° ekanidan chiqadi.', '<b>Идея доказательства.</b> Проведём диагональ AC. Так как AB ∥ CD, ∠BAC = ∠DCA (накрест лежащие), а так как BC ∥ AD, ∠BCA = ∠DAC. AC — общая сторона. Значит, △ABC = △CDA (по стороне и двум прилежащим углам). Отсюда AB = CD, BC = AD и ∠B = ∠D. Свойство 3 следует из того, что односторонние углы при параллельных дают 180°.', '<b>Proof idea.</b> Draw diagonal AC. Since AB ∥ CD, ∠BAC = ∠DCA (alternate angles); since BC ∥ AD, ∠BCA = ∠DAC. AC is a common side. So △ABC ≅ △CDA (side and two adjacent angles). Hence AB = CD, BC = AD and ∠B = ∠D. Property 3 follows because co-interior angles between parallel lines add up to 180°.'),
      L('4-xossa uchun △AOB va △COD ni solishtiramiz: AB = CD, ∠OAB = ∠OCD, ∠OBA = ∠ODC. Uchburchaklar teng, demak AO = OC va BO = OD.', 'Для свойства 4 сравним △AOB и △COD: AB = CD, ∠OAB = ∠OCD, ∠OBA = ∠ODC. Треугольники равны, значит AO = OC и BO = OD.', 'For property 4 compare △AOB and △COD: AB = CD, ∠OAB = ∠OCD, ∠OBA = ∠ODC. The triangles are congruent, so AO = OC and BO = OD.')
    ] },
    { kind: 'rule', h: L('Parallelogramm alomatlari', 'Признаки параллелограмма', 'Tests for a parallelogram'), p: [
      L('Alomat — bu teskari teorema: u to‘rtburchak parallelogramm ekanini isbotlash uchun ishlatiladi. Agar to‘rtburchakda quyidagilardan <b>biri</b> bajarilsa, u parallelogramm:', 'Признак — это обратная теорема: с её помощью доказывают, что четырёхугольник — параллелограмм. Если в четырёхугольнике выполнено <b>одно</b> из условий, он — параллелограмм:', 'A test is a converse theorem: we use it to prove that a quadrilateral is a parallelogram. If <b>any one</b> of the following holds, the quadrilateral is a parallelogram:')
    ], list: [
      L('<b>1-alomat.</b> Ikki qarama-qarshi tomoni ham teng, ham parallel (masalan, BC = AD va BC ∥ AD).', '<b>Признак 1.</b> Две противоположные стороны равны и параллельны (например, BC = AD и BC ∥ AD).', '<b>Test 1.</b> One pair of opposite sides is both equal and parallel (for example, BC = AD and BC ∥ AD).'),
      L('<b>2-alomat.</b> Qarama-qarshi tomonlar juft-jufti bilan teng (AB = CD va BC = AD).', '<b>Признак 2.</b> Противоположные стороны попарно равны (AB = CD и BC = AD).', '<b>Test 2.</b> Both pairs of opposite sides are equal (AB = CD and BC = AD).'),
      L('<b>3-alomat.</b> Diagonallar kesishish nuqtasida teng ikkiga bo‘linadi.', '<b>Признак 3.</b> Диагонали точкой пересечения делятся пополам.', '<b>Test 3.</b> The diagonals bisect each other.'),
      L('<b>4-alomat.</b> Qarama-qarshi burchaklar juft-jufti bilan teng.', '<b>Признак 4.</b> Противоположные углы попарно равны.', '<b>Test 4.</b> Both pairs of opposite angles are equal.')
    ], after: [
      L('<b>1-alomat isboti g‘oyasi.</b> AC diagonalni o‘tkazamiz. BC ∥ AD bo‘lgani uchun ∠BCA = ∠DAC. BC = AD, AC — umumiy. Demak, △ABC = △CDA (ikki tomon va ular orasidagi burchak bo‘yicha). Bundan ∠BAC = ∠DCA, bu esa ichki almashinuvchi burchaklar, ya’ni AB ∥ CD. Ikki juft tomon parallel — parallelogramm.', '<b>Идея доказательства признака 1.</b> Проведём AC. Так как BC ∥ AD, ∠BCA = ∠DAC. BC = AD, AC общая. Значит, △ABC = △CDA (по двум сторонам и углу между ними). Отсюда ∠BAC = ∠DCA — накрест лежащие углы, то есть AB ∥ CD. Обе пары сторон параллельны — параллелограмм.', '<b>Proof idea for test 1.</b> Draw AC. Since BC ∥ AD, ∠BCA = ∠DAC. BC = AD and AC is common, so △ABC ≅ △CDA (two sides and the included angle). Hence ∠BAC = ∠DCA, which are alternate angles, so AB ∥ CD. Both pairs of sides are parallel — a parallelogram.'),
      L('Diqqat: «bir juft tomon teng, boshqa juft parallel» sharti yetarli emas — bunday to‘rtburchak teng yonli trapetsiya ham bo‘lishi mumkin.', 'Внимание: условия «одна пара сторон равна, другая параллельна» недостаточно — такой четырёхугольник может оказаться равнобедренной трапецией.', 'Careful: “one pair of sides equal and the other pair parallel” is not enough — such a quadrilateral may be an isosceles trapezium.')
    ] },
    { kind: 'steps', h: L('Parallelogramm ekanini qanday isbotlash kerak', 'Как доказать, что это параллелограмм', 'How to prove a figure is a parallelogram'), list: [
      L('1. Berilganlarni yozib oling: qaysi tomonlar, burchaklar yoki diagonal bo‘laklari teng yoki parallel.', '1. Выпишите данные: какие стороны, углы или части диагоналей равны или параллельны.', '1. Write down what is given: which sides, angles or diagonal parts are equal or parallel.'),
      L('2. To‘rtta alomatdan qaysi biri berilganlarga eng yaqin ekanini tanlang.', '2. Выберите, какой из четырёх признаков ближе всего к данным.', '2. Choose which of the four tests is closest to the data.'),
      L('3. Yetishmagan tenglikni teng uchburchaklar yoki parallel chiziqlardagi burchaklar orqali isbotlang.', '3. Недостающее равенство докажите через равные треугольники или углы при параллельных.', '3. Prove the missing equality using congruent triangles or angles at parallel lines.'),
      L('4. Alomatni nomi bilan aytib, xulosa yozing: «demak, ABCD — parallelogramm».', '4. Назовите признак и запишите вывод: «значит, ABCD — параллелограмм».', '4. Name the test and write the conclusion: “so ABCD is a parallelogram”.'),
      L('5. Endi parallelogramm xossalaridan foydalanib, masalaning asosiy savoliga javob bering.', '5. Теперь, пользуясь свойствами параллелограмма, ответьте на главный вопрос задачи.', '5. Now use the properties of a parallelogram to answer the main question.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Parallelogrammning bir burchagi 52°. Qolgan burchaklarini toping.', 'Один угол параллелограмма 52°. Найдите остальные углы.', 'One angle of a parallelogram is 52°. Find the other angles.'),
        s: L('∠A = 52°. Qarama-qarshi burchak ∠C = 52°. Qo‘shni burchak ∠B = 180° − 52° = 128°, va ∠D = ∠B = 128°. Tekshirish: 52 + 128 + 52 + 128 = 360°.', '∠A = 52°. Противоположный ∠C = 52°. Соседний ∠B = 180° − 52° = 128°, и ∠D = ∠B = 128°. Проверка: 52 + 128 + 52 + 128 = 360°.', '∠A = 52°. The opposite angle ∠C = 52°. The neighbouring angle ∠B = 180° − 52° = 128°, and ∠D = ∠B = 128°. Check: 52 + 128 + 52 + 128 = 360°.') },
      { q: L('Parallelogrammning perimetri 46 cm, bir tomoni ikkinchisidan 5 cm uzun. Tomonlarini toping.', 'Периметр параллелограмма 46 см, одна сторона на 5 см длиннее другой. Найдите стороны.', 'A parallelogram has perimeter 46 cm, and one side is 5 cm longer than the other. Find the sides.'),
        s: L('Tomonlar a va a + 5. P = 2(a + a + 5) = 46, ya’ni 2a + 5 = 23, a = 9. Tomonlar: 9 cm, 14 cm, 9 cm, 14 cm.', 'Стороны a и a + 5. P = 2(a + a + 5) = 46, то есть 2a + 5 = 23, a = 9. Стороны: 9 см, 14 см, 9 см, 14 см.', 'Let the sides be a and a + 5. P = 2(a + a + 5) = 46, so 2a + 5 = 23 and a = 9. Sides: 9 cm, 14 cm, 9 cm, 14 cm.') },
      { q: L('ABCD parallelogrammda A burchak bissektrisasi BC tomonni K nuqtada kesadi. BK = 7 cm, KC = 3 cm. Perimetrni toping.', 'В параллелограмме ABCD биссектриса угла A пересекает BC в точке K. BK = 7 см, KC = 3 см. Найдите периметр.', 'In parallelogram ABCD the bisector of angle A meets BC at K. BK = 7 cm, KC = 3 cm. Find the perimeter.'),
        s: L('∠BAK = ∠KAD (bissektrisa). BC ∥ AD bo‘lgani uchun ∠KAD = ∠BKA (ichki almashinuvchi). Demak, ∠BAK = ∠BKA, △ABK teng yonli, AB = BK = 7 cm. BC = 7 + 3 = 10 cm. P = 2(7 + 10) = 34 cm.', '∠BAK = ∠KAD (биссектриса). Так как BC ∥ AD, ∠KAD = ∠BKA (накрест лежащие). Значит, ∠BAK = ∠BKA, △ABK равнобедренный, AB = BK = 7 см. BC = 7 + 3 = 10 см. P = 2(7 + 10) = 34 см.', '∠BAK = ∠KAD (bisector). Since BC ∥ AD, ∠KAD = ∠BKA (alternate angles). So ∠BAK = ∠BKA, △ABK is isosceles and AB = BK = 7 cm. BC = 7 + 3 = 10 cm. P = 2(7 + 10) = 34 cm.') },
      { q: L('To‘rtburchakning diagonallari O nuqtada kesishadi, AO = 6, OC = 6, BO = 4, OD = 4. Bu parallelogrammmi?', 'Диагонали четырёхугольника пересекаются в точке O, AO = 6, OC = 6, BO = 4, OD = 4. Это параллелограмм?', 'The diagonals of a quadrilateral meet at O, with AO = 6, OC = 6, BO = 4, OD = 4. Is it a parallelogram?'),
        s: L('Ha. Har bir diagonal O nuqtada teng ikkiga bo‘lingan, bu 3-alomat. Demak, ABCD — parallelogramm, va endi AB = CD, ∠A = ∠C deb yozishimiz mumkin.', 'Да. Каждая диагональ делится точкой O пополам — это признак 3. Значит, ABCD — параллелограмм, и теперь можно писать AB = CD, ∠A = ∠C.', 'Yes. Each diagonal is bisected at O, which is test 3. So ABCD is a parallelogram, and we may now write AB = CD and ∠A = ∠C.') }
    ] },
    { kind: 'table', h: L('Xossa va alomat: farqi nimada?', 'Свойство и признак: в чём разница?', 'Property versus test'), table: {
      head: [L('Gap', 'Утверждение', 'Statement'), L('Xossa (ABCD — ▱ ⇒ …)', 'Свойство (ABCD — ▱ ⇒ …)', 'Property (ABCD is ▱ ⇒ …)'), L('Alomat (… ⇒ ▱)', 'Признак (… ⇒ ▱)', 'Test (… ⇒ ▱)')],
      rows: [
        [L('Qarama-qarshi tomonlar teng', 'Противоположные стороны равны', 'Opposite sides equal'), L('ha', 'да', 'yes'), L('ha', 'да', 'yes')],
        [L('Qarama-qarshi burchaklar teng', 'Противоположные углы равны', 'Opposite angles equal'), L('ha', 'да', 'yes'), L('ha', 'да', 'yes')],
        [L('Diagonallar teng ikkiga bo‘linadi', 'Диагонали делятся пополам', 'Diagonals bisect each other'), L('ha', 'да', 'yes'), L('ha', 'да', 'yes')],
        [L('Bir juft tomon teng va parallel', 'Пара сторон равна и параллельна', 'One pair equal and parallel'), L('ha', 'да', 'yes'), L('ha', 'да', 'yes')],
        [L('Diagonallar teng', 'Диагонали равны', 'Diagonals equal'), L('yo‘q (faqat to‘g‘ri to‘rtburchakda)', 'нет (только у прямоугольника)', 'no (only in a rectangle)'), L('yo‘q', 'нет', 'no')]
      ] }, after: [
      L('Xossadan foydalanish uchun avval shakl parallelogramm ekanini bilishimiz kerak; alomat esa aynan shuni isbotlash uchun xizmat qiladi.', 'Чтобы пользоваться свойством, нужно сначала знать, что фигура — параллелограмм; признак как раз служит для доказательства этого.', 'To use a property we must first know the figure is a parallelogram; a test is exactly what proves that.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Diagonallarni teng deb olish.</b> Oddiy parallelogrammda diagonallar teng emas, ular faqat bir-birini teng ikkiga bo‘ladi.', '<b>Считать диагонали равными.</b> В обычном параллелограмме диагонали не равны, они только делят друг друга пополам.', '<b>Assuming the diagonals are equal.</b> In a general parallelogram they are not; they only bisect each other.'),
      L('<b>Diagonal burchakni teng ikkiga bo‘ladi deyish.</b> Bu faqat rombda to‘g‘ri.', '<b>Говорить, что диагональ делит угол пополам.</b> Это верно только для ромба.', '<b>Saying a diagonal bisects an angle.</b> That is true only in a rhombus.'),
      L('<b>Qo‘shni burchaklarni teng deb yozish.</b> Qo‘shni burchaklar yig‘indisi 180°, teng esa qarama-qarshi burchaklar.', '<b>Писать, что соседние углы равны.</b> Соседние углы в сумме дают 180°, а равны противоположные.', '<b>Writing that neighbouring angles are equal.</b> Neighbouring angles add up to 180°; it is opposite angles that are equal.'),
      L('<b>Xossani alomat o‘rniga ishlatish.</b> Shakl parallelogramm ekani isbotlanmagan bo‘lsa, uning xossalariga tayanib bo‘lmaydi.', '<b>Использовать свойство вместо признака.</b> Пока не доказано, что фигура — параллелограмм, опираться на его свойства нельзя.', '<b>Using a property in place of a test.</b> Until you have proved the figure is a parallelogram, you cannot rely on its properties.'),
      L('<b>Balandlikni yon tomon bilan adashtirish.</b> Balandlik tomonga perpendikulyar; yon tomon esa odatda qiya.', '<b>Путать высоту с боковой стороной.</b> Высота перпендикулярна стороне, а боковая сторона обычно наклонная.', '<b>Confusing the height with a slanted side.</b> The height is perpendicular to the base; the side is usually slanted.')
    ] },
    { kind: 'life', h: L('Hayotda parallelogramm', 'Параллелограмм в жизни', 'Parallelograms in real life'), p: [
      L('<b>Ko‘tarish mexanizmlari.</b> Avtoservisdagi ko‘targich, yig‘iladigan zinapoya va qaychisimon platformalar sharnirli parallelogrammlar asosida ishlaydi. Tomonlar uzunligi o‘zgarmaydi, burchaklar esa o‘zgaradi, lekin qarama-qarshi tomonlar doim parallel qoladi. Shu sababli platforma yuqoriga ko‘tarilganda ham gorizontal holatda turadi.', '<b>Подъёмные механизмы.</b> Подъёмник в автосервисе, складная лестница и ножничные платформы работают на шарнирных параллелограммах. Длины сторон не меняются, меняются углы, но противоположные стороны всегда остаются параллельными. Поэтому платформа при подъёме остаётся горизонтальной.', '<b>Lifting mechanisms.</b> A car-service lift, a folding ladder and scissor platforms all work on hinged parallelograms. The side lengths stay the same while the angles change, yet opposite sides always stay parallel. That is why the platform stays level as it rises.'),
      L('<b>Stol lampasi</b> va chizmachilik pantografi ham shu printsipda: lampa boshchasi har qanday holatda bir xil yo‘nalishda qoladi. <b>Fizikada</b> ikki kuch yig‘indisi «parallelogramm qoidasi» bilan topiladi: kuchlar parallelogrammning ikki tomoni bo‘lsa, natijaviy kuch uning diagonali bo‘ladi.', '<b>Настольная лампа</b> и чертёжный пантограф устроены так же: головка лампы в любом положении смотрит в одну сторону. <b>В физике</b> сумму двух сил находят по «правилу параллелограмма»: если силы — две стороны параллелограмма, равнодействующая — его диагональ.', 'A <b>desk lamp</b> and a drawing pantograph work the same way: the lamp head keeps pointing in one direction whatever the position. <b>In physics</b>, two forces are added by the “parallelogram rule”: if the forces are two sides of a parallelogram, the resultant is its diagonal.'),
      L('<b>Qurilishda</b> ustalar ramka to‘g‘ri yig‘ilganini diagonallarni o‘lchab tekshiradi: agar qarama-qarshi tomonlar teng bo‘lsa, ramka kamida parallelogramm; diagonallar ham teng chiqsa — u to‘g‘ri to‘rtburchak.', '<b>На стройке</b> мастера проверяют раму, измеряя стороны и диагонали: если противоположные стороны равны, рама — по крайней мере параллелограмм; если ещё и диагонали равны — прямоугольник.', '<b>On building sites</b> workers check a frame by measuring: if opposite sides are equal, the frame is at least a parallelogram; if the diagonals are also equal, it is a rectangle.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Har qanday to‘rtburchak tomonlarining o‘rtalarini tutashtirsak, doim parallelogramm hosil bo‘ladi (Varinyon teoremasi). Buni keyingi mavzularda o‘rta chiziq yordamida isbotlaymiz.', 'Если соединить середины сторон любого четырёхугольника, всегда получится параллелограмм (теорема Вариньона). Мы докажем это позже с помощью средней линии.', 'Joining the midpoints of the sides of any quadrilateral always gives a parallelogram (Varignon’s theorem). We will prove this later using the midline.'),
      L('Parallelogrammda diagonallar kvadratlari yig‘indisi barcha tomonlar kvadratlari yig‘indisiga teng: d₁² + d₂² = 2(a² + b²).', 'В параллелограмме сумма квадратов диагоналей равна сумме квадратов всех сторон: d₁² + d₂² = 2(a² + b²).', 'In a parallelogram the squares of the diagonals add up to the squares of all four sides: d₁² + d₂² = 2(a² + b²).'),
      L('Diagonallar kesishish nuqtasi parallelogrammning simmetriya markazi: shaklni shu nuqta atrofida 180° ga aylantirsak, u o‘ziga ustma-ust tushadi.', 'Точка пересечения диагоналей — центр симметрии параллелограмма: при повороте на 180° вокруг неё фигура совпадает сама с собой.', 'The meeting point of the diagonals is the centre of symmetry: turning the figure 180° about it maps it onto itself.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. Parallelogrammning ikki burchagi ayirmasi 40°. Burchaklarini toping.', '1. Разность двух углов параллелограмма 40°. Найдите углы.', '1. Two angles of a parallelogram differ by 40°. Find the angles.'),
      L('2. Parallelogrammning diagonallari 10 cm va 16 cm. AO va BO nechaga teng?', '2. Диагонали параллелограмма 10 см и 16 см. Чему равны AO и BO?', '2. The diagonals of a parallelogram are 10 cm and 16 cm. What are AO and BO?'),
      L('3. Parallelogrammning tomonlari 3 : 5 nisbatda, perimetri 48 cm. Tomonlarini toping.', '3. Стороны параллелограмма относятся как 3 : 5, периметр 48 см. Найдите стороны.', '3. The sides of a parallelogram are in ratio 3 : 5 and the perimeter is 48 cm. Find the sides.')
    ], after: [
      L('Javoblar: 1) x + (x + 40) = 180, burchaklar 70°, 110°, 70°, 110°; 2) AO = 5 cm, BO = 8 cm; 3) yarim perimetr 24, bir qism 3, tomonlar 9 cm va 15 cm.', 'Ответы: 1) x + (x + 40) = 180, углы 70°, 110°, 70°, 110°; 2) AO = 5 см, BO = 8 см; 3) полупериметр 24, одна часть 3, стороны 9 см и 15 см.', 'Answers: 1) x + (x + 40) = 180, the angles are 70°, 110°, 70°, 110°; 2) AO = 5 cm, BO = 8 cm; 3) the half-perimeter is 24, one part is 3, sides 9 cm and 15 cm.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Parallelogramm — qarama-qarshi tomonlari juft-jufti bilan parallel to‘rtburchak.', 'Параллелограмм — четырёхугольник с попарно параллельными противоположными сторонами.', 'A parallelogram is a quadrilateral with both pairs of opposite sides parallel.'),
      L('Xossalar: qarama-qarshi tomonlar va burchaklar teng, qo‘shni burchaklar yig‘indisi 180°, diagonallar teng ikkiga bo‘linadi.', 'Свойства: противоположные стороны и углы равны, сумма соседних углов 180°, диагонали делятся пополам.', 'Properties: opposite sides and angles are equal, neighbouring angles add up to 180°, the diagonals bisect each other.'),
      L('Alomatlar: bir juft tomon teng va parallel; ikki juft tomon teng; diagonallar teng ikkiga bo‘linadi; qarama-qarshi burchaklar teng.', 'Признаки: пара сторон равна и параллельна; обе пары сторон равны; диагонали делятся пополам; противоположные углы равны.', 'Tests: one pair of sides equal and parallel; both pairs of sides equal; diagonals bisect each other; opposite angles equal.'),
      L('Isbotlarning asosi — diagonal o‘tkazib, teng uchburchaklar hosil qilish.', 'Основа доказательств — провести диагональ и получить равные треугольники.', 'The key to the proofs is drawing a diagonal to get congruent triangles.'),
      L('Perimetr P = 2(a + b); burchak bissektrisasi parallelogrammdan teng yonli uchburchak kesib oladi.', 'Периметр P = 2(a + b); биссектриса угла отсекает от параллелограмма равнобедренный треугольник.', 'The perimeter is P = 2(a + b); an angle bisector cuts off an isosceles triangle.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-2';

  // ---------- t3. To‘g‘ri to‘rtburchak, romb va kvadrat ----------
  T.add(P, 't3', { sections: [
    { kind: 'intro', h: L('Parallelogrammning uch «farzandi»', 'Три «потомка» параллелограмма', 'Three special parallelograms'), p: [
      L('Oldingi mavzuda parallelogrammni o‘rgandik. Endi unga qo‘shimcha shart qo‘shamiz va yangi, yanada «tartibli» shakllar hosil bo‘ladi. Agar barcha burchaklar to‘g‘ri bo‘lsa — <b>to‘g‘ri to‘rtburchak</b>; barcha tomonlar teng bo‘lsa — <b>romb</b>; ikkala shart ham bajarilsa — <b>kvadrat</b>.', 'В прошлой теме мы изучили параллелограмм. Теперь добавим к нему условие — и получим новые, более «правильные» фигуры. Если все углы прямые — <b>прямоугольник</b>; если все стороны равны — <b>ромб</b>; если выполнены оба условия — <b>квадрат</b>.', 'In the last topic we studied the parallelogram. Now we add one more condition and get new, more “orderly” figures. If all angles are right angles, it is a <b>rectangle</b>; if all sides are equal, a <b>rhombus</b>; if both conditions hold, a <b>square</b>.'),
      L('Muhim fikr: bu shakllarning hammasi parallelogramm, shuning uchun parallelogrammning barcha xossalari ularga ham tegishli. Ammo ularning har biri o‘ziga xos qo‘shimcha xossaga ega. To‘g‘ri to‘rtburchakda diagonallar teng, rombda diagonallar perpendikulyar va burchaklarni teng ikkiga bo‘ladi, kvadratda esa bularning hammasi birga keladi.', 'Важная мысль: все эти фигуры — параллелограммы, поэтому все свойства параллелограмма относятся и к ним. Но у каждой есть и особые свойства. У прямоугольника диагонали равны, у ромба диагонали перпендикулярны и делят углы пополам, а у квадрата всё это вместе.', 'Key idea: all of these figures are parallelograms, so every property of a parallelogram holds for them too. But each also has extra properties of its own. A rectangle has equal diagonals, a rhombus has perpendicular diagonals that bisect its angles, and a square has all of these together.'),
      L('Atrofimizga qarasak, bu shakllar hamma joyda: kitob, telefon ekrani, shaxmat taxtasi, deraza oynasi, olmos shaklidagi naqshlar. Ularni bir-biridan ajrata bilish va to‘g‘ri nomlash geometriyaning muhim ko‘nikmasi.', 'Посмотрите вокруг — эти фигуры повсюду: книга, экран телефона, шахматная доска, оконное стекло, узоры в форме ромба. Умение различать их и правильно называть — важный навык геометрии.', 'Look around — these figures are everywhere: a book, a phone screen, a chessboard, a window pane, diamond-shaped patterns. Telling them apart and naming them correctly is an important geometry skill.')
    ] },
    { kind: 'def', h: L('Ta’riflar', 'Определения', 'Definitions'), list: [
      L('<b>To‘g‘ri to‘rtburchak</b> — barcha burchaklari to‘g‘ri bo‘lgan parallelogramm. (Aslida bitta burchak 90° bo‘lsa yetarli: qolganlari ham avtomatik 90° bo‘ladi.)', '<b>Прямоугольник</b> — параллелограмм, у которого все углы прямые. (На самом деле достаточно одного прямого угла: остальные автоматически будут 90°.)', 'A <b>rectangle</b> is a parallelogram with all angles right angles. (In fact one right angle is enough: the others are then automatically 90°.)'),
      L('<b>Romb</b> — barcha tomonlari teng bo‘lgan parallelogramm. (Bu yerda ham ikki qo‘shni tomon teng bo‘lsa yetarli.)', '<b>Ромб</b> — параллелограмм, у которого все стороны равны. (И здесь достаточно, чтобы были равны две соседние стороны.)', 'A <b>rhombus</b> is a parallelogram with all sides equal. (Here too it is enough for two neighbouring sides to be equal.)'),
      L('<b>Kvadrat</b> — barcha tomonlari teng to‘g‘ri to‘rtburchak. Boshqacha aytganda, kvadrat — burchaklari to‘g‘ri bo‘lgan romb.', '<b>Квадрат</b> — прямоугольник, у которого все стороны равны. Иначе говоря, квадрат — ромб с прямыми углами.', 'A <b>square</b> is a rectangle with all sides equal. In other words, a square is a rhombus with right angles.')
    ], after: [
      L('Shakllar «oilasi» shunday: to‘rtburchak ⊃ parallelogramm ⊃ to‘g‘ri to‘rtburchak va romb ⊃ kvadrat. Har qanday kvadrat to‘g‘ri to‘rtburchak ham, romb ham hisoblanadi, lekin aksincha emas.', '«Семейство» фигур такое: четырёхугольник ⊃ параллелограмм ⊃ прямоугольник и ромб ⊃ квадрат. Любой квадрат — и прямоугольник, и ромб, но не наоборот.', 'The family tree is: quadrilateral ⊃ parallelogram ⊃ rectangle and rhombus ⊃ square. Every square is both a rectangle and a rhombus, but not the other way round.')
    ] },
    { kind: 'history', h: L('Tarixdan: misrliklar arqoni va Sharq naqshlari', 'Из истории: верёвка египтян и узоры Востока', 'History: Egyptian ropes and eastern patterns'), p: [
      L('Qadimgi Misrda Nil daryosi har yili toshib, dalalar chegarasini yuvib ketardi. Yer o‘lchovchilar — «arqon tortuvchilar» — chegaralarni qayta tiklash uchun to‘g‘ri burchak yasashlari kerak edi. Ular 12 ta teng bo‘lakka tugun bilan bo‘lingan arqondan 3, 4 va 5 bo‘lakli uchburchak tuzib, aniq to‘g‘ri burchak olishgan. Piramidalar asoslari ham deyarli mukammal kvadrat: Xeops piramidasi tomonlari bir-biridan bir necha santimetrgagina farq qiladi.', 'В Древнем Египте Нил ежегодно разливался и смывал границы полей. Землемеры — «натягиватели верёвки» — должны были строить прямые углы, чтобы восстановить границы. Верёвку, разделённую узлами на 12 равных частей, они складывали в треугольник со сторонами 3, 4 и 5 и получали точный прямой угол. Основания пирамид — почти идеальные квадраты: стороны пирамиды Хеопса отличаются лишь на несколько сантиметров.', 'In ancient Egypt the Nile flooded every year and washed away field boundaries. Surveyors — the “rope-stretchers” — had to make right angles to restore them. They took a rope knotted into 12 equal parts and formed a triangle with sides 3, 4 and 5, which gives an exact right angle. The bases of the pyramids are almost perfect squares: the sides of the Great Pyramid differ by only a few centimetres.'),
      L('Romb va kvadrat Sharq naqqoshligida eng sevimli shakllardan. Buxorodagi Ismoil Somoniy maqbarasining g‘ishtli devorlarida romb va kvadratlardan iborat naqshlar ko‘rinadi. Yevklid «Negizlar»ida kvadratni alohida ta’riflagan va to‘g‘ri to‘rtburchak yuzini tomonlar ko‘paytmasi orqali ifodalagan. «Romb» so‘zi esa yunoncha «aylanuvchi tepa» degan ma’noga ega.', 'Ромб и квадрат — любимые фигуры восточного орнамента. На кирпичных стенах мавзолея Исмаила Самани в Бухаре видны узоры из ромбов и квадратов. Евклид в «Началах» отдельно определил квадрат и выражал площадь прямоугольника через произведение сторон. Слово «ромб» происходит от греческого «вращающийся волчок».', 'The rhombus and the square are favourite shapes of eastern ornament. The brick walls of the Ismail Samani mausoleum in Bukhara show patterns of rhombuses and squares. In the Elements Euclid defined the square separately and expressed a rectangle’s area through the product of its sides. The word “rhombus” comes from a Greek word for a spinning top.')
    ] },
    { kind: 'rule', h: L('To‘g‘ri to‘rtburchakning xossasi va alomati', 'Свойство и признак прямоугольника', 'Rectangle: property and test'), p: [
      L('<b>Xossa.</b> To‘g‘ri to‘rtburchakning diagonallari teng: AC = BD.', '<b>Свойство.</b> Диагонали прямоугольника равны: AC = BD.', '<b>Property.</b> The diagonals of a rectangle are equal: AC = BD.'),
      L('<b>Isbot.</b> △ABD va △DCA to‘g‘ri burchakli uchburchaklarni qaraymiz. AB = DC (parallelogramm xossasi), AD — umumiy katet, ∠A = ∠D = 90°. Demak, uchburchaklar ikki katet bo‘yicha teng, va ularning gipotenuzalari ham teng: BD = AC.', '<b>Доказательство.</b> Рассмотрим прямоугольные треугольники △ABD и △DCA. AB = DC (свойство параллелограмма), AD — общий катет, ∠A = ∠D = 90°. Треугольники равны по двум катетам, значит, равны и гипотенузы: BD = AC.', '<b>Proof.</b> Look at the right triangles △ABD and △DCA. AB = DC (parallelogram property), AD is a common leg and ∠A = ∠D = 90°. The triangles are congruent by two legs, so their hypotenuses are equal: BD = AC.'),
      L('<b>Alomat.</b> Agar parallelogrammning diagonallari teng bo‘lsa, u to‘g‘ri to‘rtburchak. Isbot g‘oyasi xuddi shu uchburchaklar orqali: ular uch tomon bo‘yicha teng, demak ∠A = ∠D; lekin ∠A + ∠D = 180°, shuning uchun har biri 90°.', '<b>Признак.</b> Если диагонали параллелограмма равны, он — прямоугольник. Идея та же: треугольники равны по трём сторонам, значит ∠A = ∠D; но ∠A + ∠D = 180°, поэтому каждый равен 90°.', '<b>Test.</b> If a parallelogram has equal diagonals, it is a rectangle. The idea uses the same triangles: they are congruent by three sides, so ∠A = ∠D; but ∠A + ∠D = 180°, so each is 90°.'),
      L('Natija: to‘g‘ri to‘rtburchakda diagonallar kesishish nuqtasi O to‘rtta uchdan bir xil masofada yotadi: OA = OB = OC = OD.', 'Следствие: точка пересечения диагоналей прямоугольника O равноудалена от всех четырёх вершин: OA = OB = OC = OD.', 'Consequence: in a rectangle the meeting point O of the diagonals is the same distance from all four vertices: OA = OB = OC = OD.')
    ] },
    { kind: 'rule', h: L('Romb va kvadratning xossalari', 'Свойства ромба и квадрата', 'Rhombus and square properties'), p: [
      L('<b>Romb xossasi.</b> Rombning diagonallari o‘zaro perpendikulyar va uning burchaklarini teng ikkiga bo‘ladi.', '<b>Свойство ромба.</b> Диагонали ромба взаимно перпендикулярны и делят его углы пополам.', '<b>Rhombus property.</b> The diagonals of a rhombus are perpendicular and bisect its angles.'),
      L('<b>Isbot.</b> ABCD rombda AB = AD, O — diagonallar kesishish nuqtasi va BD ning o‘rtasi. △ABD teng yonli, AO esa uning medianasi. Teng yonli uchburchakda asosga o‘tkazilgan mediana ham balandlik, ham bissektrisa. Demak, AC ⊥ BD va ∠BAO = ∠DAO.', '<b>Доказательство.</b> В ромбе ABCD AB = AD, O — точка пересечения диагоналей и середина BD. △ABD равнобедренный, AO — его медиана. В равнобедренном треугольнике медиана к основанию является и высотой, и биссектрисой. Значит, AC ⊥ BD и ∠BAO = ∠DAO.', '<b>Proof.</b> In rhombus ABCD, AB = AD and O, where the diagonals meet, is the midpoint of BD. △ABD is isosceles and AO is its median. In an isosceles triangle the median to the base is also the height and the bisector. So AC ⊥ BD and ∠BAO = ∠DAO.'),
      L('<b>Romb alomatlari.</b> Agar parallelogrammning diagonallari perpendikulyar bo‘lsa yoki diagonal uning burchagini teng ikkiga bo‘lsa, u romb.', '<b>Признаки ромба.</b> Если диагонали параллелограмма перпендикулярны или диагональ делит его угол пополам, он — ромб.', '<b>Rhombus tests.</b> If a parallelogram’s diagonals are perpendicular, or a diagonal bisects one of its angles, it is a rhombus.'),
      L('<b>Kvadrat</b> ham to‘g‘ri to‘rtburchak, ham romb bo‘lgani uchun unda barcha xossalar bor: to‘rtta tomon teng, to‘rtta burchak 90°, diagonallar teng, perpendikulyar, kesishish nuqtasida teng ikkiga bo‘linadi va burchaklarni 45° li ikki qismga ajratadi.', '<b>Квадрат</b> — и прямоугольник, и ромб, поэтому у него все свойства: четыре равные стороны, четыре угла по 90°, диагонали равны, перпендикулярны, делятся пополам и делят углы на две части по 45°.', 'A <b>square</b> is both a rectangle and a rhombus, so it has every property: four equal sides, four 90° angles, and diagonals that are equal, perpendicular, bisect each other and split each angle into two 45° parts.')
    ] },
    { kind: 'steps', h: L('To‘rtburchak turini aniqlash algoritmi', 'Алгоритм определения вида четырёхугольника', 'Deciding which quadrilateral it is'), list: [
      L('1. Avval parallelogramm ekanini tekshiring (alomatlardan biri bilan).', '1. Сначала проверьте, что это параллелограмм (по одному из признаков).', '1. First check it is a parallelogram (using one of the tests).'),
      L('2. Burchak 90° mi yoki diagonallar tengmi? Ha bo‘lsa — to‘g‘ri to‘rtburchak.', '2. Есть угол 90° или равные диагонали? Если да — прямоугольник.', '2. Is there a 90° angle, or are the diagonals equal? If so, it is a rectangle.'),
      L('3. Qo‘shni tomonlar tengmi yoki diagonallar perpendikulyarmi? Ha bo‘lsa — romb.', '3. Соседние стороны равны или диагонали перпендикулярны? Если да — ромб.', '3. Are neighbouring sides equal, or are the diagonals perpendicular? If so, it is a rhombus.'),
      L('4. 2- va 3-qadam ikkalasi ham bajarilsa — kvadrat.', '4. Если выполнены и шаг 2, и шаг 3 — квадрат.', '4. If both step 2 and step 3 hold, it is a square.'),
      L('5. Eng aniq nomni tanlang: kvadratni shunchaki «parallelogramm» deyish xato emas, lekin to‘liq javob emas.', '5. Выберите самое точное название: назвать квадрат «параллелограммом» не ошибка, но ответ неполный.', '5. Give the most precise name: calling a square a “parallelogram” is not wrong, but it is not the full answer.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('To‘g‘ri to‘rtburchakning diagonali 14 cm, diagonallar orasidagi burchak 60°. Qisqa tomonini toping.', 'Диагональ прямоугольника 14 см, угол между диагоналями 60°. Найдите меньшую сторону.', 'A rectangle has a diagonal of 14 cm and the angle between the diagonals is 60°. Find the shorter side.'),
        s: L('OA = OB = 14 : 2 = 7 cm. △AOB da ∠AOB = 60° va OA = OB, demak qolgan ikki burchak ham (180° − 60°) : 2 = 60°. Uchburchak teng tomonli, AB = 7 cm. Bu 60° li burchak qarshisidagi tomon, ya’ni qisqa tomon: 7 cm.', 'OA = OB = 14 : 2 = 7 см. В △AOB ∠AOB = 60° и OA = OB, значит остальные углы (180° − 60°) : 2 = 60°. Треугольник равносторонний, AB = 7 см. Это меньшая сторона: 7 см.', 'OA = OB = 14 ÷ 2 = 7 cm. In △AOB, ∠AOB = 60° and OA = OB, so the other angles are (180° − 60°) ÷ 2 = 60°. The triangle is equilateral and AB = 7 cm. This is the shorter side: 7 cm.') },
      { q: L('Rombning bir burchagi 120°, qisqa diagonali 9 cm. Perimetrini toping.', 'Один угол ромба 120°, меньшая диагональ 9 см. Найдите периметр.', 'A rhombus has an angle of 120° and its shorter diagonal is 9 cm. Find its perimeter.'),
        s: L('Qo‘shni burchak 180° − 120° = 60°. Qisqa diagonal 120° li burchaklarni tutashtiradi va 60° li burchaklar qarshisida yotadi; u rombni ikkita uchburchakka bo‘ladi, har birida ikki tomon teng va ular orasidagi burchak 60°. Demak, uchburchaklar teng tomonli va tomon = 9 cm. P = 4 · 9 = 36 cm.', 'Соседний угол 180° − 120° = 60°. Меньшая диагональ делит ромб на два треугольника, в каждом две стороны равны и угол между ними 60°. Значит, треугольники равносторонние и сторона = 9 см. P = 4 · 9 = 36 см.', 'The neighbouring angle is 180° − 120° = 60°. The shorter diagonal splits the rhombus into two triangles, each with two equal sides and a 60° angle between them. So the triangles are equilateral and the side is 9 cm. P = 4 · 9 = 36 cm.') },
      { q: L('Rombning diagonali uning tomoni bilan 35° li burchak hosil qiladi. Rombning burchaklarini toping.', 'Диагональ ромба образует со стороной угол 35°. Найдите углы ромба.', 'A diagonal of a rhombus makes an angle of 35° with a side. Find the angles of the rhombus.'),
        s: L('Diagonal burchakni teng ikkiga bo‘ladi, demak bu burchak 2 · 35° = 70°. Qo‘shni burchak 180° − 70° = 110°. Burchaklar: 70°, 110°, 70°, 110°.', 'Диагональ делит угол пополам, значит этот угол 2 · 35° = 70°. Соседний 180° − 70° = 110°. Углы: 70°, 110°, 70°, 110°.', 'The diagonal bisects the angle, so that angle is 2 · 35° = 70°. The neighbouring angle is 180° − 70° = 110°. The angles are 70°, 110°, 70°, 110°.') },
      { q: L('Kvadratning diagonallari kesishish nuqtasidan tomonigacha masofa 5 cm. Perimetrni toping.', 'Расстояние от точки пересечения диагоналей квадрата до стороны 5 см. Найдите периметр.', 'The distance from the centre of a square to a side is 5 cm. Find the perimeter.'),
        s: L('Markazdan tomongacha perpendikulyar tomonning yarmiga teng (u tomonga parallel bo‘lgan o‘rta kesmaning yarmi). Tomon 10 cm, P = 40 cm.', 'Перпендикуляр от центра к стороне равен половине стороны. Сторона 10 см, P = 40 см.', 'The perpendicular from the centre to a side is half the side. So the side is 10 cm and P = 40 cm.') }
    ] },
    { kind: 'table', h: L('Xossalar jadvali', 'Таблица свойств', 'Properties at a glance'), table: {
      head: [L('Xossa', 'Свойство', 'Property'), L('Parallelogramm', 'Параллелограмм', 'Parallelogram'), L('To‘g‘ri to‘rtburchak', 'Прямоугольник', 'Rectangle'), L('Romb', 'Ромб', 'Rhombus'), L('Kvadrat', 'Квадрат', 'Square')],
      rows: [
        [L('Diagonallar teng ikkiga bo‘linadi', 'Диагонали делятся пополам', 'Diagonals bisect each other'), L('ha', 'да', 'yes'), L('ha', 'да', 'yes'), L('ha', 'да', 'yes'), L('ha', 'да', 'yes')],
        [L('Diagonallar teng', 'Диагонали равны', 'Diagonals equal'), L('yo‘q', 'нет', 'no'), L('ha', 'да', 'yes'), L('yo‘q', 'нет', 'no'), L('ha', 'да', 'yes')],
        [L('Diagonallar perpendikulyar', 'Диагонали перпендикулярны', 'Diagonals perpendicular'), L('yo‘q', 'нет', 'no'), L('yo‘q', 'нет', 'no'), L('ha', 'да', 'yes'), L('ha', 'да', 'yes')],
        [L('Diagonal burchakni teng bo‘ladi', 'Диагональ делит угол пополам', 'Diagonal bisects the angle'), L('yo‘q', 'нет', 'no'), L('yo‘q', 'нет', 'no'), L('ha', 'да', 'yes'), L('ha', 'да', 'yes')],
        [L('Barcha burchaklar 90°', 'Все углы 90°', 'All angles 90°'), L('yo‘q', 'нет', 'no'), L('ha', 'да', 'yes'), L('yo‘q', 'нет', 'no'), L('ha', 'да', 'yes')],
        [L('Barcha tomonlar teng', 'Все стороны равны', 'All sides equal'), L('yo‘q', 'нет', 'no'), L('yo‘q', 'нет', 'no'), L('ha', 'да', 'yes'), L('ha', 'да', 'yes')]
      ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>«Kvadrat to‘g‘ri to‘rtburchak emas».</b> Noto‘g‘ri: kvadrat to‘g‘ri to‘rtburchakning xususiy holi.', '<b>«Квадрат — не прямоугольник».</b> Неверно: квадрат — частный случай прямоугольника.', '<b>“A square is not a rectangle.”</b> Wrong: a square is a special rectangle.'),
      L('<b>Diagonallari teng har qanday to‘rtburchakni to‘g‘ri to‘rtburchak deyish.</b> Teng yonli trapetsiyada ham diagonallar teng. Avval parallelogramm ekanini isbotlash kerak.', '<b>Называть прямоугольником любой четырёхугольник с равными диагоналями.</b> У равнобедренной трапеции диагонали тоже равны. Сначала нужно доказать, что это параллелограмм.', '<b>Calling any quadrilateral with equal diagonals a rectangle.</b> An isosceles trapezium also has equal diagonals. First prove it is a parallelogram.'),
      L('<b>Diagonallari perpendikulyar har qanday to‘rtburchakni romb deyish.</b> «Varrak» (deltoid) shaklida ham diagonallar perpendikulyar, lekin u romb emas.', '<b>Называть ромбом любой четырёхугольник с перпендикулярными диагоналями.</b> У «воздушного змея» (дельтоида) диагонали тоже перпендикулярны, но это не ромб.', '<b>Calling any quadrilateral with perpendicular diagonals a rhombus.</b> A kite also has perpendicular diagonals but is not a rhombus.'),
      L('<b>Rombda diagonallar teng deb hisoblash.</b> Faqat kvadratda shunday.', '<b>Считать, что у ромба диагонали равны.</b> Так только у квадрата.', '<b>Assuming a rhombus has equal diagonals.</b> Only a square does.'),
      L('<b>Rombning tomoni va diagonalini adashtirish.</b> Chizmada har bir kesmani harf bilan belgilang.', '<b>Путать сторону ромба с диагональю.</b> Обозначайте на чертеже каждый отрезок буквами.', '<b>Mixing up a rhombus’s side and diagonal.</b> Label every segment with letters on your drawing.')
    ] },
    { kind: 'life', h: L('Hayotda', 'В жизни', 'In real life'), p: [
      L('<b>Duradgor va quruvchilar</b> deraza yoki eshik ramkasi to‘g‘ri to‘rtburchak ekanini burchakni o‘lchab emas, balki ikki diagonalni ruletka bilan o‘lchab tekshiradi: qarama-qarshi tomonlar teng va diagonallar teng bo‘lsa, burchaklar albatta 90°. Bu usul katta binolar poydevorini belgilashda ham qo‘llanadi.', '<b>Столяры и строители</b> проверяют, прямоугольная ли рама окна или двери, не транспортиром, а рулеткой по диагоналям: если противоположные стороны и диагонали равны, углы обязательно 90°. Так же размечают фундаменты больших зданий.', '<b>Carpenters and builders</b> check that a window or door frame is rectangular not with a protractor but by measuring both diagonals with a tape: if opposite sides are equal and the diagonals are equal, the angles must be 90°. Foundations of big buildings are marked out the same way.'),
      L('<b>Romb</b> shakli yo‘l belgilarida, karta o‘yinlaridagi «g‘ishtin» belgisida, metall to‘rlarda (setka-rabitsa) uchraydi. To‘r cho‘zilganda katakchalar rombligicha qoladi, faqat burchaklari o‘zgaradi — bu rombning tomonlari teng, burchaklari esa erkin ekanini ko‘rsatadi.', '<b>Ромб</b> встречается в дорожных знаках, в карточной масти «бубны», в сетке-рабице. Когда сетку растягивают, ячейки остаются ромбами, меняются только углы — у ромба стороны равны, а углы свободны.', 'The <b>rhombus</b> appears in road signs, the “diamonds” suit of playing cards and chain-link fencing. When the fence is stretched, its cells stay rhombuses and only the angles change — a rhombus has fixed equal sides but free angles.'),
      L('<b>Kvadrat</b> shaxmat taxtasi, plitkalar va kompyuter ekranining piksellari shakli. Raqamli tasvir millionlab mayda kvadratlardan tashkil topgan.', '<b>Квадрат</b> — форма шахматной доски, плитки и пикселей на экране. Цифровое изображение состоит из миллионов крошечных квадратов.', 'The <b>square</b> is the shape of a chessboard, floor tiles and the pixels on a screen. A digital image is made of millions of tiny squares.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Kvadrat — bir xil perimetrdagi barcha to‘g‘ri to‘rtburchaklar orasida yuzi eng katta bo‘lgani.', 'Квадрат имеет наибольшую площадь среди всех прямоугольников с данным периметром.', 'Among all rectangles with the same perimeter, the square has the largest area.'),
      L('Kvadratning 4 ta simmetriya o‘qi, rombning va to‘g‘ri to‘rtburchakning esa 2 tadan simmetriya o‘qi bor.', 'У квадрата 4 оси симметрии, у ромба и у прямоугольника — по 2.', 'A square has 4 lines of symmetry; a rhombus and a rectangle have 2 each.'),
      L('To‘g‘ri to‘rtburchak atrofida doim aylana chizish mumkin, romb ichiga esa doim aylana chizish mumkin. Kvadratda ikkalasi ham bor.', 'Около прямоугольника всегда можно описать окружность, а в ромб всегда можно вписать окружность. У квадрата есть обе.', 'A circle can always be drawn through the vertices of a rectangle, and a circle can always be drawn inside a rhombus touching all its sides. A square has both.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. To‘g‘ri to‘rtburchakning diagonali 12 cm. Diagonallar kesishish nuqtasidan uchlargacha masofa qancha?', '1. Диагональ прямоугольника 12 см. Каково расстояние от точки пересечения диагоналей до вершин?', '1. A rectangle’s diagonal is 12 cm. How far is the centre from each vertex?'),
      L('2. Rombning burchaklaridan biri boshqasidan 4 marta katta. Burchaklarini toping.', '2. Один угол ромба в 4 раза больше другого. Найдите углы.', '2. One angle of a rhombus is 4 times another. Find the angles.'),
      L('3. Diagonallari teng va perpendikulyar bo‘lgan parallelogramm qanday shakl?', '3. Какой фигурой является параллелограмм с равными и перпендикулярными диагоналями?', '3. What is a parallelogram whose diagonals are equal and perpendicular?')
    ], after: [
      L('Javoblar: 1) 6 cm; 2) x + 4x = 180°, 36° va 144°; 3) kvadrat.', 'Ответы: 1) 6 см; 2) x + 4x = 180°, 36° и 144°; 3) квадрат.', 'Answers: 1) 6 cm; 2) x + 4x = 180°, so 36° and 144°; 3) a square.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('To‘g‘ri to‘rtburchak, romb va kvadrat — parallelogrammning xususiy hollari; ularga parallelogramm xossalari ham tegishli.', 'Прямоугольник, ромб и квадрат — частные случаи параллелограмма; свойства параллелограмма верны и для них.', 'Rectangles, rhombuses and squares are special parallelograms, so all parallelogram properties apply to them.'),
      L('To‘g‘ri to‘rtburchak: barcha burchaklar 90°, diagonallar teng.', 'Прямоугольник: все углы 90°, диагонали равны.', 'Rectangle: all angles 90°, diagonals equal.'),
      L('Romb: barcha tomonlar teng, diagonallar perpendikulyar va burchaklarni teng ikkiga bo‘ladi.', 'Ромб: все стороны равны, диагонали перпендикулярны и делят углы пополам.', 'Rhombus: all sides equal, diagonals perpendicular and bisecting the angles.'),
      L('Kvadrat = to‘g‘ri to‘rtburchak va romb bir vaqtda: barcha xossalar birga.', 'Квадрат = одновременно прямоугольник и ромб: все свойства вместе.', 'Square = rectangle and rhombus at once: every property together.'),
      L('Alomatlar: diagonallari teng parallelogramm — to‘g‘ri to‘rtburchak; diagonallari perpendikulyar parallelogramm — romb.', 'Признаки: параллелограмм с равными диагоналями — прямоугольник; с перпендикулярными — ромб.', 'Tests: a parallelogram with equal diagonals is a rectangle; one with perpendicular diagonals is a rhombus.')
    ] }
  ] });

  // ---------- t4. Uchburchakning o‘rta chizig‘i ----------
  T.add(P, 't4', { sections: [
    { kind: 'intro', h: L('Ikki o‘rtani tutashtirsak…', 'Если соединить две середины…', 'Join two midpoints and…'), p: [
      L('Istalgan uchburchak chizing. Ikki tomonining o‘rtasini belgilang va ularni kesma bilan tutashtiring. Endi bu kesmani uchinchi tomon bilan solishtiring. Qanday uchburchak chizmang, natija bir xil: kesma uchinchi tomonga parallel va roppa-rosa uning yarmiga teng! Bu tasodif emas, balki geometriyaning eng foydali teoremalaridan biri.', 'Нарисуйте любой треугольник. Отметьте середины двух сторон и соедините их отрезком. Теперь сравните этот отрезок с третьей стороной. Какой бы треугольник вы ни нарисовали, результат один: отрезок параллелен третьей стороне и ровно в два раза короче её! Это не случайность, а одна из самых полезных теорем геометрии.', 'Draw any triangle. Mark the midpoints of two sides and join them with a segment. Now compare it with the third side. Whatever triangle you draw, the result is the same: the segment is parallel to the third side and exactly half as long! This is no accident but one of the most useful theorems in geometry.'),
      L('Bu kesma <b>uchburchakning o‘rta chizig‘i</b> deyiladi. Uning yordamida biz daryoning kengligini unga tushmasdan o‘lchashimiz, har qanday to‘rtburchak ichida parallelogramm topishimiz va keyinroq trapetsiya o‘rta chizig‘ini o‘rganishimiz mumkin bo‘ladi.', 'Этот отрезок называется <b>средней линией треугольника</b>. С её помощью можно измерить ширину реки, не переплывая её, найти параллелограмм внутри любого четырёхугольника, а позже — изучить среднюю линию трапеции.', 'This segment is called the <b>midline of the triangle</b>. With it we can measure the width of a river without crossing it, find a parallelogram inside any quadrilateral, and later study the midline of a trapezium.'),
      L('Isbotda oldingi mavzulardagi parallelogramm alomatlari ishlatiladi — demak, bu mavzu avval o‘rganganlarimizni bir joyga bog‘laydi.', 'В доказательстве используются признаки параллелограмма из предыдущих тем — эта тема связывает изученное воедино.', 'The proof uses the parallelogram tests from earlier topics, so this topic ties together what we have learned.')
    ] },
    { kind: 'def', h: L('O‘rta chiziq ta’rifi', 'Определение средней линии', 'Definition of the midline'), p: [
      L('<b>Uchburchakning o‘rta chizig‘i</b> — uning ikki tomoni o‘rtalarini tutashtiruvchi kesma. ABC uchburchakda M — AB ning o‘rtasi, N — BC ning o‘rtasi bo‘lsa, MN — o‘rta chiziq. U AC tomonga «qarshi» turadi; AC ni uning <b>asosi</b> deymiz.', '<b>Средняя линия треугольника</b> — отрезок, соединяющий середины двух его сторон. Если в △ABC M — середина AB, N — середина BC, то MN — средняя линия. Она «противостоит» стороне AC; AC называют её <b>основанием</b>.', 'A <b>midline of a triangle</b> is a segment joining the midpoints of two of its sides. If in △ABC M is the midpoint of AB and N is the midpoint of BC, then MN is a midline. It sits opposite side AC, which we call its <b>base</b>.'),
      L('Har bir uchburchakning <b>uchta</b> o‘rta chizig‘i bor: har bir juft tomon uchun bittadan. Ularni mediana bilan adashtirmang: mediana uchni qarama-qarshi tomon o‘rtasi bilan tutashtiradi, o‘rta chiziq esa ikki o‘rtani tutashtiradi va uchlarga tegmaydi.', 'У каждого треугольника <b>три</b> средние линии — по одной для каждой пары сторон. Не путайте её с медианой: медиана соединяет вершину с серединой противоположной стороны, а средняя линия соединяет две середины и вершин не касается.', 'Every triangle has <b>three</b> midlines, one for each pair of sides. Do not confuse a midline with a median: a median joins a vertex to the midpoint of the opposite side, while a midline joins two midpoints and does not touch any vertex.')
    ] },
    { kind: 'history', h: L('Tarixdan', 'Из истории', 'History'), p: [
      L('O‘rta chiziq g‘oyasi Yevklid «Negizlar»ida o‘xshash uchburchaklar va proporsiyalar haqidagi VI kitobda aniq ko‘rinadi: tomonlarni teng nisbatda bo‘luvchi to‘g‘ri chiziq uchinchi tomonga parallel bo‘ladi. Miloddan avvalgi VI asrda yashagan Fales esa parallel chiziqlar teng kesmalar ajratishini bilgan; o‘rta chiziq teoremasi Fales teoremasining eng sodda holi.', 'Идея средней линии ясно видна в VI книге «Начал» Евклида о подобии и пропорциях: прямая, делящая стороны в одном отношении, параллельна третьей стороне. А Фалес, живший в VI веке до н. э., знал, что параллельные прямые отсекают равные отрезки; теорема о средней линии — простейший случай теоремы Фалеса.', 'The idea of the midline is clear in Book VI of Euclid’s Elements, on similarity and proportion: a line dividing two sides in the same ratio is parallel to the third side. Thales, in the 6th century BC, knew that parallel lines cut off equal segments; the midline theorem is the simplest case of Thales’ theorem.'),
      L('XVIII asrda fransuz matematigi Per Varinyon har qanday to‘rtburchak tomonlari o‘rtalari parallelogramm hosil qilishini o‘rta chiziq yordamida isbotlagan. Bu teorema uning nomi bilan ataladi va hozir ham olimpiada masalalarida tez-tez uchraydi. Beruniy ham Yer o‘lchamlarini hisoblaganda proporsional kesmalar g‘oyasiga tayangan.', 'В XVIII веке французский математик Пьер Вариньон с помощью средней линии доказал, что середины сторон любого четырёхугольника образуют параллелограмм. Эта теорема носит его имя и часто встречается на олимпиадах. Беруни при вычислении размеров Земли тоже опирался на идею пропорциональных отрезков.', 'In the 18th century the French mathematician Pierre Varignon used the midline to prove that the midpoints of the sides of any quadrilateral form a parallelogram. The theorem bears his name and still appears often in olympiad problems. Al-Biruni, too, relied on proportional segments when he calculated the size of the Earth.')
    ] },
    { kind: 'rule', h: L('O‘rta chiziq haqidagi teorema', 'Теорема о средней линии', 'The midline theorem'), p: [
      L('<b>Teorema.</b> Uchburchakning o‘rta chizig‘i uchinchi tomonga parallel va uning yarmiga teng: <b>MN ∥ AC, MN = AC / 2</b>.', '<b>Теорема.</b> Средняя линия треугольника параллельна третьей стороне и равна её половине: <b>MN ∥ AC, MN = AC / 2</b>.', '<b>Theorem.</b> A midline of a triangle is parallel to the third side and half its length: <b>MN ∥ AC, MN = AC / 2</b>.'),
      L('<b>Isbot g‘oyasi.</b> MN kesmani N nuqtadan tashqariga uning o‘ziga teng masofaga davom ettiramiz va K nuqtani hosil qilamiz: NK = MN. △MBN va △KCN ni solishtiramiz: BN = NC (N — o‘rta), MN = NK (yasashga ko‘ra), ∠MNB = ∠KNC (vertikal burchaklar). Demak, uchburchaklar teng, bundan CK = BM = AM va ∠MBN = ∠KCN.', '<b>Идея доказательства.</b> Продолжим MN за точку N на такое же расстояние и получим точку K: NK = MN. Сравним △MBN и △KCN: BN = NC (N — середина), MN = NK (по построению), ∠MNB = ∠KNC (вертикальные). Треугольники равны, отсюда CK = BM = AM и ∠MBN = ∠KCN.', '<b>Proof idea.</b> Extend MN beyond N by its own length to a point K, so NK = MN. Compare △MBN and △KCN: BN = NC (N is the midpoint), MN = NK (by construction), ∠MNB = ∠KNC (vertical angles). The triangles are congruent, so CK = BM = AM and ∠MBN = ∠KCN.'),
      L('∠MBN = ∠KCN — ichki almashinuvchi burchaklar, demak CK ∥ AB, ya’ni CK ∥ AM. To‘rtburchak AMKC da AM va CK ham teng, ham parallel — u parallelogramm (1-alomat). Shuning uchun MK ∥ AC va MK = AC. Ammo MN = MK / 2, ya’ni MN = AC / 2. Teorema isbotlandi.', '∠MBN = ∠KCN — накрест лежащие, значит CK ∥ AB, то есть CK ∥ AM. В четырёхугольнике AMKC стороны AM и CK равны и параллельны — это параллелограмм (признак 1). Поэтому MK ∥ AC и MK = AC. Но MN = MK / 2, то есть MN = AC / 2. Теорема доказана.', '∠MBN = ∠KCN are alternate angles, so CK ∥ AB, i.e. CK ∥ AM. In quadrilateral AMKC the sides AM and CK are equal and parallel — it is a parallelogram (test 1). So MK ∥ AC and MK = AC. But MN = MK / 2, so MN = AC / 2. The theorem is proved.'),
      L('<b>Teskari tasdiq.</b> Agar to‘g‘ri chiziq uchburchak bir tomonining o‘rtasidan o‘tib, ikkinchi tomonga parallel bo‘lsa, u uchinchi tomonni ham teng ikkiga bo‘ladi.', '<b>Обратное утверждение.</b> Если прямая проходит через середину одной стороны треугольника параллельно другой, то она делит третью сторону пополам.', '<b>Converse.</b> If a line passes through the midpoint of one side of a triangle parallel to another side, it bisects the third side.')
    ] },
    { kind: 'rule', h: L('Teoremadan kelib chiqadigan natijalar', 'Следствия из теоремы', 'Consequences'), list: [
      L('Uchta o‘rta chiziq uchburchakni <b>4 ta teng uchburchakka</b> bo‘ladi; har biri asl uchburchakdan ikki marta kichik tomonlarga ega.', 'Три средние линии делят треугольник на <b>4 равных треугольника</b>; у каждого стороны вдвое меньше исходных.', 'The three midlines cut the triangle into <b>4 congruent triangles</b>, each with sides half the original.'),
      L('O‘rta chiziqlardan tuzilgan uchburchak perimetri asl perimetrning <b>yarmiga</b> teng.', 'Периметр треугольника из средних линий равен <b>половине</b> исходного периметра.', 'The triangle formed by the midlines has <b>half</b> the original perimeter.'),
      L('O‘rta chiziq uchburchakdan unga o‘xshash, tomonlari 2 marta kichik uchburchak kesib oladi.', 'Средняя линия отсекает треугольник, подобный исходному, со сторонами вдвое меньше.', 'A midline cuts off a triangle similar to the original with sides half as long.'),
      L('<b>Varinyon teoremasi:</b> istalgan to‘rtburchak tomonlari o‘rtalari parallelogramm uchlari bo‘ladi, uning tomonlari diagonallarga parallel va ularning yarmiga teng.', '<b>Теорема Вариньона:</b> середины сторон любого четырёхугольника — вершины параллелограмма, стороны которого параллельны диагоналям и равны их половинам.', '<b>Varignon’s theorem:</b> the midpoints of the sides of any quadrilateral are the vertices of a parallelogram whose sides are parallel to the diagonals and half as long.')
    ] },
    { kind: 'steps', h: L('O‘rta chiziq masalalarini yechish', 'Решение задач на среднюю линию', 'Solving midline problems'), list: [
      L('1. Chizmada tomonlar o‘rtalarini belgilang va qaysi kesma o‘rta chiziq ekanini aniqlang.', '1. Отметьте на чертеже середины сторон и определите, какой отрезок — средняя линия.', '1. Mark the midpoints on your drawing and decide which segment is a midline.'),
      L('2. Uning asosi — qaysi tomonga parallel ekanini toping (ikki o‘rtadan farqli, uchinchi tomon).', '2. Найдите её основание — сторону, которой она параллельна (третью, не содержащую середин).', '2. Find its base — the side it is parallel to (the third side, not containing the midpoints).'),
      L('3. Formulani qo‘llang: o‘rta chiziq = asos : 2 yoki asos = 2 · o‘rta chiziq.', '3. Примените формулу: средняя линия = основание : 2 или основание = 2 · средняя линия.', '3. Apply the formula: midline = base ÷ 2, or base = 2 · midline.'),
      L('4. Parallellikdan burchaklar tengligini chiqaring (mos yoki ichki almashinuvchi burchaklar).', '4. Из параллельности выведите равенство углов (соответственные или накрест лежащие).', '4. Use the parallel lines to find equal angles (corresponding or alternate).'),
      L('5. To‘rtburchak masalasida diagonal o‘tkazib, uni ikki uchburchakka ajrating.', '5. В задаче с четырёхугольником проведите диагональ и разбейте его на два треугольника.', '5. In a quadrilateral problem draw a diagonal to split it into two triangles.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Uchburchak tomonlari 8 cm, 10 cm va 14 cm. O‘rta chiziqlarini va ular hosil qilgan uchburchak perimetrini toping.', 'Стороны треугольника 8 см, 10 см и 14 см. Найдите средние линии и периметр треугольника, который они образуют.', 'A triangle has sides 8 cm, 10 cm and 14 cm. Find its midlines and the perimeter of the triangle they form.'),
        s: L('O‘rta chiziqlar tomonlarning yarmi: 4 cm, 5 cm, 7 cm. Perimetr 4 + 5 + 7 = 16 cm. Tekshirish: asl perimetr 32 cm, uning yarmi 16 cm.', 'Средние линии — половины сторон: 4 см, 5 см, 7 см. Периметр 4 + 5 + 7 = 16 см. Проверка: исходный периметр 32 см, его половина 16 см.', 'The midlines are half the sides: 4 cm, 5 cm, 7 cm. Perimeter 4 + 5 + 7 = 16 cm. Check: the original perimeter is 32 cm, and half of it is 16 cm.') },
      { q: L('Teng yonli uchburchakda asosga parallel o‘rta chiziq 6 cm, perimetr 40 cm. Yon tomonini toping.', 'В равнобедренном треугольнике средняя линия, параллельная основанию, 6 см, периметр 40 см. Найдите боковую сторону.', 'In an isosceles triangle the midline parallel to the base is 6 cm and the perimeter is 40 cm. Find a leg.'),
        s: L('Asos 2 · 6 = 12 cm. Yon tomonlar yig‘indisi 40 − 12 = 28 cm, har biri 14 cm.', 'Основание 2 · 6 = 12 см. Сумма боковых сторон 40 − 12 = 28 см, каждая 14 см.', 'The base is 2 · 6 = 12 cm. The legs add up to 40 − 12 = 28 cm, so each is 14 cm.') },
      { q: L('To‘rtburchak diagonallari 10 cm va 16 cm. Tomonlari o‘rtalarini ketma-ket tutashtirganda hosil bo‘lgan to‘rtburchak perimetrini toping.', 'Диагонали четырёхугольника 10 см и 16 см. Найдите периметр четырёхугольника, вершины которого — середины его сторон.', 'A quadrilateral has diagonals 10 cm and 16 cm. Find the perimeter of the quadrilateral whose vertices are the midpoints of its sides.'),
        s: L('Har bir tomoni tegishli uchburchakning o‘rta chizig‘i va diagonalning yarmiga teng. Ikki tomon 5 cm, ikki tomon 8 cm. P = 2(5 + 8) = 26 cm — diagonallar yig‘indisiga teng.', 'Каждая сторона — средняя линия соответствующего треугольника и равна половине диагонали. Две стороны по 5 см, две по 8 см. P = 2(5 + 8) = 26 см — сумма диагоналей.', 'Each side is a midline of a triangle and equals half a diagonal. Two sides are 5 cm and two are 8 cm. P = 2(5 + 8) = 26 cm — the sum of the diagonals.') },
      { q: L('ABC uchburchakda MN — o‘rta chiziq (M ∈ AB, N ∈ BC), ∠A = 65°. ∠BMN ni toping.', 'В △ABC MN — средняя линия (M ∈ AB, N ∈ BC), ∠A = 65°. Найдите ∠BMN.', 'In △ABC, MN is a midline (M on AB, N on BC) and ∠A = 65°. Find ∠BMN.'),
        s: L('MN ∥ AC, AB — kesuvchi. ∠BMN va ∠BAC — mos burchaklar, demak ∠BMN = 65°.', 'MN ∥ AC, AB — секущая. ∠BMN и ∠BAC — соответственные, значит ∠BMN = 65°.', 'MN ∥ AC and AB is a transversal. ∠BMN and ∠BAC are corresponding angles, so ∠BMN = 65°.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>O‘rta chiziqni mediana bilan adashtirish.</b> Mediana uchdan chiqadi; o‘rta chiziq esa ikki tomon o‘rtasini tutashtiradi.', '<b>Путать среднюю линию с медианой.</b> Медиана выходит из вершины; средняя линия соединяет середины двух сторон.', '<b>Confusing a midline with a median.</b> A median starts at a vertex; a midline joins two midpoints.'),
      L('<b>Noto‘g‘ri asos tanlash.</b> O‘rta chiziq u tutashtirgan tomonlarning hech biriga emas, faqat uchinchi tomonga parallel.', '<b>Выбирать не то основание.</b> Средняя линия параллельна не тем сторонам, середины которых соединяет, а третьей.', '<b>Picking the wrong base.</b> The midline is parallel not to the sides whose midpoints it joins but to the third side.'),
      L('<b>2 ga ko‘paytirish o‘rniga bo‘lish.</b> Asos o‘rta chiziqdan ikki marta uzun, aksincha emas.', '<b>Делить вместо умножать на 2.</b> Основание вдвое длиннее средней линии, а не наоборот.', '<b>Dividing instead of multiplying by 2.</b> The base is twice the midline, not the other way round.'),
      L('<b>Kesma o‘rtalarni tutashtirmasa ham uni o‘rta chiziq deyish.</b> Agar nuqta faqat «taxminan» o‘rtada bo‘lsa, teorema ishlamaydi — shartni tekshiring.', '<b>Называть средней линией отрезок, не соединяющий середины.</b> Если точка лишь «примерно» посередине, теорема не работает — проверяйте условие.', '<b>Calling a segment a midline when it does not join midpoints.</b> If a point is only “roughly” in the middle, the theorem does not apply — check the conditions.'),
      L('<b>Perimetr va yuzni adashtirish.</b> O‘rta chiziqlar uchburchagi perimetri asl perimetrning yarmi, lekin uning yuzi asl yuzning yarmi emas, balki to‘rtdan biri, chunki uchburchak 4 ta teng bo‘lakka bo‘linadi.', '<b>Путать периметр и площадь.</b> Периметр треугольника из средних линий — половина исходного, но его площадь — не половина, а четверть исходной, ведь треугольник делится на 4 равные части.', '<b>Mixing up perimeter and area.</b> The midline triangle has half the original perimeter, but its area is not half — it is a quarter, because the triangle is split into 4 equal pieces.')
    ] },
    { kind: 'life', h: L('Hayotda o‘rta chiziq', 'Средняя линия в жизни', 'The midline in real life'), p: [
      L('<b>Ko‘l yoki botqoqlik kengligini o‘lchash.</b> Ko‘lning ikki chetidagi A va C nuqtalar orasidagi masofani to‘g‘ridan-to‘g‘ri o‘lchab bo‘lmaydi. Quruqlikda biror B nuqta tanlanadi, BA va BC kesmalarning o‘rtalari M va N topiladi. MN ni o‘lchab, uni 2 ga ko‘paytirsak, AC topiladi. Yer o‘lchovchilar va harbiy topograflar bu usulni asrlar davomida qo‘llab kelgan.', '<b>Измерение ширины озера или болота.</b> Расстояние между точками A и C на разных берегах напрямую не измерить. На суше выбирают точку B, находят середины M и N отрезков BA и BC. Измерив MN и умножив на 2, получают AC. Землемеры и топографы пользовались этим способом веками.', '<b>Measuring across a lake or marsh.</b> You cannot measure directly between points A and C on opposite shores. Choose a point B on dry land, find the midpoints M and N of BA and BC, measure MN and double it to get AC. Surveyors and map-makers have used this method for centuries.'),
      L('<b>Tom va ko‘priklar.</b> Uchburchak shaklidagi tom fermalarida yon tomonlar o‘rtalarini tutashtiruvchi gorizontal to‘sin qo‘yiladi. Uning uzunligi asosning aniq yarmi bo‘lgani uchun ustalar materialni oldindan hisoblab qo‘yadi.', '<b>Крыши и мосты.</b> В треугольных стропильных фермах ставят горизонтальную балку, соединяющую середины боковых сторон. Её длина ровно половина основания, поэтому мастера заранее рассчитывают материал.', '<b>Roofs and bridges.</b> Triangular roof trusses often have a horizontal beam joining the midpoints of the sloping sides. Its length is exactly half the base, so builders can work out the material in advance.'),
      L('<b>Kompyuter grafikasi</b>da Serpinskiy uchburchagi o‘rta chiziqlar yordamida chiziladi: uchburchakni 4 ga bo‘lib, o‘rtadagisini olib tashlash qayta-qayta takrorlanadi.', 'В <b>компьютерной графике</b> треугольник Серпинского строят с помощью средних линий: делят треугольник на 4 части, убирают среднюю — и повторяют снова и снова.', 'In <b>computer graphics</b> the Sierpiński triangle is drawn using midlines: split a triangle into 4, remove the middle one, and repeat again and again.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Serpinskiy uchburchagida har qadamda yuzning to‘rtdan biri olib tashlanadi; cheksiz qadamdan so‘ng yuz nolga intiladi, perimetr esa cheksiz o‘sadi!', 'В треугольнике Серпинского на каждом шаге убирают четверть площади; после бесконечного числа шагов площадь стремится к нулю, а периметр растёт бесконечно!', 'In the Sierpiński triangle a quarter of the area is removed at each step; after infinitely many steps the area tends to zero while the perimeter grows without limit!'),
      L('O‘rta chiziqlar uchburchagi medianalari asl uchburchak medianalari bilan bir nuqtada kesishadi.', 'Медианы треугольника из средних линий пересекаются в той же точке, что и медианы исходного.', 'The medians of the midline triangle meet at the same point as the medians of the original triangle.'),
      L('Rombning tomonlari o‘rtalari to‘g‘ri to‘rtburchak, to‘g‘ri to‘rtburchakniki esa romb hosil qiladi.', 'Середины сторон ромба образуют прямоугольник, а прямоугольника — ромб.', 'The midpoints of a rhombus’s sides form a rectangle, and those of a rectangle form a rhombus.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. Teng tomonli uchburchak perimetri 36 cm. O‘rta chizig‘i nechaga teng?', '1. Периметр равностороннего треугольника 36 см. Чему равна средняя линия?', '1. An equilateral triangle has perimeter 36 cm. How long is a midline?'),
      L('2. O‘rta chiziqlar uchburchagi perimetri 15 cm. Asl uchburchak perimetri qancha?', '2. Периметр треугольника из средних линий 15 см. Каков периметр исходного?', '2. The midline triangle has perimeter 15 cm. What is the original perimeter?'),
      L('3. To‘g‘ri to‘rtburchak diagonali 9 cm. Tomonlari o‘rtalaridan hosil bo‘lgan romb perimetri qancha?', '3. Диагональ прямоугольника 9 см. Каков периметр ромба из середин его сторон?', '3. A rectangle has diagonal 9 cm. What is the perimeter of the rhombus formed by the midpoints of its sides?')
    ], after: [
      L('Javoblar: 1) tomon 12 cm, o‘rta chiziq 6 cm; 2) 30 cm; 3) har bir tomon 4,5 cm, P = 18 cm.', 'Ответы: 1) сторона 12 см, средняя линия 6 см; 2) 30 см; 3) каждая сторона 4,5 см, P = 18 см.', 'Answers: 1) the side is 12 cm, the midline 6 cm; 2) 30 cm; 3) each side is 4.5 cm, P = 18 cm.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('O‘rta chiziq — uchburchak ikki tomoni o‘rtalarini tutashtiruvchi kesma; har bir uchburchakda ular 3 ta.', 'Средняя линия — отрезок, соединяющий середины двух сторон; в каждом треугольнике их 3.', 'A midline joins the midpoints of two sides; every triangle has 3.'),
      L('O‘rta chiziq uchinchi tomonga parallel va uning yarmiga teng.', 'Средняя линия параллельна третьей стороне и равна её половине.', 'A midline is parallel to the third side and half as long.'),
      L('Isbot: kesmani davom ettirib, parallelogramm hosil qilish.', 'Доказательство: продлить отрезок и получить параллелограмм.', 'Proof: extend the segment to build a parallelogram.'),
      L('Uchta o‘rta chiziq uchburchakni 4 ta teng uchburchakka bo‘ladi, perimetri ikki marta kichik.', 'Три средние линии делят треугольник на 4 равных, периметр вдвое меньше.', 'The three midlines split the triangle into 4 congruent pieces, with half the perimeter.'),
      L('To‘rtburchak tomonlari o‘rtalari doim parallelogramm hosil qiladi (Varinyon).', 'Середины сторон четырёхугольника всегда образуют параллелограмм (Вариньон).', 'The midpoints of a quadrilateral’s sides always form a parallelogram (Varignon).')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-2';

  // ---------- t5. Trapetsiya va uning o‘rta chizig‘i ----------
  T.add(P, 't5', { sections: [
    { kind: 'intro', h: L('Faqat bir juft parallel tomon', 'Только одна пара параллельных сторон', 'Only one pair of parallel sides'), p: [
      L('Paqir yon tomondan qaraganda, stol chirog‘ining abajuri, ko‘prik tayanchi, Misr piramidasining kesimi — ularning hammasi bir xil shaklga ega: ikki tomoni parallel, qolgan ikkitasi esa parallel emas. Bunday to‘rtburchak <b>trapetsiya</b> deb ataladi. Parallelogrammdan farqli o‘laroq, trapetsiya tomonlari «nosimmetrik» bo‘lishi mumkin, lekin u ham o‘ziga xos chiroyli qonunlarga bo‘ysunadi.', 'Ведро сбоку, абажур настольной лампы, опора моста, сечение египетской пирамиды — все они одной формы: две стороны параллельны, а две другие — нет. Такой четырёхугольник называется <b>трапецией</b>. В отличие от параллелограмма, трапеция может быть «несимметричной», но и она подчиняется своим красивым законам.', 'A bucket seen from the side, a lampshade, a bridge support, the cross-section of an Egyptian pyramid — all share one shape: two sides are parallel and the other two are not. Such a quadrilateral is called a <b>trapezium</b> (in American English, a trapezoid). Unlike a parallelogram it can look lopsided, yet it obeys its own elegant laws.'),
      L('Bu mavzuda trapetsiya elementlari, uning turlari (teng yonli va to‘g‘ri burchakli), teng yonli trapetsiya xossalari va eng muhimi — <b>trapetsiyaning o‘rta chizig‘i</b> haqida gaplashamiz. O‘rta chiziq asoslarning o‘rta arifmetigiga teng: m = (a + b)/2. Bu formula keyinroq trapetsiya yuzini topishda asosiy rol o‘ynaydi.', 'В этой теме поговорим об элементах трапеции, её видах (равнобедренная и прямоугольная), свойствах равнобедренной трапеции и, главное, о <b>средней линии трапеции</b>. Средняя линия равна среднему арифметическому оснований: m = (a + b)/2. Эта формула потом станет ключевой для площади трапеции.', 'In this topic we look at the parts of a trapezium, its types (isosceles and right-angled), the properties of an isosceles trapezium and, most importantly, the <b>midline of a trapezium</b>. The midline equals the average of the bases: m = (a + b)/2. This formula will later be the key to the area of a trapezium.')
    ] },
    { kind: 'def', h: L('Ta’rif va elementlar', 'Определение и элементы', 'Definition and parts'), p: [
      L('<b>Trapetsiya</b> — ikki tomoni parallel, qolgan ikki tomoni parallel bo‘lmagan to‘rtburchak. Parallel tomonlar <b>asoslar</b> (a — katta asos, b — kichik asos), parallel bo‘lmaganlari esa <b>yon tomonlar</b> deyiladi. Asoslar orasidagi masofa — <b>balandlik</b> h.', '<b>Трапеция</b> — четырёхугольник, у которого две стороны параллельны, а две другие не параллельны. Параллельные стороны — <b>основания</b> (a — большее, b — меньшее), непараллельные — <b>боковые стороны</b>. Расстояние между основаниями — <b>высота</b> h.', 'A <b>trapezium</b> is a quadrilateral with two parallel sides and two non-parallel sides. The parallel sides are the <b>bases</b> (a the longer, b the shorter); the others are the <b>legs</b>. The distance between the bases is the <b>height</b> h.')
    ], list: [
      L('<b>Teng yonli trapetsiya</b> — yon tomonlari teng trapetsiya.', '<b>Равнобедренная трапеция</b> — трапеция с равными боковыми сторонами.', 'An <b>isosceles trapezium</b> has equal legs.'),
      L('<b>To‘g‘ri burchakli trapetsiya</b> — bir yon tomoni asoslarga perpendikulyar trapetsiya; bu yon tomon balandlikka teng.', '<b>Прямоугольная трапеция</b> — одна боковая сторона перпендикулярна основаниям; эта сторона равна высоте.', 'A <b>right trapezium</b> has one leg perpendicular to the bases; that leg equals the height.'),
      L('<b>O‘rta chiziq</b> — yon tomonlar o‘rtalarini tutashtiruvchi kesma.', '<b>Средняя линия</b> — отрезок, соединяющий середины боковых сторон.', 'The <b>midline</b> is the segment joining the midpoints of the legs.')
    ], after: [
      L('Har bir yon tomonga yopishgan ikki burchak yig‘indisi 180°: ular parallel asoslar va kesuvchi hosil qilgan ichki bir tomonli burchaklar.', 'Сумма двух углов, прилежащих к боковой стороне, равна 180°: это односторонние углы при параллельных основаниях и секущей.', 'The two angles along each leg add up to 180°: they are co-interior angles between the parallel bases.')
    ] },
    { kind: 'history', h: L('Tarixdan: Misr va Bobil yer o‘lchovchilari', 'Из истории: землемеры Египта и Вавилона', 'History: surveyors of Egypt and Babylon'), p: [
      L('Trapetsiya shaklidagi yer uchastkalari bilan qadimgi Misr va Bobil hisobchilari ko‘p ishlagan. Bobil loy taxtachalarida trapetsiya shaklidagi dalani parallel chiziqlar bilan teng bo‘laklarga bo‘lish masalalari saqlanib qolgan. Moskva matematik papirusida (taxminan miloddan avvalgi 1850-yil) kesik piramida hajmi hisoblangan — uning yon yoqlari aynan trapetsiyalardir.', 'С участками в форме трапеции много работали писцы Древнего Египта и Вавилона. На вавилонских глиняных табличках сохранились задачи о делении трапециевидного поля параллельными линиями на равные части. В Московском математическом папирусе (около 1850 г. до н. э.) вычислен объём усечённой пирамиды — её боковые грани именно трапеции.', 'Scribes in ancient Egypt and Babylon worked a lot with fields shaped like trapezia. Babylonian clay tablets contain problems about dividing a trapezium-shaped field into equal parts by parallel lines. The Moscow Mathematical Papyrus (about 1850 BC) computes the volume of a truncated pyramid, whose side faces are exactly trapezia.'),
      L('«Trapetsiya» so‘zi yunoncha «trapezion» — «kichik stol» so‘zidan olingan. Yevklid bu atamani hozirgidan kengroq ma’noda ishlatgan, aniq ta’rifni esa keyinroq Prokl bergan. O‘rta Osiyo me’morlari gumbaz ostidagi o‘tish qismlarini va peshtoq bezaklarini trapetsiya shaklidagi bo‘laklardan yig‘ishgan.', 'Слово «трапеция» происходит от греческого «трапезион» — «столик». Евклид употреблял этот термин шире, чем мы, а точное определение позже дал Прокл. Зодчие Средней Азии собирали переходы под куполами и украшения порталов из трапециевидных деталей.', 'The word “trapezium” comes from the Greek trapezion, “little table”. Euclid used the term more loosely than we do; Proclus later gave the precise definition. Central Asian architects built the transitions beneath domes and the decoration of portals from trapezium-shaped pieces.')
    ] },
    { kind: 'rule', h: L('Teng yonli trapetsiya xossalari', 'Свойства равнобедренной трапеции', 'Properties of an isosceles trapezium'), list: [
      L('Asosdagi burchaklar teng: ∠A = ∠D va ∠B = ∠C.', 'Углы при основании равны: ∠A = ∠D и ∠B = ∠C.', 'The base angles are equal: ∠A = ∠D and ∠B = ∠C.'),
      L('Diagonallar teng: AC = BD.', 'Диагонали равны: AC = BD.', 'The diagonals are equal: AC = BD.'),
      L('Kichik asos uchlaridan tushirilgan balandliklar katta asosdan teng kesmalar ajratadi: har biri (a − b)/2.', 'Высоты из концов меньшего основания отсекают от большего равные отрезки: по (a − b)/2.', 'The heights dropped from the ends of the shorter base cut off equal pieces of the longer base, each (a − b)/2.'),
      L('Asoslar o‘rtalari orqali o‘tuvchi to‘g‘ri chiziq — simmetriya o‘qi.', 'Прямая через середины оснований — ось симметрии.', 'The line through the midpoints of the bases is a line of symmetry.')
    ], after: [
      L('<b>Isbot g‘oyasi.</b> B va C dan BH va CK balandliklarni tushiramiz. To‘g‘ri burchakli △ABH va △DCK da AB = DC (gipotenuzalar) va BH = CK (katetlar). Ular teng, demak ∠A = ∠D va AH = KD. Diagonallar tengligi △ABD = △DCA dan kelib chiqadi (ikki tomon va ular orasidagi burchak).', '<b>Идея доказательства.</b> Опустим высоты BH и CK. В прямоугольных △ABH и △DCK AB = DC (гипотенузы) и BH = CK (катеты). Они равны, значит ∠A = ∠D и AH = KD. Равенство диагоналей следует из △ABD = △DCA (по двум сторонам и углу между ними).', '<b>Proof idea.</b> Drop heights BH and CK. In right triangles △ABH and △DCK, AB = DC (hypotenuses) and BH = CK (legs). They are congruent, so ∠A = ∠D and AH = KD. Equal diagonals follow from △ABD ≅ △DCA (two sides and the included angle).'),
      L('Teskari tasdiqlar ham to‘g‘ri: asosdagi burchaklari teng yoki diagonallari teng trapetsiya teng yonli.', 'Верны и обратные утверждения: трапеция с равными углами при основании или равными диагоналями — равнобедренная.', 'The converses are also true: a trapezium with equal base angles or equal diagonals is isosceles.')
    ] },
    { kind: 'rule', h: L('Trapetsiya o‘rta chizig‘i haqidagi teorema', 'Теорема о средней линии трапеции', 'The trapezium midline theorem'), p: [
      L('<b>Teorema.</b> Trapetsiyaning o‘rta chizig‘i asoslarga parallel va ularning yarim yig‘indisiga teng: <b>m = (a + b) / 2</b>.', '<b>Теорема.</b> Средняя линия трапеции параллельна основаниям и равна их полусумме: <b>m = (a + b) / 2</b>.', '<b>Theorem.</b> The midline of a trapezium is parallel to the bases and equals half their sum: <b>m = (a + b) / 2</b>.'),
      L('<b>Isbot g‘oyasi.</b> ABCD trapetsiyada (AD ∥ BC) M — AB ning, N — CD ning o‘rtasi. B va N orqali to‘g‘ri chiziq o‘tkazib, uni AD ning davomi bilan K nuqtada kesishtiramiz. △BCN va △KDN teng: CN = ND, ∠BNC = ∠KND (vertikal), ∠BCN = ∠KDN (ichki almashinuvchi). Demak, BN = NK va DK = BC = b.', '<b>Идея доказательства.</b> В трапеции ABCD (AD ∥ BC) M — середина AB, N — середина CD. Проведём прямую BN до пересечения с продолжением AD в точке K. △BCN = △KDN: CN = ND, ∠BNC = ∠KND (вертикальные), ∠BCN = ∠KDN (накрест лежащие). Значит, BN = NK и DK = BC = b.', '<b>Proof idea.</b> In trapezium ABCD (AD ∥ BC) let M be the midpoint of AB and N the midpoint of CD. Draw line BN to meet the extension of AD at K. △BCN ≅ △KDN: CN = ND, ∠BNC = ∠KND (vertical), ∠BCN = ∠KDN (alternate). So BN = NK and DK = BC = b.'),
      L('Endi △ABK da M — AB ning, N — BK ning o‘rtasi, demak MN — uchburchakning o‘rta chizig‘i. Shuning uchun MN ∥ AK va MN = AK / 2 = (AD + DK) / 2 = (a + b) / 2. Ko‘rib turibsizki, trapetsiya teoremasi uchburchak teoremasiga keltirildi.', 'Теперь в △ABK M — середина AB, N — середина BK, значит MN — средняя линия треугольника. Поэтому MN ∥ AK и MN = AK / 2 = (AD + DK) / 2 = (a + b) / 2. Теорема о трапеции сведена к теореме о треугольнике.', 'Now in △ABK, M is the midpoint of AB and N the midpoint of BK, so MN is a midline of the triangle. Hence MN ∥ AK and MN = AK / 2 = (AD + DK) / 2 = (a + b) / 2. The trapezium theorem has been reduced to the triangle one.')
    ] },
    { kind: 'steps', h: L('Trapetsiya masalasini yechish tartibi', 'Порядок решения задач на трапецию', 'How to tackle a trapezium problem'), list: [
      L('1. Asoslarni va yon tomonlarni aniq belgilang; qaysi tomonlar parallel ekanini yozing.', '1. Чётко обозначьте основания и боковые стороны; запишите, какие стороны параллельны.', '1. Label the bases and legs clearly; write down which sides are parallel.'),
      L('2. Kichik asos uchlaridan balandliklar tushiring: trapetsiya to‘g‘ri to‘rtburchak va ikki to‘g‘ri burchakli uchburchakka bo‘linadi.', '2. Опустите высоты из концов меньшего основания: трапеция разобьётся на прямоугольник и два прямоугольных треугольника.', '2. Drop heights from the ends of the shorter base: the trapezium splits into a rectangle and two right triangles.'),
      L('3. Teng yonli bo‘lsa, katta asosdan ajralgan bo‘laklar (a − b)/2 ekanini ishlating.', '3. Если трапеция равнобедренная, используйте, что отсекаемые отрезки равны (a − b)/2.', '3. If it is isosceles, use the fact that the cut-off pieces are (a − b)/2.'),
      L('4. Yon tomondagi burchaklar yig‘indisi 180° ekanini unutmang.', '4. Не забывайте, что углы при боковой стороне в сумме дают 180°.', '4. Remember that the angles along a leg add up to 180°.'),
      L('5. O‘rta chiziq so‘ralsa, m = (a + b)/2; noma’lum asos so‘ralsa, a = 2m − b.', '5. Если спрашивают среднюю линию — m = (a + b)/2; если неизвестно основание — a = 2m − b.', '5. For the midline use m = (a + b)/2; for an unknown base use a = 2m − b.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Trapetsiya asoslari 7 cm va 15 cm. O‘rta chiziqni toping.', 'Основания трапеции 7 см и 15 см. Найдите среднюю линию.', 'A trapezium has bases 7 cm and 15 cm. Find the midline.'),
        s: L('m = (7 + 15) : 2 = 22 : 2 = 11 cm.', 'm = (7 + 15) : 2 = 22 : 2 = 11 см.', 'm = (7 + 15) ÷ 2 = 22 ÷ 2 = 11 cm.') },
      { q: L('Trapetsiya o‘rta chizig‘i 12 cm, asoslardan biri 9 cm. Ikkinchi asosni toping.', 'Средняя линия трапеции 12 см, одно основание 9 см. Найдите другое.', 'A trapezium’s midline is 12 cm and one base is 9 cm. Find the other base.'),
        s: L('a + b = 2m = 24 cm, ikkinchi asos 24 − 9 = 15 cm.', 'a + b = 2m = 24 см, другое основание 24 − 9 = 15 см.', 'a + b = 2m = 24 cm, so the other base is 24 − 9 = 15 cm.') },
      { q: L('Teng yonli trapetsiyada asoslar 6 cm va 14 cm, o‘tkir burchagi 45°. Balandlikni toping.', 'В равнобедренной трапеции основания 6 см и 14 см, острый угол 45°. Найдите высоту.', 'An isosceles trapezium has bases 6 cm and 14 cm and an acute angle of 45°. Find the height.'),
        s: L('Balandliklar katta asosdan (14 − 6) : 2 = 4 cm dan ajratadi. To‘g‘ri burchakli uchburchakda o‘tkir burchak 45°, demak u teng yonli: balandlik = 4 cm.', 'Высоты отсекают от большего основания по (14 − 6) : 2 = 4 см. В прямоугольном треугольнике острый угол 45°, значит он равнобедренный: высота = 4 см.', 'The heights cut off (14 − 6) ÷ 2 = 4 cm each from the longer base. The right triangle has a 45° angle, so it is isosceles: the height is 4 cm.') },
      { q: L('Teng yonli trapetsiyaning bir burchagi 68°. Qolgan burchaklarini toping.', 'Один угол равнобедренной трапеции 68°. Найдите остальные.', 'One angle of an isosceles trapezium is 68°. Find the others.'),
        s: L('Asosdagi burchaklar teng: ikkinchi o‘tkir burchak ham 68°. Yon tomondagi burchak 180° − 68° = 112°. Burchaklar: 68°, 68°, 112°, 112°.', 'Углы при основании равны: второй острый тоже 68°. Угол при боковой стороне 180° − 68° = 112°. Углы: 68°, 68°, 112°, 112°.', 'Base angles are equal, so the other acute angle is also 68°. The angle along the leg is 180° − 68° = 112°. Angles: 68°, 68°, 112°, 112°.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>O‘rta chiziqni a + b deb yozish.</b> 2 ga bo‘lishni unutmang: m — asoslarning o‘rta arifmetigi.', '<b>Писать среднюю линию как a + b.</b> Не забудьте разделить на 2: m — среднее арифметическое оснований.', '<b>Writing the midline as a + b.</b> Do not forget to divide by 2: m is the average of the bases.'),
      L('<b>Yon tomonni balandlik deb olish.</b> Faqat to‘g‘ri burchakli trapetsiyaning perpendikulyar yon tomoni balandlikka teng.', '<b>Принимать боковую сторону за высоту.</b> Высоте равна только перпендикулярная боковая сторона прямоугольной трапеции.', '<b>Taking a leg as the height.</b> Only the perpendicular leg of a right trapezium equals the height.'),
      L('<b>Har qanday trapetsiyada diagonallarni teng deb hisoblash.</b> Bu faqat teng yonli trapetsiyada to‘g‘ri.', '<b>Считать диагонали равными в любой трапеции.</b> Это верно только для равнобедренной.', '<b>Assuming any trapezium has equal diagonals.</b> Only an isosceles one does.'),
      L('<b>(a − b)/2 bo‘lakni teng yonli bo‘lmagan trapetsiyada ishlatish.</b> Umumiy holda ikki bo‘lak har xil bo‘ladi.', '<b>Использовать (a − b)/2 для неравнобедренной трапеции.</b> В общем случае два отрезка разные.', '<b>Using (a − b)/2 in a non-isosceles trapezium.</b> In general the two pieces differ.'),
      L('<b>O‘rta chiziqni asoslarni tutashtiruvchi kesma deb o‘ylash.</b> U yon tomonlar o‘rtalarini tutashtiradi.', '<b>Думать, что средняя линия соединяет основания.</b> Она соединяет середины боковых сторон.', '<b>Thinking the midline joins the bases.</b> It joins the midpoints of the legs.')
    ] },
    { kind: 'life', h: L('Hayotda trapetsiya', 'Трапеция в жизни', 'Trapezia in real life'), p: [
      L('<b>To‘g‘onlar va kanallar.</b> Suv omborlari to‘g‘onining ko‘ndalang kesimi trapetsiya shaklida: pastki asos keng, chunki chuqurlikda suv bosimi kuchliroq. Farg‘ona vodiysidagi katta kanallarning kesimi ham teng yonli trapetsiya — yon devorlari qiya bo‘lgani uchun tuproq ko‘chmaydi.', '<b>Плотины и каналы.</b> Поперечное сечение плотины водохранилища — трапеция: нижнее основание широкое, потому что на глубине давление воды сильнее. Сечение больших каналов Ферганской долины — тоже равнобедренная трапеция: наклонные стенки не осыпаются.', '<b>Dams and canals.</b> The cross-section of a reservoir dam is a trapezium: the bottom is wide because water pressure is greater at depth. The cross-section of the big canals in the Fergana Valley is an isosceles trapezium too — sloping banks do not collapse.'),
      L('<b>Zinapoya va pog‘onalar.</b> Agar zinapoya yuqoriga torayib borsa, o‘rta pog‘onaning uzunligi eng pastki va eng yuqori pog‘onalar yig‘indisining yarmiga teng — bu o‘rta chiziq teoremasining o‘zi. Usta har bir pog‘ona uzunligini teng qadam bilan hisoblaydi.', '<b>Лестницы и ступени.</b> Если лестница сужается кверху, длина средней ступени равна полусумме нижней и верхней — это и есть теорема о средней линии. Мастер рассчитывает каждую ступень с равным шагом.', '<b>Ladders and steps.</b> If a ladder narrows towards the top, the middle rung equals half the sum of the bottom and top rungs — that is the midline theorem itself. A craftsman works out every rung with an equal step.'),
      L('<b>Sumka, abajur, paqir, avtomobil oynasi</b> — bularning yon ko‘rinishi trapetsiya. Dizaynerlar material sarfini o‘rta chiziq orqali tez hisoblaydi.', '<b>Сумка, абажур, ведро, стекло автомобиля</b> — их вид сбоку трапеция. Дизайнеры быстро считают расход материала через среднюю линию.', '<b>Bags, lampshades, buckets and car windows</b> all look like trapezia from the side. Designers quickly estimate material using the midline.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Har qanday trapetsiyada asoslar o‘rtalari, diagonallar kesishish nuqtasi va yon tomonlar davomlari kesishish nuqtasi bitta to‘g‘ri chiziqda yotadi.', 'В любой трапеции середины оснований, точка пересечения диагоналей и точка пересечения продолжений боковых сторон лежат на одной прямой.', 'In any trapezium the midpoints of the bases, the meeting point of the diagonals and the meeting point of the extended legs all lie on one line.'),
      L('Faqat teng yonli trapetsiya atrofida aylana chizish mumkin.', 'Около трапеции можно описать окружность только если она равнобедренная.', 'A circle can be drawn through all four vertices of a trapezium only if it is isosceles.'),
      L('Britaniyada «trapezium», AQShda esa «trapezoid» deyiladi — va qiziq tomoni, ikki mamlakatda bu so‘zlarning ma’nosi tarixan teskari bo‘lgan!', 'В Британии говорят «trapezium», а в США — «trapezoid», причём исторически значения этих слов в двух странах были противоположными!', 'In Britain it is a “trapezium” and in the USA a “trapezoid” — and historically the two countries used these words with opposite meanings!')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. Asoslar 4 cm va 10 cm. O‘rta chiziq nechaga teng?', '1. Основания 4 см и 10 см. Чему равна средняя линия?', '1. The bases are 4 cm and 10 cm. What is the midline?'),
      L('2. To‘g‘ri burchakli trapetsiyaning o‘tkir burchagi 50°. Qolgan burchaklarini toping.', '2. Острый угол прямоугольной трапеции 50°. Найдите остальные углы.', '2. A right trapezium has an acute angle of 50°. Find the other angles.'),
      L('3. O‘rta chiziq 9 cm, asoslar 1 : 2 nisbatda. Asoslarni toping.', '3. Средняя линия 9 см, основания относятся как 1 : 2. Найдите основания.', '3. The midline is 9 cm and the bases are in ratio 1 : 2. Find the bases.')
    ], after: [
      L('Javoblar: 1) 7 cm; 2) 90°, 90°, 50°, 130°; 3) a + b = 18, asoslar 6 cm va 12 cm.', 'Ответы: 1) 7 см; 2) 90°, 90°, 50°, 130°; 3) a + b = 18, основания 6 см и 12 см.', 'Answers: 1) 7 cm; 2) 90°, 90°, 50°, 130°; 3) a + b = 18, the bases are 6 cm and 12 cm.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Trapetsiya — faqat bir juft tomoni parallel to‘rtburchak; parallel tomonlar — asoslar.', 'Трапеция — четырёхугольник, у которого параллельна только одна пара сторон; это основания.', 'A trapezium has exactly one pair of parallel sides, the bases.'),
      L('Yon tomonga yopishgan burchaklar yig‘indisi 180°.', 'Углы при боковой стороне в сумме дают 180°.', 'The angles along a leg add up to 180°.'),
      L('Teng yonli trapetsiyada asosdagi burchaklar va diagonallar teng.', 'В равнобедренной трапеции углы при основании и диагонали равны.', 'An isosceles trapezium has equal base angles and equal diagonals.'),
      L('O‘rta chiziq asoslarga parallel va m = (a + b)/2.', 'Средняя линия параллельна основаниям и m = (a + b)/2.', 'The midline is parallel to the bases and m = (a + b)/2.'),
      L('Ko‘p masalalar balandlik tushirib, trapetsiyani to‘g‘ri to‘rtburchak va uchburchaklarga ajratish orqali yechiladi.', 'Многие задачи решаются, если опустить высоты и разбить трапецию на прямоугольник и треугольники.', 'Many problems are solved by dropping heights and splitting the trapezium into a rectangle and triangles.')
    ] }
  ] });

  // ---------- t6. Fales teoremasi va uning tatbiqi ----------
  T.add(P, 't6', { sections: [
    { kind: 'intro', h: L('Piramida soyasidan teoremagacha', 'От тени пирамиды к теореме', 'From a pyramid’s shadow to a theorem'), p: [
      L('Rivoyat qilishlaricha, yunon donishmandi Fales Misrga kelganida, fir’avn undan ulkan piramidaning balandligini o‘lchashni so‘ragan. Fales piramidaga chiqmagan ham, uni buzmagan ham. U tayoqni yerga tik qo‘yib, soyalar uzunligini kuzatgan: tayoq soyasi uning balandligiga teng bo‘lgan paytda piramida soyasi ham piramida balandligiga teng bo‘ladi. Shunday qilib, Fales faqat soyani o‘lchab, piramida balandligini topgan.', 'Рассказывают, что когда греческий мудрец Фалес приехал в Египет, фараон попросил его измерить высоту огромной пирамиды. Фалес не стал подниматься на пирамиду. Он воткнул в землю палку и наблюдал за тенями: в тот момент, когда тень палки равна её высоте, тень пирамиды равна высоте пирамиды. Так, измерив лишь тень, Фалес нашёл высоту.', 'The story goes that when the Greek sage Thales visited Egypt, the pharaoh asked him to measure the height of a great pyramid. Thales did not climb it. He stood a stick upright and watched the shadows: at the moment when the stick’s shadow equals its height, the pyramid’s shadow also equals the pyramid’s height. By measuring only a shadow, Thales found the height.'),
      L('Bu g‘oyaning orqasida bugun biz o‘rganadigan teorema yotadi: <b>parallel to‘g‘ri chiziqlar burchak tomonlarida proporsional kesmalar ajratadi</b>. Quyosh nurlari deyarli parallel bo‘lgani uchun soyalar ham shu qoidaga bo‘ysunadi. Bu teorema yordamida kesmani chizg‘ich va sirkul bilan istalgan sonli teng bo‘lakka bo‘lishni ham o‘rganamiz.', 'За этой идеей стоит теорема, которую мы изучим сегодня: <b>параллельные прямые отсекают на сторонах угла пропорциональные отрезки</b>. Солнечные лучи почти параллельны, поэтому тени подчиняются этому правилу. С помощью теоремы мы научимся делить отрезок циркулем и линейкой на любое число равных частей.', 'Behind this idea lies the theorem we study today: <b>parallel lines cut the sides of an angle into proportional segments</b>. The Sun’s rays are almost parallel, so shadows obey this rule. With this theorem we will also learn to divide a segment into any number of equal parts using compasses and a ruler.')
    ] },
    { kind: 'def', h: L('Asosiy tushunchalar', 'Основные понятия', 'Key ideas'), p: [
      L('Burchak tomonlarini (yoki ikki ixtiyoriy to‘g‘ri chiziqni) bir nechta <b>parallel to‘g‘ri chiziqlar</b> kesib o‘tsin. Har bir tomonda parallel chiziqlar orasida kesmalar hosil bo‘ladi. Bir tomondagi kesmalar a₁, a₂, a₃ …, ikkinchisidagilar b₁, b₂, b₃ … bo‘lsin.', 'Пусть стороны угла (или две любые прямые) пересекают несколько <b>параллельных прямых</b>. На каждой стороне между параллельными образуются отрезки. Обозначим отрезки на одной стороне a₁, a₂, a₃ …, на другой — b₁, b₂, b₃ …', 'Let several <b>parallel lines</b> cross the sides of an angle (or any two lines). On each side, segments are formed between the parallel lines. Call the segments on one side a₁, a₂, a₃ … and those on the other b₁, b₂, b₃ …'),
      L('<b>Proporsional kesmalar</b> — uzunliklari nisbati teng bo‘lgan kesmalar: a₁ : a₂ = b₁ : b₂. Masalan, 2 cm va 3 cm kesmalar 4 cm va 6 cm kesmalarga proporsional, chunki 2 : 3 = 4 : 6.', '<b>Пропорциональные отрезки</b> — отрезки с равным отношением длин: a₁ : a₂ = b₁ : b₂. Например, отрезки 2 см и 3 см пропорциональны отрезкам 4 см и 6 см, так как 2 : 3 = 4 : 6.', '<b>Proportional segments</b> are segments whose lengths are in the same ratio: a₁ : a₂ = b₁ : b₂. For example, 2 cm and 3 cm are proportional to 4 cm and 6 cm, because 2 : 3 = 4 : 6.'),
      L('Muhim: teoremada faqat bir tomondagi kesmalar boshqa tomondagi kesmalar bilan taqqoslanadi. Parallel chiziqlarning o‘z bo‘laklari (ko‘ndalang kesmalar) boshqa qonunga bo‘ysunadi.', 'Важно: в теореме сравниваются отрезки на одной стороне с отрезками на другой. Сами отрезки параллельных прямых подчиняются другому закону.', 'Important: the theorem compares segments on one side with segments on the other. The pieces of the parallel lines themselves follow a different law.')
    ] },
    { kind: 'history', h: L('Fales — birinchi matematik', 'Фалес — первый математик', 'Thales — the first mathematician'), p: [
      L('<b>Milet</b>lik <b>Fales</b> (taxminan miloddan avvalgi 625–547-yillar) Kichik Osiyodagi yunon shahrida yashagan savdogar, muhandis va faylasuf. Uni ko‘pincha tarixdagi birinchi matematik deb atashadi, chunki u geometrik faktlarni shunchaki o‘lchab emas, balki mantiqiy <b>isbotlab</b> ko‘rsatishga birinchilardan bo‘lib harakat qilgan. Unga diametrga tiralgan burchak to‘g‘ri ekanligi, teng yonli uchburchakda asosdagi burchaklar tengligi va vertikal burchaklar tengligi kabi teoremalar nisbat beriladi.', '<b>Фалес Милетский</b> (около 625–547 гг. до н. э.) — купец, инженер и философ из греческого города в Малой Азии. Его часто называют первым математиком в истории, потому что он одним из первых стал не просто измерять, а логически <b>доказывать</b> геометрические факты. Ему приписывают теоремы о том, что угол, опирающийся на диаметр, прямой, что углы при основании равнобедренного треугольника равны и что вертикальные углы равны.', '<b>Thales of Miletus</b> (about 625–547 BC) was a merchant, engineer and philosopher from a Greek city in Asia Minor. He is often called the first mathematician in history because he was among the first to <b>prove</b> geometric facts by reasoning instead of merely measuring them. He is credited with showing that an angle standing on a diameter is a right angle, that the base angles of an isosceles triangle are equal and that vertical angles are equal.'),
      L('Fales Misr kohinlaridan yer o‘lchash san’atini o‘rgangan va 585-yilgi Quyosh tutilishini oldindan aytgani bilan mashhur. U kemaning qirg‘oqdan uzoqligini ham o‘xshash uchburchaklar yordamida aniqlagan. Keyinchalik Beruniy ham tog‘ cho‘qqisidan ufqqa qarab Yer radiusini hisoblaganda proporsiyalardan foydalangan — bu Fales g‘oyasining ajoyib davomi.', 'Фалес учился землемерию у египетских жрецов и прославился тем, что предсказал солнечное затмение 585 года до н. э. Он также определял расстояние от берега до корабля с помощью подобных треугольников. Позже Беруни, вычисляя радиус Земли по наклону горизонта с вершины горы, тоже пользовался пропорциями — замечательное продолжение идеи Фалеса.', 'Thales learned land surveying from Egyptian priests and is famous for predicting the solar eclipse of 585 BC. He also found the distance of a ship from the shore using similar triangles. Much later, al-Biruni used proportions when he computed the Earth’s radius from the dip of the horizon seen from a mountain — a splendid continuation of Thales’ idea.')
    ] },
    { kind: 'rule', h: L('Fales teoremasi', 'Теорема Фалеса', 'Thales’ theorem'), p: [
      L('<b>Teorema.</b> Agar burchakning bir tomonida ketma-ket teng kesmalar ajratilib, ularning uchlari orqali parallel to‘g‘ri chiziqlar o‘tkazilsa, bu chiziqlar burchakning ikkinchi tomonida ham teng kesmalar ajratadi.', '<b>Теорема.</b> Если на одной стороне угла отложить подряд равные отрезки и через их концы провести параллельные прямые, то эти прямые отсекут на другой стороне тоже равные отрезки.', '<b>Theorem.</b> If equal segments are marked one after another on one side of an angle and parallel lines are drawn through their ends, these lines cut off equal segments on the other side as well.'),
      L('<b>Isbot g‘oyasi.</b> Birinchi tomonda A₁A₂ = A₂A₃, ikkinchisida mos ravishda B₁, B₂, B₃. B₂ orqali birinchi tomonga parallel chiziq o‘tkazib, ikki parallelogramm va ikki uchburchak hosil qilamiz. Parallelogrammlarda qarama-qarshi tomonlar teng, shuning uchun uchburchaklarning bir tomoni teng bo‘ladi; ularning burchaklari esa parallel chiziqlardagi mos burchaklar sifatida teng. Demak, uchburchaklar teng va B₁B₂ = B₂B₃.', '<b>Идея доказательства.</b> На первой стороне A₁A₂ = A₂A₃, на второй соответственно B₁, B₂, B₃. Через точки B проведём прямые, параллельные первой стороне, получим параллелограммы и треугольники. В параллелограммах противоположные стороны равны, поэтому у треугольников равны стороны, а их углы равны как соответственные при параллельных. Значит, треугольники равны и B₁B₂ = B₂B₃.', '<b>Proof idea.</b> On the first side A₁A₂ = A₂A₃; on the second side the matching points are B₁, B₂, B₃. Through the B-points draw lines parallel to the first side, forming parallelograms and triangles. Opposite sides of a parallelogram are equal, so the triangles have an equal side, and their angles are equal as corresponding angles at parallel lines. So the triangles are congruent and B₁B₂ = B₂B₃.'),
      L('<b>Umumlashgan teorema (proporsional kesmalar haqida).</b> Parallel to‘g‘ri chiziqlar burchak tomonlarida proporsional kesmalar ajratadi: <b>a₁ : a₂ = b₁ : b₂</b>. Butun sonli nisbatlar uchun bu teorema bevosita Fales teoremasidan kelib chiqadi: kesmalarni umumiy o‘lchov birligiga bo‘lamiz.', '<b>Обобщённая теорема (о пропорциональных отрезках).</b> Параллельные прямые отсекают на сторонах угла пропорциональные отрезки: <b>a₁ : a₂ = b₁ : b₂</b>. Для целых отношений она прямо следует из теоремы Фалеса: делим отрезки на общую единицу измерения.', '<b>Generalised theorem (proportional segments).</b> Parallel lines cut the sides of an angle into proportional segments: <b>a₁ : a₂ = b₁ : b₂</b>. For whole-number ratios this follows directly from Thales’ theorem: split the segments into a common unit.'),
      L('Diqqat: o‘rta chiziq teoremasi Fales teoremasining xususiy holi — ikki teng kesma va bitta parallel chiziq.', 'Заметим: теорема о средней линии — частный случай теоремы Фалеса: два равных отрезка и одна параллельная прямая.', 'Note: the midline theorem is a special case of Thales’ theorem — two equal segments and one parallel line.')
    ] },
    { kind: 'steps', h: L('Kesmani n ta teng bo‘lakka bo‘lish', 'Деление отрезка на n равных частей', 'Dividing a segment into n equal parts'), list: [
      L('1. AB kesma berilgan. A nuqtadan AB ga to‘g‘ri kelmaydigan ixtiyoriy nur o‘tkazing.', '1. Дан отрезок AB. Из точки A проведите произвольный луч, не лежащий на AB.', '1. You are given segment AB. From A draw any ray not along AB.'),
      L('2. Sirkul bilan nur ustida A dan boshlab n ta bir xil kesma ajrating: A₁, A₂, …, Aₙ nuqtalar hosil bo‘ladi.', '2. Циркулем отложите на луче от A n одинаковых отрезков: получатся точки A₁, A₂, …, Aₙ.', '2. With compasses mark n equal segments along the ray from A: points A₁, A₂, …, Aₙ.'),
      L('3. Oxirgi nuqta Aₙ ni B bilan tutashtiring.', '3. Соедините последнюю точку Aₙ с B.', '3. Join the last point Aₙ to B.'),
      L('4. Qolgan A₁, A₂, … nuqtalar orqali AₙB ga parallel to‘g‘ri chiziqlar o‘tkazing.', '4. Через остальные точки A₁, A₂, … проведите прямые, параллельные AₙB.', '4. Through the other points A₁, A₂, … draw lines parallel to AₙB.'),
      L('5. Ular AB ni n ta teng bo‘lakka bo‘ladi — Fales teoremasiga ko‘ra. O‘lchov chizg‘ichi kerak emas!', '5. Они разделят AB на n равных частей — по теореме Фалеса. Линейка с делениями не нужна!', '5. They divide AB into n equal parts — by Thales’ theorem. No measuring scale is needed!')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Burchakning bir tomonida 3 cm, 3 cm, 3 cm li kesmalar ajratilib, uchlari orqali parallel chiziqlar o‘tkazildi. Ikkinchi tomondagi birinchi kesma 5 cm. Qolganlarini toping.', 'На одной стороне угла отложены отрезки 3 см, 3 см, 3 см, через концы проведены параллельные прямые. Первый отрезок на другой стороне 5 см. Найдите остальные.', 'Segments of 3 cm, 3 cm, 3 cm are marked on one side of an angle, and parallel lines are drawn through their ends. The first segment on the other side is 5 cm. Find the rest.'),
        s: L('Fales teoremasiga ko‘ra, ikkinchi tomondagi kesmalar ham teng: 5 cm, 5 cm, 5 cm. Jami 15 cm.', 'По теореме Фалеса отрезки на другой стороне тоже равны: 5 см, 5 см, 5 см. Всего 15 см.', 'By Thales’ theorem the segments on the other side are also equal: 5 cm, 5 cm, 5 cm — 15 cm in total.') },
      { q: L('Parallel chiziqlar burchak tomonlarida a₁ = 4 cm, a₂ = 6 cm va b₁ = 10 cm kesmalar ajratdi. b₂ ni toping.', 'Параллельные прямые отсекли на сторонах угла a₁ = 4 см, a₂ = 6 см и b₁ = 10 см. Найдите b₂.', 'Parallel lines cut segments a₁ = 4 cm, a₂ = 6 cm and b₁ = 10 cm on the sides of an angle. Find b₂.'),
        s: L('a₁ : a₂ = b₁ : b₂, ya’ni 4 : 6 = 10 : b₂. b₂ = 6 · 10 : 4 = 15 cm.', 'a₁ : a₂ = b₁ : b₂, то есть 4 : 6 = 10 : b₂. b₂ = 6 · 10 : 4 = 15 см.', 'a₁ : a₂ = b₁ : b₂, so 4 : 6 = 10 : b₂, giving b₂ = 6 · 10 ÷ 4 = 15 cm.') },
      { q: L('Tayoq balandligi 1,5 m, soyasi 2 m. Shu paytda daraxt soyasi 12 m. Daraxt balandligini toping.', 'Высота палки 1,5 м, её тень 2 м. В тот же момент тень дерева 12 м. Найдите высоту дерева.', 'A stick 1.5 m tall casts a 2 m shadow. At the same moment a tree’s shadow is 12 m. How tall is the tree?'),
        s: L('Quyosh nurlari parallel, shuning uchun balandlik va soya nisbati bir xil: h : 12 = 1,5 : 2. h = 12 · 1,5 : 2 = 9 m.', 'Солнечные лучи параллельны, поэтому отношение высоты к тени одинаково: h : 12 = 1,5 : 2. h = 12 · 1,5 : 2 = 9 м.', 'The Sun’s rays are parallel, so height and shadow are in the same ratio: h : 12 = 1.5 : 2, so h = 12 · 1.5 ÷ 2 = 9 m.') },
      { q: L('14 cm li kesmani 3 : 4 nisbatda bo‘lish kerak. Bo‘laklarni toping va yasash usulini ayting.', 'Отрезок 14 см нужно разделить в отношении 3 : 4. Найдите части и опишите построение.', 'Divide a 14 cm segment in the ratio 3 : 4. Find the parts and describe the construction.'),
        s: L('Jami 7 qism, bitta qism 2 cm: bo‘laklar 6 cm va 8 cm. Yasash: nur ustida 7 ta teng kesma ajratamiz, 7-nuqtani kesma oxiri bilan tutashtiramiz va 3-nuqta orqali unga parallel chiziq o‘tkazamiz.', 'Всего 7 частей, одна часть 2 см: части 6 см и 8 см. Построение: на луче откладываем 7 равных отрезков, соединяем 7-ю точку с концом отрезка и через 3-ю точку проводим параллельную прямую.', 'There are 7 parts, each 2 cm: the pieces are 6 cm and 8 cm. Construction: mark 7 equal segments on a ray, join the 7th point to the end of the segment, and draw a parallel line through the 3rd point.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Chiziqlar parallel ekanini tekshirmaslik.</b> Teorema faqat parallel to‘g‘ri chiziqlar uchun to‘g‘ri.', '<b>Не проверять параллельность.</b> Теорема верна только для параллельных прямых.', '<b>Not checking that the lines are parallel.</b> The theorem works only for parallel lines.'),
      L('<b>Proporsiyani noto‘g‘ri tuzish.</b> Bir tomondagi kesmalar nisbatini ikkinchi tomondagi mos kesmalar nisbatiga tenglang, aralashtirmang.', '<b>Неверно составлять пропорцию.</b> Приравнивайте отношение отрезков одной стороны к отношению соответствующих отрезков другой.', '<b>Setting up the proportion wrongly.</b> Equate the ratio on one side with the ratio of the matching segments on the other — do not mix them.'),
      L('<b>Teng kesmalar har doim tengga o‘tadi deb o‘ylash.</b> Bir tomondagi teng kesmalar ikkinchi tomonda ham teng bo‘ladi, lekin ular birinchi tomondagilarga teng bo‘lishi shart emas (3 cm → 5 cm).', '<b>Думать, что отрезки переносятся без изменения.</b> Равные отрезки одной стороны дают равные на другой, но не обязательно равные исходным (3 см → 5 см).', '<b>Thinking the segments stay the same length.</b> Equal segments on one side give equal segments on the other, but not necessarily equal to the originals (3 cm → 5 cm).'),
      L('<b>Parallel chiziqlar bo‘laklarini ham shu proporsiyaga kiritish.</b> Ko‘ndalang kesmalar uchun o‘xshash uchburchaklar kerak bo‘ladi.', '<b>Включать в пропорцию отрезки самих параллельных.</b> Для них нужны подобные треугольники.', '<b>Putting the pieces of the parallel lines into the same proportion.</b> Those need similar triangles.')
    ] },
    { kind: 'life', h: L('Hayotda Fales teoremasi', 'Теорема Фалеса в жизни', 'Thales’ theorem in real life'), p: [
      L('<b>Balandlikni soya orqali o‘lchash.</b> Minora, daraxt yoki uy balandligini bilish uchun unga chiqish shart emas: o‘z bo‘yingiz va soyangizni, keyin minora soyasini o‘lchang. Proporsiya javobni beradi. Xuddi shu usulda Samarqanddagi minoralar balandligini ham taxminan aniqlash mumkin.', '<b>Измерение высоты по тени.</b> Чтобы узнать высоту башни, дерева или дома, не нужно на них забираться: измерьте свой рост и тень, затем тень башни. Пропорция даст ответ. Так можно примерно определить и высоту минаретов Самарканда.', '<b>Measuring height from shadows.</b> You do not have to climb a tower, tree or house to know its height: measure your own height and shadow, then the tower’s shadow. A proportion gives the answer. The minarets of Samarkand can be estimated this way too.'),
      L('<b>Chizmachilik va tikuvchilik.</b> Chizmachi kesmani 7 yoki 9 ta teng bo‘lakka bo‘lishi kerak bo‘lsa, chizg‘ichdagi bo‘linmalar mos kelmasligi mumkin. Fales usuli bilan qiya chiziq va parallel chiziqlar yordamida aniq bo‘lish oson. Tikuvchilar tugmalar orasini, duradgorlar esa javon tokchalarini shu usulda teng taqsimlaydi.', '<b>Черчение и шитьё.</b> Если чертёжнику нужно разделить отрезок на 7 или 9 равных частей, деления линейки могут не подойти. Способом Фалеса — наклонной и параллельными — сделать это точно легко. Портные так распределяют пуговицы, а столяры — полки.', '<b>Technical drawing and sewing.</b> If a draughtsman has to split a line into 7 or 9 equal parts, the ruler’s marks may not fit. Thales’ method, with a slanted line and parallels, does it exactly. Tailors space buttons and carpenters space shelves the same way.'),
      L('<b>Daftarning chiziqlari</b> ham Fales asbobi: chiziqli varaqni qiyalatib qo‘yib, istalgan kesmani teng bo‘laklarga bo‘lish mumkin.', '<b>Линейки тетради</b> — тоже инструмент Фалеса: положив лист наискосок, можно разделить любой отрезок на равные части.', 'The <b>lines on lined paper</b> are a Thales tool too: tilt the paper and you can split any segment into equal parts.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('«Fales teoremasi» nomi turli mamlakatlarda turli teoremalarga beriladi: ba’zilarida bu — diametrga tiralgan burchak haqidagi teorema.', 'Название «теорема Фалеса» в разных странах относят к разным теоремам: в некоторых так называют теорему об угле, опирающемся на диаметр.', 'The name “Thales’ theorem” refers to different results in different countries: in some it means the theorem about an angle standing on a diameter.'),
      L('Fales «yetti donishmand»dan biri hisoblangan; unga «O‘zingni bil» degan mashhur so‘z ham nisbat beriladi.', 'Фалеса считали одним из «семи мудрецов»; ему приписывают знаменитое изречение «Познай самого себя».', 'Thales was counted among the “Seven Sages”, and the famous saying “Know thyself” is sometimes credited to him.'),
      L('Fotoapparat va proyektorlar ishlashi ham proporsional kesmalar qonuniga asoslangan.', 'Работа фотоаппаратов и проекторов тоже основана на законе пропорциональных отрезков.', 'Cameras and projectors also work on the law of proportional segments.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. Parallel chiziqlar burchak tomonlarida 2 cm, 5 cm va 6 cm, x kesmalar ajratdi. x ni toping.', '1. Параллельные прямые отсекли на сторонах угла 2 см, 5 см и 6 см, x. Найдите x.', '1. Parallel lines cut 2 cm, 5 cm on one side and 6 cm, x on the other. Find x.'),
      L('2. Bo‘yingiz 1,6 m, soyangiz 2,4 m. Minora soyasi 36 m. Minora balandligi qancha?', '2. Ваш рост 1,6 м, тень 2,4 м. Тень башни 36 м. Какова высота башни?', '2. You are 1.6 m tall and your shadow is 2.4 m. A tower’s shadow is 36 m. How tall is the tower?'),
      L('3. Kesmani 5 ta teng bo‘lakka bo‘lish uchun nur ustida nechta kesma ajratish kerak?', '3. Сколько отрезков надо отложить на луче, чтобы разделить отрезок на 5 равных частей?', '3. How many segments must you mark on the ray to divide a segment into 5 equal parts?')
    ], after: [
      L('Javoblar: 1) 2 : 5 = 6 : x, x = 15 cm; 2) h = 36 · 1,6 : 2,4 = 24 m; 3) 5 ta teng kesma.', 'Ответы: 1) 2 : 5 = 6 : x, x = 15 см; 2) h = 36 · 1,6 : 2,4 = 24 м; 3) 5 равных отрезков.', 'Answers: 1) 2 : 5 = 6 : x, x = 15 cm; 2) h = 36 · 1.6 ÷ 2.4 = 24 m; 3) 5 equal segments.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Fales teoremasi: burchak tomonida teng kesmalar ajratib, parallel chiziqlar o‘tkazsak, ikkinchi tomonda ham teng kesmalar hosil bo‘ladi.', 'Теорема Фалеса: если на стороне угла отложить равные отрезки и провести параллельные, на другой стороне тоже получатся равные отрезки.', 'Thales’ theorem: equal segments on one side of an angle, with parallel lines through their ends, give equal segments on the other side.'),
      L('Umumlashgani: parallel chiziqlar proporsional kesmalar ajratadi, a₁ : a₂ = b₁ : b₂.', 'Обобщение: параллельные прямые отсекают пропорциональные отрезки, a₁ : a₂ = b₁ : b₂.', 'Generalisation: parallel lines cut proportional segments, a₁ : a₂ = b₁ : b₂.'),
      L('Isbot g‘oyasi — parallelogrammlar va teng uchburchaklar.', 'Идея доказательства — параллелограммы и равные треугольники.', 'Proof idea: parallelograms and congruent triangles.'),
      L('Teorema yordamida kesmani istalgan sonli teng bo‘lakka yoki berilgan nisbatda bo‘lish mumkin.', 'Теорема позволяет делить отрезок на любое число равных частей или в данном отношении.', 'It lets us divide a segment into any number of equal parts or in a given ratio.'),
      L('Fales — isbotlangan geometriyaning asoschilaridan biri; soyalar orqali balandlikni o‘lchash uning mashhur usuli.', 'Фалес — один из основателей доказательной геометрии; измерение высоты по тени — его знаменитый способ.', 'Thales was one of the founders of proof-based geometry; measuring height by shadows is his famous method.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-2';

  // ---------- t7. O‘q va markaziy simmetriya ----------
  T.add(P, 't7', { sections: [
    { kind: 'intro', h: L('Ko‘zgu va aylanish', 'Зеркало и поворот', 'Mirrors and half-turns'), p: [
      L('Kapalak qanotlari, inson yuzi, chinor bargi, Registon peshtoqi — bularning barchasida chap va o‘ng tomon bir-birining «ko‘zgudagi aksi». Bunday go‘zallikni matematikada <b>simmetriya</b> deyiladi. Yunoncha «symmetria» so‘zi «mutanosiblik, uyg‘unlik» degan ma’noni anglatadi.', 'Крылья бабочки, лицо человека, лист платана, портал Регистана — во всём этом левая и правая половины являются «зеркальным отражением» друг друга. Такую красоту в математике называют <b>симметрией</b>. Греческое слово «symmetria» означает «соразмерность, гармония».', 'A butterfly’s wings, a human face, a plane-tree leaf, the portal of the Registan — in each of these the left and right halves are “mirror images” of each other. Mathematicians call this beauty <b>symmetry</b>. The Greek word symmetria means “proportion, harmony”.'),
      L('Simmetriyaning ikki asosiy turi bor. <b>O‘q simmetriyasi</b> ko‘zguga o‘xshaydi: shaklni to‘g‘ri chiziq bo‘ylab bukib qo‘ysak, ikki yarmi ustma-ust tushadi. <b>Markaziy simmetriya</b> esa nuqta atrofida 180° ga aylantirishdir: shaklni «teskari» qilib aylantirsak, u o‘ziga ustma-ust tushadi. Masalan, «S» harfi va parallelogramm aynan shunday.', 'Есть два основных вида симметрии. <b>Осевая симметрия</b> похожа на зеркало: если согнуть фигуру по прямой, половинки совпадут. <b>Центральная симметрия</b> — поворот вокруг точки на 180°: перевернув фигуру «вверх ногами», мы совместим её с собой. Так устроены буква «S» и параллелограмм.', 'There are two main kinds of symmetry. <b>Line (reflective) symmetry</b> is like a mirror: fold the figure along a line and the halves match. <b>Point (central) symmetry</b> is a half-turn of 180° about a point: turn the figure upside down and it lands on itself. The letter “S” and a parallelogram are like this.'),
      L('Bu mavzuda nuqtalar va shakllarning simmetriyasini aniq ta’riflaymiz, koordinatalar orqali simmetrik nuqtalarni topishni o‘rganamiz va qaysi to‘rtburchaklarda qanday simmetriya borligini aniqlaymiz.', 'В этой теме мы точно определим симметрию точек и фигур, научимся находить симметричные точки по координатам и выясним, какие четырёхугольники какую симметрию имеют.', 'In this topic we define the symmetry of points and figures precisely, learn to find symmetric points using coordinates, and work out which quadrilaterals have which symmetry.')
    ] },
    { kind: 'def', h: L('Ta’riflar', 'Определения', 'Definitions'), list: [
      L('A va A₁ nuqtalar <b>l to‘g‘ri chiziqqa nisbatan simmetrik</b>, agar l to‘g‘ri chiziq AA₁ kesmaga perpendikulyar bo‘lib, uni teng ikkiga bo‘lsa. l — <b>simmetriya o‘qi</b>. l ustidagi nuqta o‘ziga o‘zi simmetrik.', 'Точки A и A₁ <b>симметричны относительно прямой l</b>, если l перпендикулярна отрезку AA₁ и проходит через его середину. l — <b>ось симметрии</b>. Точка на l симметрична сама себе.', 'Points A and A₁ are <b>symmetric about line l</b> if l is perpendicular to segment AA₁ and passes through its midpoint. l is the <b>axis (line) of symmetry</b>. A point on l is its own mirror image.'),
      L('A va A₁ nuqtalar <b>O nuqtaga nisbatan simmetrik</b>, agar O — AA₁ kesmaning o‘rtasi bo‘lsa. O — <b>simmetriya markazi</b>; u o‘ziga o‘zi simmetrik.', 'Точки A и A₁ <b>симметричны относительно точки O</b>, если O — середина отрезка AA₁. O — <b>центр симметрии</b>; он симметричен сам себе.', 'Points A and A₁ are <b>symmetric about point O</b> if O is the midpoint of AA₁. O is the <b>centre of symmetry</b>; it is its own image.'),
      L('Shakl <b>simmetriya o‘qiga ega</b>, agar uning har bir nuqtasiga l ga nisbatan simmetrik nuqta ham shu shaklga tegishli bo‘lsa. Bunday shakl o‘qqa nisbatan simmetrik deyiladi.', 'Фигура <b>имеет ось симметрии</b> l, если точка, симметричная любой её точке относительно l, тоже принадлежит фигуре.', 'A figure <b>has a line of symmetry</b> l if the mirror image in l of every point of the figure also belongs to the figure.'),
      L('Shakl <b>simmetriya markaziga ega</b>, agar uning har bir nuqtasiga O ga nisbatan simmetrik nuqta ham shu shaklga tegishli bo‘lsa.', 'Фигура <b>имеет центр симметрии</b> O, если точка, симметричная любой её точке относительно O, тоже принадлежит фигуре.', 'A figure <b>has a centre of symmetry</b> O if the image about O of every point of the figure also belongs to the figure.')
    ], after: [
      L('Ikkala simmetriya ham <b>harakat</b>dir: ular masofalarni saqlaydi, shuning uchun kesma kesmaga, burchak unga teng burchakka, shakl esa unga teng shaklga o‘tadi.', 'Обе симметрии — <b>движения</b>: они сохраняют расстояния, поэтому отрезок переходит в равный отрезок, угол — в равный угол, фигура — в равную фигуру.', 'Both symmetries are <b>isometries</b>: they preserve distances, so a segment goes to an equal segment, an angle to an equal angle and a figure to a congruent figure.')
    ] },
    { kind: 'history', h: L('Tarixdan: girih va simmetriya ilmi', 'Из истории: гирих и наука о симметрии', 'History: girih and the science of symmetry'), p: [
      L('Simmetriya — insoniyatning eng qadimgi bezak tamoyillaridan biri. Afrosiyob devoriy suratlari, Shohi Zinda ansambli koshinlari va Buxorodagi Poi Kalon majmuasi naqshlarida o‘q va markaziy simmetriya bir-biriga uyg‘un holda qo‘llangan. O‘rta asr <b>girih</b> ustalari bitta kichik naqsh bo‘lagini chizib, keyin uni simmetriya o‘qlari va markazlariga nisbatan qayta-qayta aks ettirish orqali butun devorni bezashgan. Bu ish uchun ular faqat sirkul va chizg‘ichdan foydalanishgan.', 'Симметрия — один из древнейших принципов украшения. В росписях Афрасиаба, изразцах Шахи-Зинды и узорах ансамбля Пои-Калян в Бухаре осевая и центральная симметрия гармонично сочетаются. Средневековые мастера <b>гирих</b> рисовали один маленький фрагмент, а потом снова и снова отражали его относительно осей и центров симметрии, покрывая всю стену. Для этого им хватало циркуля и линейки.', 'Symmetry is one of humanity’s oldest principles of decoration. In the wall paintings of Afrasiyab, the tiles of Shah-i-Zinda and the patterns of the Poi Kalyan complex in Bukhara, line and point symmetry are combined in harmony. Medieval <b>girih</b> masters drew one small fragment and then reflected it again and again in lines and centres of symmetry to cover a whole wall — using only compasses and a straight edge.'),
      L('X asrda Bag‘dodda ishlagan Abu-l-Vafo al-Buzjoniy hunarmandlar uchun «Hunarmandga zarur geometrik yasashlar haqida» kitobini yozgan; unda simmetrik naqshlarni yasash usullari bor. 2007-yilda olimlar Isfahondagi XV asr girih naqshlarida zamonaviy matematikada faqat 1970-yillarda kashf qilingan «kvazidavriy» mozaikalarga o‘xshash tuzilmani topishgan. XIX–XX asrlarda esa simmetriya kristallar va atom zarralari fizikasining asosiy tiliga aylandi.', 'Абу-ль-Вафа аль-Бузджани, работавший в X веке в Багдаде, написал для ремесленников книгу о геометрических построениях; в ней есть способы построения симметричных узоров. В 2007 году учёные обнаружили в узорах гирих XV века в Исфахане структуру, похожую на «квазипериодические» мозаики, открытые современной математикой только в 1970-х. А в XIX–XX веках симметрия стала главным языком физики кристаллов и элементарных частиц.', 'Abu’l-Wafa al-Buzjani, working in Baghdad in the 10th century, wrote a book for craftsmen on geometric constructions, including ways to build symmetric patterns. In 2007 researchers found in 15th-century girih patterns in Isfahan a structure resembling the “quasi-periodic” tilings that modern mathematics discovered only in the 1970s. In the 19th and 20th centuries symmetry became the main language of crystal and particle physics.')
    ] },
    { kind: 'rule', h: L('Simmetriya koordinatalarda', 'Симметрия в координатах', 'Symmetry in coordinates'), p: [
      L('Koordinata tekisligida simmetrik nuqtalarni topish juda oson. A(x; y) nuqta berilgan bo‘lsin:', 'На координатной плоскости симметричные точки находить очень легко. Пусть дана точка A(x; y):', 'On the coordinate plane, symmetric points are very easy to find. Let A(x; y) be given:')
    ], list: [
      L('<b>Ox o‘qiga</b> nisbatan: (x; y) → (x; −y) — ordinata ishorasi o‘zgaradi.', 'Относительно <b>оси Ox</b>: (x; y) → (x; −y) — меняется знак ординаты.', 'About the <b>x-axis</b>: (x; y) → (x; −y) — the y-coordinate changes sign.'),
      L('<b>Oy o‘qiga</b> nisbatan: (x; y) → (−x; y) — abssissa ishorasi o‘zgaradi.', 'Относительно <b>оси Oy</b>: (x; y) → (−x; y) — меняется знак абсциссы.', 'About the <b>y-axis</b>: (x; y) → (−x; y) — the x-coordinate changes sign.'),
      L('<b>Koordinata boshi O</b> ga nisbatan: (x; y) → (−x; −y) — ikkala ishora o‘zgaradi.', 'Относительно <b>начала координат O</b>: (x; y) → (−x; −y) — меняются оба знака.', 'About the <b>origin O</b>: (x; y) → (−x; −y) — both signs change.'),
      L('<b>y = x</b> to‘g‘ri chiziqqa nisbatan: (x; y) → (y; x) — koordinatalar o‘rin almashadi.', 'Относительно прямой <b>y = x</b>: (x; y) → (y; x) — координаты меняются местами.', 'About the line <b>y = x</b>: (x; y) → (y; x) — the coordinates swap.'),
      L('Ixtiyoriy <b>M(a; b)</b> nuqtaga nisbatan: (x; y) → (2a − x; 2b − y), chunki M kesmaning o‘rtasi.', 'Относительно произвольной точки <b>M(a; b)</b>: (x; y) → (2a − x; 2b − y), так как M — середина отрезка.', 'About any point <b>M(a; b)</b>: (x; y) → (2a − x; 2b − y), because M is the midpoint.')
    ], after: [
      L('<b>Asoslash.</b> Masalan, A(x; y) va A₁(x; −y) uchun AA₁ kesma vertikal, ya’ni Ox ga perpendikulyar, uning o‘rtasi (x; 0) esa Ox ustida yotadi. Ta’rifning ikkala sharti bajarildi.', '<b>Обоснование.</b> Например, для A(x; y) и A₁(x; −y) отрезок AA₁ вертикален, то есть перпендикулярен Ox, а его середина (x; 0) лежит на Ox. Оба условия определения выполнены.', '<b>Why.</b> For A(x; y) and A₁(x; −y), segment AA₁ is vertical, so it is perpendicular to the x-axis, and its midpoint (x; 0) lies on the x-axis. Both conditions of the definition hold.')
    ] },
    { kind: 'rule', h: L('Qaysi shaklda qanday simmetriya bor?', 'Какая симметрия у каких фигур?', 'Which figures have which symmetry?'), list: [
      L('<b>Parallelogramm</b>: simmetriya markazi bor (diagonallar kesishish nuqtasi), umumiy holda o‘qi yo‘q. Sababi: diagonallar kesishish nuqtasida teng ikkiga bo‘linadi.', '<b>Параллелограмм</b>: есть центр симметрии (точка пересечения диагоналей), осей в общем случае нет. Причина: диагонали делятся точкой пересечения пополам.', '<b>Parallelogram</b>: has a centre of symmetry (where the diagonals meet) but in general no lines of symmetry. Reason: the diagonals bisect each other.'),
      L('<b>To‘g‘ri to‘rtburchak</b>: markaz va 2 ta o‘q — qarama-qarshi tomonlar o‘rtalari orqali o‘tuvchi to‘g‘ri chiziqlar.', '<b>Прямоугольник</b>: центр и 2 оси — прямые через середины противоположных сторон.', '<b>Rectangle</b>: a centre and 2 lines — through the midpoints of opposite sides.'),
      L('<b>Romb</b>: markaz va 2 ta o‘q — uning diagonallari.', '<b>Ромб</b>: центр и 2 оси — его диагонали.', '<b>Rhombus</b>: a centre and 2 lines — its diagonals.'),
      L('<b>Kvadrat</b>: markaz va 4 ta o‘q.', '<b>Квадрат</b>: центр и 4 оси.', '<b>Square</b>: a centre and 4 lines.'),
      L('<b>Teng yonli trapetsiya</b>: 1 ta o‘q, markaz yo‘q. <b>Teng yonli uchburchak</b>: 1 ta o‘q; <b>teng tomonli</b>: 3 ta o‘q; uchburchakda markaz hech qachon bo‘lmaydi.', '<b>Равнобедренная трапеция</b>: 1 ось, центра нет. <b>Равнобедренный треугольник</b>: 1 ось; <b>равносторонний</b>: 3 оси; центра у треугольника не бывает.', '<b>Isosceles trapezium</b>: 1 line, no centre. <b>Isosceles triangle</b>: 1 line; <b>equilateral</b>: 3 lines; a triangle never has a centre of symmetry.'),
      L('<b>Aylana</b>: markazi — simmetriya markazi, markaz orqali o‘tuvchi har bir to‘g‘ri chiziq — o‘q (cheksiz ko‘p).', '<b>Окружность</b>: центр — центр симметрии, любая прямая через центр — ось (их бесконечно много).', '<b>Circle</b>: its centre is a centre of symmetry, and every line through the centre is a line of symmetry (infinitely many).')
    ] },
    { kind: 'steps', h: L('Simmetrik shaklni yasash', 'Построение симметричной фигуры', 'Constructing a symmetric figure'), list: [
      L('1. Shaklning uchlarini belgilang (ko‘pburchak uchun uchlarining o‘zi yetarli).', '1. Отметьте вершины фигуры (для многоугольника достаточно вершин).', '1. Mark the vertices of the figure (for a polygon the vertices are enough).'),
      L('2. O‘q simmetriyasi uchun: har bir uchdan o‘qqa perpendikulyar tushiring va uni o‘q orqasiga xuddi shu uzunlikda davom ettiring.', '2. Для осевой симметрии: из каждой вершины опустите перпендикуляр на ось и продлите его за ось на ту же длину.', '2. For line symmetry: from each vertex drop a perpendicular to the line and extend it the same distance beyond.'),
      L('3. Markaziy simmetriya uchun: har bir uchni markaz bilan tutashtirib, kesmani markazdan keyin xuddi shu uzunlikda davom ettiring.', '3. Для центральной симметрии: соедините каждую вершину с центром и продлите отрезок за центр на ту же длину.', '3. For point symmetry: join each vertex to the centre and extend the segment the same distance past it.'),
      L('4. Hosil bo‘lgan nuqtalarni xuddi shu tartibda tutashtiring.', '4. Соедините полученные точки в том же порядке.', '4. Join the new points in the same order.'),
      L('5. Tekshiring: yangi shakl asl shaklga teng bo‘lishi kerak (tomonlar va burchaklar mos ravishda teng).', '5. Проверьте: новая фигура должна быть равна исходной (соответствующие стороны и углы равны).', '5. Check: the new figure must be congruent to the original (matching sides and angles are equal).')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('A(3; −5) nuqtaga Ox, Oy o‘qlariga va koordinata boshiga nisbatan simmetrik nuqtalarni toping.', 'Найдите точки, симметричные A(3; −5) относительно Ox, Oy и начала координат.', 'Find the images of A(3; −5) in the x-axis, the y-axis and the origin.'),
        s: L('Ox ga nisbatan: (3; 5). Oy ga nisbatan: (−3; −5). O ga nisbatan: (−3; 5).', 'Относительно Ox: (3; 5). Относительно Oy: (−3; −5). Относительно O: (−3; 5).', 'In the x-axis: (3; 5). In the y-axis: (−3; −5). In the origin: (−3; 5).') },
      { q: L('A(1; 4) nuqtaga M(3; 2) nuqtaga nisbatan simmetrik nuqtani toping.', 'Найдите точку, симметричную A(1; 4) относительно M(3; 2).', 'Find the image of A(1; 4) in the point M(3; 2).'),
        s: L('M — AA₁ ning o‘rtasi: (1 + x) : 2 = 3, (4 + y) : 2 = 2. Bundan x = 5, y = 0. Javob: A₁(5; 0).', 'M — середина AA₁: (1 + x) : 2 = 3, (4 + y) : 2 = 2. Отсюда x = 5, y = 0. Ответ: A₁(5; 0).', 'M is the midpoint of AA₁: (1 + x) ÷ 2 = 3 and (4 + y) ÷ 2 = 2. So x = 5 and y = 0. Answer: A₁(5; 0).') },
      { q: L('Parallelogramm ABCD ning uchta uchi A(−2; 1), B(1; 4), C(5; 2). Diagonallar kesishish nuqtasini va D uchni toping.', 'Даны три вершины параллелограмма ABCD: A(−2; 1), B(1; 4), C(5; 2). Найдите точку пересечения диагоналей и вершину D.', 'Three vertices of parallelogram ABCD are A(−2; 1), B(1; 4), C(5; 2). Find the meeting point of the diagonals and vertex D.'),
        s: L('Markaz O — AC ning o‘rtasi: ((−2 + 5) : 2; (1 + 2) : 2) = (1,5; 1,5). D nuqta B ga O ga nisbatan simmetrik: D = (2 · 1,5 − 1; 2 · 1,5 − 4) = (2; −1).', 'Центр O — середина AC: ((−2 + 5) : 2; (1 + 2) : 2) = (1,5; 1,5). D симметрична B относительно O: D = (2 · 1,5 − 1; 2 · 1,5 − 4) = (2; −1).', 'The centre O is the midpoint of AC: ((−2 + 5) ÷ 2; (1 + 2) ÷ 2) = (1.5; 1.5). D is the image of B about O: D = (2 · 1.5 − 1; 2 · 1.5 − 4) = (2; −1).') },
      { q: L('Lotin alifbosining bosh harflari A, H, N, S, Z, O dan qaysilarida simmetriya o‘qi, qaysilarida markazi bor?', 'У каких из заглавных латинских букв A, H, N, S, Z, O есть ось симметрии, а у каких — центр?', 'Which of the capital letters A, H, N, S, Z, O have a line of symmetry, and which a centre?'),
        s: L('O‘q: A (vertikal), H (2 ta), O (ko‘p). Markaz: H, N, S, Z, O. Demak, H va O ikkalasiga ega; N, S, Z faqat markazga; A faqat o‘qqa.', 'Ось: A (вертикальная), H (2), O (много). Центр: H, N, S, Z, O. Значит, H и O имеют и то и другое; N, S, Z — только центр; A — только ось.', 'Lines: A (vertical), H (2), O (many). Centre: H, N, S, Z, O. So H and O have both; N, S and Z have only a centre; A has only a line.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Ox ga nisbatan simmetriyada x ni o‘zgartirish.</b> Ox ga nisbatan aks ettirganda nuqta yuqoridan pastga o‘tadi — o‘zgaradigani y.', '<b>При симметрии относительно Ox менять x.</b> При отражении в Ox точка переходит сверху вниз — меняется y.', '<b>Changing x when reflecting in the x-axis.</b> Reflecting in the x-axis moves the point up or down — it is y that changes.'),
      L('<b>Parallelogrammning diagonalini simmetriya o‘qi deb hisoblash.</b> Diagonal faqat romb va kvadratda o‘q bo‘ladi.', '<b>Считать диагональ параллелограмма осью симметрии.</b> Диагональ — ось только у ромба и квадрата.', '<b>Treating a parallelogram’s diagonal as a line of symmetry.</b> A diagonal is a line of symmetry only in a rhombus or square.'),
      L('<b>To‘g‘ri to‘rtburchak diagonallarini o‘q deb sanash.</b> Uning o‘qlari tomonlar o‘rtalari orqali o‘tadi.', '<b>Считать диагонали прямоугольника осями.</b> Его оси проходят через середины сторон.', '<b>Counting a rectangle’s diagonals as lines of symmetry.</b> Its lines go through the midpoints of the sides.'),
      L('<b>Markaziy simmetriyani o‘q simmetriyasi bilan adashtirish.</b> Markaziy simmetriya — 180° li aylanish, ko‘zgu emas: «S» harfi ko‘zguda teskari ko‘rinadi, lekin aylantirilsa o‘zi bo‘lib qoladi.', '<b>Путать центральную симметрию с осевой.</b> Центральная симметрия — поворот на 180°, а не зеркало: «S» в зеркале выглядит перевёрнутой, а при повороте остаётся собой.', '<b>Confusing point and line symmetry.</b> Point symmetry is a 180° turn, not a mirror: “S” looks reversed in a mirror but stays itself when turned.'),
      L('<b>Simmetrik nuqtani o‘qdan boshqa masofada qo‘yish.</b> A va A₁ o‘qdan bir xil masofada bo‘lishi shart.', '<b>Ставить симметричную точку на другом расстоянии от оси.</b> A и A₁ должны быть на одинаковом расстоянии от оси.', '<b>Placing the image at a different distance from the line.</b> A and A₁ must be equally far from it.')
    ] },
    { kind: 'life', h: L('Hayotda simmetriya', 'Симметрия в жизни', 'Symmetry in real life'), p: [
      L('<b>Me’morchilik.</b> Registon maydonidagi uchta madrasa — Ulug‘bek, Sherdor va Tillakori — maydon o‘qiga nisbatan simmetrik joylashgan. Sherdor va Ulug‘bek madrasalari bir-biriga qarama-qarshi turadi. Simmetriya binoga muvozanat va salobat beradi, shuning uchun saroylar, masjidlar va ko‘priklar ko‘pincha o‘qqa nisbatan simmetrik quriladi.', '<b>Архитектура.</b> Три медресе Регистана — Улугбека, Шердор и Тилля-Кари — расположены симметрично относительно оси площади. Медресе Шердор и Улугбека стоят друг напротив друга. Симметрия придаёт зданию равновесие и величие, поэтому дворцы, мечети и мосты часто строят симметричными.', '<b>Architecture.</b> The three madrasahs of the Registan — Ulugh Beg, Sher-Dor and Tilya-Kori — are arranged symmetrically about the square’s axis, with Sher-Dor and Ulugh Beg facing each other. Symmetry gives a building balance and grandeur, which is why palaces, mosques and bridges are often built symmetric.'),
      L('<b>Texnika va tabiat.</b> Samolyot, avtomobil va qayiq o‘qqa nisbatan simmetrik — aks holda ular bir tomonga og‘ib ketadi. Ventilyator parraklari va g‘ildirak markaziy simmetriyaga ega, bu esa aylanishda tebranishni kamaytiradi. Qor parchasi 6 ta simmetriya o‘qiga ega, chunki suv molekulalari olti burchakli panjarada joylashadi.', '<b>Техника и природа.</b> Самолёт, автомобиль и лодка симметричны относительно оси — иначе их уводило бы в сторону. Лопасти вентилятора и колесо имеют центральную симметрию, что уменьшает вибрацию при вращении. У снежинки 6 осей симметрии, потому что молекулы воды выстраиваются в шестиугольную решётку.', '<b>Technology and nature.</b> Planes, cars and boats are symmetric about an axis — otherwise they would pull to one side. Fan blades and wheels have point symmetry, which reduces wobble as they spin. A snowflake has 6 lines of symmetry because water molecules form a hexagonal lattice.'),
      L('<b>Kompyuter</b> grafik dasturlaridagi «aks ettirish» tugmasi aynan (x; y) → (−x; y) formulasini bajaradi.', 'Кнопка «отразить» в графических программах выполняет именно формулу (x; y) → (−x; y).', 'The “flip horizontally” button in graphics software performs exactly the formula (x; y) → (−x; y).')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Ikki parallel o‘qqa nisbatan ketma-ket aks ettirish shaklni siljitadi, ikki kesishuvchi o‘qqa nisbatan esa aylantiradi.', 'Два отражения подряд относительно параллельных осей дают сдвиг, а относительно пересекающихся — поворот.', 'Two reflections in parallel lines give a slide (translation); in crossing lines they give a rotation.'),
      L('Tekislikdagi takrorlanuvchi naqshlarning faqat 17 ta turi bor — va ularning deyarli barchasi islom naqqoshligida uchraydi.', 'Существует всего 17 типов повторяющихся узоров на плоскости — и почти все встречаются в исламском орнаменте.', 'There are only 17 types of repeating wallpaper pattern in the plane — and almost all of them appear in Islamic ornament.'),
      L('«ABBA», «2002» kabi so‘z va sonlar o‘qiga nisbatan simmetrik — ular palindrom deyiladi.', 'Слова и числа вроде «ABBA», «2002» симметричны — их называют палиндромами.', 'Words and numbers such as “ABBA” and “2002” read the same both ways — they are called palindromes.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. B(−4; 7) nuqtaga koordinata boshiga nisbatan simmetrik nuqtani toping.', '1. Найдите точку, симметричную B(−4; 7) относительно начала координат.', '1. Find the image of B(−4; 7) in the origin.'),
      L('2. Muntazam oltiburchakning nechta simmetriya o‘qi bor? Markazi bormi?', '2. Сколько осей симметрии у правильного шестиугольника? Есть ли центр?', '2. How many lines of symmetry does a regular hexagon have? Does it have a centre?'),
      L('3. Teng tomonli uchburchakda simmetriya markazi bormi?', '3. Есть ли центр симметрии у равностороннего треугольника?', '3. Does an equilateral triangle have a centre of symmetry?')
    ], after: [
      L('Javoblar: 1) (4; −7); 2) 6 ta o‘q, markazi bor; 3) yo‘q — 180° ga aylantirsak, uchi pastga qaraydi.', 'Ответы: 1) (4; −7); 2) 6 осей, центр есть; 3) нет — при повороте на 180° вершина окажется внизу.', 'Answers: 1) (4; −7); 2) 6 lines, and yes, it has a centre; 3) no — a 180° turn makes the top vertex point down.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('l ga nisbatan simmetriya: l AA₁ ga perpendikulyar va uni teng ikkiga bo‘ladi.', 'Симметрия относительно l: l перпендикулярна AA₁ и делит её пополам.', 'Symmetry in a line l: l is perpendicular to AA₁ and bisects it.'),
      L('O ga nisbatan simmetriya: O — AA₁ ning o‘rtasi (180° li aylanish).', 'Симметрия относительно O: O — середина AA₁ (поворот на 180°).', 'Symmetry in a point O: O is the midpoint of AA₁ (a 180° turn).'),
      L('Koordinatalarda: Ox → (x; −y), Oy → (−x; y), O → (−x; −y).', 'В координатах: Ox → (x; −y), Oy → (−x; y), O → (−x; −y).', 'In coordinates: x-axis → (x; −y), y-axis → (−x; y), origin → (−x; −y).'),
      L('Parallelogrammda markaz bor; to‘g‘ri to‘rtburchak va rombda markaz va 2 o‘q; kvadratda markaz va 4 o‘q.', 'У параллелограмма есть центр; у прямоугольника и ромба — центр и 2 оси; у квадрата — центр и 4 оси.', 'A parallelogram has a centre; a rectangle and a rhombus have a centre and 2 lines; a square has a centre and 4 lines.'),
      L('Simmetriya masofani saqlaydi va shaklni unga teng shaklga o‘tkazadi.', 'Симметрия сохраняет расстояния и переводит фигуру в равную.', 'Symmetry preserves distance and maps a figure to a congruent one.')
    ] }
  ] });

  // ---------- t8. Yuz tushunchasi. To‘g‘ri to‘rtburchakning yuzi ----------
  T.add(P, 't8', { sections: [
    { kind: 'intro', h: L('Qancha joy egallaydi?', 'Сколько места занимает?', 'How much room does it take?'), p: [
      L('Xonaga gilam olmoqchisiz, devorni bo‘yamoqchisiz yoki dalaga bug‘doy ekmoqchisiz. Har uchala holda ham savol bitta: shakl tekislikda qancha joy egallaydi? Bu miqdor <b>yuz</b> deb ataladi. Perimetr shakl chegarasining uzunligini o‘lchasa, yuz uning «ichini» o‘lchaydi.', 'Вы хотите купить ковёр в комнату, покрасить стену или засеять поле пшеницей. Во всех трёх случаях вопрос один: сколько места фигура занимает на плоскости? Эта величина называется <b>площадью</b>. Периметр измеряет длину границы, а площадь — «внутренность» фигуры.', 'You want to buy a carpet for a room, paint a wall or sow a field with wheat. In all three cases the question is the same: how much of the plane does the figure take up? That amount is called its <b>area</b>. Perimeter measures the length of the boundary; area measures the inside.'),
      L('5-sinfdan bilamizki, to‘g‘ri to‘rtburchak yuzi uzunlik va enining ko‘paytmasiga teng. Endi biz bu formulani shunchaki eslab qolmasdan, yuzning asosiy xossalaridan (aksiomalaridan) <b>keltirib chiqaramiz</b>. Bu poydevor ustiga keyingi mavzularda parallelogramm, uchburchak, trapetsiya va istalgan ko‘pburchak yuzlari quriladi.', 'Из 5 класса мы знаем, что площадь прямоугольника равна произведению длины на ширину. Теперь мы не просто вспомним формулу, а <b>выведем</b> её из основных свойств (аксиом) площади. На этом фундаменте в следующих темах строятся площади параллелограмма, треугольника, трапеции и любого многоугольника.', 'Since grade 5 we have known that a rectangle’s area is length times width. Now we will not just remember the formula but <b>derive</b> it from the basic properties (axioms) of area. On this foundation the next topics build the areas of parallelograms, triangles, trapezia and any polygon.')
    ] },
    { kind: 'def', h: L('Yuzning xossalari', 'Свойства площади', 'Properties of area'), p: [
      L('Har bir ko‘pburchakka musbat son — uning <b>yuzi</b> S mos qo‘yiladi. Yuz quyidagi uchta xossaga bo‘ysunadi:', 'Каждому многоугольнику ставится в соответствие положительное число — его <b>площадь</b> S. Площадь подчиняется трём свойствам:', 'Every polygon is assigned a positive number, its <b>area</b> S. Area obeys three properties:')
    ], list: [
      L('<b>1. Teng shakllarning yuzlari teng.</b> Agar ikki shaklni ustma-ust qo‘yish mumkin bo‘lsa, ular bir xil joy egallaydi.', '<b>1. Равные фигуры имеют равные площади.</b> Если фигуры можно совместить наложением, они занимают одинаковое место.', '<b>1. Congruent figures have equal areas.</b> If two figures can be placed exactly on top of each other, they take up the same room.'),
      L('<b>2. Additivlik.</b> Agar shakl bir-birini qoplamaydigan bo‘laklarga bo‘lingan bo‘lsa, uning yuzi bo‘laklar yuzlari yig‘indisiga teng.', '<b>2. Аддитивность.</b> Если фигура разбита на неперекрывающиеся части, её площадь равна сумме площадей частей.', '<b>2. Additivity.</b> If a figure is split into non-overlapping pieces, its area is the sum of the areas of the pieces.'),
      L('<b>3. Birlik.</b> Tomoni bir o‘lchov birligiga teng kvadratning yuzi 1 ga teng (1 cm², 1 m² …).', '<b>3. Единица.</b> Площадь квадрата со стороной в одну единицу длины равна 1 (1 см², 1 м² …).', '<b>3. Unit.</b> A square with side one unit has area 1 (1 cm², 1 m² …).')
    ], after: [
      L('Yuzlari teng shakllar <b>tengdosh</b> deyiladi. Teng shakllar har doim tengdosh, lekin tengdosh shakllar teng bo‘lishi shart emas: 2 × 8 to‘g‘ri to‘rtburchak va 4 × 4 kvadrat tengdosh (16 birlik), ammo ular turli shakllar.', 'Фигуры с равными площадями называются <b>равновеликими</b>. Равные фигуры всегда равновелики, но равновеликие не обязательно равны: прямоугольник 2 × 8 и квадрат 4 × 4 равновелики (16 единиц), но это разные фигуры.', 'Figures with the same area are called <b>equal in area</b> (equivalent). Congruent figures always have equal areas, but figures with equal areas need not be congruent: a 2 × 8 rectangle and a 4 × 4 square both have area 16, yet they are different shapes.')
    ] },
    { kind: 'history', h: L('Tarixdan: Nil toshqinlari va geometriyaning tug‘ilishi', 'Из истории: разливы Нила и рождение геометрии', 'History: Nile floods and the birth of geometry'), p: [
      L('«Geometriya» so‘zi yunoncha «yer o‘lchash» degani. Yunon tarixchisi Gerodot yozishicha, Misrda har yili Nil toshib, dalalar chegaralarini yuvib ketgan, fir’avn esa soliqni yer maydoniga qarab olgan. Shuning uchun maxsus amaldorlar uchastkalarni qayta o‘lchab, ularning yuzini hisoblashgan. Rind papirusida (taxminan miloddan avvalgi 1650-yil) to‘g‘ri to‘rtburchak, uchburchak va trapetsiya shaklidagi dalalar yuzini topish masalalari bor.', 'Слово «геометрия» по-гречески значит «землемерие». Греческий историк Геродот писал, что в Египте Нил ежегодно разливался и смывал границы полей, а фараон собирал налог по площади земли. Поэтому особые чиновники заново измеряли участки и вычисляли их площадь. В папирусе Ринда (около 1650 г. до н. э.) есть задачи на площадь прямоугольных, треугольных и трапециевидных полей.', 'The word “geometry” means “earth measuring” in Greek. The Greek historian Herodotus wrote that the Nile flooded every year and washed away field boundaries, while the pharaoh taxed land by its area. So special officials re-measured the plots and calculated their areas. The Rhind Papyrus (about 1650 BC) contains problems on the areas of rectangular, triangular and trapezium-shaped fields.'),
      L('Al-Xorazmiy IX asrda «Al-jabr val-muqobala» kitobining geometriya bobida kvadrat, to‘g‘ri to‘rtburchak va boshqa shakllar yuzlarini hisoblash qoidalarini meros taqsimoti va yer o‘lchash masalalari bilan birga bergan. Beruniy esa «Qonuni Mas’udiy» asarida yer maydonlarini va hatto Yer sirtining katta qismlarini o‘lchash bilan shug‘ullangan.', 'Аль-Хорезми в IX веке в геометрической главе книги «Аль-джабр валь-мукабала» дал правила вычисления площадей квадрата, прямоугольника и других фигур вместе с задачами о разделе наследства и измерении земли. А Беруни в «Каноне Масуда» занимался измерением земельных участков и даже больших частей поверхности Земли.', 'In the 9th century al-Khwarizmi, in the geometry chapter of his book on al-jabr, gave rules for the areas of squares, rectangles and other figures, together with problems on inheritance and land measurement. Al-Biruni, in his Mas’udic Canon, worked on measuring plots of land and even large parts of the Earth’s surface.')
    ] },
    { kind: 'rule', h: L('To‘g‘ri to‘rtburchak yuzi: S = ab', 'Площадь прямоугольника: S = ab', 'Area of a rectangle: S = ab'), p: [
      L('<b>Teorema.</b> Tomonlari a va b bo‘lgan to‘g‘ri to‘rtburchakning yuzi <b>S = a · b</b>. Kvadrat uchun (a = b) S = a².', '<b>Теорема.</b> Площадь прямоугольника со сторонами a и b равна <b>S = a · b</b>. Для квадрата (a = b) S = a².', '<b>Theorem.</b> A rectangle with sides a and b has area <b>S = a · b</b>. For a square (a = b), S = a².'),
      L('<b>Natural sonlar uchun g‘oya.</b> Agar a = 5 va b = 3 bo‘lsa, to‘g‘ri to‘rtburchakni 3 qator, har birida 5 tadan birlik kvadratlarga bo‘lish mumkin. 3-xossaga ko‘ra har biri 1 ga teng, 2-xossaga ko‘ra jami 5 · 3 = 15.', '<b>Идея для натуральных чисел.</b> Если a = 5 и b = 3, прямоугольник разбивается на 3 ряда по 5 единичных квадратов. По свойству 3 каждый равен 1, по свойству 2 всего 5 · 3 = 15.', '<b>Idea for whole numbers.</b> If a = 5 and b = 3, the rectangle splits into 3 rows of 5 unit squares. By property 3 each has area 1, and by property 2 the total is 5 · 3 = 15.'),
      L('<b>Kasr sonlar uchun.</b> Birlik kvadratni n × n mayda kvadratlarga bo‘lsak, har birining yuzi 1/n² bo‘ladi (ular teng va jami 1). Agar a = p/n, b = q/n bo‘lsa, to‘g‘ri to‘rtburchakka p · q ta mayda kvadrat sig‘adi: S = pq/n² = a · b. Ixtiyoriy (irratsional) uzunliklar uchun esa bu tenglik yaqinlashish orqali isbotlanadi.', '<b>Для дробных чисел.</b> Разобьём единичный квадрат на n × n маленьких квадратов, площадь каждого 1/n² (они равны и в сумме дают 1). Если a = p/n, b = q/n, то в прямоугольник помещается p · q маленьких квадратов: S = pq/n² = a · b. Для произвольных (иррациональных) длин равенство доказывается приближениями.', '<b>For fractions.</b> Split the unit square into n × n small squares; each has area 1/n² (they are congruent and total 1). If a = p/n and b = q/n, the rectangle holds p · q small squares: S = pq/n² = a · b. For arbitrary (irrational) lengths the formula is proved by approximation.'),
      L('Muhim: a va b <b>bir xil birlikda</b> bo‘lishi kerak, yuz birligi esa shu birlikning kvadrati.', 'Важно: a и b должны быть в <b>одних единицах</b>, а единица площади — квадрат этой единицы.', 'Important: a and b must be in the <b>same unit</b>, and the area unit is the square of that unit.')
    ] },
    { kind: 'table', h: L('Yuz birliklari', 'Единицы площади', 'Units of area'), table: {
      head: [L('Birlik', 'Единица', 'Unit'), L('Qiymati', 'Значение', 'Equals'), L('Qayerda ishlatiladi', 'Где используется', 'Used for')],
      rows: [
        ['1 cm²', '100 mm²', L('daftar varag‘i, rasm', 'тетрадный лист, рисунок', 'notebook pages, drawings')],
        ['1 dm²', '100 cm²', L('plitka, kitob muqovasi', 'плитка, обложка книги', 'tiles, book covers')],
        ['1 m²', L('100 dm² = 10 000 cm²', '100 дм² = 10 000 см²', '100 dm² = 10 000 cm²'), L('xona, devor, gilam', 'комната, стена, ковёр', 'rooms, walls, carpets')],
        [L('1 ar (sotix)', '1 ар (сотка)', '1 are'), '100 m²', L('tomorqa, hovli', 'приусадебный участок', 'garden plots')],
        [L('1 gektar', '1 гектар', '1 hectare'), L('100 ar = 10 000 m²', '100 ар = 10 000 м²', '100 ares = 10 000 m²'), L('dala, bog‘, stadion', 'поле, сад, стадион', 'fields, orchards, stadiums')],
        ['1 km²', L('100 ga = 1 000 000 m²', '100 га = 1 000 000 м²', '100 ha = 1 000 000 m²'), L('shahar, viloyat, davlat', 'город, область, страна', 'cities, regions, countries')]
      ] }, after: [
      L('Diqqat: uzunlik birliklari 10 marta farq qilsa, yuz birliklari 100 marta farq qiladi, chunki 1 dm² = 10 cm · 10 cm = 100 cm².', 'Внимание: если единицы длины отличаются в 10 раз, единицы площади отличаются в 100 раз, ведь 1 дм² = 10 см · 10 см = 100 см².', 'Careful: if length units differ by a factor of 10, area units differ by a factor of 100, because 1 dm² = 10 cm · 10 cm = 100 cm².')
    ] },
    { kind: 'steps', h: L('Yuz masalasini yechish tartibi', 'Порядок решения задач на площадь', 'How to solve an area problem'), list: [
      L('1. Barcha uzunliklarni bir xil birlikka keltiring.', '1. Переведите все длины в одни единицы.', '1. Convert all lengths to the same unit.'),
      L('2. Murakkab shaklni to‘g‘ri to‘rtburchaklarga bo‘ling yoki uni katta to‘g‘ri to‘rtburchakdan «kesib olingan» deb qarang.', '2. Разбейте сложную фигуру на прямоугольники или представьте её как большой прямоугольник с вырезом.', '2. Split a complicated shape into rectangles, or view it as a large rectangle with a piece cut out.'),
      L('3. Har bir bo‘lak yuzini S = ab bilan toping.', '3. Найдите площадь каждой части по S = ab.', '3. Find each piece’s area with S = ab.'),
      L('4. Bo‘laklarni qo‘shing (yoki kesilgan qismni ayiring).', '4. Сложите части (или вычтите вырезанную).', '4. Add the pieces (or subtract the cut-out part).'),
      L('5. Javobni kvadrat birliklarda yozing va kerak bo‘lsa boshqa birlikka o‘tkazing.', '5. Запишите ответ в квадратных единицах и при необходимости переведите.', '5. Give the answer in square units and convert if needed.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Xona uzunligi 5,2 m, eni 3,5 m. Polga necha m² laminat kerak?', 'Длина комнаты 5,2 м, ширина 3,5 м. Сколько м² ламината нужно на пол?', 'A room is 5.2 m long and 3.5 m wide. How many m² of laminate are needed for the floor?'),
        s: L('S = 5,2 · 3,5 = 18,2 m². Amalda kesish chiqindisi uchun taxminan 10 % qo‘shiladi: ≈ 20 m².', 'S = 5,2 · 3,5 = 18,2 м². На практике добавляют около 10 % на обрезки: ≈ 20 м².', 'S = 5.2 · 3.5 = 18.2 m². In practice about 10% is added for offcuts: ≈ 20 m².') },
      { q: L('Kvadratning perimetri 36 cm. Uning yuzini toping.', 'Периметр квадрата 36 см. Найдите его площадь.', 'A square has perimeter 36 cm. Find its area.'),
        s: L('Tomon a = 36 : 4 = 9 cm. S = 9² = 81 cm².', 'Сторона a = 36 : 4 = 9 см. S = 9² = 81 см².', 'Side a = 36 ÷ 4 = 9 cm. S = 9² = 81 cm².') },
      { q: L('To‘g‘ri to‘rtburchakning yuzi 72 cm², bir tomoni ikkinchisidan 2 marta uzun. Tomonlarini toping.', 'Площадь прямоугольника 72 см², одна сторона в 2 раза длиннее другой. Найдите стороны.', 'A rectangle has area 72 cm² and one side is twice the other. Find the sides.'),
        s: L('Tomonlar x va 2x. 2x² = 72, x² = 36, x = 6. Tomonlar 6 cm va 12 cm.', 'Стороны x и 2x. 2x² = 72, x² = 36, x = 6. Стороны 6 см и 12 см.', 'Let the sides be x and 2x. 2x² = 72, x² = 36, x = 6. The sides are 6 cm and 12 cm.') },
      { q: L('«L» shaklidagi xona: 8 m × 6 m to‘g‘ri to‘rtburchakdan bir burchagida 3 m × 2 m qism kesilgan. Yuzini toping.', 'Комната в форме «Г»: из прямоугольника 8 м × 6 м в углу вырезан участок 3 м × 2 м. Найдите площадь.', 'An L-shaped room is an 8 m × 6 m rectangle with a 3 m × 2 m piece cut from one corner. Find its area.'),
        s: L('Kesish usuli: 8 · 6 − 3 · 2 = 48 − 6 = 42 m². Boshqa usul: shaklni ikki to‘g‘ri to‘rtburchakka bo‘lish ham xuddi shu 42 m² ni beradi — additivlik xossasi ishlayapti.', 'Способ вычитания: 8 · 6 − 3 · 2 = 48 − 6 = 42 м². Если разбить фигуру на два прямоугольника, получится те же 42 м² — работает аддитивность.', 'Subtraction: 8 · 6 − 3 · 2 = 48 − 6 = 42 m². Splitting the shape into two rectangles gives the same 42 m² — additivity at work.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Turli birliklarni ko‘paytirish.</b> 2 m · 50 cm ≠ 100. Avval 50 cm = 0,5 m ga o‘tkazing: S = 1 m².', '<b>Умножать разные единицы.</b> 2 м · 50 см ≠ 100. Сначала 50 см = 0,5 м: S = 1 м².', '<b>Multiplying different units.</b> 2 m · 50 cm ≠ 100. First convert 50 cm = 0.5 m: S = 1 m².'),
      L('<b>1 m² = 100 cm² deb o‘ylash.</b> To‘g‘risi 1 m² = 10 000 cm².', '<b>Думать, что 1 м² = 100 см².</b> На самом деле 1 м² = 10 000 см².', '<b>Thinking 1 m² = 100 cm².</b> In fact 1 m² = 10 000 cm².'),
      L('<b>Perimetr va yuzni adashtirish.</b> Perimetr — uzunlik (m), yuz — kvadrat birlik (m²). Perimetri teng shakllarning yuzi har xil bo‘lishi mumkin.', '<b>Путать периметр и площадь.</b> Периметр — длина (м), площадь — квадратные единицы (м²). При равных периметрах площади могут быть разными.', '<b>Confusing perimeter and area.</b> Perimeter is a length (m); area is in square units (m²). Shapes with equal perimeters can have different areas.'),
      L('<b>Tomon 2 marta oshsa, yuz ham 2 marta oshadi deyish.</b> Kvadrat tomoni 2 marta oshsa, yuz 4 marta oshadi.', '<b>Думать, что при удвоении стороны площадь удваивается.</b> Если сторону квадрата увеличить в 2 раза, площадь вырастет в 4 раза.', '<b>Thinking area doubles when the side doubles.</b> Double a square’s side and its area grows 4 times.'),
      L('<b>Kesilgan qismni ayirishni unutish.</b> «L» shaklidagi yoki teshikli shaklda avval butun to‘g‘ri to‘rtburchak yuzini toping, keyin ortiqcha qismni ayiring. Chizmani har doim bo‘laklarga ajratib, har bir bo‘lakni alohida belgilang.', '<b>Забывать вычесть вырезанную часть.</b> Для фигуры в форме «Г» или с отверстием сначала найдите площадь всего прямоугольника, затем вычтите лишнее. Всегда делите чертёж на части и подписывайте каждую.', '<b>Forgetting to subtract the cut-out part.</b> For an L-shape or a shape with a hole, first find the whole rectangle’s area, then subtract the missing piece. Always split the drawing into parts and label each one.')
    ] },
    { kind: 'life', h: L('Hayotda yuz', 'Площадь в жизни', 'Area in real life'), p: [
      L('<b>Ta’mir.</b> Devorga bo‘yoq olishdan oldin devor yuzini hisoblaymiz va eshik hamda derazalar yuzini ayiramiz. Bo‘yoq bankasida odatda «1 litr — 8–10 m²» deb yoziladi. Gilam, plitka, oboy, laminat — hammasi kvadrat metrda sotiladi.', '<b>Ремонт.</b> Перед покупкой краски вычисляем площадь стены и вычитаем площадь дверей и окон. На банке обычно пишут «1 литр — 8–10 м²». Ковры, плитка, обои, ламинат — всё продаётся в квадратных метрах.', '<b>Home improvement.</b> Before buying paint we calculate the wall’s area and subtract doors and windows. Tins usually say “1 litre covers 8–10 m²”. Carpets, tiles, wallpaper and laminate are all sold by the square metre.'),
      L('<b>Qishloq xo‘jaligi.</b> Fermerlar ekin maydonini gektarda o‘lchaydi; hosildorlik «sentner/gektar»da hisoblanadi. Tomorqa esa sotixda (1 sotix = 100 m²) o‘lchanadi. <b>Ko‘chmas mulk</b> narxi ham bir kvadrat metr narxiga qarab belgilanadi.', '<b>Сельское хозяйство.</b> Фермеры измеряют посевы в гектарах, урожайность — в центнерах с гектара. Приусадебный участок меряют сотками (1 сотка = 100 м²). Цена <b>недвижимости</b> тоже считается за квадратный метр.', '<b>Farming.</b> Farmers measure crop land in hectares and yield in centners per hectare. Garden plots are measured in “sotkas” (1 sotka = 100 m²). <b>Property</b> prices are also quoted per square metre.'),
      L('<b>Quyosh panellari</b> qancha energiya berishi ularning yuziga bog‘liq: har bir kvadrat metr panel quyoshli kunda taxminan 150–200 vatt elektr beradi.', 'Сколько энергии дают <b>солнечные панели</b>, зависит от их площади: каждый квадратный метр в солнечный день даёт примерно 150–200 ватт.', 'How much energy <b>solar panels</b> produce depends on their area: each square metre gives roughly 150–200 watts on a sunny day.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Futbol maydoni taxminan 0,7 gektar; O‘zbekiston maydoni esa taxminan 449 ming km².', 'Футбольное поле — примерно 0,7 гектара; площадь Узбекистана — около 449 тысяч км².', 'A football pitch is about 0.7 hectares; Uzbekistan covers about 449 thousand km².'),
      L('Perimetri 20 cm bo‘lgan to‘g‘ri to‘rtburchaklar orasida eng katta yuz 5 × 5 kvadratda: 25 cm².', 'Среди прямоугольников с периметром 20 см наибольшая площадь у квадрата 5 × 5: 25 см².', 'Among rectangles with perimeter 20 cm, the largest area belongs to the 5 × 5 square: 25 cm².'),
      L('Inson terisining yuzi taxminan 1,7–2 m², o‘pkalardagi alveolalar yuzi esa tennis kortining yarmiga teng!', 'Площадь кожи человека около 1,7–2 м², а площадь альвеол лёгких — с половину теннисного корта!', 'Human skin has an area of about 1.7–2 m², while the alveoli in the lungs cover about half a tennis court!')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. 3,5 ga necha m²?', '1. Сколько м² в 3,5 га?', '1. How many m² are in 3.5 ha?'),
      L('2. Kvadrat yuzi 49 cm². Perimetrini toping.', '2. Площадь квадрата 49 см². Найдите периметр.', '2. A square has area 49 cm². Find its perimeter.'),
      L('3. To‘g‘ri to‘rtburchak tomonlari 3 marta oshirilsa, yuzi necha marta oshadi?', '3. Во сколько раз увеличится площадь прямоугольника, если обе стороны увеличить в 3 раза?', '3. If both sides of a rectangle are tripled, how many times larger is the area?')
    ], after: [
      L('Javoblar: 1) 35 000 m²; 2) tomon 7 cm, P = 28 cm; 3) 9 marta.', 'Ответы: 1) 35 000 м²; 2) сторона 7 см, P = 28 см; 3) в 9 раз.', 'Answers: 1) 35 000 m²; 2) side 7 cm, P = 28 cm; 3) 9 times.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Yuz — shakl tekislikda egallagan joy miqdori; u musbat son.', 'Площадь — величина места, занимаемого фигурой на плоскости; это положительное число.', 'Area is the amount of the plane a figure covers; it is a positive number.'),
      L('Xossalar: teng shakllar yuzi teng; bo‘laklar yuzlari qo‘shiladi; birlik kvadrat yuzi 1.', 'Свойства: равные фигуры имеют равные площади; площади частей складываются; единичный квадрат имеет площадь 1.', 'Properties: congruent figures have equal areas; areas of pieces add up; the unit square has area 1.'),
      L('Tengdosh shakllar — yuzlari teng shakllar (ular teng bo‘lishi shart emas).', 'Равновеликие фигуры — фигуры с равными площадями (не обязательно равные).', 'Figures equal in area need not be congruent.'),
      L('To‘g‘ri to‘rtburchak: S = ab; kvadrat: S = a².', 'Прямоугольник: S = ab; квадрат: S = a².', 'Rectangle: S = ab; square: S = a².'),
      L('1 m² = 10 000 cm², 1 ar = 100 m², 1 ga = 10 000 m².', '1 м² = 10 000 см², 1 ар = 100 м², 1 га = 10 000 м².', '1 m² = 10 000 cm², 1 are = 100 m², 1 ha = 10 000 m².')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-2';

  // ---------- t9. Parallelogramm va uchburchakning yuzi ----------
  T.add(P, 't9', { sections: [
    { kind: 'intro', h: L('Kesib, ko‘chirib, yig‘ib', 'Отрезать, перенести, сложить', 'Cut, move, reassemble'), p: [
      L('Qog‘ozdan parallelogramm qirqib oling. Uning bir uchidan qarama-qarshi tomonga balandlik tushiring va shu chiziq bo‘ylab qaychi bilan kichik uchburchakni kesib oling. Endi bu uchburchakni parallelogrammning narigi tomoniga yopishtiring. Nima hosil bo‘ldi? To‘g‘ri to‘rtburchak! Qog‘oz ham yo‘qolmadi, ham qo‘shilmadi — demak, yuz o‘zgarmadi.', 'Вырежьте из бумаги параллелограмм. Опустите из вершины высоту на противоположную сторону и отрежьте ножницами по ней маленький треугольник. Теперь приложите его к другой стороне параллелограмма. Что получилось? Прямоугольник! Бумага не пропала и не добавилась — значит, площадь не изменилась.', 'Cut a parallelogram out of paper. Drop a height from one vertex to the opposite side and snip off the small triangle along it. Now stick that triangle onto the other end of the parallelogram. What do you get? A rectangle! No paper was lost or added, so the area did not change.'),
      L('Bu oddiy tajriba parallelogramm yuzi formulasining butun isbotini o‘z ichiga oladi. Undan keyin esa bitta diagonal orqali uchburchak yuzini ham topamiz. Uchburchak yuzi formulasi — geometriyaning eng ko‘p ishlatiladigan formulalaridan biri, chunki har qanday ko‘pburchakni uchburchaklarga bo‘lish mumkin.', 'В этом простом опыте спрятано всё доказательство формулы площади параллелограмма. А затем с помощью одной диагонали найдём и площадь треугольника. Формула площади треугольника — одна из самых используемых в геометрии, ведь любой многоугольник можно разрезать на треугольники.', 'This simple experiment contains the whole proof of the formula for a parallelogram’s area. Then, with a single diagonal, we will find the area of a triangle too. The triangle area formula is one of the most used in geometry, because any polygon can be cut into triangles.')
    ] },
    { kind: 'def', h: L('Asos va balandlik', 'Основание и высота', 'Base and height'), p: [
      L('Parallelogramm yoki uchburchak yuzini topish uchun ikki miqdor kerak: <b>asos</b> — tanlangan tomon a, va unga tushirilgan <b>balandlik</b> h — qarama-qarshi uchdan (yoki tomondan) asos yotgan to‘g‘ri chiziqqa perpendikulyar. Balandlik va asos <b>mos</b> bo‘lishi shart: h aynan a tomonga tushirilgan bo‘lishi kerak.', 'Для площади параллелограмма или треугольника нужны две величины: <b>основание</b> — выбранная сторона a, и проведённая к ней <b>высота</b> h — перпендикуляр из противоположной вершины (или стороны) на прямую, содержащую основание. Основание и высота должны быть <b>соответствующими</b>: h проведена именно к стороне a.', 'To find the area of a parallelogram or triangle we need two quantities: a <b>base</b> — a chosen side a — and the <b>height</b> h to it — the perpendicular from the opposite vertex (or side) to the line containing the base. The base and height must <b>match</b>: h must be drawn to side a itself.'),
      L('Uchburchakning uchta balandligi bor, har bir tomonga bittadan. O‘tmas burchakli uchburchakda ikki balandlik shakl tashqarisiga tushadi — asosni davom ettirish kerak bo‘ladi. To‘g‘ri burchakli uchburchakda esa ikki katet bir-biriga balandlik bo‘lib xizmat qiladi.', 'У треугольника три высоты, по одной к каждой стороне. В тупоугольном треугольнике две высоты падают вне фигуры — основание приходится продолжать. В прямоугольном треугольнике два катета служат высотами друг к другу.', 'A triangle has three heights, one to each side. In an obtuse triangle two of the heights fall outside the figure — you must extend the base. In a right triangle the two legs serve as heights to each other.')
    ] },
    { kind: 'history', h: L('Tarixdan: Misr, Yevklid va Geron', 'Из истории: Египет, Евклид и Герон', 'History: Egypt, Euclid and Heron'), p: [
      L('Rind papirusida uchburchak shaklidagi yer uchastkasi yuzini «asosning yarmini balandlikka ko‘paytirish» orqali topish masalasi bor — bu bizning formulamizning o‘zi. Yevklid «Negizlar»ning I kitobida bir asosda va bir xil parallel chiziqlar orasida yotgan parallelogrammlar tengdosh ekanini, uchburchak esa shunday parallelogrammning yarmi ekanini isbotlagan.', 'В папирусе Ринда есть задача о площади треугольного участка: «половину основания умножить на высоту» — это наша формула. Евклид в I книге «Начал» доказал, что параллелограммы на одном основании между одними параллельными равновелики, а треугольник — половина такого параллелограмма.', 'The Rhind Papyrus has a problem on the area of a triangular plot: “take half the base times the height” — exactly our formula. In Book I of the Elements Euclid proved that parallelograms on the same base between the same parallels have equal areas, and that a triangle is half of such a parallelogram.'),
      L('I asrda Iskandariyada yashagan muhandis <b>Geron</b> uchburchak yuzini balandliksiz, faqat uchta tomon orqali topish formulasini bergan: S = √(p(p − a)(p − b)(p − c)), bunda p — yarim perimetr. Bu formulani 9-sinfda isbotlaymiz. <b>Beruniy</b> esa uchburchak yuzini hisoblashning bir nechta usullarini taqqoslab, Geron formulasining o‘z isbotini ham bergan.', 'Инженер <b>Герон</b>, живший в I веке в Александрии, дал формулу площади треугольника без высоты, только по трём сторонам: S = √(p(p − a)(p − b)(p − c)), где p — полупериметр. Её мы докажем в 9 классе. <b>Беруни</b> сравнивал несколько способов вычисления площади треугольника и дал своё доказательство формулы Герона.', 'The engineer <b>Heron</b>, who lived in Alexandria in the 1st century AD, gave a formula for a triangle’s area from its three sides alone, without the height: S = √(p(p − a)(p − b)(p − c)), where p is the half-perimeter. We will prove it in grade 9. <b>Al-Biruni</b> compared several ways of calculating a triangle’s area and gave his own proof of Heron’s formula.')
    ] },
    { kind: 'rule', h: L('Parallelogramm yuzi: S = a · h', 'Площадь параллелограмма: S = a · h', 'Parallelogram area: S = a · h'), p: [
      L('<b>Teorema.</b> Parallelogrammning yuzi uning tomoni va shu tomonga tushirilgan balandlik ko‘paytmasiga teng: <b>S = a · h</b>.', '<b>Теорема.</b> Площадь параллелограмма равна произведению стороны на проведённую к ней высоту: <b>S = a · h</b>.', '<b>Theorem.</b> The area of a parallelogram equals a side times the height to that side: <b>S = a · h</b>.'),
      L('<b>Isbot.</b> ABCD parallelogrammda AD = a asos. B dan BH ⊥ AD, C dan CK ⊥ AD davomiga balandliklar tushiramiz; BH = CK = h. To‘g‘ri burchakli △ABH va △DCK teng (gipotenuzalar AB = DC, katetlar BH = CK). Parallelogramm = trapetsiya HBCD + △ABH; to‘g‘ri to‘rtburchak HBCK = trapetsiya HBCD + △DCK. Uchburchaklar teng bo‘lgani uchun yuzlar teng: S = HK · h = a · h, chunki HK = BC = a.', '<b>Доказательство.</b> В параллелограмме ABCD основание AD = a. Опустим высоты BH ⊥ AD и CK на продолжение AD; BH = CK = h. Прямоугольные △ABH и △DCK равны (гипотенузы AB = DC, катеты BH = CK). Параллелограмм = трапеция HBCD + △ABH; прямоугольник HBCK = трапеция HBCD + △DCK. Треугольники равны, значит площади равны: S = HK · h = a · h, так как HK = BC = a.', '<b>Proof.</b> In parallelogram ABCD let AD = a be the base. Drop heights BH ⊥ AD and CK onto the extension of AD; BH = CK = h. The right triangles △ABH and △DCK are congruent (hypotenuses AB = DC, legs BH = CK). Parallelogram = trapezium HBCD + △ABH; rectangle HBCK = trapezium HBCD + △DCK. Since the triangles are congruent, the areas are equal: S = HK · h = a · h, because HK = BC = a.'),
      L('<b>Natija.</b> Bir xil asosga va bir xil balandlikka ega barcha parallelogrammlar tengdosh — ular qanchalik «qiyshaygan» bo‘lmasin.', '<b>Следствие.</b> Все параллелограммы с одинаковыми основанием и высотой равновелики — как бы сильно они ни были «скошены».', '<b>Consequence.</b> All parallelograms with the same base and height have equal areas, however much they lean.'),
      L('Parallelogrammda ikki juft asos-balandlik bor: S = a · hₐ = b · h_b. Bundan kalta tomonga uzunroq balandlik tushishi kelib chiqadi.', 'У параллелограмма две пары основание-высота: S = a · hₐ = b · h_b. Отсюда к меньшей стороне проведена большая высота.', 'A parallelogram has two base-height pairs: S = a · hₐ = b · h_b. So the shorter side has the longer height.')
    ] },
    { kind: 'rule', h: L('Uchburchak yuzi: S = ½ a h', 'Площадь треугольника: S = ½ a h', 'Triangle area: S = ½ a h'), p: [
      L('<b>Teorema.</b> Uchburchakning yuzi uning tomoni va shu tomonga tushirilgan balandlik ko‘paytmasining yarmiga teng: <b>S = ½ · a · h</b>.', '<b>Теорема.</b> Площадь треугольника равна половине произведения стороны на проведённую к ней высоту: <b>S = ½ · a · h</b>.', '<b>Theorem.</b> The area of a triangle is half a side times the height to that side: <b>S = ½ · a · h</b>.'),
      L('<b>Isbot.</b> ABC uchburchakni olib, B uchidan AC ga parallel, C uchidan AB ga parallel to‘g‘ri chiziqlar o‘tkazamiz. Ular D nuqtada kesishadi va ABDC parallelogramm hosil bo‘ladi. BC diagonal uni ikkita teng uchburchakka bo‘ladi (△ABC = △DCB, uch tomon bo‘yicha). Demak, S△ = ½ · S▱ = ½ · a · h.', '<b>Доказательство.</b> Возьмём △ABC и проведём через B прямую, параллельную AC, а через C — параллельную AB. Они пересекутся в точке D, получится параллелограмм ABDC. Диагональ BC делит его на два равных треугольника (△ABC = △DCB по трём сторонам). Значит, S△ = ½ · S▱ = ½ · a · h.', '<b>Proof.</b> Take △ABC and draw a line through B parallel to AC and a line through C parallel to AB. They meet at D, forming parallelogram ABDC. Diagonal BC splits it into two congruent triangles (△ABC ≅ △DCB by three sides). So S△ = ½ · S▱ = ½ · a · h.')
    ], list: [
      L('<b>To‘g‘ri burchakli uchburchak:</b> S = ½ · a · b, bu yerda a va b — katetlar.', '<b>Прямоугольный треугольник:</b> S = ½ · a · b, где a и b — катеты.', '<b>Right triangle:</b> S = ½ · a · b, where a and b are the legs.'),
      L('<b>Asoslari teng bo‘lgan uchburchaklar</b> yuzlarining nisbati balandliklar nisbatiga teng; balandliklari teng bo‘lsa — asoslar nisbatiga teng.', '<b>Площади треугольников с равными основаниями</b> относятся как высоты; с равными высотами — как основания.', '<b>Triangles with equal bases</b> have areas in the ratio of their heights; with equal heights, in the ratio of their bases.'),
      L('<b>Mediana</b> uchburchakni ikkita tengdosh uchburchakka bo‘ladi (asoslari teng, balandligi umumiy).', '<b>Медиана</b> делит треугольник на два равновеликих (основания равны, высота общая).', 'A <b>median</b> splits a triangle into two triangles of equal area (equal bases, common height).')
    ] },
    { kind: 'steps', h: L('Yuzni topish algoritmi', 'Алгоритм нахождения площади', 'Area algorithm'), list: [
      L('1. Shaklni aniqlang: parallelogramm yoki uchburchak.', '1. Определите фигуру: параллелограмм или треугольник.', '1. Identify the figure: parallelogram or triangle.'),
      L('2. Balandlik berilgan tomonni asos qilib oling — ular mos bo‘lishi kerak.', '2. Возьмите за основание ту сторону, к которой дана высота — они должны соответствовать.', '2. Take as base the side whose height is given — they must match.'),
      L('3. Balandlik berilmagan bo‘lsa, uni to‘g‘ri burchakli uchburchakdan toping (masalan, 30° li burchak qarshisidagi katet gipotenuzaning yarmi).', '3. Если высота не дана, найдите её из прямоугольного треугольника (например, катет против угла 30° равен половине гипотенузы).', '3. If no height is given, find it from a right triangle (for example, the leg opposite 30° is half the hypotenuse).'),
      L('4. Formulani qo‘llang: parallelogramm S = ah, uchburchak S = ½ah.', '4. Примените формулу: параллелограмм S = ah, треугольник S = ½ah.', '4. Apply the formula: parallelogram S = ah, triangle S = ½ah.'),
      L('5. Ikkinchi balandlik so‘ralsa, yuzni boshqa tomonga bo‘ling: h₂ = S : b (uchburchakda h₂ = 2S : b).', '5. Если нужна вторая высота, разделите площадь на другую сторону: h₂ = S : b (в треугольнике h₂ = 2S : b).', '5. For a second height, divide the area by the other side: h₂ = S ÷ b (in a triangle h₂ = 2S ÷ b).')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Parallelogramm tomoni 12 cm, unga tushirilgan balandlik 5 cm. Yuzini toping.', 'Сторона параллелограмма 12 см, высота к ней 5 см. Найдите площадь.', 'A parallelogram has a side of 12 cm with height 5 cm to it. Find its area.'),
        s: L('S = 12 · 5 = 60 cm².', 'S = 12 · 5 = 60 см².', 'S = 12 · 5 = 60 cm².') },
      { q: L('Parallelogramm tomonlari 10 cm va 8 cm, ular orasidagi burchak 30°. Yuzini toping.', 'Стороны параллелограмма 10 см и 8 см, угол между ними 30°. Найдите площадь.', 'A parallelogram has sides 10 cm and 8 cm with a 30° angle between them. Find its area.'),
        s: L('8 cm li tomon uchidan 10 cm li tomonga balandlik tushiramiz. To‘g‘ri burchakli uchburchakda gipotenuza 8 cm, 30° qarshisidagi katet h = 8 : 2 = 4 cm. S = 10 · 4 = 40 cm².', 'Опустим высоту из конца стороны 8 см на сторону 10 см. В прямоугольном треугольнике гипотенуза 8 см, катет против 30° h = 8 : 2 = 4 см. S = 10 · 4 = 40 см².', 'Drop a height from the end of the 8 cm side onto the 10 cm side. In the right triangle the hypotenuse is 8 cm and the leg opposite 30° is h = 8 ÷ 2 = 4 cm. S = 10 · 4 = 40 cm².') },
      { q: L('To‘g‘ri burchakli uchburchak katetlari 6 cm va 8 cm, gipotenuzasi 10 cm. Gipotenuzaga tushirilgan balandlikni toping.', 'Катеты прямоугольного треугольника 6 см и 8 см, гипотенуза 10 см. Найдите высоту к гипотенузе.', 'A right triangle has legs 6 cm and 8 cm and hypotenuse 10 cm. Find the height to the hypotenuse.'),
        s: L('Yuz katetlar orqali: S = ½ · 6 · 8 = 24 cm². Yuz gipotenuza orqali: S = ½ · 10 · h. 24 = 5h, h = 4,8 cm. Bu «yuzni ikki usulda yozish» — juda foydali usul.', 'Площадь через катеты: S = ½ · 6 · 8 = 24 см². Через гипотенузу: S = ½ · 10 · h. 24 = 5h, h = 4,8 см. Это приём «площадь двумя способами» — очень полезный.', 'Area from the legs: S = ½ · 6 · 8 = 24 cm². Area from the hypotenuse: S = ½ · 10 · h. So 24 = 5h and h = 4.8 cm. This “area two ways” trick is very useful.') },
      { q: L('Parallelogramm tomonlari 15 cm va 10 cm, katta tomonga tushirilgan balandlik 6 cm. Kichik tomonga tushirilgan balandlikni toping.', 'Стороны параллелограмма 15 см и 10 см, высота к большей стороне 6 см. Найдите высоту к меньшей.', 'A parallelogram has sides 15 cm and 10 cm, and the height to the longer side is 6 cm. Find the height to the shorter side.'),
        s: L('S = 15 · 6 = 90 cm². h₂ = 90 : 10 = 9 cm. Kalta tomonga uzunroq balandlik tushdi — kutilganidek.', 'S = 15 · 6 = 90 см². h₂ = 90 : 10 = 9 см. К меньшей стороне — большая высота, как и ожидалось.', 'S = 15 · 6 = 90 cm². h₂ = 90 ÷ 10 = 9 cm. The shorter side has the longer height, as expected.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Yon tomonni balandlik o‘rniga olish.</b> 10 va 8 tomonli parallelogramm yuzi 80 emas! Balandlik qiya tomondan qisqa.', '<b>Брать боковую сторону вместо высоты.</b> Площадь параллелограмма со сторонами 10 и 8 — не 80! Высота короче наклонной стороны.', '<b>Using the slanted side instead of the height.</b> A parallelogram with sides 10 and 8 does not have area 80! The height is shorter than the slanted side.'),
      L('<b>Uchburchakda ½ ni unutish.</b> Uchburchak — parallelogrammning yarmi.', '<b>Забывать ½ для треугольника.</b> Треугольник — половина параллелограмма.', '<b>Forgetting the ½ for a triangle.</b> A triangle is half a parallelogram.'),
      L('<b>Asos va balandlikni aralashtirish.</b> h boshqa tomonga tushirilgan bo‘lsa, uni bu tomonga ko‘paytirib bo‘lmaydi.', '<b>Смешивать основание и высоту.</b> Если h проведена к другой стороне, умножать её на эту сторону нельзя.', '<b>Mixing bases and heights.</b> If h belongs to a different side, you cannot multiply it by this one.'),
      L('<b>O‘tmas burchakli uchburchakda balandlik yo‘q deb o‘ylash.</b> U bor, faqat tashqariga — asosning davomiga tushadi.', '<b>Думать, что у тупоугольного треугольника нет высоты.</b> Она есть, только падает снаружи — на продолжение основания.', '<b>Thinking an obtuse triangle has no height.</b> It does — it just falls outside, onto the extended base.')
    ] },
    { kind: 'life', h: L('Hayotda', 'В жизни', 'In real life'), p: [
      L('<b>Tom va yelkanlar.</b> Uyning uchburchak shaklidagi frontoni (tom ostidagi devor qismi)ni qoplash uchun material miqdori ½ · asos · balandlik bilan hisoblanadi. Yelkanli qayiq yelkani ham uchburchak: uning yuzi qancha katta bo‘lsa, shamol shuncha kuchli itaradi.', '<b>Крыши и паруса.</b> Материал для треугольного фронтона дома считают по ½ · основание · высота. Парус лодки — тоже треугольник: чем больше его площадь, тем сильнее толкает ветер.', '<b>Roofs and sails.</b> The material for the triangular gable of a house is worked out as ½ · base · height. A boat’s sail is a triangle too: the larger its area, the harder the wind pushes.'),
      L('<b>Yer o‘lchash va xaritalar.</b> Geodezistlar katta maydonni uchburchaklar to‘riga bo‘ladi (triangulyatsiya) va har birining yuzini qo‘shib chiqadi. Bu usul bilan XIX asrda butun mamlakatlar xaritasi tuzilgan. <b>Kompyuter o‘yinlari</b>dagi 3D modellar ham millionlab mayda uchburchaklardan yasaladi.', '<b>Землемерие и карты.</b> Геодезисты разбивают большой участок на сеть треугольников (триангуляция) и складывают их площади. Так в XIX веке составлялись карты целых стран. 3D-модели в <b>компьютерных играх</b> тоже состоят из миллионов крошечных треугольников.', '<b>Surveying and maps.</b> Surveyors split a large area into a net of triangles (triangulation) and add up their areas. In the 19th century whole countries were mapped this way. The 3D models in <b>video games</b> are also built from millions of tiny triangles.'),
      L('<b>Parallelogramm</b> shaklidagi ko‘p qavatli avtoturargoh rampalari yoki qiya devorlarni bo‘yashda ham S = a · h ishlatiladi.', 'При покраске наклонных стен или пандусов-параллелограммов тоже используют S = a · h.', 'Painting slanted walls or parallelogram-shaped ramps also uses S = a · h.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Uchburchak medianalari uni 6 ta tengdosh uchburchakka bo‘ladi.', 'Медианы треугольника делят его на 6 равновеликих треугольников.', 'The three medians of a triangle cut it into 6 triangles of equal area.'),
      L('Katakli qog‘ozdagi ko‘pburchak yuzini Pik formulasi bilan topish mumkin: S = I + B/2 − 1 (I — ichki, B — chegaradagi tugunlar soni).', 'Площадь многоугольника на клетчатой бумаге находят по формуле Пика: S = I + B/2 − 1 (I — внутренние узлы, B — узлы на границе).', 'A polygon on squared paper has area given by Pick’s formula: S = I + B/2 − 1 (I interior grid points, B boundary points).'),
      L('Perimetri berilgan uchburchaklar orasida eng katta yuzga teng tomonli uchburchak ega.', 'Среди треугольников с данным периметром наибольшую площадь имеет равносторонний.', 'Among triangles with a given perimeter, the equilateral one has the largest area.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. Uchburchak asosi 14 cm, balandligi 9 cm. Yuzini toping.', '1. Основание треугольника 14 см, высота 9 см. Найдите площадь.', '1. A triangle has base 14 cm and height 9 cm. Find its area.'),
      L('2. Parallelogramm yuzi 54 cm², balandligi 6 cm. Asosini toping.', '2. Площадь параллелограмма 54 см², высота 6 см. Найдите основание.', '2. A parallelogram has area 54 cm² and height 6 cm. Find the base.'),
      L('3. Teng yonli to‘g‘ri burchakli uchburchak kateti 10 cm. Yuzini toping.', '3. Катет равнобедренного прямоугольного треугольника 10 см. Найдите площадь.', '3. An isosceles right triangle has legs of 10 cm. Find its area.')
    ], after: [
      L('Javoblar: 1) 63 cm²; 2) 9 cm; 3) ½ · 10 · 10 = 50 cm².', 'Ответы: 1) 63 см²; 2) 9 см; 3) ½ · 10 · 10 = 50 см².', 'Answers: 1) 63 cm²; 2) 9 cm; 3) ½ · 10 · 10 = 50 cm².')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Parallelogramm yuzi S = a · h — uni kesib, to‘g‘ri to‘rtburchakka aylantirish mumkin.', 'Площадь параллелограмма S = a · h — его можно разрезать и сложить в прямоугольник.', 'Parallelogram area S = a · h — it can be cut and rearranged into a rectangle.'),
      L('Uchburchak yuzi S = ½ · a · h — u parallelogrammning yarmi.', 'Площадь треугольника S = ½ · a · h — он половина параллелограмма.', 'Triangle area S = ½ · a · h — it is half a parallelogram.'),
      L('To‘g‘ri burchakli uchburchak: S = ½ · katet · katet.', 'Прямоугольный треугольник: S = ½ · катет · катет.', 'Right triangle: S = ½ · leg · leg.'),
      L('Asos va balandlik mos bo‘lishi shart.', 'Основание и высота должны соответствовать друг другу.', 'The base and height must match.'),
      L('Yuzni ikki usulda yozib, noma’lum balandlikni topish mumkin.', 'Записав площадь двумя способами, можно найти неизвестную высоту.', 'Writing the area two ways lets you find an unknown height.')
    ] }
  ] });

  // ---------- t10. Romb, trapetsiya va ko‘pburchakning yuzi ----------
  T.add(P, 't10', { sections: [
    { kind: 'intro', h: L('Har qanday shaklning yuzi', 'Площадь любой фигуры', 'The area of any figure'), p: [
      L('Endi bizda ikki kuchli vosita bor: to‘g‘ri to‘rtburchak yuzi va uchburchak yuzi. Ularning yordamida istalgan ko‘pburchak yuzini topa olamiz. Bu mavzuda romb (va diagonallari perpendikulyar har qanday to‘rtburchak), trapetsiya va ixtiyoriy ko‘pburchak yuzlarini o‘rganamiz.', 'Теперь у нас есть два сильных инструмента: площадь прямоугольника и площадь треугольника. С их помощью можно найти площадь любого многоугольника. В этой теме изучим площади ромба (и любого четырёхугольника с перпендикулярными диагоналями), трапеции и произвольного многоугольника.', 'We now have two powerful tools: the area of a rectangle and the area of a triangle. With them we can find the area of any polygon. In this topic we study the areas of a rhombus (and any quadrilateral with perpendicular diagonals), a trapezium and an arbitrary polygon.'),
      L('Asosiy g‘oya bitta: shaklni uchburchaklarga yoki to‘g‘ri to‘rtburchaklarga bo‘lamiz, yoki uni katta, oddiy shakl ichiga joylab, ortiqcha qismlarni ayiramiz. Yuzning additivlik xossasi bunga kafolat beradi. Shuningdek, oldingi mavzulardagi o‘rta chiziq bu yerda yana paydo bo‘ladi: trapetsiya yuzi = o‘rta chiziq · balandlik.', 'Главная идея одна: разрезаем фигуру на треугольники или прямоугольники, либо помещаем её в большую простую фигуру и вычитаем лишнее. Это гарантирует свойство аддитивности площади. А средняя линия из прошлых тем снова появится: площадь трапеции = средняя линия · высота.', 'The main idea is always the same: cut the figure into triangles or rectangles, or place it inside a large simple figure and subtract the extra parts. The additivity of area guarantees this works. The midline from earlier topics reappears too: trapezium area = midline · height.')
    ] },
    { kind: 'def', h: L('Kerakli tushunchalar', 'Нужные понятия', 'What we need'), list: [
      L('<b>Romb diagonallari</b> d₁ va d₂ o‘zaro perpendikulyar va kesishish nuqtasida teng ikkiga bo‘linadi.', '<b>Диагонали ромба</b> d₁ и d₂ перпендикулярны и делятся точкой пересечения пополам.', 'The <b>diagonals of a rhombus</b>, d₁ and d₂, are perpendicular and bisect each other.'),
      L('<b>Trapetsiya</b> asoslari a va b, balandligi h — asoslar orasidagi masofa; o‘rta chizig‘i m = (a + b)/2.', '<b>Трапеция</b>: основания a и b, высота h — расстояние между основаниями; средняя линия m = (a + b)/2.', 'A <b>trapezium</b> has bases a and b, height h (the distance between the bases) and midline m = (a + b)/2.'),
      L('<b>Triangulyatsiya</b> — ko‘pburchakni bir-birini qoplamaydigan uchburchaklarga bo‘lish. Qavariq n-burchakni bitta uchdan diagonallar bilan (n − 2) ta uchburchakka bo‘lish mumkin.', '<b>Триангуляция</b> — разбиение многоугольника на неперекрывающиеся треугольники. Выпуклый n-угольник диагоналями из одной вершины делится на (n − 2) треугольника.', '<b>Triangulation</b> means cutting a polygon into non-overlapping triangles. A convex n-gon splits into (n − 2) triangles by the diagonals from one vertex.')
    ] },
    { kind: 'history', h: L('Tarixdan: Bobil, Misr va al-Xorazmiy', 'Из истории: Вавилон, Египет и аль-Хорезми', 'History: Babylon, Egypt and al-Khwarizmi'), p: [
      L('Trapetsiya yuzi formulasi insoniyatga 4000 yildan ortiq vaqtdan beri ma’lum. Bobil va Misr hisobchilari dalalar yuzini «asoslarning yarim yig‘indisini balandlikka ko‘paytirib» topishgan. Ammo ular ba’zan to‘rtburchak shaklidagi istalgan dala uchun «qarama-qarshi tomonlar o‘rta qiymatlarining ko‘paytmasi» kabi taxminiy qoidani ham ishlatishgan — bu faqat to‘g‘ri to‘rtburchak uchun aniq, boshqa hollarda yuzni oshirib ko‘rsatadi.', 'Формула площади трапеции известна человечеству более 4000 лет. Писцы Вавилона и Египта находили площадь полей, «умножая полусумму оснований на высоту». Но иногда они применяли и приближённое правило для любого четырёхугольного поля — «произведение средних значений противоположных сторон», которое точно только для прямоугольника, а в других случаях завышает площадь.', 'The trapezium area formula has been known for more than 4000 years. Babylonian and Egyptian scribes found field areas by “multiplying half the sum of the bases by the height”. But they sometimes also used a rough rule for any four-sided field — “the product of the averages of opposite sides” — which is exact only for a rectangle and otherwise overstates the area.'),
      L('Al-Xorazmiy «Al-jabr» kitobida romb yuzini «bir diagonalni ikkinchisining yarmiga ko‘paytirish» orqali topishni o‘rgatgan va trapetsiya hamda turli to‘rtburchaklarni uchburchaklarga bo‘lib hisoblash usullarini keltirgan. Samarqand va Buxoro me’morlari girih naqshlarini yasashda romb, trapetsiya va ko‘pburchak plitkalar yuzini hisoblab, sopol va koshin miqdorini oldindan bilganlar.', 'Аль-Хорезми в книге «Аль-джабр» учил находить площадь ромба, «умножая одну диагональ на половину другой», и приводил способы вычисления трапеций и разных четырёхугольников разбиением на треугольники. Зодчие Самарканда и Бухары, создавая гирих, вычисляли площади ромбических, трапециевидных и многоугольных плиток, чтобы заранее знать количество изразцов.', 'In his al-jabr book al-Khwarizmi taught finding the area of a rhombus by “multiplying one diagonal by half the other”, and showed how to compute trapezia and various quadrilaterals by splitting them into triangles. Architects in Samarkand and Bukhara, creating girih, calculated the areas of rhombic, trapezium-shaped and polygonal tiles to know in advance how many glazed tiles they needed.')
    ] },
    { kind: 'rule', h: L('Romb yuzi: S = d₁d₂ / 2', 'Площадь ромба: S = d₁d₂ / 2', 'Rhombus area: S = d₁d₂ / 2'), p: [
      L('<b>Teorema.</b> Rombning yuzi diagonallari ko‘paytmasining yarmiga teng: <b>S = d₁ · d₂ / 2</b>.', '<b>Теорема.</b> Площадь ромба равна половине произведения диагоналей: <b>S = d₁ · d₂ / 2</b>.', '<b>Theorem.</b> The area of a rhombus is half the product of its diagonals: <b>S = d₁ · d₂ / 2</b>.'),
      L('<b>Isbot.</b> AC = d₁ diagonal rombni ikkita teng uchburchakka bo‘ladi: △ABC va △ADC. Ikkinchi diagonal BD ga perpendikulyar bo‘lgani uchun BO va DO — bu uchburchaklarning AC ga tushirilgan balandliklari, har biri d₂/2. Demak, S = 2 · ½ · d₁ · d₂/2 = d₁d₂/2.', '<b>Доказательство.</b> Диагональ AC = d₁ делит ромб на два равных треугольника △ABC и △ADC. Так как BD ⊥ AC, отрезки BO и DO — высоты этих треугольников к AC, каждая d₂/2. Значит, S = 2 · ½ · d₁ · d₂/2 = d₁d₂/2.', '<b>Proof.</b> Diagonal AC = d₁ splits the rhombus into two congruent triangles △ABC and △ADC. Since BD ⊥ AC, the segments BO and DO are the heights of these triangles to AC, each d₂/2. So S = 2 · ½ · d₁ · d₂/2 = d₁d₂/2.'),
      L('<b>Umumlashma.</b> Diagonallari perpendikulyar <b>har qanday</b> qavariq to‘rtburchak (masalan, deltoid yoki kvadrat) yuzi ham d₁d₂/2. Kvadrat uchun d₁ = d₂ = d, S = d²/2.', '<b>Обобщение.</b> Площадь <b>любого</b> выпуклого четырёхугольника с перпендикулярными диагоналями (например, дельтоида или квадрата) тоже d₁d₂/2. Для квадрата d₁ = d₂ = d, S = d²/2.', '<b>Generalisation.</b> <b>Any</b> convex quadrilateral with perpendicular diagonals (a kite or a square, for example) also has area d₁d₂/2. For a square d₁ = d₂ = d, so S = d²/2.'),
      L('Romb parallelogramm bo‘lgani uchun S = a · h formulasi ham to‘g‘ri — masalaga qarab qulayini tanlang.', 'Ромб — параллелограмм, поэтому верна и формула S = a · h — выбирайте удобную.', 'A rhombus is a parallelogram, so S = a · h also works — choose whichever is convenient.')
    ] },
    { kind: 'rule', h: L('Trapetsiya yuzi: S = (a + b)/2 · h', 'Площадь трапеции: S = (a + b)/2 · h', 'Trapezium area: S = (a + b)/2 · h'), p: [
      L('<b>Teorema.</b> Trapetsiya yuzi asoslar yarim yig‘indisining balandlikka ko‘paytmasiga teng: <b>S = (a + b)/2 · h = m · h</b>.', '<b>Теорема.</b> Площадь трапеции равна произведению полусуммы оснований на высоту: <b>S = (a + b)/2 · h = m · h</b>.', '<b>Theorem.</b> The area of a trapezium is half the sum of the bases times the height: <b>S = (a + b)/2 · h = m · h</b>.'),
      L('<b>Isbot.</b> ABCD trapetsiyada (AD = a, BC = b) BD diagonalni o‘tkazamiz. U trapetsiyani ikki uchburchakka bo‘ladi: △ABD (asosi a) va △BCD (asosi b). Ikkalasining balandligi bir xil — trapetsiya balandligi h. Demak, S = ½ah + ½bh = (a + b)/2 · h.', '<b>Доказательство.</b> В трапеции ABCD (AD = a, BC = b) проведём диагональ BD. Она делит трапецию на △ABD (основание a) и △BCD (основание b). Высота у обоих одна — высота трапеции h. Значит, S = ½ah + ½bh = (a + b)/2 · h.', '<b>Proof.</b> In trapezium ABCD (AD = a, BC = b) draw diagonal BD. It splits the trapezium into △ABD (base a) and △BCD (base b). Both have the same height — the trapezium’s height h. So S = ½ah + ½bh = (a + b)/2 · h.'),
      L('Ikkinchi isbot: ikkita bir xil trapetsiyani biri ikkinchisiga teskari qilib qo‘ysak, asosi (a + b) va balandligi h bo‘lgan parallelogramm hosil bo‘ladi. Uning yarmi — (a + b)h/2.', 'Второе доказательство: приложив две одинаковые трапеции, одну перевёрнутую, получим параллелограмм с основанием (a + b) и высотой h. Половина его — (a + b)h/2.', 'A second proof: put two identical trapezia together, one turned upside down, and you get a parallelogram with base (a + b) and height h. Half of it is (a + b)h/2.')
    ] },
    { kind: 'steps', h: L('Ko‘pburchak yuzini topish', 'Площадь многоугольника', 'Finding a polygon’s area'), list: [
      L('1. <b>Bo‘lish usuli:</b> ko‘pburchakni diagonallar bilan uchburchaklarga (yoki to‘g‘ri to‘rtburchak va trapetsiyalarga) bo‘ling.', '1. <b>Разбиение:</b> разрежьте многоугольник диагоналями на треугольники (или прямоугольники и трапеции).', '1. <b>Splitting:</b> cut the polygon with diagonals into triangles (or rectangles and trapezia).'),
      L('2. Har bir bo‘lakning yuzini kerakli formula bilan toping.', '2. Найдите площадь каждой части по подходящей формуле.', '2. Find the area of each piece with the right formula.'),
      L('3. Yuzlarni qo‘shing.', '3. Сложите площади.', '3. Add the areas.'),
      L('4. <b>To‘ldirish usuli:</b> agar bo‘lish noqulay bo‘lsa, shaklni to‘g‘ri to‘rtburchak ichiga joylang va ortiqcha uchburchaklar yuzini ayiring.', '4. <b>Дополнение:</b> если разбивать неудобно, впишите фигуру в прямоугольник и вычтите площади лишних треугольников.', '4. <b>Completing:</b> if splitting is awkward, put the figure inside a rectangle and subtract the extra triangles.'),
      L('5. Koordinatalar yoki katakli qog‘ozda ishlasangiz, to‘ldirish usuli eng tez.', '5. На координатной или клетчатой бумаге метод дополнения самый быстрый.', '5. On coordinate or squared paper the completing method is usually the fastest.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Romb diagonallari 10 cm va 24 cm. Uning yuzini va tomonini toping.', 'Диагонали ромба 10 см и 24 см. Найдите площадь и сторону.', 'A rhombus has diagonals 10 cm and 24 cm. Find its area and its side.'),
        s: L('S = 10 · 24 : 2 = 120 cm². Diagonallar yarmlari 5 cm va 12 cm, ular to‘g‘ri burchakli uchburchak katetlari; gipotenuza — romb tomoni 13 cm (5, 12, 13 — mashhur uchlik). Tekshirish: balandlik h = 120 : 13 ≈ 9,2 cm.', 'S = 10 · 24 : 2 = 120 см². Половины диагоналей 5 см и 12 см — катеты прямоугольного треугольника; гипотенуза — сторона ромба 13 см (5, 12, 13 — известная тройка). Проверка: высота h = 120 : 13 ≈ 9,2 см.', 'S = 10 · 24 ÷ 2 = 120 cm². The half-diagonals 5 cm and 12 cm are the legs of a right triangle whose hypotenuse, the side, is 13 cm (5, 12, 13 is a famous triple). Check: the height is 120 ÷ 13 ≈ 9.2 cm.') },
      { q: L('Trapetsiya asoslari 9 cm va 15 cm, balandligi 8 cm. Yuzini toping.', 'Основания трапеции 9 см и 15 см, высота 8 см. Найдите площадь.', 'A trapezium has bases 9 cm and 15 cm and height 8 cm. Find its area.'),
        s: L('S = (9 + 15) : 2 · 8 = 12 · 8 = 96 cm². O‘rta chiziq 12 cm ekanini ham ko‘rdik.', 'S = (9 + 15) : 2 · 8 = 12 · 8 = 96 см². Заодно средняя линия 12 см.', 'S = (9 + 15) ÷ 2 · 8 = 12 · 8 = 96 cm². Along the way, the midline is 12 cm.') },
      { q: L('Teng yonli trapetsiyada asoslar 4 cm va 10 cm, o‘tkir burchagi 45°. Yuzini toping.', 'В равнобедренной трапеции основания 4 см и 10 см, острый угол 45°. Найдите площадь.', 'An isosceles trapezium has bases 4 cm and 10 cm and an acute angle of 45°. Find its area.'),
        s: L('Balandliklar katta asosdan (10 − 4) : 2 = 3 cm ajratadi. 45° li to‘g‘ri burchakli uchburchakda katetlar teng: h = 3 cm. S = (4 + 10) : 2 · 3 = 21 cm².', 'Высоты отсекают от большего основания по (10 − 4) : 2 = 3 см. В прямоугольном треугольнике с углом 45° катеты равны: h = 3 см. S = (4 + 10) : 2 · 3 = 21 см².', 'The heights cut off (10 − 4) ÷ 2 = 3 cm from the longer base. With a 45° angle the right triangle has equal legs: h = 3 cm. S = (4 + 10) ÷ 2 · 3 = 21 cm².') },
      { q: L('Uchlari A(0; 0), B(6; 0), C(8; 4), D(2; 6) bo‘lgan to‘rtburchak yuzini toping.', 'Найдите площадь четырёхугольника с вершинами A(0; 0), B(6; 0), C(8; 4), D(2; 6).', 'Find the area of the quadrilateral with vertices A(0; 0), B(6; 0), C(8; 4), D(2; 6).'),
        s: L('Uni 8 × 6 to‘g‘ri to‘rtburchak ichiga joylaymiz (S = 48). Ortiqcha uchburchaklar: B(6;0)–(8;0)–C: ½ · 2 · 4 = 4; C–(8;6)–D: ½ · 6 · 2 = 6; D–(0;6)–A: ½ · 2 · 6 = 6. To‘rtburchak yuzi 48 − 4 − 6 − 6 = 32 birlik².', 'Поместим его в прямоугольник 8 × 6 (S = 48). Лишние треугольники: B(6;0)–(8;0)–C: ½ · 2 · 4 = 4; C–(8;6)–D: ½ · 6 · 2 = 6; D–(0;6)–A: ½ · 2 · 6 = 6. Площадь 48 − 4 − 6 − 6 = 32 ед².', 'Put it inside the 8 × 6 rectangle (S = 48). Extra triangles: B(6;0)–(8;0)–C: ½ · 2 · 4 = 4; C–(8;6)–D: ½ · 6 · 2 = 6; D–(0;6)–A: ½ · 2 · 6 = 6. The area is 48 − 4 − 6 − 6 = 32 square units.') }
    ] },
    { kind: 'table', h: L('Yuz formulalari jadvali', 'Таблица формул площади', 'Area formulas at a glance'), table: {
      head: [L('Shakl', 'Фигура', 'Figure'), L('Formula', 'Формула', 'Formula'), L('Belgilar', 'Обозначения', 'Symbols')],
      rows: [
        [L('To‘g‘ri to‘rtburchak', 'Прямоугольник', 'Rectangle'), 'S = ab', L('a, b — tomonlar', 'a, b — стороны', 'a, b — sides')],
        [L('Kvadrat', 'Квадрат', 'Square'), L('S = a² = d²/2', 'S = a² = d²/2', 'S = a² = d²/2'), L('a — tomon, d — diagonal', 'a — сторона, d — диагональ', 'a — side, d — diagonal')],
        [L('Parallelogramm', 'Параллелограмм', 'Parallelogram'), 'S = a · h', L('h — a ga balandlik', 'h — высота к a', 'h — height to a')],
        [L('Uchburchak', 'Треугольник', 'Triangle'), L('S = ½ a h', 'S = ½ a h', 'S = ½ a h'), L('h — a ga balandlik', 'h — высота к a', 'h — height to a')],
        [L('Romb', 'Ромб', 'Rhombus'), L('S = d₁d₂/2 = a · h', 'S = d₁d₂/2 = a · h', 'S = d₁d₂/2 = a · h'), L('d₁, d₂ — diagonallar', 'd₁, d₂ — диагонали', 'd₁, d₂ — diagonals')],
        [L('Trapetsiya', 'Трапеция', 'Trapezium'), L('S = (a + b)/2 · h', 'S = (a + b)/2 · h', 'S = (a + b)/2 · h'), L('a, b — asoslar', 'a, b — основания', 'a, b — bases')]
      ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Romb yuzini d₁ · d₂ deb yozish.</b> 2 ga bo‘lish shart: romb diagonallar hosil qilgan to‘g‘ri to‘rtburchakning yarmi.', '<b>Писать площадь ромба как d₁ · d₂.</b> Нужно делить на 2: ромб — половина прямоугольника, построенного на диагоналях.', '<b>Writing the rhombus area as d₁ · d₂.</b> You must halve it: the rhombus is half the rectangle built on its diagonals.'),
      L('<b>Trapetsiyada yon tomonni balandlik deb olish.</b> Faqat to‘g‘ri burchakli trapetsiyada perpendikulyar yon tomon balandlikka teng.', '<b>Брать боковую сторону трапеции за высоту.</b> Только у прямоугольной трапеции перпендикулярная сторона равна высоте.', '<b>Taking a trapezium’s leg as its height.</b> Only the perpendicular leg of a right trapezium equals the height.'),
      L('<b>(a + b) · h deb, 2 ga bo‘lmaslik.</b> Bu ikki trapetsiyaning yuzi bo‘lib qoladi.', '<b>Писать (a + b) · h без деления на 2.</b> Получится площадь двух трапеций.', '<b>Writing (a + b) · h without halving.</b> That is the area of two trapezia.'),
      L('<b>Bo‘laklar ustma-ust tushishi.</b> Ko‘pburchakni bo‘lganda bo‘laklar bir-birini qoplamasligi va bo‘shliq qolmasligi kerak.', '<b>Перекрывающиеся части.</b> При разбиении части не должны накладываться и не должно оставаться пробелов.', '<b>Overlapping pieces.</b> When you split a polygon, the pieces must not overlap or leave gaps.'),
      L('<b>d₁d₂/2 formulasini diagonallari perpendikulyar bo‘lmagan to‘rtburchakda ishlatish.</b> Oddiy parallelogrammda bu noto‘g‘ri.', '<b>Применять d₁d₂/2 к четырёхугольнику с неперпендикулярными диагоналями.</b> Для обычного параллелограмма это неверно.', '<b>Using d₁d₂/2 when the diagonals are not perpendicular.</b> It is wrong for a general parallelogram.')
    ] },
    { kind: 'life', h: L('Hayotda', 'В жизни', 'In real life'), p: [
      L('<b>Yer uchastkalari.</b> Ko‘p dalalar va tomorqalar to‘g‘ri to‘rtburchak emas, balki trapetsiya yoki noto‘g‘ri ko‘pburchak shaklida. Kadastr xizmati xodimlari uchastka chegarasini GPS bilan o‘lchaydi, koordinatalarni oladi va ko‘pburchakni uchburchaklarga bo‘lib, yuzni hisoblaydi. Yer solig‘i aynan shu yuzga qarab belgilanadi — xuddi qadimgi Misrdagidek!', '<b>Земельные участки.</b> Многие поля и огороды — не прямоугольники, а трапеции или неправильные многоугольники. Работники кадастра измеряют границу по GPS, получают координаты и, разбивая многоугольник на треугольники, вычисляют площадь. Земельный налог назначают именно по ней — как в Древнем Египте!', '<b>Land plots.</b> Many fields and gardens are not rectangles but trapezia or irregular polygons. Land-registry staff measure the boundary with GPS, record the coordinates and calculate the area by splitting the polygon into triangles. Land tax is set by this area — just as in ancient Egypt!'),
      L('<b>Naqsh va plitkalar.</b> Girih ustalari va bugungi dizaynerlar romb va trapetsiya plitkalar sonini hisoblash uchun devor yuzini bitta plitka yuziga bo‘lishadi. <b>Kanallar</b>da oqib o‘tayotgan suv miqdori trapetsiya shaklidagi ko‘ndalang kesim yuzini suv tezligiga ko‘paytirib topiladi.', '<b>Узоры и плитка.</b> Мастера гирих и современные дизайнеры, чтобы рассчитать число ромбических и трапециевидных плиток, делят площадь стены на площадь одной плитки. Расход воды в <b>каналах</b> находят, умножая площадь трапециевидного сечения на скорость течения.', '<b>Patterns and tiles.</b> Girih masters and modern designers divide a wall’s area by the area of one rhombic or trapezium tile to know how many tiles they need. The flow of water in <b>canals</b> is found by multiplying the area of the trapezium-shaped cross-section by the water’s speed.'),
      L('<b>Varrak (deltoid)</b> uchun qancha mato kerakligini diagonallar orqali d₁d₂/2 bilan bir zumda hisoblash mumkin.', 'Сколько ткани нужно на <b>воздушного змея</b>, мгновенно считается по диагоналям: d₁d₂/2.', 'The fabric needed for a <b>kite</b> is quickly found from its diagonals: d₁d₂/2.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Bolyai–Gervin teoremasi: tengdosh ikki ko‘pburchakning birini chekli sonli bo‘laklarga kesib, ulardan ikkinchisini yig‘ish mumkin.', 'Теорема Бойяи–Гервина: из двух равновеликих многоугольников один всегда можно разрезать на конечное число частей и сложить из них другой.', 'The Bolyai–Gerwien theorem: of two polygons with equal area, one can always be cut into finitely many pieces that reassemble into the other.'),
      L('Koordinatalar orqali ko‘pburchak yuzini topishning «shnurok formulasi» bor — GPS dasturlari aynan shundan foydalanadi.', 'Есть «формула шнурования» для площади многоугольника по координатам вершин — её используют GPS-программы.', 'There is a “shoelace formula” for a polygon’s area from vertex coordinates — GPS software uses it.'),
      L('Arximed aylana yuzini unga ichki va tashqi chizilgan 96-burchaklar yuzlari orasida qisib topgan.', 'Архимед нашёл площадь круга, зажав её между площадями вписанного и описанного 96-угольников.', 'Archimedes trapped the area of a circle between the areas of inscribed and circumscribed 96-gons.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), list: [
      L('1. Romb yuzi 48 cm², bir diagonali 12 cm. Ikkinchi diagonalni toping.', '1. Площадь ромба 48 см², одна диагональ 12 см. Найдите другую.', '1. A rhombus has area 48 cm² and one diagonal 12 cm. Find the other diagonal.'),
      L('2. Trapetsiya yuzi 60 cm², balandligi 5 cm. O‘rta chizig‘ini toping.', '2. Площадь трапеции 60 см², высота 5 см. Найдите среднюю линию.', '2. A trapezium has area 60 cm² and height 5 cm. Find its midline.'),
      L('3. Kvadrat diagonali 6 cm. Yuzini toping.', '3. Диагональ квадрата 6 см. Найдите площадь.', '3. A square has diagonal 6 cm. Find its area.')
    ], after: [
      L('Javoblar: 1) d₂ = 2 · 48 : 12 = 8 cm; 2) m = 60 : 5 = 12 cm; 3) S = 6² : 2 = 18 cm².', 'Ответы: 1) d₂ = 2 · 48 : 12 = 8 см; 2) m = 60 : 5 = 12 см; 3) S = 6² : 2 = 18 см².', 'Answers: 1) d₂ = 2 · 48 ÷ 12 = 8 cm; 2) m = 60 ÷ 5 = 12 cm; 3) S = 6² ÷ 2 = 18 cm².')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Romb yuzi S = d₁d₂/2; bu diagonallari perpendikulyar har qanday to‘rtburchak uchun to‘g‘ri.', 'Площадь ромба S = d₁d₂/2; это верно для любого четырёхугольника с перпендикулярными диагоналями.', 'Rhombus area S = d₁d₂/2; it holds for any quadrilateral with perpendicular diagonals.'),
      L('Trapetsiya yuzi S = (a + b)/2 · h = o‘rta chiziq · balandlik.', 'Площадь трапеции S = (a + b)/2 · h = средняя линия · высота.', 'Trapezium area S = (a + b)/2 · h = midline · height.'),
      L('Isbotlar: diagonal o‘tkazib, shaklni uchburchaklarga bo‘lish.', 'Доказательства: провести диагональ и разбить фигуру на треугольники.', 'Proofs: draw a diagonal and split the figure into triangles.'),
      L('Ixtiyoriy ko‘pburchak yuzi — bo‘lish yoki to‘ldirish usuli bilan.', 'Площадь любого многоугольника — разбиением или дополнением.', 'Any polygon’s area comes from splitting or completing.'),
      L('Bu formulalar 4000 yildan beri yer o‘lchashda ishlatilmoqda.', 'Этими формулами пользуются в землемерии уже 4000 лет.', 'These formulas have been used in land surveying for 4000 years.')
    ] }
  ] });
})(this);
