// Nuvemath — 8-sinf, II qism nazariyasi (ikkinchi yarmi: t11–t20). Format: js/theory/GUIDE.md
// Vaqtinchalik fayl: keyinroq js/theory/g8-2.js ga qo‘shiladi.
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-2';

  // ---------- t11. Pifagor teoremasi va uning isboti ----------
  T.add(P, 't11', { sections: [
    { kind: 'intro', h: L('Eng mashhur teorema', 'Самая знаменитая теорема', 'The most famous theorem'), p: [
      L('Tasavvur qiling: siz hovlida turibsiz, uydan darvozagacha to‘g‘ri yo‘lak yo‘q. Siz avval 30 qadam to‘g‘riga, keyin 40 qadam chapga yurasiz. Agar o‘tlarni bosib to‘g‘ridan-to‘g‘ri yursangiz, necha qadam bo‘lardi? Javob — atigi 50 qadam. Bu sonni o‘lchamasdan, faqat hisoblab topish mumkin. Buning siri — geometriyadagi eng mashhur teorema, <b>Pifagor teoremasi</b>.', 'Представьте: вы во дворе, и прямой дорожки от дома до ворот нет. Вы идёте 30 шагов прямо, затем 40 шагов налево. Сколько шагов было бы, если идти напрямик через газон? Ответ — всего 50 шагов. Это число можно не измерять, а вычислить. Секрет — в самой знаменитой теореме геометрии, <b>теореме Пифагора</b>.', 'Imagine you are in a yard with no straight path from the house to the gate. You walk 30 steps forward, then 40 steps to the left. How many steps would it be if you cut straight across the grass? The answer is just 50 steps. You do not need to measure it — you can calculate it. The secret is the most famous theorem in geometry, <b>Pythagoras’ theorem</b>.'),
      L('Bu teorema to‘g‘ri burchakli uchburchakning uchta tomonini bitta chiroyli tenglik bilan bog‘laydi. Ikki tomonni bilsak, uchinchisini doimo topa olamiz. Shu sababli u quruvchilar, duradgorlar, uchuvchilar, dasturchilar va muhandislarning har kungi quroli. Telefoningiz ekranining «dyuym» o‘lchami ham, kompyuter o‘yinidagi ikki qahramon orasidagi masofa ham shu teorema bilan hisoblanadi.', 'Эта теорема связывает три стороны прямоугольного треугольника одним красивым равенством. Зная две стороны, мы всегда найдём третью. Поэтому она — ежедневный инструмент строителей, столяров, лётчиков, программистов и инженеров. Диагональ экрана телефона в дюймах и расстояние между двумя героями компьютерной игры считаются именно по ней.', 'The theorem links the three sides of a right triangle with one beautiful equation. Know two sides and you can always find the third. That is why it is an everyday tool for builders, carpenters, pilots, programmers and engineers. The diagonal size of your phone screen in inches and the distance between two characters in a video game are both computed with it.'),
      L('Bu mavzuda biz teoremaning mazmunini, uni qanday isbotlash mumkinligini, uning ming yillik tarixini va masalalarda qo‘llashni o‘rganamiz. Eng muhimi — nega u to‘g‘ri ekanini o‘z ko‘zimiz bilan ko‘rib, tushunib olamiz.', 'В этой теме мы изучим смысл теоремы, способы её доказательства, её тысячелетнюю историю и применение в задачах. Главное — своими глазами увидеть и понять, почему она верна.', 'In this topic we learn what the theorem says, how it can be proved, its thousands of years of history and how to use it in problems. Most importantly, we will see with our own eyes why it is true.')
    ] },
    { kind: 'def', h: L('Katetlar va gipotenuza', 'Катеты и гипотенуза', 'Legs and hypotenuse'), p: [
      L('Bitta burchagi 90° bo‘lgan uchburchak <b>to‘g‘ri burchakli uchburchak</b> deyiladi. Uning tomonlari maxsus nomlarga ega:', 'Треугольник, у которого один угол равен 90°, называется <b>прямоугольным</b>. Его стороны имеют особые названия:', 'A triangle with one angle of 90° is called a <b>right triangle</b>. Its sides have special names:')
    ], list: [
      L('<b>Katetlar</b> — to‘g‘ri burchakni hosil qiluvchi ikki tomon. Odatda a va b harflari bilan belgilanadi.', '<b>Катеты</b> — две стороны, образующие прямой угол. Обычно обозначаются a и b.', 'The <b>legs</b> (catheti) are the two sides that form the right angle. They are usually called a and b.'),
      L('<b>Gipotenuza</b> — to‘g‘ri burchak qarshisida yotgan tomon. U c harfi bilan belgilanadi va doimo eng uzun tomon bo‘ladi.', '<b>Гипотенуза</b> — сторона, лежащая против прямого угла. Обозначается c и всегда является самой длинной стороной.', 'The <b>hypotenuse</b> is the side opposite the right angle. It is called c and is always the longest side.'),
      L('To‘g‘ri burchakli uchburchakning qolgan ikki burchagi o‘tkir va ularning yig‘indisi 90° ga teng.', 'Два других угла прямоугольного треугольника острые, их сумма равна 90°.', 'The other two angles of a right triangle are acute and add up to 90°.')
    ], after: [
      L('«Gipotenuza» so‘zi yunoncha bo‘lib, «ostiga tortilgan» degan ma’noni beradi: qadimgi chizmalarda bu tomon to‘g‘ri burchak ostiga tortilgan ip kabi ko‘ringan. «Katet» esa «tik tushirilgan» degan ma’noni anglatadi.', 'Слово «гипотенуза» греческое и означает «стягивающая»: на древних чертежах эта сторона была похожа на нить, натянутую под прямым углом. «Катет» означает «отвесный».', 'The word “hypotenuse” is Greek for “stretching under”: in ancient drawings this side looked like a string stretched beneath the right angle. “Cathetus” means “let fall vertically”.'),
      L('Diqqat: gipotenuzani topishda avvalo to‘g‘ri burchak qayerdaligini aniqlang. Uning qarshisidagi tomon — gipotenuza, qolganlari — katetlar.', 'Внимание: чтобы найти гипотенузу, сначала определите, где прямой угол. Сторона напротив него — гипотенуза, остальные — катеты.', 'Careful: to find the hypotenuse, first locate the right angle. The side opposite it is the hypotenuse; the other two are legs.')
    ] },
    { kind: 'history', h: L('Pifagor va undan oldingilar', 'Пифагор и его предшественники', 'Pythagoras and those before him'), p: [
      L('<b>Pifagor</b> miloddan avvalgi VI asrda Samos orolida tug‘ilgan yunon faylasufi va matematigi. U Misr va Bobilda ko‘p yillar o‘qigan, so‘ng Italiyaning janubidagi Kroton shahrida o‘z maktabini ochgan. Rivoyatlarga ko‘ra, teoremani isbotlaganda u xursandligidan xudolarga yuzta ho‘kiz qurbon qilgan. Biroq bu shunchaki afsona bo‘lishi mumkin: Pifagor hayoti haqidagi ma’lumotlarning ko‘pi undan yuzlab yil keyin yozilgan.', '<b>Пифагор</b> — греческий философ и математик, родившийся в VI веке до н. э. на острове Самос. Он много лет учился в Египте и Вавилоне, затем основал свою школу в городе Кротон на юге Италии. По легенде, доказав теорему, он на радостях принёс в жертву богам сто быков. Но это может быть лишь легендой: большинство сведений о Пифагоре записано спустя сотни лет.', '<b>Pythagoras</b> was a Greek philosopher and mathematician born in the 6th century BC on the island of Samos. He studied for years in Egypt and Babylon, then founded his school in Croton in southern Italy. Legend says that when he proved the theorem he sacrificed a hundred oxen to the gods in joy. This may only be a story: most of what we know about him was written down centuries later.'),
      L('Aslida bu bog‘lanish Pifagordan ancha oldin ma’lum bo‘lgan. Bobilda miloddan avvalgi taxminan 1800-yillarda yozilgan <b>Plimpton 322</b> loy taxtachasida 3, 4, 5 kabi «Pifagor uchliklari»ning o‘n beshta qatori bor — ular orasida 119, 120, 169 kabi katta sonlar ham uchraydi. Qadimgi Xitoyning «Chjoubi suanjing» kitobida va Hindistonning «Sulba-sutra» qo‘llanmalarida ham bu qoida qurbongohlar qurish uchun ishlatilgan.', 'На самом деле эта связь была известна задолго до Пифагора. Вавилонская глиняная табличка <b>Плимптон 322</b>, написанная около 1800 г. до н. э., содержит пятнадцать строк «пифагоровых троек» вроде 3, 4, 5 — среди них есть и большие числа, например 119, 120, 169. В древнекитайской книге «Чжоуби суаньцзин» и в индийских «Шульба-сутрах» это правило использовали при строительстве алтарей.', 'In fact this relation was known long before Pythagoras. The Babylonian clay tablet <b>Plimpton 322</b>, written around 1800 BC, lists fifteen rows of “Pythagorean triples” like 3, 4, 5 — including large ones such as 119, 120, 169. The ancient Chinese book “Zhoubi Suanjing” and the Indian “Sulba Sutras” also used the rule for building altars.'),
      L('Pifagorning xizmati shundaki, yunonlar birinchi bo‘lib bu qoidani <i>har qanday</i> to‘g‘ri burchakli uchburchak uchun mantiqan isbotlashga intilgan. Keyinroq <b>Yevklid</b> «Negizlar» kitobining birinchi qismini aynan shu teorema bilan yakunlagan.', 'Заслуга Пифагора в том, что греки первыми стремились логически доказать это правило для <i>любого</i> прямоугольного треугольника. Позже <b>Евклид</b> завершил первую книгу «Начал» именно этой теоремой.', 'Pythagoras’ achievement is that the Greeks were the first to seek a logical proof for <i>every</i> right triangle. Later <b>Euclid</b> ended the first book of his “Elements” with exactly this theorem.')
    ] },
    { kind: 'rule', h: L('Teorema va uning ma’nosi', 'Теорема и её смысл', 'The theorem and its meaning'), p: [
      L('<b>Teorema.</b> To‘g‘ri burchakli uchburchakda gipotenuza kvadrati katetlar kvadratlarining yig‘indisiga teng: <b>c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup></b>.', '<b>Теорема.</b> В прямоугольном треугольнике квадрат гипотенузы равен сумме квадратов катетов: <b>c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup></b>.', '<b>Theorem.</b> In a right triangle the square of the hypotenuse equals the sum of the squares of the legs: <b>c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup></b>.'),
      L('Geometrik ma’nosi juda chiroyli: har bir tomonga tashqi tomondan kvadrat chizsak, gipotenuzaga qurilgan kvadratning yuzi katetlarga qurilgan ikki kvadrat yuzlarining yig‘indisiga teng bo‘ladi. Masalan, 3, 4, 5 uchburchakda: 9 + 16 = 25. Qadimgi yunonlar teoremani aynan yuzlar haqidagi gap sifatida tushunishgan.', 'Геометрический смысл очень красив: если построить на каждой стороне квадрат наружу, то площадь квадрата на гипотенузе равна сумме площадей квадратов на катетах. Например, в треугольнике 3, 4, 5: 9 + 16 = 25. Древние греки понимали теорему именно как утверждение о площадях.', 'Its geometric meaning is beautiful: if you draw a square outward on each side, the area of the square on the hypotenuse equals the sum of the areas of the squares on the legs. For the 3, 4, 5 triangle: 9 + 16 = 25. The ancient Greeks understood the theorem precisely as a statement about areas.'),
      L('Formulani uch xil ko‘rinishda yozish foydali:', 'Формулу полезно записать в трёх видах:', 'It is useful to write the formula in three forms:')
    ], list: [
      L('gipotenuza: c = √(a<sup>2</sup> + b<sup>2</sup>);', 'гипотенуза: c = √(a<sup>2</sup> + b<sup>2</sup>);', 'hypotenuse: c = √(a<sup>2</sup> + b<sup>2</sup>);'),
      L('birinchi katet: a = √(c<sup>2</sup> − b<sup>2</sup>);', 'первый катет: a = √(c<sup>2</sup> − b<sup>2</sup>);', 'first leg: a = √(c<sup>2</sup> − b<sup>2</sup>);'),
      L('ikkinchi katet: b = √(c<sup>2</sup> − a<sup>2</sup>).', 'второй катет: b = √(c<sup>2</sup> − a<sup>2</sup>).', 'second leg: b = √(c<sup>2</sup> − a<sup>2</sup>).')
    ], after: [
      L('Esda tuting: katetni topayotganda kvadratlar <b>ayiriladi</b>, gipotenuzani topayotganda esa <b>qo‘shiladi</b>.', 'Запомните: при поиске катета квадраты <b>вычитаются</b>, а при поиске гипотенузы — <b>складываются</b>.', 'Remember: to find a leg you <b>subtract</b> the squares; to find the hypotenuse you <b>add</b> them.')
    ] },
    { kind: 'steps', h: L('Isbot: to‘rtta uchburchak', 'Доказательство: четыре треугольника', 'Proof: four triangles'), p: [
      L('Eng tushunarli isbotlardan biri yuzlarni hisoblashga asoslangan. Uni qadamma-qadam ko‘rib chiqamiz:', 'Одно из самых наглядных доказательств основано на подсчёте площадей. Разберём его по шагам:', 'One of the clearest proofs is based on counting areas. Let us go through it step by step:')
    ], list: [
      L('1-qadam. Katetlari a va b, gipotenuzasi c bo‘lgan to‘rtta bir xil to‘g‘ri burchakli uchburchak olamiz.', 'Шаг 1. Берём четыре одинаковых прямоугольных треугольника с катетами a и b и гипотенузой c.', 'Step 1. Take four identical right triangles with legs a and b and hypotenuse c.'),
      L('2-qadam. Ularni tomoni (a + b) bo‘lgan katta kvadrat ichiga shunday joylashtiramizki, har bir burchakda bittadan uchburchak tursin.', 'Шаг 2. Укладываем их в большой квадрат со стороной (a + b) так, чтобы в каждом углу было по треугольнику.', 'Step 2. Place them inside a big square of side (a + b) so that each corner holds one triangle.'),
      L('3-qadam. O‘rtada tomonlari c bo‘lgan to‘rtburchak qoladi. Uning burchaklari 180° − 90° = 90°, chunki uchburchakning ikki o‘tkir burchagi yig‘indisi 90°. Demak, u kvadrat.', 'Шаг 3. В середине остаётся четырёхугольник со сторонами c. Его углы равны 180° − 90° = 90°, ведь два острых угла треугольника в сумме дают 90°. Значит, это квадрат.', 'Step 3. A quadrilateral with sides c is left in the middle. Its angles are 180° − 90° = 90°, because the two acute angles of the triangle add to 90°. So it is a square.'),
      L('4-qadam. Katta kvadrat yuzini ikki usulda yozamiz: (a + b)<sup>2</sup> = 4 · ab/2 + c<sup>2</sup>.', 'Шаг 4. Запишем площадь большого квадрата двумя способами: (a + b)<sup>2</sup> = 4 · ab/2 + c<sup>2</sup>.', 'Step 4. Write the area of the big square in two ways: (a + b)<sup>2</sup> = 4 · ab/2 + c<sup>2</sup>.'),
      L('5-qadam. Qavsni ochamiz: a<sup>2</sup> + 2ab + b<sup>2</sup> = 2ab + c<sup>2</sup>. Ikkala tomondan 2ab ni olib tashlasak, a<sup>2</sup> + b<sup>2</sup> = c<sup>2</sup>. Isbot tugadi!', 'Шаг 5. Раскроем скобки: a<sup>2</sup> + 2ab + b<sup>2</sup> = 2ab + c<sup>2</sup>. Убрав 2ab из обеих частей, получим a<sup>2</sup> + b<sup>2</sup> = c<sup>2</sup>. Доказано!', 'Step 5. Expand: a<sup>2</sup> + 2ab + b<sup>2</sup> = 2ab + c<sup>2</sup>. Cancel 2ab on both sides to get a<sup>2</sup> + b<sup>2</sup> = c<sup>2</sup>. Proved!')
    ], after: [
      L('Boshqa isbot o‘xshash uchburchaklarga asoslanadi: to‘g‘ri burchak uchidan gipotenuzaga balandlik tushirsak, uchburchak o‘ziga o‘xshash ikki kichik uchburchakka bo‘linadi va a<sup>2</sup> = c · a<sub>c</sub>, b<sup>2</sup> = c · b<sub>c</sub> kelib chiqadi; ularni qo‘shsak, a<sup>2</sup> + b<sup>2</sup> = c(a<sub>c</sub> + b<sub>c</sub>) = c<sup>2</sup>. Hozirgi kunda bu teoremaning 400 dan ortiq turli isboti ma’lum!', 'Другое доказательство опирается на подобные треугольники: высота из вершины прямого угла делит треугольник на два меньших, подобных исходному, откуда a<sup>2</sup> = c · a<sub>c</sub>, b<sup>2</sup> = c · b<sub>c</sub>; складывая, получаем a<sup>2</sup> + b<sup>2</sup> = c(a<sub>c</sub> + b<sub>c</sub>) = c<sup>2</sup>. Сегодня известно более 400 различных доказательств!', 'Another proof uses similar triangles: the altitude from the right angle splits the triangle into two smaller ones similar to the original, giving a<sup>2</sup> = c · a<sub>c</sub> and b<sup>2</sup> = c · b<sub>c</sub>; adding them, a<sup>2</sup> + b<sup>2</sup> = c(a<sub>c</sub> + b<sub>c</sub>) = c<sup>2</sup>. More than 400 different proofs are known today!')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Har bir masalada avval qaysi tomon gipotenuza ekanini aniqlaymiz, so‘ng formulaning kerakli ko‘rinishini tanlaymiz.', 'В каждой задаче сначала определяем, какая сторона — гипотенуза, затем выбираем нужный вид формулы.', 'In each problem we first decide which side is the hypotenuse, then choose the right form of the formula.')
    ], ex: [
      { q: L('Katetlari 6 sm va 8 sm bo‘lgan to‘g‘ri burchakli uchburchakning gipotenuzasini toping.', 'Найдите гипотенузу прямоугольного треугольника с катетами 6 см и 8 см.', 'Find the hypotenuse of a right triangle with legs 6 cm and 8 cm.'), s: L('c<sup>2</sup> = 6<sup>2</sup> + 8<sup>2</sup> = 36 + 64 = 100. Demak, c = √100 = <b>10 sm</b>. E’tibor bering: bu 3, 4, 5 uchburchakning ikki marta kattalashtirilgani.', 'c<sup>2</sup> = 6<sup>2</sup> + 8<sup>2</sup> = 36 + 64 = 100. Значит, c = √100 = <b>10 см</b>. Заметьте: это треугольник 3, 4, 5, увеличенный вдвое.', 'c<sup>2</sup> = 6<sup>2</sup> + 8<sup>2</sup> = 36 + 64 = 100, so c = √100 = <b>10 cm</b>. Notice this is the 3, 4, 5 triangle doubled.') },
      { q: L('Gipotenuza 13 sm, bitta kateti 5 sm. Ikkinchi katetni toping.', 'Гипотенуза 13 см, один катет 5 см. Найдите второй катет.', 'The hypotenuse is 13 cm and one leg is 5 cm. Find the other leg.'), s: L('b<sup>2</sup> = c<sup>2</sup> − a<sup>2</sup> = 169 − 25 = 144, b = √144 = <b>12 sm</b>. Bu yerda kvadratlar ayirildi, chunki noma’lum — katet.', 'b<sup>2</sup> = c<sup>2</sup> − a<sup>2</sup> = 169 − 25 = 144, b = √144 = <b>12 см</b>. Здесь квадраты вычитаются, потому что неизвестен катет.', 'b<sup>2</sup> = c<sup>2</sup> − a<sup>2</sup> = 169 − 25 = 144, so b = √144 = <b>12 cm</b>. We subtracted because the unknown is a leg.') },
      { q: L('Katetlari 1 va 2 bo‘lgan uchburchakning gipotenuzasi qancha?', 'Чему равна гипотенуза треугольника с катетами 1 и 2?', 'What is the hypotenuse of a triangle with legs 1 and 2?'), s: L('c<sup>2</sup> = 1 + 4 = 5, c = <b>√5 ≈ 2,24</b>. Javob har doim ham butun son bo‘lavermaydi — ildizni shu ko‘rinishda qoldirish mumkin.', 'c<sup>2</sup> = 1 + 4 = 5, c = <b>√5 ≈ 2,24</b>. Ответ не всегда целый — корень можно оставить в таком виде.', 'c<sup>2</sup> = 1 + 4 = 5, so c = <b>√5 ≈ 2.24</b>. The answer is not always a whole number — it is fine to leave the root.') },
      { q: L('To‘g‘ri to‘rtburchakning tomonlari 9 m va 12 m. Uning diagonali qancha?', 'Стороны прямоугольника 9 м и 12 м. Чему равна диагональ?', 'A rectangle has sides 9 m and 12 m. How long is its diagonal?'), s: L('Diagonal to‘g‘ri to‘rtburchakni ikkita to‘g‘ri burchakli uchburchakka bo‘ladi, katetlar 9 va 12. d<sup>2</sup> = 81 + 144 = 225, d = <b>15 m</b>.', 'Диагональ делит прямоугольник на два прямоугольных треугольника с катетами 9 и 12. d<sup>2</sup> = 81 + 144 = 225, d = <b>15 м</b>.', 'The diagonal splits the rectangle into two right triangles with legs 9 and 12. d<sup>2</sup> = 81 + 144 = 225, so d = <b>15 m</b>.') }
    ] },
    { kind: 'table', h: L('Pifagor uchliklari', 'Пифагоровы тройки', 'Pythagorean triples'), p: [
      L('Uchala tomoni butun son bo‘lgan to‘g‘ri burchakli uchburchaklar uchun sonlar <b>Pifagor uchliklari</b> deyiladi. Ularni yodda tutish masalalarni tez yechishga yordam beradi. Har bir uchlikni istalgan butun songa ko‘paytirsak, yana uchlik hosil bo‘ladi: 3, 4, 5 → 6, 8, 10 → 9, 12, 15.', 'Числа, являющиеся сторонами прямоугольного треугольника с целыми сторонами, называются <b>пифагоровыми тройками</b>. Помнить их полезно для быстрого решения задач. Умножив тройку на любое целое число, снова получим тройку: 3, 4, 5 → 6, 8, 10 → 9, 12, 15.', 'Whole numbers that are the sides of a right triangle are called <b>Pythagorean triples</b>. Knowing them helps you solve problems fast. Multiply a triple by any whole number and you get another triple: 3, 4, 5 → 6, 8, 10 → 9, 12, 15.')
    ], table: { head: [L('a', 'a', 'a'), L('b', 'b', 'b'), L('c', 'c', 'c'), L('Tekshiruv', 'Проверка', 'Check')], rows: [
      ['3', '4', '5', L('9 + 16 = 25', '9 + 16 = 25', '9 + 16 = 25')],
      ['5', '12', '13', L('25 + 144 = 169', '25 + 144 = 169', '25 + 144 = 169')],
      ['8', '15', '17', L('64 + 225 = 289', '64 + 225 = 289', '64 + 225 = 289')],
      ['7', '24', '25', L('49 + 576 = 625', '49 + 576 = 625', '49 + 576 = 625')],
      ['20', '21', '29', L('400 + 441 = 841', '400 + 441 = 841', '400 + 441 = 841')]
    ] }, after: [
      L('Qiziq qonuniyat: agar m &gt; n natural sonlar bo‘lsa, a = m<sup>2</sup> − n<sup>2</sup>, b = 2mn, c = m<sup>2</sup> + n<sup>2</sup> har doim uchlik beradi. m = 2, n = 1 da 3, 4, 5 chiqadi; m = 3, n = 2 da esa 5, 12, 13.', 'Интересная закономерность: если m &gt; n — натуральные числа, то a = m<sup>2</sup> − n<sup>2</sup>, b = 2mn, c = m<sup>2</sup> + n<sup>2</sup> всегда дают тройку. При m = 2, n = 1 получаем 3, 4, 5; при m = 3, n = 2 — 5, 12, 13.', 'A neat pattern: for whole numbers m &gt; n, a = m<sup>2</sup> − n<sup>2</sup>, b = 2mn, c = m<sup>2</sup> + n<sup>2</sup> always form a triple. m = 2, n = 1 gives 3, 4, 5; m = 3, n = 2 gives 5, 12, 13.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Kvadratlar o‘rniga tomonlarni qo‘shish.</b> 3 + 4 = 7 emas! Gipotenuza 5 ga teng. Avval kvadratga ko‘taring, keyin qo‘shing, oxirida ildiz chiqaring.', '<b>Сложение сторон вместо квадратов.</b> 3 + 4 = 7 — неверно! Гипотенуза равна 5. Сначала возведите в квадрат, затем сложите, в конце извлеките корень.', '<b>Adding the sides instead of the squares.</b> 3 + 4 = 7 is wrong! The hypotenuse is 5. Square first, then add, then take the root.'),
      L('<b>Ildizni unutish.</b> c<sup>2</sup> = 100 topilgach, javobni 100 deb yozish xato. c = 10.', '<b>Забыли корень.</b> Найдя c<sup>2</sup> = 100, писать ответ 100 — ошибка. c = 10.', '<b>Forgetting the root.</b> After finding c<sup>2</sup> = 100, writing 100 as the answer is wrong. c = 10.'),
      L('<b>Katetni topishda qo‘shish.</b> Agar gipotenuza ma’lum bo‘lsa, kvadratlar ayiriladi: a<sup>2</sup> = c<sup>2</sup> − b<sup>2</sup>.', '<b>Сложение при поиске катета.</b> Если известна гипотенуза, квадраты вычитаются: a<sup>2</sup> = c<sup>2</sup> − b<sup>2</sup>.', '<b>Adding when looking for a leg.</b> If the hypotenuse is known, subtract: a<sup>2</sup> = c<sup>2</sup> − b<sup>2</sup>.'),
      L('<b>To‘g‘ri burchaksiz uchburchakka qo‘llash.</b> Teorema faqat to‘g‘ri burchakli uchburchak uchun o‘rinli. Boshqa uchburchaklarda avval balandlik tushirib, to‘g‘ri burchakli uchburchak hosil qilish kerak.', '<b>Применение к непрямоугольному треугольнику.</b> Теорема верна только для прямоугольных треугольников. В остальных случаях нужно сначала провести высоту.', '<b>Using it on a triangle without a right angle.</b> The theorem only holds for right triangles. For others, first draw an altitude to create right triangles.'),
      L('<b>√(a<sup>2</sup> + b<sup>2</sup>) ni a + b deb soddalashtirish.</b> Yig‘indining ildizi ildizlar yig‘indisiga teng emas: √(9 + 16) = 5, lekin √9 + √16 = 7.', '<b>Упрощение √(a<sup>2</sup> + b<sup>2</sup>) до a + b.</b> Корень из суммы не равен сумме корней: √(9 + 16) = 5, но √9 + √16 = 7.', '<b>Simplifying √(a<sup>2</sup> + b<sup>2</sup>) to a + b.</b> The root of a sum is not the sum of the roots: √(9 + 16) = 5, but √9 + √16 = 7.')
    ] },
    { kind: 'life', h: L('Hayotda Pifagor teoremasi', 'Теорема Пифагора в жизни', 'Pythagoras in everyday life'), p: [
      L('<b>Televizor va telefon ekrani.</b> Ekran o‘lchami dyuymlarda diagonal bo‘yicha beriladi. Eni 48 sm, bo‘yi 36 sm bo‘lgan ekranning diagonali √(48<sup>2</sup> + 36<sup>2</sup>) = 60 sm, ya’ni taxminan 24 dyuym.', '<b>Экран телевизора и телефона.</b> Размер экрана указывают по диагонали в дюймах. У экрана шириной 48 см и высотой 36 см диагональ √(48<sup>2</sup> + 36<sup>2</sup>) = 60 см, т.е. около 24 дюймов.', '<b>TV and phone screens.</b> Screen size is given as the diagonal in inches. A screen 48 cm wide and 36 cm tall has a diagonal of √(48<sup>2</sup> + 36<sup>2</sup>) = 60 cm, about 24 inches.'),
      L('<b>Qurilish.</b> Usta poydevor burchagi to‘g‘ri ekanini tekshirish uchun bir tomonga 3 m, ikkinchisiga 4 m o‘lchab, uchlari orasidagi masofani o‘lchaydi. Agar 5 m chiqsa — burchak to‘g‘ri. Tom yopishda esa qiya taxta uzunligi uyning yarim eni va tom balandligidan hisoblanadi.', '<b>Строительство.</b> Чтобы проверить прямой угол фундамента, мастер отмеряет 3 м по одной стороне и 4 м по другой и измеряет расстояние между концами. Если 5 м — угол прямой. При устройстве крыши длину стропила считают по половине ширины дома и высоте крыши.', '<b>Building.</b> To check that a foundation corner is square, a builder measures 3 m along one side and 4 m along the other, then the distance between the ends. If it is 5 m, the corner is right. For a roof, the length of a rafter is computed from half the house width and the roof height.'),
      L('<b>Navigatsiya va o‘yinlar.</b> Kema 12 km shimolga va 5 km sharqqa suzsa, portdan 13 km uzoqlashadi. Kompyuter o‘yinlarida ikki nuqta orasidagi masofa ham √((x<sub>2</sub> − x<sub>1</sub>)<sup>2</sup> + (y<sub>2</sub> − y<sub>1</sub>)<sup>2</sup>) formulasi bilan, ya’ni Pifagor teoremasi bilan hisoblanadi.', '<b>Навигация и игры.</b> Если корабль прошёл 12 км на север и 5 км на восток, он удалился от порта на 13 км. В компьютерных играх расстояние между двумя точками тоже считается по формуле √((x<sub>2</sub> − x<sub>1</sub>)<sup>2</sup> + (y<sub>2</sub> − y<sub>1</sub>)<sup>2</sup>), т.е. по теореме Пифагора.', '<b>Navigation and games.</b> A ship that sails 12 km north and 5 km east ends up 13 km from port. In video games the distance between two points is computed as √((x<sub>2</sub> − x<sub>1</sub>)<sup>2</sup> + (y<sub>2</sub> − y<sub>1</sub>)<sup>2</sup>) — Pythagoras again.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('1876-yilda AQShning bo‘lajak prezidenti <b>Jeyms Garfild</b> trapetsiya yuzi yordamida teoremaning o‘z isbotini topgan va uni jurnalda chop ettirgan.', 'В 1876 году будущий президент США <b>Джеймс Гарфилд</b> нашёл собственное доказательство теоремы через площадь трапеции и опубликовал его в журнале.', 'In 1876 the future US president <b>James Garfield</b> found his own proof using the area of a trapezium and published it in a journal.'),
      L('O‘rta asrlarda talabalar teoremani «eshak ko‘prigi» deb atashgan: kim undan o‘ta olmasa, geometriyani tushuna olmaydi, deb hisoblangan.', 'В Средние века студенты называли теорему «ослиным мостом»: считалось, что кто не перейдёт через неё, не поймёт геометрию.', 'In the Middle Ages students called the theorem the “bridge of asses”: whoever could not cross it would never understand geometry.'),
      L('Teorema faqat kvadratlar uchun emas: tomonlarga qurilgan har qanday o‘xshash shakllar (yarim doiralar, teng tomonli uchburchaklar) uchun ham katta shakl yuzi ikki kichigining yig‘indisiga teng.', 'Теорема верна не только для квадратов: для любых подобных фигур на сторонах (полукругов, равносторонних треугольников) площадь большой фигуры равна сумме двух меньших.', 'It is not just about squares: for any similar shapes built on the sides (semicircles, equilateral triangles) the big shape’s area equals the sum of the two smaller ones.'),
      L('Fermaning mashhur teoremasi aytadiki, n &gt; 2 da a<sup>n</sup> + b<sup>n</sup> = c<sup>n</sup> tenglama natural sonlarda yechimga ega emas. Uni 350 yildan keyin, 1994-yilda Endryu Uayls isbotlagan.', 'Знаменитая теорема Ферма утверждает, что при n &gt; 2 уравнение a<sup>n</sup> + b<sup>n</sup> = c<sup>n</sup> не имеет решений в натуральных числах. Её доказал Эндрю Уайлс в 1994 году, спустя 350 лет.', 'Fermat’s famous theorem says that for n &gt; 2 the equation a<sup>n</sup> + b<sup>n</sup> = c<sup>n</sup> has no whole-number solutions. Andrew Wiles proved it in 1994, 350 years later.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), p: [
      L('Avval o‘zingiz yeching, so‘ng javob bilan solishtiring.', 'Сначала решите сами, потом сверьтесь с ответом.', 'Solve first on your own, then compare with the answer.')
    ], ex: [
      { q: L('Katetlar 9 va 40. Gipotenuza?', 'Катеты 9 и 40. Гипотенуза?', 'Legs 9 and 40. Hypotenuse?'), s: L('81 + 1600 = 1681 = 41<sup>2</sup>. Javob: <b>41</b>.', '81 + 1600 = 1681 = 41<sup>2</sup>. Ответ: <b>41</b>.', '81 + 1600 = 1681 = 41<sup>2</sup>. Answer: <b>41</b>.') },
      { q: L('10 m uzunlikdagi narvon devorga suyalgan, pastki uchi devordan 6 m uzoqda. Narvon qanday balandlikka yetadi?', 'Лестница длиной 10 м приставлена к стене, её низ в 6 м от стены. На какую высоту она достаёт?', 'A 10 m ladder leans on a wall with its foot 6 m away. How high does it reach?'), s: L('Narvon — gipotenuza. h = √(100 − 36) = √64 = <b>8 m</b>.', 'Лестница — гипотенуза. h = √(100 − 36) = √64 = <b>8 м</b>.', 'The ladder is the hypotenuse. h = √(100 − 36) = √64 = <b>8 m</b>.') },
      { q: L('Kvadratning diagonali 10 sm. Uning tomoni qancha?', 'Диагональ квадрата 10 см. Чему равна сторона?', 'A square’s diagonal is 10 cm. How long is its side?'), s: L('a<sup>2</sup> + a<sup>2</sup> = 100, a<sup>2</sup> = 50, a = <b>5√2 ≈ 7,07 sm</b>.', 'a<sup>2</sup> + a<sup>2</sup> = 100, a<sup>2</sup> = 50, a = <b>5√2 ≈ 7,07 см</b>.', 'a<sup>2</sup> + a<sup>2</sup> = 100, a<sup>2</sup> = 50, a = <b>5√2 ≈ 7.07 cm</b>.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('To‘g‘ri burchakni hosil qiluvchi tomonlar — katetlar, uning qarshisidagi tomon — gipotenuza (eng uzun tomon).', 'Стороны, образующие прямой угол, — катеты, сторона против него — гипотенуза (самая длинная).', 'The sides forming the right angle are the legs; the side opposite it is the hypotenuse (the longest side).'),
      L('Pifagor teoremasi: c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup>.', 'Теорема Пифагора: c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup>.', 'Pythagoras’ theorem: c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup>.'),
      L('Gipotenuza uchun kvadratlar qo‘shiladi, katet uchun ayiriladi; oxirida ildiz chiqariladi.', 'Для гипотенузы квадраты складывают, для катета — вычитают; в конце извлекают корень.', 'For the hypotenuse add the squares; for a leg subtract them; finish by taking the square root.'),
      L('Isbot g‘oyasi: tomoni a + b bo‘lgan kvadrat yuzini ikki usulda hisoblash.', 'Идея доказательства: вычислить площадь квадрата со стороной a + b двумя способами.', 'Proof idea: compute the area of a square of side a + b in two ways.'),
      L('Bu bog‘lanishni Bobil (Plimpton 322), Xitoy va Hindistonda bilishgan; yunonlar uni isbotlagan.', 'Эту связь знали в Вавилоне (Плимптон 322), Китае и Индии; греки её доказали.', 'Babylon (Plimpton 322), China and India knew the relation; the Greeks proved it.'),
      L('Pifagor uchliklari: 3, 4, 5; 5, 12, 13; 8, 15, 17; 7, 24, 25.', 'Пифагоровы тройки: 3, 4, 5; 5, 12, 13; 8, 15, 17; 7, 24, 25.', 'Pythagorean triples: 3, 4, 5; 5, 12, 13; 8, 15, 17; 7, 24, 25.')
    ] }
  ] });

  // ---------- t12. Pifagor teoremasining natijalari. Teskari teorema ----------
  T.add(P, 't12', { sections: [
    { kind: 'intro', h: L('Teoremadan kelib chiqadigan xulosalar', 'Что следует из теоремы', 'What follows from the theorem'), p: [
      L('Matematikada yaxshi teorema — bu bitta natija emas, balki ko‘plab yangi xulosalarning manbai. Pifagor teoremasi ham shunday: undan bir qator foydali faktlar kelib chiqadi. Masalan, nega to‘g‘ridan yurgan yo‘l qiyshiq yo‘ldan qisqa? Nega kvadrat diagonali tomonidan taxminan 1,4 marta uzun? Bularning barchasi Pifagor teoremasining <b>natijalari</b>.', 'Хорошая теорема в математике — не один результат, а источник множества новых выводов. Так и с теоремой Пифагора: из неё вытекает ряд полезных фактов. Почему прямой путь короче косого? Почему диагональ квадрата примерно в 1,4 раза длиннее стороны? Всё это — <b>следствия</b> теоремы Пифагора.', 'In mathematics a good theorem is not one result but a source of many new conclusions. Pythagoras’ theorem is like that: a series of useful facts follow from it. Why is a straight path shorter than a slanted one? Why is a square’s diagonal about 1.4 times its side? All these are <b>consequences</b> of Pythagoras’ theorem.'),
      L('Shuningdek, savolni teskari qo‘yish mumkin: agar uchburchak tomonlari uchun a<sup>2</sup> + b<sup>2</sup> = c<sup>2</sup> bajarilsa, u albatta to‘g‘ri burchaklimi? Javob — ha, va bu <b>teskari teorema</b> deyiladi. Undan qadimgi Misr quruvchilari ham foydalangan. Ushbu mavzuda natijalarni, teskari teoremani va uchburchak turini tomonlari bo‘yicha aniqlashni o‘rganamiz.', 'Можно также задать обратный вопрос: если для сторон треугольника выполняется a<sup>2</sup> + b<sup>2</sup> = c<sup>2</sup>, обязательно ли он прямоугольный? Ответ — да, и это <b>обратная теорема</b>. Ею пользовались ещё строители Древнего Египта. В этой теме изучим следствия, обратную теорему и определение вида треугольника по сторонам.', 'We can also ask the reverse question: if a triangle’s sides satisfy a<sup>2</sup> + b<sup>2</sup> = c<sup>2</sup>, must it be right-angled? The answer is yes, and this is the <b>converse theorem</b>. Ancient Egyptian builders relied on it. In this topic we study the consequences, the converse and how to tell a triangle’s type from its sides.')
    ] },
    { kind: 'def', h: L('Perpendikulyar, og‘ma va proyeksiya', 'Перпендикуляр, наклонная и проекция', 'Perpendicular, oblique and projection'), p: [
      L('Natijalarni tushunish uchun uchta atama kerak. To‘g‘ri chiziqdan tashqaridagi A nuqtadan shu chiziqqa tushirilgan kesmalarni ko‘ramiz:', 'Для понимания следствий нужны три термина. Рассмотрим отрезки, проведённые из точки A вне прямой к этой прямой:', 'To understand the consequences we need three terms. Consider segments drawn from a point A outside a line to that line:')
    ], list: [
      L('<b>Perpendikulyar</b> AH — to‘g‘ri chiziq bilan 90° burchak hosil qiluvchi kesma; H — perpendikulyar asosi.', '<b>Перпендикуляр</b> AH — отрезок, образующий с прямой угол 90°; H — основание перпендикуляра.', 'The <b>perpendicular</b> AH meets the line at 90°; H is the foot of the perpendicular.'),
      L('<b>Og‘ma</b> AB — A ni to‘g‘ri chiziqning H dan boshqa istalgan B nuqtasi bilan tutashtiruvchi kesma.', '<b>Наклонная</b> AB — отрезок, соединяющий A с любой точкой B прямой, отличной от H.', 'An <b>oblique</b> (slanted segment) AB joins A to any point B of the line other than H.'),
      L('<b>Og‘maning proyeksiyasi</b> HB — perpendikulyar asosi bilan og‘ma asosi orasidagi kesma.', '<b>Проекция наклонной</b> HB — отрезок между основанием перпендикуляра и основанием наклонной.', 'The <b>projection</b> of the oblique, HB, is the segment between the foot of the perpendicular and the foot of the oblique.')
    ], after: [
      L('AHB uchburchak to‘g‘ri burchakli: AH va HB — katetlar, og‘ma AB — gipotenuza. Shuning uchun AB<sup>2</sup> = AH<sup>2</sup> + HB<sup>2</sup>. Barcha natijalar shu tenglikdan kelib chiqadi.', 'Треугольник AHB прямоугольный: AH и HB — катеты, наклонная AB — гипотенуза. Поэтому AB<sup>2</sup> = AH<sup>2</sup> + HB<sup>2</sup>. Все следствия вытекают из этого равенства.', 'Triangle AHB is right-angled: AH and HB are legs and the oblique AB is the hypotenuse, so AB<sup>2</sup> = AH<sup>2</sup> + HB<sup>2</sup>. All the consequences come from this equation.')
    ] },
    { kind: 'history', h: L('Misrning «arqon tortuvchilari»', 'Египетские «натягиватели верёвки»', 'Egypt’s “rope-stretchers”'), p: [
      L('Qadimgi Misrda Nil daryosi har yili toshib, dalalar chegaralarini yuvib ketardi. Suv qaytgach, yerlarni qaytadan o‘lchash kerak bo‘lardi. Bu ishni maxsus mutaxassislar — yunonlar ularni <b>«arqon tortuvchilar»</b> (garpedonaptlar) deb atashgan — bajarishgan. Ularning asosiy quroli teng oraliqlarda 12 ta tugun bog‘langan arqon edi.', 'В Древнем Египте Нил каждый год разливался и смывал границы полей. Когда вода уходила, землю приходилось размечать заново. Этим занимались особые специалисты — греки называли их <b>«натягивателями верёвки»</b> (гарпедонаптами). Их главным инструментом была верёвка с 12 узлами на равных расстояниях.', 'In ancient Egypt the Nile flooded every year and washed away field boundaries. When the water went down the land had to be marked out again. Special surveyors did this — the Greeks called them <b>“rope-stretchers”</b> (harpedonaptae). Their main tool was a rope with 12 knots at equal spacing.'),
      L('Arqonni 3, 4 va 5 bo‘lakdan iborat uchburchak qilib tortishsa, 3 va 4 bo‘laklar orasida aniq to‘g‘ri burchak hosil bo‘lardi. Bu — teskari teoremaning amaliy qo‘llanishi: 3<sup>2</sup> + 4<sup>2</sup> = 5<sup>2</sup> bo‘lgani uchun burchak 90°. Tarixchilar Misrliklar bu usulni piramida va ibodatxonalar asosini belgilashda ham qo‘llagan bo‘lishi mumkin, deb taxmin qilishadi. Teskari teoremaning qat’iy isbotini esa <b>Yevklid</b> «Negizlar»ning birinchi kitobidagi oxirgi, 48-taklif sifatida bergan.', 'Если натянуть верёвку треугольником из 3, 4 и 5 отрезков, между отрезками 3 и 4 получался точный прямой угол. Это практическое применение обратной теоремы: так как 3<sup>2</sup> + 4<sup>2</sup> = 5<sup>2</sup>, угол равен 90°. Историки предполагают, что египтяне могли так размечать и основания пирамид и храмов. Строгое доказательство обратной теоремы дал <b>Евклид</b> — последнее, 48-е предложение первой книги «Начал».', 'Stretching the rope into a triangle of 3, 4 and 5 sections gave an exact right angle between the 3 and 4 sections. That is the converse theorem in practice: since 3<sup>2</sup> + 4<sup>2</sup> = 5<sup>2</sup>, the angle is 90°. Historians suggest Egyptians may have laid out the bases of pyramids and temples this way. The strict proof of the converse was given by <b>Euclid</b> as the last, 48th proposition of Book I of the “Elements”.')
    ] },
    { kind: 'rule', h: L('Pifagor teoremasining natijalari', 'Следствия теоремы Пифагора', 'Consequences of the theorem'), list: [
      L('<b>1-natija.</b> To‘g‘ri burchakli uchburchakda har bir katet gipotenuzadan kichik: c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> &gt; a<sup>2</sup>, demak c &gt; a.', '<b>Следствие 1.</b> В прямоугольном треугольнике любой катет меньше гипотенузы: c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> &gt; a<sup>2</sup>, значит c &gt; a.', '<b>Consequence 1.</b> In a right triangle each leg is shorter than the hypotenuse: c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> &gt; a<sup>2</sup>, so c &gt; a.'),
      L('<b>2-natija.</b> Bir nuqtadan to‘g‘ri chiziqqa tushirilgan perpendikulyar har qanday og‘madan qisqa. Shuning uchun nuqtadan to‘g‘ri chiziqqacha masofa perpendikulyar bo‘yicha o‘lchanadi.', '<b>Следствие 2.</b> Перпендикуляр, проведённый из точки к прямой, короче любой наклонной. Поэтому расстояние от точки до прямой измеряют по перпендикуляру.', '<b>Consequence 2.</b> The perpendicular from a point to a line is shorter than any oblique. That is why distance from a point to a line is measured along the perpendicular.'),
      L('<b>3-natija.</b> Bir nuqtadan o‘tkazilgan ikki og‘madan proyeksiyasi uzunrog‘i uzunroq; teng og‘malarning proyeksiyalari teng.', '<b>Следствие 3.</b> Из двух наклонных, проведённых из одной точки, длиннее та, у которой проекция длиннее; равные наклонные имеют равные проекции.', '<b>Consequence 3.</b> Of two obliques from the same point, the one with the longer projection is longer; equal obliques have equal projections.'),
      L('<b>4-natija.</b> Tomoni a bo‘lgan kvadrat diagonali d = a√2 ≈ 1,41a.', '<b>Следствие 4.</b> Диагональ квадрата со стороной a равна d = a√2 ≈ 1,41a.', '<b>Consequence 4.</b> The diagonal of a square with side a is d = a√2 ≈ 1.41a.'),
      L('<b>5-natija.</b> Tomoni a bo‘lgan teng tomonli uchburchak balandligi h = a√3/2 ≈ 0,87a.', '<b>Следствие 5.</b> Высота равностороннего треугольника со стороной a равна h = a√3/2 ≈ 0,87a.', '<b>Consequence 5.</b> The height of an equilateral triangle with side a is h = a√3/2 ≈ 0.87a.')
    ], after: [
      L('5-natijani tekshiramiz: balandlik asosni teng ikkiga bo‘ladi, shuning uchun h<sup>2</sup> = a<sup>2</sup> − (a/2)<sup>2</sup> = 3a<sup>2</sup>/4, h = a√3/2.', 'Проверим следствие 5: высота делит основание пополам, поэтому h<sup>2</sup> = a<sup>2</sup> − (a/2)<sup>2</sup> = 3a<sup>2</sup>/4, h = a√3/2.', 'Check consequence 5: the height halves the base, so h<sup>2</sup> = a<sup>2</sup> − (a/2)<sup>2</sup> = 3a<sup>2</sup>/4, h = a√3/2.')
    ] },
    { kind: 'rule', h: L('Teskari teorema', 'Обратная теорема', 'The converse theorem'), p: [
      L('<b>Teorema.</b> Agar uchburchakning bir tomoni kvadrati qolgan ikki tomoni kvadratlari yig‘indisiga teng bo‘lsa (c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup>), u holda bu uchburchak to‘g‘ri burchakli, to‘g‘ri burchak esa c tomon qarshisida yotadi.', '<b>Теорема.</b> Если квадрат одной стороны треугольника равен сумме квадратов двух других (c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup>), то треугольник прямоугольный, а прямой угол лежит против стороны c.', '<b>Theorem.</b> If the square of one side of a triangle equals the sum of the squares of the other two (c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup>), then the triangle is right-angled, with the right angle opposite side c.'),
      L('<b>Isbot g‘oyasi.</b> Katetlari a va b bo‘lgan yangi to‘g‘ri burchakli uchburchak chizamiz. Pifagor teoremasiga ko‘ra uning gipotenuzasi √(a<sup>2</sup> + b<sup>2</sup>) = c. Demak, yangi uchburchak bilan berilgan uchburchakning uchala tomoni teng va ular uch tomon bo‘yicha (TTT alomati) teng. Teng uchburchaklarning mos burchaklari teng, shuning uchun berilgan uchburchakda ham 90° li burchak bor.', '<b>Идея доказательства.</b> Построим новый прямоугольный треугольник с катетами a и b. По теореме Пифагора его гипотенуза равна √(a<sup>2</sup> + b<sup>2</sup>) = c. Значит, у нового и данного треугольников все три стороны равны, и они равны по трём сторонам. Соответствующие углы равных треугольников равны, поэтому в данном треугольнике тоже есть угол 90°.', '<b>Proof idea.</b> Draw a new right triangle with legs a and b. By Pythagoras its hypotenuse is √(a<sup>2</sup> + b<sup>2</sup>) = c. So the new triangle and the given one have all three sides equal, and they are congruent (SSS). Corresponding angles of congruent triangles are equal, so the given triangle also has a 90° angle.'),
      L('Teorema va teskari teorema birgalikda shuni bildiradi: uchburchak to‘g‘ri burchakli bo‘lishi uchun c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> bo‘lishi <b>zarur va yetarli</b>.', 'Теорема и обратная к ней вместе означают: для того чтобы треугольник был прямоугольным, <b>необходимо и достаточно</b>, чтобы c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup>.', 'Together, the theorem and its converse say that c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> is <b>necessary and sufficient</b> for a triangle to be right-angled.')
    ] },
    { kind: 'steps', h: L('Uchburchak turini tomonlari bo‘yicha aniqlash', 'Определение вида треугольника по сторонам', 'Telling a triangle’s type from its sides'), list: [
      L('1-qadam. Eng uzun tomonni toping va uni c deb belgilang.', 'Шаг 1. Найдите самую длинную сторону и обозначьте её c.', 'Step 1. Find the longest side and call it c.'),
      L('2-qadam. Uchburchak mavjudligini tekshiring: a + b &gt; c bo‘lishi shart.', 'Шаг 2. Проверьте, существует ли треугольник: должно быть a + b &gt; c.', 'Step 2. Check that the triangle exists: a + b &gt; c must hold.'),
      L('3-qadam. c<sup>2</sup> va a<sup>2</sup> + b<sup>2</sup> ni hisoblang.', 'Шаг 3. Вычислите c<sup>2</sup> и a<sup>2</sup> + b<sup>2</sup>.', 'Step 3. Compute c<sup>2</sup> and a<sup>2</sup> + b<sup>2</sup>.'),
      L('4-qadam. Taqqoslang: teng bo‘lsa — to‘g‘ri burchakli; c<sup>2</sup> kichik bo‘lsa — o‘tkir burchakli; c<sup>2</sup> katta bo‘lsa — o‘tmas burchakli.', 'Шаг 4. Сравните: если равны — прямоугольный; если c<sup>2</sup> меньше — остроугольный; если c<sup>2</sup> больше — тупоугольный.', 'Step 4. Compare: equal — right-angled; c<sup>2</sup> smaller — acute; c<sup>2</sup> larger — obtuse.')
    ], after: [
      L('Nega shunday? Ikki tomon a va b ni qaychi kabi tasavvur qiling. Ular orasidagi burchak kattalashsa, uchlari orasidagi masofa c ham o‘sadi. Burchak 90° bo‘lganda c<sup>2</sup> aynan a<sup>2</sup> + b<sup>2</sup> ga teng; burchak kichikroq bo‘lsa c qisqaroq, kattaroq bo‘lsa — uzunroq.', 'Почему так? Представьте стороны a и b как ножницы. Чем больше угол между ними, тем больше расстояние c между концами. При 90° c<sup>2</sup> ровно равно a<sup>2</sup> + b<sup>2</sup>; при меньшем угле c короче, при большем — длиннее.', 'Why? Think of sides a and b as the blades of scissors. The wider the angle between them, the longer the distance c between their tips. At 90° c<sup>2</sup> is exactly a<sup>2</sup> + b<sup>2</sup>; at a smaller angle c is shorter, at a larger one longer.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Tomonlari 7, 24, 25 bo‘lgan uchburchak to‘g‘ri burchaklimi?', 'Является ли треугольник со сторонами 7, 24, 25 прямоугольным?', 'Is the triangle with sides 7, 24, 25 right-angled?'), s: L('Eng uzun tomon 25. 7<sup>2</sup> + 24<sup>2</sup> = 49 + 576 = 625 = 25<sup>2</sup>. Teskari teoremaga ko‘ra <b>ha</b>, to‘g‘ri burchak 25 tomon qarshisida.', 'Самая длинная сторона 25. 7<sup>2</sup> + 24<sup>2</sup> = 49 + 576 = 625 = 25<sup>2</sup>. По обратной теореме — <b>да</b>, прямой угол против стороны 25.', 'Longest side 25. 7<sup>2</sup> + 24<sup>2</sup> = 49 + 576 = 625 = 25<sup>2</sup>. By the converse, <b>yes</b>; the right angle is opposite 25.') },
      { q: L('Tomonlari 5, 6, 8 bo‘lgan uchburchak turini aniqlang.', 'Определите вид треугольника со сторонами 5, 6, 8.', 'Classify the triangle with sides 5, 6, 8.'), s: L('8<sup>2</sup> = 64, 5<sup>2</sup> + 6<sup>2</sup> = 61. 64 &gt; 61, demak eng katta burchak 90° dan katta — uchburchak <b>o‘tmas burchakli</b>.', '8<sup>2</sup> = 64, 5<sup>2</sup> + 6<sup>2</sup> = 61. 64 &gt; 61, значит наибольший угол больше 90° — треугольник <b>тупоугольный</b>.', '8<sup>2</sup> = 64, 5<sup>2</sup> + 6<sup>2</sup> = 61. Since 64 &gt; 61, the largest angle exceeds 90° — the triangle is <b>obtuse</b>.') },
      { q: L('Tomoni 6 sm bo‘lgan kvadrat diagonali va teng tomonli uchburchak balandligini toping.', 'Найдите диагональ квадрата и высоту равностороннего треугольника со стороной 6 см.', 'Find the diagonal of a square and the height of an equilateral triangle, both with side 6 cm.'), s: L('Kvadrat: d = 6√2 ≈ <b>8,49 sm</b>. Uchburchak: h = 6√3/2 = 3√3 ≈ <b>5,20 sm</b>.', 'Квадрат: d = 6√2 ≈ <b>8,49 см</b>. Треугольник: h = 6√3/2 = 3√3 ≈ <b>5,20 см</b>.', 'Square: d = 6√2 ≈ <b>8.49 cm</b>. Triangle: h = 6√3/2 = 3√3 ≈ <b>5.20 cm</b>.') },
      { q: L('A nuqtadan to‘g‘ri chiziqqa uzunligi 12 bo‘lgan perpendikulyar va uzunligi 13 bo‘lgan og‘ma o‘tkazilgan. Og‘ma proyeksiyasini toping.', 'Из точки A к прямой проведены перпендикуляр длиной 12 и наклонная длиной 13. Найдите проекцию наклонной.', 'From point A a perpendicular of length 12 and an oblique of length 13 are drawn to a line. Find the projection of the oblique.'), s: L('Og‘ma — gipotenuza: HB = √(13<sup>2</sup> − 12<sup>2</sup>) = √25 = <b>5</b>.', 'Наклонная — гипотенуза: HB = √(13<sup>2</sup> − 12<sup>2</sup>) = √25 = <b>5</b>.', 'The oblique is the hypotenuse: HB = √(13<sup>2</sup> − 12<sup>2</sup>) = √25 = <b>5</b>.') }
    ] },
    { kind: 'table', h: L('Uchburchak turlari jadvali', 'Таблица видов треугольников', 'Table of triangle types'), p: [
      L('c — eng uzun tomon. Taqqoslash natijasi eng katta burchakning turini ko‘rsatadi.', 'c — наибольшая сторона. Результат сравнения показывает вид наибольшего угла.', 'c is the longest side. The comparison tells you the type of the largest angle.')
    ], table: { head: [L('Tomonlar', 'Стороны', 'Sides'), L('c<sup>2</sup>', 'c<sup>2</sup>', 'c<sup>2</sup>'), L('a<sup>2</sup> + b<sup>2</sup>', 'a<sup>2</sup> + b<sup>2</sup>', 'a<sup>2</sup> + b<sup>2</sup>'), L('Turi', 'Вид', 'Type')], rows: [
      [L('6, 8, 10', '6, 8, 10', '6, 8, 10'), '100', '100', L('to‘g‘ri burchakli', 'прямоугольный', 'right')],
      [L('4, 5, 6', '4, 5, 6', '4, 5, 6'), '36', '41', L('o‘tkir burchakli', 'остроугольный', 'acute')],
      [L('3, 5, 7', '3, 5, 7', '3, 5, 7'), '49', '34', L('o‘tmas burchakli', 'тупоугольный', 'obtuse')],
      [L('9, 40, 41', '9, 40, 41', '9, 40, 41'), '1681', '1681', L('to‘g‘ri burchakli', 'прямоугольный', 'right')],
      [L('1, 1, √2', '1, 1, √2', '1, 1, √2'), '2', '2', L('to‘g‘ri burchakli, teng yonli', 'прямоугольный, равнобедренный', 'right isosceles')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Eng uzun tomonni c deb olmaslik.</b> 13, 5, 12 sonlarida birinchi son eng uzun; 5<sup>2</sup> + 13<sup>2</sup> ni 12<sup>2</sup> bilan taqqoslash noto‘g‘ri xulosaga olib keladi.', '<b>Не взяли за c наибольшую сторону.</b> В числах 13, 5, 12 наибольшее — первое; сравнивать 5<sup>2</sup> + 13<sup>2</sup> с 12<sup>2</sup> — ошибка.', '<b>Not taking the longest side as c.</b> In 13, 5, 12 the first number is the longest; comparing 5<sup>2</sup> + 13<sup>2</sup> with 12<sup>2</sup> gives a wrong conclusion.'),
      L('<b>Teorema bilan teskari teoremani chalkashtirish.</b> To‘g‘ri burchak ma’lum bo‘lsa — tomonni hisoblaymiz (teorema); tomonlar ma’lum bo‘lsa — burchakni aniqlaymiz (teskari teorema).', '<b>Путают теорему и обратную.</b> Известен прямой угол — вычисляем сторону (теорема); известны стороны — определяем угол (обратная теорема).', '<b>Mixing up the theorem and its converse.</b> If the right angle is known, compute a side (theorem); if the sides are known, decide the angle (converse).'),
      L('<b>Mavjudlikni tekshirmaslik.</b> 2, 3, 6 «o‘tmas burchakli» emas — bunday uchburchak umuman yo‘q, chunki 2 + 3 &lt; 6.', '<b>Не проверили существование.</b> 2, 3, 6 — не «тупоугольный»: такого треугольника нет вовсе, ведь 2 + 3 &lt; 6.', '<b>Not checking existence.</b> 2, 3, 6 is not “obtuse” — no such triangle exists, since 2 + 3 &lt; 6.'),
      L('<b>Kvadrat diagonalini 2a deb olish.</b> Diagonal a√2 ≈ 1,41a, ikki tomondan qisqa.', '<b>Считают диагональ квадрата равной 2a.</b> Диагональ a√2 ≈ 1,41a, она короче двух сторон.', '<b>Taking a square’s diagonal as 2a.</b> It is a√2 ≈ 1.41a, shorter than two sides.')
    ] },
    { kind: 'life', h: L('Amaliyotda', 'На практике', 'In practice'), p: [
      L('<b>Duradgor va quruvchilar</b> bugun ham «3–4–5 qoidasi» bilan ishlaydi: devor burchagidan bir tomonga 60 sm, ikkinchisiga 80 sm belgilab, oralig‘ini o‘lchaydi. 100 sm chiqsa, burchak to‘g‘ri. Katta maydonlarda 6, 8, 10 m yoki 9, 12, 15 m ishlatiladi.', '<b>Столяры и строители</b> и сегодня пользуются «правилом 3–4–5»: отмечают от угла 60 см по одной стене и 80 см по другой и меряют расстояние. Если 100 см — угол прямой. На больших площадках берут 6, 8, 10 м или 9, 12, 15 м.', '<b>Carpenters and builders</b> still use the “3–4–5 rule”: mark 60 cm along one wall and 80 cm along the other from a corner, then measure between the marks. If it is 100 cm, the corner is square. On big sites they use 6, 8, 10 m or 9, 12, 15 m.'),
      L('<b>Eng qisqa yo‘l.</b> 2-natija tufayli ko‘prik yoki quvurni daryoga perpendikulyar qurish eng arzon: perpendikulyar — eng qisqa masofa. Futbolchi ham himoyachini quvib yetish uchun to‘g‘ri chiziq bo‘ylab, perpendikulyar yo‘nalishda yuguradi.', '<b>Кратчайший путь.</b> Благодаря следствию 2 мост или трубу дешевле строить перпендикулярно реке: перпендикуляр — кратчайшее расстояние. Футболист, чтобы перехватить соперника, тоже бежит по перпендикуляру к его линии.', '<b>The shortest path.</b> Because of consequence 2, a bridge or pipe is cheapest when built perpendicular to the river: the perpendicular is the shortest distance. A footballer cutting off an opponent runs perpendicular to the opponent’s line, too.'),
      L('<b>Sport maydonlari.</b> Futbol maydoni chiziqlarini belgilashda diagonallarni o‘lchashadi: to‘g‘ri to‘rtburchakda ular teng bo‘lishi kerak, aks holda maydon «qiyshaygan».', '<b>Спортивные площадки.</b> Размечая футбольное поле, измеряют диагонали: в прямоугольнике они должны быть равны, иначе поле «перекошено».', '<b>Sports fields.</b> When marking a football pitch, groundsmen measure the diagonals: in a rectangle they must be equal, otherwise the pitch is skewed.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('8, 15, 17 — to‘g‘ri burchaklimi?', '8, 15, 17 — прямоугольный?', '8, 15, 17 — right-angled?'), s: L('64 + 225 = 289 = 17<sup>2</sup>. <b>Ha.</b>', '64 + 225 = 289 = 17<sup>2</sup>. <b>Да.</b>', '64 + 225 = 289 = 17<sup>2</sup>. <b>Yes.</b>') },
      { q: L('6, 7, 9 — qanday uchburchak?', '6, 7, 9 — какой треугольник?', '6, 7, 9 — which type?'), s: L('81 va 36 + 49 = 85. 81 &lt; 85 — <b>o‘tkir burchakli</b>.', '81 и 36 + 49 = 85. 81 &lt; 85 — <b>остроугольный</b>.', '81 versus 36 + 49 = 85. 81 &lt; 85 — <b>acute</b>.') },
      { q: L('Kvadrat diagonali 4√2. Tomoni?', 'Диагональ квадрата 4√2. Сторона?', 'A square’s diagonal is 4√2. Its side?'), s: L('d = a√2 ⇒ a = <b>4</b>.', 'd = a√2 ⇒ a = <b>4</b>.', 'd = a√2 ⇒ a = <b>4</b>.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Katet gipotenuzadan kichik; perpendikulyar har qanday og‘madan qisqa.', 'Катет меньше гипотенузы; перпендикуляр короче любой наклонной.', 'A leg is shorter than the hypotenuse; the perpendicular is shorter than any oblique.'),
      L('Proyeksiyasi uzun og‘ma uzunroq; teng og‘malarning proyeksiyalari teng.', 'Наклонная с большей проекцией длиннее; равные наклонные имеют равные проекции.', 'The oblique with the longer projection is longer; equal obliques have equal projections.'),
      L('Kvadrat diagonali a√2, teng tomonli uchburchak balandligi a√3/2.', 'Диагональ квадрата a√2, высота равностороннего треугольника a√3/2.', 'A square’s diagonal is a√2; an equilateral triangle’s height is a√3/2.'),
      L('Teskari teorema: c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup> bo‘lsa, uchburchak to‘g‘ri burchakli.', 'Обратная теорема: если c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup>, треугольник прямоугольный.', 'Converse: if c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup>, the triangle is right-angled.'),
      L('c<sup>2</sup> &lt; a<sup>2</sup> + b<sup>2</sup> — o‘tkir, c<sup>2</sup> &gt; a<sup>2</sup> + b<sup>2</sup> — o‘tmas burchakli uchburchak.', 'c<sup>2</sup> &lt; a<sup>2</sup> + b<sup>2</sup> — остроугольный, c<sup>2</sup> &gt; a<sup>2</sup> + b<sup>2</sup> — тупоугольный.', 'c<sup>2</sup> &lt; a<sup>2</sup> + b<sup>2</sup> — acute; c<sup>2</sup> &gt; a<sup>2</sup> + b<sup>2</sup> — obtuse.'),
      L('Misr arqon tortuvchilari 3–4–5 arqon bilan to‘g‘ri burchak yasashgan.', 'Египетские натягиватели верёвки строили прямой угол верёвкой 3–4–5.', 'Egyptian rope-stretchers made right angles with a 3–4–5 rope.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-2';

  // ---------- t13. Uchburchak balandligi. Geron formulasi ----------
  T.add(P, 't13', { sections: [
    { kind: 'intro', h: L('Faqat tomonlar ma’lum bo‘lsa', 'Когда известны только стороны', 'When only the sides are known'), p: [
      L('Dehqon uchburchak shaklidagi yer uchastkasini sotib olmoqchi. U ruletka bilan uchala tomonni o‘lchadi: 13 m, 14 m va 15 m. Ammo yuzni hisoblash uchun balandlik kerak, maydon o‘rtasida esa daraxtlar o‘sgani sababli balandlikni to‘g‘ridan-to‘g‘ri o‘lchab bo‘lmaydi. Nima qilish kerak? Ikki yo‘l bor: balandlikni Pifagor teoremasi yordamida hisoblash yoki qadimgi olim Geron kashf etgan ajoyib formuladan foydalanish.', 'Фермер хочет купить треугольный участок земли. Он измерил рулеткой все три стороны: 13 м, 14 м и 15 м. Но для площади нужна высота, а измерить её напрямую нельзя — посреди участка растут деревья. Что делать? Есть два пути: вычислить высоту с помощью теоремы Пифагора или воспользоваться замечательной формулой, открытой древним учёным Героном.', 'A farmer wants to buy a triangular plot of land. With a tape measure he finds the three sides: 13 m, 14 m and 15 m. To find the area he needs a height, but trees in the middle of the field make it impossible to measure directly. What can he do? There are two ways: compute the height with Pythagoras’ theorem, or use the wonderful formula discovered by the ancient scholar Heron.'),
      L('Bu mavzuda uchburchakning balandligi nima ekanini eslaymiz, uni tomonlar orqali hisoblashni va <b>Geron formulasini</b> o‘rganamiz. Bu formula yuzni faqat uchta tomon orqali, hech qanday burchak yoki balandliksiz topishga imkon beradi.', 'В этой теме вспомним, что такое высота треугольника, научимся вычислять её через стороны и изучим <b>формулу Герона</b>. Она позволяет найти площадь только по трём сторонам, без углов и высот.', 'In this topic we recall what a triangle’s height is, learn to compute it from the sides, and study <b>Heron’s formula</b>, which gives the area from the three sides alone, with no angles or heights.')
    ] },
    { kind: 'def', h: L('Balandlik va yarim perimetr', 'Высота и полупериметр', 'Height and semi-perimeter'), p: [
      L('Uchburchakning <b>balandligi</b> — uchidan qarshi tomonga (yoki uning davomiga) tushirilgan perpendikulyar. Har bir uchburchakning uchta balandligi bor: h<sub>a</sub>, h<sub>b</sub>, h<sub>c</sub>. O‘tkir burchakli uchburchakda ular ichkarida, to‘g‘ri burchaklida ikki balandlik katetlar bilan ustma-ust tushadi, o‘tmas burchaklida esa ikkitasi tashqarida yotadi.', '<b>Высота</b> треугольника — перпендикуляр, опущенный из вершины на противоположную сторону (или её продолжение). У каждого треугольника три высоты: h<sub>a</sub>, h<sub>b</sub>, h<sub>c</sub>. В остроугольном они внутри, в прямоугольном две совпадают с катетами, в тупоугольном две лежат снаружи.', 'A triangle’s <b>height</b> (altitude) is the perpendicular from a vertex to the opposite side or its extension. Every triangle has three: h<sub>a</sub>, h<sub>b</sub>, h<sub>c</sub>. In an acute triangle they lie inside; in a right triangle two of them coincide with the legs; in an obtuse triangle two lie outside.'),
      L('<b>Yarim perimetr</b> — perimetrning yarmi: p = (a + b + c)/2. U Geron formulasining asosiy qismi. Masalan, 13, 14, 15 uchburchakda p = 42/2 = 21.', '<b>Полупериметр</b> — половина периметра: p = (a + b + c)/2. Это основная часть формулы Герона. Например, у треугольника 13, 14, 15 p = 42/2 = 21.', 'The <b>semi-perimeter</b> is half the perimeter: p = (a + b + c)/2. It is the heart of Heron’s formula. For the 13, 14, 15 triangle, p = 42/2 = 21.'),
      L('Yuz va balandlik bog‘lanishi: S = a · h<sub>a</sub>/2, shuning uchun h<sub>a</sub> = 2S/a. Demak, yuzni bilsak, istalgan balandlikni bir zumda topamiz.', 'Связь площади и высоты: S = a · h<sub>a</sub>/2, поэтому h<sub>a</sub> = 2S/a. Зная площадь, мгновенно находим любую высоту.', 'Area and height are linked by S = a · h<sub>a</sub>/2, so h<sub>a</sub> = 2S/a. Once you know the area, every height follows at once.')
    ] },
    { kind: 'history', h: L('Iskandariyalik Geron', 'Герон Александрийский', 'Heron of Alexandria'), p: [
      L('<b>Geron</b> milodiy I asrda Misrning Iskandariya shahrida yashagan yunon muhandisi va matematigi. U o‘z davrining eng mohir ixtirochilaridan edi: bug‘ bilan aylanuvchi shar (eolipil), ibodatxona eshiklarini avtomatik ochuvchi mexanizm, tanga tashlansa suv beradigan avtomat va hatto oddiy «qo‘g‘irchoq teatri» robotini yaratgan.', '<b>Герон</b> — греческий инженер и математик, живший в I веке н. э. в египетском городе Александрия. Он был одним из самых искусных изобретателей своего времени: создал вращающийся паром шар (эолипил), механизм автоматического открывания дверей храма, автомат, выдающий воду за монету, и даже простой «кукольный театр»-робот.', '<b>Heron</b> was a Greek engineer and mathematician who lived in Alexandria, Egypt, in the 1st century AD. He was one of the most inventive minds of his age: he built a steam-spun sphere (the aeolipile), a mechanism that opened temple doors automatically, a coin-operated water dispenser and even a simple robot “puppet theatre”.'),
      L('Formulani Geron «Metrika» (O‘lchashlar) kitobida isboti bilan keltirgan. Bu kitob uzoq vaqt yo‘qolgan deb hisoblangan va faqat 1896-yilda Istanbulda topilgan qo‘lyozmadan to‘liq ma’lum bo‘ldi. Arab olimlari, jumladan Beruniy, formulani Arximedga ham nisbat berishgan — ehtimol u Gerondan oldin ham ma’lum bo‘lgan. Geron misollarida yuz ildizini taqribiy hisoblash usulini ham ko‘rsatgan, bu usul hozir ham kompyuterlarda ishlatiladi.', 'Формулу с доказательством Герон привёл в книге «Метрика» («Измерения»). Эта книга долго считалась утерянной и стала известна полностью лишь по рукописи, найденной в Стамбуле в 1896 году. Арабские учёные, в том числе Беруни, приписывали формулу Архимеду — возможно, она была известна и раньше Герона. В примерах Герон показал и способ приближённого извлечения корня, который используют компьютеры до сих пор.', 'Heron gave the formula with a proof in his book “Metrica” (Measurements). The book was long thought lost and became fully known only from a manuscript found in Istanbul in 1896. Arabic scholars, including Biruni, credited the formula to Archimedes — it may have been known before Heron. In his examples Heron also showed a method for approximating square roots that computers still use today.')
    ] },
    { kind: 'rule', h: L('Geron formulasi', 'Формула Герона', 'Heron’s formula'), p: [
      L('<b>Teorema.</b> Tomonlari a, b, c bo‘lgan uchburchakning yuzi', '<b>Теорема.</b> Площадь треугольника со сторонами a, b, c равна', '<b>Theorem.</b> The area of a triangle with sides a, b, c is'),
      L('<b>S = √(p(p − a)(p − b)(p − c))</b>, bunda p = (a + b + c)/2.', '<b>S = √(p(p − a)(p − b)(p − c))</b>, где p = (a + b + c)/2.', '<b>S = √(p(p − a)(p − b)(p − c))</b>, where p = (a + b + c)/2.'),
      L('<b>Isbot g‘oyasi.</b> c tomonga balandlik h tushiramiz; u c ni x va c − x bo‘laklarga bo‘ladi. Ikki to‘g‘ri burchakli uchburchakda Pifagor teoremasi: h<sup>2</sup> = a<sup>2</sup> − x<sup>2</sup> = b<sup>2</sup> − (c − x)<sup>2</sup>. Bundan x = (a<sup>2</sup> + c<sup>2</sup> − b<sup>2</sup>)/(2c) topiladi. So‘ng h<sup>2</sup> ni kvadratlar ayirmasi formulasi bilan ko‘paytuvchilarga ajratsak, h<sup>2</sup> = 4p(p − a)(p − b)(p − c)/c<sup>2</sup> chiqadi. S = c · h/2 ga qo‘ysak — Geron formulasi hosil bo‘ladi.', '<b>Идея доказательства.</b> Проведём высоту h к стороне c; она делит c на части x и c − x. В двух прямоугольных треугольниках по теореме Пифагора: h<sup>2</sup> = a<sup>2</sup> − x<sup>2</sup> = b<sup>2</sup> − (c − x)<sup>2</sup>. Отсюда x = (a<sup>2</sup> + c<sup>2</sup> − b<sup>2</sup>)/(2c). Разложив h<sup>2</sup> на множители по формуле разности квадратов, получим h<sup>2</sup> = 4p(p − a)(p − b)(p − c)/c<sup>2</sup>. Подставив в S = c · h/2, получаем формулу Герона.', '<b>Proof idea.</b> Drop the height h to side c; it splits c into parts x and c − x. Pythagoras in the two right triangles gives h<sup>2</sup> = a<sup>2</sup> − x<sup>2</sup> = b<sup>2</sup> − (c − x)<sup>2</sup>, so x = (a<sup>2</sup> + c<sup>2</sup> − b<sup>2</sup>)/(2c). Factorising h<sup>2</sup> with the difference of squares gives h<sup>2</sup> = 4p(p − a)(p − b)(p − c)/c<sup>2</sup>. Substituting into S = c · h/2 yields Heron’s formula.')
    ], after: [
      L('E’tibor bering: p − a, p − b, p − c ayirmalar doimo musbat, chunki har bir tomon qolgan ikkisining yig‘indisidan kichik. Agar ulardan biri 0 yoki manfiy chiqsa, bunday uchburchak mavjud emas.', 'Заметьте: разности p − a, p − b, p − c всегда положительны, ведь каждая сторона меньше суммы двух других. Если одна из них равна 0 или отрицательна — такого треугольника нет.', 'Note that p − a, p − b and p − c are always positive, because each side is less than the sum of the other two. If one of them is zero or negative, no such triangle exists.')
    ] },
    { kind: 'steps', h: L('Geron formulasi bo‘yicha hisoblash', 'Вычисление по формуле Герона', 'Computing with Heron’s formula'), list: [
      L('1-qadam. Tomonlarni qo‘shib, yarim perimetr p ni toping.', 'Шаг 1. Сложите стороны и найдите полупериметр p.', 'Step 1. Add the sides and find the semi-perimeter p.'),
      L('2-qadam. Uchta ayirmani hisoblang: p − a, p − b, p − c. Ularning yig‘indisi p ga teng bo‘lishi kerak — bu yaxshi tekshiruv.', 'Шаг 2. Вычислите три разности: p − a, p − b, p − c. Их сумма должна равняться p — хорошая проверка.', 'Step 2. Compute p − a, p − b, p − c. They must add up to p — a handy check.'),
      L('3-qadam. To‘rtta sonni ko‘paytiring. Ko‘paytmani tub ko‘paytuvchilarga ajratsangiz, ildiz chiqarish osonlashadi.', 'Шаг 3. Перемножьте четыре числа. Разложение произведения на простые множители упрощает извлечение корня.', 'Step 3. Multiply the four numbers. Splitting the product into prime factors makes the root easier.'),
      L('4-qadam. Kvadrat ildiz chiqaring — bu yuz S.', 'Шаг 4. Извлеките квадратный корень — это площадь S.', 'Step 4. Take the square root — that is the area S.'),
      L('5-qadam. Kerak bo‘lsa, balandlikni h = 2S/a formulasi bilan toping.', 'Шаг 5. При необходимости найдите высоту по формуле h = 2S/a.', 'Step 5. If needed, find a height with h = 2S/a.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Tomonlari 13, 14, 15 bo‘lgan uchburchak yuzini va 14 ga tushirilgan balandligini toping.', 'Найдите площадь треугольника со сторонами 13, 14, 15 и высоту к стороне 14.', 'Find the area of the 13, 14, 15 triangle and the height to side 14.'), s: L('p = 21; ayirmalar 8, 7, 6. S = √(21 · 8 · 7 · 6) = √7056 = <b>84</b>. h = 2 · 84/14 = <b>12</b>. Dehqonning uchastkasi 84 m<sup>2</sup> ekan!', 'p = 21; разности 8, 7, 6. S = √(21 · 8 · 7 · 6) = √7056 = <b>84</b>. h = 2 · 84/14 = <b>12</b>. Участок фермера — 84 м<sup>2</sup>!', 'p = 21; differences 8, 7, 6. S = √(21 · 8 · 7 · 6) = √7056 = <b>84</b>. h = 2 · 84/14 = <b>12</b>. The farmer’s plot is 84 m<sup>2</sup>!') },
      { q: L('Tomonlari 5, 5, 6 bo‘lgan teng yonli uchburchak yuzini ikki usulda toping.', 'Найдите площадь равнобедренного треугольника 5, 5, 6 двумя способами.', 'Find the area of the isosceles triangle 5, 5, 6 in two ways.'), s: L('Geron: p = 8, S = √(8 · 3 · 3 · 2) = √144 = 12. Balandlik orqali: asosga tushirilgan balandlik uni 3 va 3 ga bo‘ladi, h = √(25 − 9) = 4, S = 6 · 4/2 = 12. Ikkala usulda <b>12</b>.', 'Герон: p = 8, S = √(8 · 3 · 3 · 2) = √144 = 12. Через высоту: высота к основанию делит его на 3 и 3, h = √(25 − 9) = 4, S = 6 · 4/2 = 12. Оба способа дают <b>12</b>.', 'Heron: p = 8, S = √(8 · 3 · 3 · 2) = √144 = 12. Via the height: the height to the base splits it into 3 and 3, h = √(25 − 9) = 4, S = 6 · 4/2 = 12. Both give <b>12</b>.') },
      { q: L('Tomoni 4 bo‘lgan teng tomonli uchburchak yuzini toping.', 'Найдите площадь равностороннего треугольника со стороной 4.', 'Find the area of an equilateral triangle with side 4.'), s: L('p = 6, S = √(6 · 2 · 2 · 2) = √48 = <b>4√3 ≈ 6,93</b>. Umumiy formula: S = a<sup>2</sup>√3/4.', 'p = 6, S = √(6 · 2 · 2 · 2) = √48 = <b>4√3 ≈ 6,93</b>. Общая формула: S = a<sup>2</sup>√3/4.', 'p = 6, S = √(6 · 2 · 2 · 2) = √48 = <b>4√3 ≈ 6.93</b>. In general S = a<sup>2</sup>√3/4.') },
      { q: L('Tomonlari 10, 17, 21 bo‘lgan uchburchakning eng kichik balandligini toping.', 'Найдите наименьшую высоту треугольника 10, 17, 21.', 'Find the shortest height of the 10, 17, 21 triangle.'), s: L('p = 24; S = √(24 · 14 · 7 · 3) = √7056 = 84. Eng kichik balandlik eng uzun tomonga tushadi: h = 2 · 84/21 = <b>8</b>.', 'p = 24; S = √(24 · 14 · 7 · 3) = √7056 = 84. Наименьшая высота проведена к наибольшей стороне: h = 2 · 84/21 = <b>8</b>.', 'p = 24; S = √(24 · 14 · 7 · 3) = √7056 = 84. The shortest height goes to the longest side: h = 2 · 84/21 = <b>8</b>.') }
    ] },
    { kind: 'table', h: L('«Geron uchburchaklari»', '«Героновы треугольники»', '“Heronian triangles”'), p: [
      L('Tomonlari va yuzi butun son bo‘lgan uchburchaklar <b>Geron uchburchaklari</b> deyiladi. Ular masala tuzish uchun juda qulay.', 'Треугольники с целыми сторонами и целой площадью называются <b>героновыми</b>. Они очень удобны для задач.', 'Triangles with whole-number sides and whole-number area are called <b>Heronian triangles</b>. They are handy for problems.')
    ], table: { head: [L('Tomonlar', 'Стороны', 'Sides'), L('p', 'p', 'p'), L('S', 'S', 'S'), L('Izoh', 'Комментарий', 'Note')], rows: [
      [L('3, 4, 5', '3, 4, 5', '3, 4, 5'), '6', '6', L('to‘g‘ri burchakli', 'прямоугольный', 'right')],
      [L('5, 5, 6', '5, 5, 6', '5, 5, 6'), '8', '12', L('teng yonli', 'равнобедренный', 'isosceles')],
      [L('13, 14, 15', '13, 14, 15', '13, 14, 15'), '21', '84', L('ketma-ket sonlar', 'подряд идущие числа', 'consecutive numbers')],
      [L('9, 10, 17', '9, 10, 17', '9, 10, 17'), '18', '36', L('o‘tmas burchakli', 'тупоугольный', 'obtuse')],
      [L('10, 13, 13', '10, 13, 13', '10, 13, 13'), '18', '60', L('teng yonli', 'равнобедренный', 'isosceles')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>p o‘rniga perimetrni olish.</b> Formuladagi p — <i>yarim</i> perimetr. 13, 14, 15 uchun p = 21, 42 emas.', '<b>Берут периметр вместо p.</b> В формуле p — <i>полу</i>периметр. Для 13, 14, 15 p = 21, а не 42.', '<b>Using the perimeter instead of p.</b> p is the <i>semi</i>-perimeter. For 13, 14, 15, p = 21, not 42.'),
      L('<b>Ildizni unutish.</b> Ko‘paytma 7056 — bu S<sup>2</sup>, yuz esa 84.', '<b>Забывают корень.</b> Произведение 7056 — это S<sup>2</sup>, а площадь 84.', '<b>Forgetting the root.</b> 7056 is S<sup>2</sup>; the area is 84.'),
      L('<b>h = S/a deb yozish.</b> Yuz formulasida 1/2 bor, shuning uchun h = 2S/a.', '<b>Пишут h = S/a.</b> В формуле площади есть 1/2, поэтому h = 2S/a.', '<b>Writing h = S/a.</b> The area formula contains 1/2, so h = 2S/a.'),
      L('<b>Katta sonlarni oldindan ko‘paytirib yuborish.</b> 21 · 8 · 7 · 6 ni ko‘paytirmasdan, ko‘paytuvchilarga ajrating: 3 · 7 · 2<sup>3</sup> · 7 · 2 · 3 = 2<sup>4</sup> · 3<sup>2</sup> · 7<sup>2</sup>, ildiz 4 · 3 · 7 = 84.', '<b>Сразу перемножают большие числа.</b> Лучше разложить 21 · 8 · 7 · 6 на множители: 2<sup>4</sup> · 3<sup>2</sup> · 7<sup>2</sup>, корень 4 · 3 · 7 = 84.', '<b>Multiplying big numbers too early.</b> Factor 21 · 8 · 7 · 6 instead: 2<sup>4</sup> · 3<sup>2</sup> · 7<sup>2</sup>, root 4 · 3 · 7 = 84.'),
      L('<b>O‘tmas burchakli uchburchakda balandlik asosini tomon ichida izlash.</b> O‘tmas burchak qo‘shnisidagi tomonga tushirilgan balandlik tomonning davomiga tushadi.', '<b>Ищут основание высоты внутри стороны в тупоугольном треугольнике.</b> Высота к стороне, прилежащей к тупому углу, падает на продолжение стороны.', '<b>Looking for the foot of the height inside the side of an obtuse triangle.</b> The height to a side next to the obtuse angle lands on the extension of that side.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Yer o‘lchash.</b> Geodezistlar katta maydonni uchburchaklarga bo‘lib, har birining tomonlarini o‘lchaydi va yuzlarni Geron formulasi bilan qo‘shib chiqadi. Ko‘pburchak shaklidagi bog‘, ko‘l yoki o‘rmon yuzini shunday hisoblash mumkin — burchak o‘lchash shart emas.', '<b>Межевание.</b> Геодезисты делят большой участок на треугольники, измеряют стороны каждого и складывают площади по формуле Герона. Так находят площадь сада, озера или леса многоугольной формы — без измерения углов.', '<b>Land surveying.</b> Surveyors split a large area into triangles, measure the sides of each and add the areas with Heron’s formula. That is how the area of an irregular garden, lake or forest is found — no angles needed.'),
      L('<b>Kompyuter grafikasi.</b> O‘yin va multfilmlardagi 3D modellar millionlab uchburchaklardan iborat. Dastur yorug‘lik va soyani hisoblashda uchburchak yuzlaridan foydalanadi; tomonlar ma’lum bo‘lganda Geron formulasi qo‘l keladi.', '<b>Компьютерная графика.</b> 3D-модели в играх и мультфильмах состоят из миллионов треугольников. Для расчёта света и тени программа использует их площади; если известны стороны, помогает формула Герона.', '<b>Computer graphics.</b> 3D models in games and cartoons are made of millions of triangles. Programs use their areas to compute light and shade; when the sides are known, Heron’s formula helps.'),
      L('<b>Ta’mirlash.</b> Uchburchak shaklidagi frontonni bo‘yash uchun qancha bo‘yoq kerakligini bilish uchun uchta tomonni o‘lchash kifoya.', '<b>Ремонт.</b> Чтобы узнать, сколько краски нужно для треугольного фронтона, достаточно измерить три стороны.', '<b>Home repairs.</b> To know how much paint a triangular gable needs, measuring its three sides is enough.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('13, 14, 15 — tomonlari ketma-ket butun son va yuzi butun son bo‘lgan eng kichik o‘tkir burchakli uchburchak; uning balandligi ham butun (12).', '13, 14, 15 — наименьший остроугольный треугольник с последовательными целыми сторонами и целой площадью; его высота тоже целая (12).', '13, 14, 15 is the smallest acute triangle with consecutive whole sides and whole area; its height is a whole number too (12).'),
      L('Hind matematigi Braxmagupta VII asrda Geron formulasini aylanaga ichki chizilgan to‘rtburchak uchun umumlashtirgan: S = √((p − a)(p − b)(p − c)(p − d)).', 'Индийский математик Брахмагупта в VII веке обобщил формулу Герона на вписанный четырёхугольник: S = √((p − a)(p − b)(p − c)(p − d)).', 'In the 7th century the Indian mathematician Brahmagupta extended Heron’s formula to cyclic quadrilaterals: S = √((p − a)(p − b)(p − c)(p − d)).'),
      L('Uchburchakning eng katta balandligi doimo eng qisqa tomonga tushiriladi, chunki h = 2S/a da a qancha kichik bo‘lsa, h shuncha katta.', 'Наибольшая высота треугольника всегда проведена к наименьшей стороне: в h = 2S/a чем меньше a, тем больше h.', 'A triangle’s longest height always goes to its shortest side: in h = 2S/a, the smaller a is, the larger h becomes.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('6, 8, 10 uchburchak yuzi Geron formulasi bilan?', 'Площадь треугольника 6, 8, 10 по формуле Герона?', 'Area of 6, 8, 10 by Heron’s formula?'), s: L('p = 12, S = √(12 · 6 · 4 · 2) = √576 = <b>24</b> (tekshiruv: 6 · 8/2 = 24).', 'p = 12, S = √(12 · 6 · 4 · 2) = √576 = <b>24</b> (проверка: 6 · 8/2 = 24).', 'p = 12, S = √(12 · 6 · 4 · 2) = √576 = <b>24</b> (check: 6 · 8/2 = 24).') },
      { q: L('S = 60, a = 10. h<sub>a</sub> = ?', 'S = 60, a = 10. h<sub>a</sub> = ?', 'S = 60, a = 10. h<sub>a</sub> = ?'), s: L('h = 2 · 60/10 = <b>12</b>.', 'h = 2 · 60/10 = <b>12</b>.', 'h = 2 · 60/10 = <b>12</b>.') },
      { q: L('Tomonlari 2, 3, 5 bo‘lgan uchburchak yuzi?', 'Площадь треугольника со сторонами 2, 3, 5?', 'Area of a triangle with sides 2, 3, 5?'), s: L('p = 5, p − c = 0, S = 0. Bunday uchburchak <b>mavjud emas</b>: nuqtalar bir to‘g‘ri chiziqda yotadi.', 'p = 5, p − c = 0, S = 0. Такого треугольника <b>нет</b>: точки лежат на одной прямой.', 'p = 5, p − c = 0, so S = 0. Such a triangle <b>does not exist</b>: the points are on one line.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Balandlik — uchidan qarshi tomonga tushirilgan perpendikulyar; uchburchakda uchta balandlik bor.', 'Высота — перпендикуляр из вершины к противоположной стороне; у треугольника три высоты.', 'A height is the perpendicular from a vertex to the opposite side; a triangle has three.'),
      L('S = a · h/2, shuning uchun h = 2S/a.', 'S = a · h/2, поэтому h = 2S/a.', 'S = a · h/2, so h = 2S/a.'),
      L('Geron formulasi: S = √(p(p − a)(p − b)(p − c)), p — yarim perimetr.', 'Формула Герона: S = √(p(p − a)(p − b)(p − c)), p — полупериметр.', 'Heron’s formula: S = √(p(p − a)(p − b)(p − c)), p is the semi-perimeter.'),
      L('Formula Pifagor teoremasi va kvadratlar ayirmasidan kelib chiqadi.', 'Формула выводится из теоремы Пифагора и разности квадратов.', 'The formula comes from Pythagoras’ theorem and the difference of squares.'),
      L('Geron I asrda Iskandariyada yashagan muhandis-ixtirochi; formula uning «Metrika» kitobida.', 'Герон — инженер-изобретатель из Александрии I века; формула — в его «Метрике».', 'Heron was a 1st-century inventor-engineer in Alexandria; the formula is in his “Metrica”.')
    ] }
  ] });

  // ---------- t14. Aylana. Markaziy burchak. Vatar va diametr ----------
  T.add(P, 't14', { sections: [
    { kind: 'intro', h: L('Eng mukammal shakl', 'Самая совершенная фигура', 'The most perfect shape'), p: [
      L('Velosiped g‘ildiragi, soat siferblati, quduq og‘zi, tarelka, Quyosh va Oyning ko‘rinishi — atrofimizda aylana juda ko‘p. Qadimgi yunonlar aylanani «eng mukammal shakl» deb atashgan, chunki uning har bir nuqtasi markazdan bir xil uzoqlikda turadi. Aynan shu xossa tufayli g‘ildirak tekis yumalaydi va silkinmaydi.', 'Колесо велосипеда, циферблат часов, край колодца, тарелка, видимые диски Солнца и Луны — вокруг нас много окружностей. Древние греки называли окружность «самой совершенной фигурой», ведь каждая её точка находится на одинаковом расстоянии от центра. Именно поэтому колесо катится ровно и не трясётся.', 'A bicycle wheel, a clock face, the rim of a well, a plate, the discs of the Sun and Moon — circles are everywhere. The ancient Greeks called the circle the “most perfect shape”, because every point on it is the same distance from the centre. That is exactly why a wheel rolls smoothly without bumping.'),
      L('Bu mavzuda aylananing asosiy elementlarini — radius, diametr, vatar va yoyni — eslaymiz, <b>markaziy burchak</b> tushunchasini kiritamiz va vatar bilan diametr orasidagi muhim bog‘lanishlarni isbotlaymiz. Bu bilimlar keyingi mavzular — urinma va ichki chizilgan burchak uchun poydevor bo‘ladi.', 'В этой теме вспомним основные элементы окружности — радиус, диаметр, хорду и дугу, — введём понятие <b>центрального угла</b> и докажем важные связи между хордой и диаметром. Это фундамент для следующих тем — касательной и вписанного угла.', 'In this topic we recall the main parts of a circle — radius, diameter, chord and arc — introduce the <b>central angle</b>, and prove key facts linking chords and diameters. This is the foundation for the next topics: tangents and inscribed angles.')
    ] },
    { kind: 'def', h: L('Aylana elementlari', 'Элементы окружности', 'Parts of a circle'), list: [
      L('<b>Aylana</b> — tekislikdagi berilgan O nuqtadan (markazdan) bir xil r masofada yotgan barcha nuqtalar to‘plami. <b>Doira</b> esa aylana va uning ichidagi nuqtalar.', '<b>Окружность</b> — множество всех точек плоскости, удалённых от данной точки O (центра) на одно и то же расстояние r. <b>Круг</b> — окружность вместе с внутренними точками.', 'A <b>circle</b> is the set of all points in a plane at the same distance r from a given point O (the centre). A <b>disc</b> is the circle together with the points inside it.'),
      L('<b>Radius</b> — markazni aylana nuqtasi bilan tutashtiruvchi kesma (uzunligi r).', '<b>Радиус</b> — отрезок, соединяющий центр с точкой окружности (длина r).', 'A <b>radius</b> joins the centre to a point of the circle (length r).'),
      L('<b>Vatar</b> — aylananing ikki nuqtasini tutashtiruvchi kesma.', '<b>Хорда</b> — отрезок, соединяющий две точки окружности.', 'A <b>chord</b> joins two points of the circle.'),
      L('<b>Diametr</b> — markazdan o‘tuvchi vatar; d = 2r. Bu eng uzun vatar.', '<b>Диаметр</b> — хорда, проходящая через центр; d = 2r. Это самая длинная хорда.', 'A <b>diameter</b> is a chord through the centre; d = 2r. It is the longest chord.'),
      L('<b>Yoy</b> — aylananing ikki nuqtasi orasidagi qismi. Har qanday ikki nuqta aylanani ikkita yoyga ajratadi.', '<b>Дуга</b> — часть окружности между двумя её точками. Любые две точки делят окружность на две дуги.', 'An <b>arc</b> is the part of the circle between two of its points. Any two points split the circle into two arcs.'),
      L('<b>Markaziy burchak</b> — uchi aylana markazida bo‘lgan burchak. AOB markaziy burchak AB yoyga <i>tiraladi</i>.', '<b>Центральный угол</b> — угол с вершиной в центре окружности. Центральный угол AOB <i>опирается</i> на дугу AB.', 'A <b>central angle</b> has its vertex at the centre. The central angle AOB <i>stands on</i> the arc AB.')
    ], after: [
      L('Yoyning gradus o‘lchovi unga tiralgan markaziy burchakka teng deb qabul qilinadi. Butun aylana 360°, yarim aylana 180°.', 'Градусная мера дуги принимается равной центральному углу, который на неё опирается. Вся окружность — 360°, полуокружность — 180°.', 'The degree measure of an arc is defined as the central angle standing on it. The whole circle is 360°, a semicircle 180°.')
    ] },
    { kind: 'history', h: L('Aylana tarixi', 'История окружности', 'A short history of the circle'), p: [
      L('Bobilliklar aylanani 360 qismga bo‘lishgan. Sababi aniq ma’lum emas, lekin ular oltmishlik sanoq tizimidan foydalanishgan va yil taxminan 360 kundan iborat deb hisoblashgan. Gradus shu tariqa paydo bo‘lgan va 4000 yildan beri ishlatilmoqda.', 'Вавилоняне делили окружность на 360 частей. Причина точно неизвестна, но они пользовались шестидесятеричной системой счисления и считали, что в году около 360 дней. Так появился градус, и он используется уже 4000 лет.', 'The Babylonians divided the circle into 360 parts. The exact reason is unknown, but they counted in base sixty and reckoned the year at about 360 days. That is how the degree was born, and it has been in use for 4000 years.'),
      L('<b>Yevklid</b> «Negizlar»ning uchinchi kitobini to‘liq aylanaga bag‘ishlagan: vatarlar, urinmalar va burchaklar haqidagi teoremalar aynan u yerda tartibli isbotlangan. Masalan, «diametrga perpendikulyar vatar teng ikkiga bo‘linadi» degan fakt shu kitobda bor. Samarqanddagi <b>Ulug‘bek rasadxonasi</b>da (XV asr) radiusi 40 metrdan ortiq bo‘lgan ulkan marmar sekstant aylana yoyi shaklida qurilgan; uning yordamida yulduzlar balandligi juda aniq o‘lchangan.', '<b>Евклид</b> целиком посвятил окружности третью книгу «Начал»: там последовательно доказаны теоремы о хордах, касательных и углах. Например, факт «диаметр, перпендикулярный хорде, делит её пополам» есть именно там. В <b>обсерватории Улугбека</b> в Самарканде (XV век) огромный мраморный секстант радиусом более 40 метров был построен в форме дуги окружности; с его помощью очень точно измеряли высоты звёзд.', '<b>Euclid</b> devoted the whole third book of his “Elements” to the circle: theorems on chords, tangents and angles are proved there in order. The fact that “a diameter perpendicular to a chord bisects it” is found there. At <b>Ulugh Beg’s observatory</b> in Samarkand (15th century) a huge marble sextant with a radius of over 40 metres was built as an arc of a circle; it measured the altitudes of stars with great precision.')
    ] },
    { kind: 'rule', h: L('Vatar va diametr haqidagi teoremalar', 'Теоремы о хорде и диаметре', 'Theorems on chords and diameters'), list: [
      L('<b>1-teorema.</b> Vatarga perpendikulyar diametr vatarni va u tortib turgan ikkala yoyni teng ikkiga bo‘ladi.', '<b>Теорема 1.</b> Диаметр, перпендикулярный хорде, делит её и обе стягиваемые ею дуги пополам.', '<b>Theorem 1.</b> A diameter perpendicular to a chord bisects the chord and both arcs it cuts off.'),
      L('<b>2-teorema (teskari).</b> Vatar o‘rtasidan o‘tuvchi diametr (vatar diametr bo‘lmasa) unga perpendikulyar.', '<b>Теорема 2 (обратная).</b> Диаметр, проходящий через середину хорды (не диаметра), перпендикулярен ей.', '<b>Theorem 2 (converse).</b> A diameter through the midpoint of a chord (that is not itself a diameter) is perpendicular to it.'),
      L('<b>3-teorema.</b> Teng vatarlar markazdan teng uzoqlikda yotadi va teng markaziy burchaklarga tiraladi; teskarisi ham to‘g‘ri.', '<b>Теорема 3.</b> Равные хорды равноудалены от центра и стягивают равные центральные углы; верно и обратное.', '<b>Theorem 3.</b> Equal chords are equally far from the centre and subtend equal central angles; the converse also holds.'),
      L('<b>4-teorema.</b> Markazga yaqinroq vatar uzunroq. Shu sababli markazdan o‘tuvchi diametr eng uzun vatar.', '<b>Теорема 4.</b> Хорда, расположенная ближе к центру, длиннее. Поэтому диаметр — самая длинная хорда.', '<b>Theorem 4.</b> A chord closer to the centre is longer. That is why the diameter is the longest chord.')
    ], after: [
      L('<b>1-teorema isboti.</b> AB vatar, O markaz. OA = OB (radiuslar), shuning uchun OAB uchburchak teng yonli. Teng yonli uchburchakda asosga tushirilgan balandlik ayni paytda mediana bo‘ladi, demak diametr AB ni teng ikkiga bo‘ladi. Shu balandlik bissektrisa ham bo‘lgani uchun markaziy burchak ham, yoy ham teng ikkiga bo‘linadi.', '<b>Доказательство теоремы 1.</b> AB — хорда, O — центр. OA = OB (радиусы), поэтому треугольник OAB равнобедренный. В нём высота к основанию является и медианой, значит диаметр делит AB пополам. Так как она и биссектриса, пополам делятся и центральный угол, и дуга.', '<b>Proof of Theorem 1.</b> Let AB be a chord and O the centre. OA = OB (radii), so triangle OAB is isosceles. In it the height to the base is also the median, so the diameter bisects AB. It is also the angle bisector, so the central angle and the arc are halved too.'),
      L('Bundan muhim formula kelib chiqadi: markazdan vatargacha masofa d bo‘lsa, vatar uzunligi <b>AB = 2√(r<sup>2</sup> − d<sup>2</sup>)</b>.', 'Отсюда важная формула: если d — расстояние от центра до хорды, то <b>AB = 2√(r<sup>2</sup> − d<sup>2</sup>)</b>.', 'This gives an important formula: if d is the distance from the centre to the chord, then <b>AB = 2√(r<sup>2</sup> − d<sup>2</sup>)</b>.')
    ] },
    { kind: 'steps', h: L('Vatar masalalarini yechish', 'Как решать задачи о хордах', 'Solving chord problems'), list: [
      L('1-qadam. Markazdan vatarga perpendikulyar tushiring — u vatarni teng ikkiga bo‘ladi.', 'Шаг 1. Опустите перпендикуляр из центра на хорду — он делит её пополам.', 'Step 1. Drop a perpendicular from the centre to the chord — it bisects the chord.'),
      L('2-qadam. Markazni vatar uchi bilan tutashtiring — bu radius.', 'Шаг 2. Соедините центр с концом хорды — это радиус.', 'Step 2. Join the centre to an end of the chord — that is a radius.'),
      L('3-qadam. Hosil bo‘lgan to‘g‘ri burchakli uchburchakda: gipotenuza r, katetlar d va vatar yarmi.', 'Шаг 3. В получившемся прямоугольном треугольнике гипотенуза r, катеты — d и половина хорды.', 'Step 3. In the resulting right triangle the hypotenuse is r and the legs are d and half the chord.'),
      L('4-qadam. Pifagor teoremasini qo‘llang va noma’lumni toping. Vatar yarmini topgan bo‘lsangiz, uni 2 ga ko‘paytirishni unutmang.', 'Шаг 4. Примените теорему Пифагора. Найдя половину хорды, не забудьте умножить на 2.', 'Step 4. Apply Pythagoras’ theorem. If you found half the chord, remember to double it.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Radiusi 13 sm bo‘lgan aylanada markazdan 5 sm uzoqlikdagi vatar uzunligini toping.', 'В окружности радиуса 13 см найдите длину хорды, удалённой от центра на 5 см.', 'In a circle of radius 13 cm, find the length of a chord 5 cm from the centre.'), s: L('Vatar yarmi √(13<sup>2</sup> − 5<sup>2</sup>) = √144 = 12. Vatar = 2 · 12 = <b>24 sm</b>.', 'Половина хорды √(13<sup>2</sup> − 5<sup>2</sup>) = √144 = 12. Хорда = 2 · 12 = <b>24 см</b>.', 'Half the chord is √(13<sup>2</sup> − 5<sup>2</sup>) = √144 = 12. Chord = 2 · 12 = <b>24 cm</b>.') },
      { q: L('Radiusi 10 bo‘lgan aylanada uzunligi 16 bo‘lgan vatar markazdan qancha uzoqda?', 'В окружности радиуса 10 хорда длиной 16. На каком расстоянии от центра она находится?', 'In a circle of radius 10 a chord has length 16. How far is it from the centre?'), s: L('Vatar yarmi 8. d = √(100 − 64) = √36 = <b>6</b>.', 'Половина хорды 8. d = √(100 − 64) = √36 = <b>6</b>.', 'Half the chord is 8. d = √(100 − 64) = √36 = <b>6</b>.') },
      { q: L('AB yoy 110°. AOB markaziy burchak va qolgan yoyni toping.', 'Дуга AB равна 110°. Найдите центральный угол AOB и оставшуюся дугу.', 'Arc AB is 110°. Find the central angle AOB and the other arc.'), s: L('Markaziy burchak yoyga teng: ∠AOB = <b>110°</b>. Qolgan yoy 360° − 110° = <b>250°</b>.', 'Центральный угол равен дуге: ∠AOB = <b>110°</b>. Оставшаяся дуга 360° − 110° = <b>250°</b>.', 'The central angle equals its arc: ∠AOB = <b>110°</b>. The other arc is 360° − 110° = <b>250°</b>.') },
      { q: L('Radiusi 6 bo‘lgan aylanada markaziy burchagi 60° bo‘lgan vatar uzunligini toping.', 'В окружности радиуса 6 найдите хорду, стягивающую центральный угол 60°.', 'In a circle of radius 6, find the chord for a central angle of 60°.'), s: L('OAB uchburchakda OA = OB = 6 va ∠O = 60°, shuning uchun qolgan burchaklar ham 60° — uchburchak teng tomonli. AB = <b>6</b>.', 'В треугольнике OAB OA = OB = 6 и ∠O = 60°, значит остальные углы тоже 60° — треугольник равносторонний. AB = <b>6</b>.', 'In triangle OAB, OA = OB = 6 and ∠O = 60°, so the other angles are 60° too — it is equilateral. AB = <b>6</b>.') }
    ] },
    { kind: 'table', h: L('Markaziy burchak va vatar uzunligi', 'Центральный угол и длина хорды', 'Central angle and chord length'), p: [
      L('Radiusi r bo‘lgan aylanada markaziy burchak qancha katta bo‘lsa, unga mos vatar shuncha uzun bo‘ladi. Burchak 0° dan 180° gacha o‘sganda vatar 0 dan diametrgacha uzayadi. Quyidagi jadvalda eng ko‘p uchraydigan burchaklar uchun vatar uzunligi va markazdan vatargacha masofa keltirilgan. Har bir qatorni o‘zingiz tekshirib ko‘ring: d<sup>2</sup> + (AB/2)<sup>2</sup> = r<sup>2</sup> bo‘lishi kerak.', 'В окружности радиуса r чем больше центральный угол, тем длиннее соответствующая хорда. Когда угол растёт от 0° до 180°, хорда растёт от 0 до диаметра. В таблице — длины хорд и расстояния до центра для самых частых углов. Проверьте каждую строку сами: должно быть d<sup>2</sup> + (AB/2)<sup>2</sup> = r<sup>2</sup>.', 'In a circle of radius r, the larger the central angle, the longer its chord. As the angle grows from 0° to 180°, the chord grows from 0 to the diameter. The table lists chord lengths and distances to the centre for the most common angles. Check each row yourself: d<sup>2</sup> + (AB/2)<sup>2</sup> = r<sup>2</sup> must hold.')
    ], table: { head: [L('Markaziy burchak', 'Центральный угол', 'Central angle'), L('Vatar AB', 'Хорда AB', 'Chord AB'), L('Masofa d', 'Расстояние d', 'Distance d'), L('OAB uchburchak', 'Треугольник OAB', 'Triangle OAB')], rows: [
      ['60°', 'r', L('r√3/2', 'r√3/2', 'r√3/2'), L('teng tomonli', 'равносторонний', 'equilateral')],
      ['90°', L('r√2', 'r√2', 'r√2'), L('r√2/2', 'r√2/2', 'r√2/2'), L('teng yonli to‘g‘ri burchakli', 'равнобедренный прямоугольный', 'right isosceles')],
      ['120°', L('r√3', 'r√3', 'r√3'), L('r/2', 'r/2', 'r/2'), L('o‘tmas burchakli teng yonli', 'тупоугольный равнобедренный', 'obtuse isosceles')],
      ['180°', '2r', '0', L('uchburchak yo‘q — diametr', 'треугольника нет — диаметр', 'no triangle — a diameter')]
    ] }, after: [
      L('Jadvaldan ko‘rinadiki, 60° li markaziy burchakka tiralgan vatar radiusga teng. Shuning uchun aylanaga radiusni sirkul bilan ketma-ket olti marta qo‘yib chiqsak, aylana roppa-rosa olti teng yoyga bo‘linadi va muntazam oltiburchak hosil bo‘ladi — asalari kataklari shakli.', 'Из таблицы видно, что хорда при центральном угле 60° равна радиусу. Поэтому, откладывая радиус циркулем шесть раз подряд, мы делим окружность ровно на шесть равных дуг и получаем правильный шестиугольник — форму пчелиных сот.', 'The table shows that the chord for a 60° central angle equals the radius. So stepping the radius around the circle six times with a compass splits it into exactly six equal arcs and gives a regular hexagon — the shape of honeycomb cells.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Vatar yarmini javob deb yozish.</b> Pifagor teoremasi vatarning <i>yarmini</i> beradi, uni 2 ga ko‘paytirish kerak.', '<b>Записывают половину хорды как ответ.</b> Теорема Пифагора даёт <i>половину</i> хорды — её надо удвоить.', '<b>Giving half the chord as the answer.</b> Pythagoras gives <i>half</i> the chord — double it.'),
      L('<b>Radius va diametrni chalkashtirish.</b> d = 2r. Masalada «diametr 20» deyilsa, r = 10.', '<b>Путают радиус и диаметр.</b> d = 2r. Если в задаче «диаметр 20», то r = 10.', '<b>Mixing up radius and diameter.</b> d = 2r. If the problem says “diameter 20”, then r = 10.'),
      L('<b>Masofani og‘ma bo‘yicha o‘lchash.</b> Markazdan vatargacha masofa — perpendikulyar uzunligi, markazdan vatar uchigacha emas.', '<b>Измеряют расстояние по наклонной.</b> Расстояние от центра до хорды — длина перпендикуляра, а не отрезка до конца хорды.', '<b>Measuring the distance along a slant.</b> The distance from the centre to a chord is the perpendicular, not the segment to an end of the chord.'),
      L('<b>Har qanday vatarni diametr deb hisoblash.</b> Faqat markazdan o‘tuvchi vatar diametr bo‘ladi.', '<b>Считают любую хорду диаметром.</b> Диаметр — только хорда через центр.', '<b>Calling any chord a diameter.</b> Only a chord through the centre is a diameter.')
    ] },
    { kind: 'life', h: L('Hayotda aylana', 'Окружность в жизни', 'Circles in real life'), p: [
      L('<b>Singan likopchani tiklash.</b> Arxeologlar topgan sopol idish bo‘lagidan butun idishning o‘lchamini aniqlashadi. Bo‘lak chetiga ikkita vatar chizib, ularning o‘rta perpendikulyarlarini o‘tkazishadi — kesishish nuqtasi markaz bo‘ladi (1–2-teoremalar). Shundan keyin radiusni o‘lchash mumkin.', '<b>Восстановление разбитой тарелки.</b> По найденному черепку археологи определяют размер всего сосуда. На краю черепка проводят две хорды и их серединные перпендикуляры — точка пересечения и есть центр (теоремы 1–2). Затем измеряют радиус.', '<b>Rebuilding a broken plate.</b> From a single shard archaeologists work out the size of the whole vessel. They draw two chords along the rim and their perpendicular bisectors — the crossing point is the centre (Theorems 1–2). Then they measure the radius.'),
      L('<b>Quvurdagi suv.</b> Diametri 1 m bo‘lgan quvurda suv sathi eni 80 sm bo‘lsa, suv chuqurligini vatar formulasi bilan hisoblash mumkin: r = 50, vatar yarmi 40, d = 30 sm, chuqurlik 50 − 30 = 20 sm.', '<b>Вода в трубе.</b> Если в трубе диаметром 1 м ширина поверхности воды 80 см, глубину можно найти по формуле хорды: r = 50, половина хорды 40, d = 30 см, глубина 50 − 30 = 20 см.', '<b>Water in a pipe.</b> If the water surface in a 1 m pipe is 80 cm wide, the chord formula gives the depth: r = 50, half-chord 40, d = 30 cm, depth 50 − 30 = 20 cm.'),
      L('<b>Soat va tortlar.</b> Soat millari markaziy burchak hosil qiladi: har bir soat 30°, har bir daqiqa 6°. Tortni 8 teng bo‘lakka bo‘lsak, har bir bo‘lak markaziy burchagi 45°.', '<b>Часы и торты.</b> Стрелки часов образуют центральный угол: каждый час — 30°, каждая минута — 6°. Торт на 8 равных кусков — по 45° каждый.', '<b>Clocks and cakes.</b> Clock hands form central angles: each hour is 30°, each minute 6°. A cake cut into 8 equal slices gives 45° per slice.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Aylana — berilgan perimetrda eng katta yuzni o‘rab oluvchi shakl. Shuning uchun ko‘plab qushlar uyasi va yog‘ tomchilari dumaloq.', 'Окружность ограничивает наибольшую площадь при данном периметре. Поэтому многие гнёзда и капли жира круглые.', 'Of all shapes with a given perimeter, the circle encloses the largest area. That is why many nests and drops of oil are round.'),
      L('Ulug‘bek rasadxonasining yer ostidagi sekstant yoyi hozir ham Samarqandda saqlanib qolgan; uning bo‘ylab har bir gradus taxminan 70 sm ga to‘g‘ri kelgan.', 'Подземная дуга секстанта обсерватории Улугбека сохранилась в Самарканде до сих пор; на ней один градус занимал около 70 см.', 'The underground arc of Ulugh Beg’s sextant still survives in Samarkand; one degree along it took up about 70 cm.'),
      L('Lyuk qopqoqlari dumaloq qilinadi, chunki dumaloq qopqoq qanday burilmasin, teshikka tushib ketmaydi — uning har qanday «eni» diametrga teng.', 'Крышки люков делают круглыми: как ни поверни круглую крышку, она не провалится в люк — её «ширина» всегда равна диаметру.', 'Manhole covers are round because a round cover cannot fall through its hole however you turn it — its “width” always equals the diameter.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('r = 5, markazdan vatargacha 4. Vatar?', 'r = 5, расстояние до хорды 4. Хорда?', 'r = 5, distance to the chord 4. Chord?'), s: L('2√(25 − 16) = 2 · 3 = <b>6</b>.', '2√(25 − 16) = 2 · 3 = <b>6</b>.', '2√(25 − 16) = 2 · 3 = <b>6</b>.') },
      { q: L('Markaziy burchak 90°, r = 4. Vatar?', 'Центральный угол 90°, r = 4. Хорда?', 'Central angle 90°, r = 4. Chord?'), s: L('Teng yonli to‘g‘ri burchakli uchburchak: 4√2 ≈ <b>5,66</b>.', 'Равнобедренный прямоугольный треугольник: 4√2 ≈ <b>5,66</b>.', 'An isosceles right triangle: 4√2 ≈ <b>5.66</b>.') },
      { q: L('Aylana 12 ta teng yoyga bo‘lingan. Har bir yoy necha gradus?', 'Окружность разделена на 12 равных дуг. Сколько градусов в каждой?', 'A circle is split into 12 equal arcs. How many degrees each?'), s: L('360° : 12 = <b>30°</b> — soat siferblatidagi kabi.', '360° : 12 = <b>30°</b> — как на циферблате.', '360° ÷ 12 = <b>30°</b> — just like a clock face.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Aylana — markazdan teng uzoqlikdagi nuqtalar; radius r, diametr 2r.', 'Окружность — точки, равноудалённые от центра; радиус r, диаметр 2r.', 'A circle is all points equally far from the centre; radius r, diameter 2r.'),
      L('Markaziy burchak uchi markazda; yoy gradus o‘lchovi unga teng.', 'Вершина центрального угла — в центре; градусная мера дуги равна ему.', 'A central angle has its vertex at the centre; its arc has the same degree measure.'),
      L('Vatarga perpendikulyar diametr vatar va yoylarni teng ikkiga bo‘ladi.', 'Диаметр, перпендикулярный хорде, делит хорду и дуги пополам.', 'A diameter perpendicular to a chord bisects the chord and its arcs.'),
      L('Vatar uzunligi: AB = 2√(r<sup>2</sup> − d<sup>2</sup>).', 'Длина хорды: AB = 2√(r<sup>2</sup> − d<sup>2</sup>).', 'Chord length: AB = 2√(r<sup>2</sup> − d<sup>2</sup>).'),
      L('Teng vatarlar markazdan teng uzoqlikda; diametr — eng uzun vatar.', 'Равные хорды равноудалены от центра; диаметр — самая длинная хорда.', 'Equal chords are equally far from the centre; the diameter is the longest chord.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-2';

  // ---------- t15. To‘g‘ri chiziq va aylana. Urinma ----------
  T.add(P, 't15', { sections: [
    { kind: 'intro', h: L('Aylanaga faqat bir nuqtada tegish', 'Коснуться окружности в одной точке', 'Touching a circle at one point'), p: [
      L('Velosiped g‘ildiragi asfalt ustida yumalayotganini kuzating. Har bir lahzada g‘ildirak yerga faqat bitta nuqtada tegib turadi. Yo‘l — to‘g‘ri chiziq, g‘ildirak — aylana, ular esa bir-biriga <b>urinadi</b>. Agar yo‘l biroz pastroq bo‘lsa, ular umuman tegmas edi; balandroq bo‘lsa — g‘ildirak yo‘lni «kesib o‘tardi», ya’ni ikki nuqtada uchrashardi.', 'Понаблюдайте, как колесо велосипеда катится по асфальту. В каждый момент оно касается земли ровно в одной точке. Дорога — прямая, колесо — окружность, и они <b>касаются</b> друг друга. Будь дорога чуть ниже, они бы не соприкасались; выше — колесо «пересекло» бы дорогу, т.е. встретилось бы с ней в двух точках.', 'Watch a bicycle wheel rolling on asphalt. At every moment the wheel touches the ground at exactly one point. The road is a line, the wheel is a circle, and they <b>touch</b>. If the road were a little lower they would not meet at all; if higher, the wheel would “cut” the road, meeting it at two points.'),
      L('Bu mavzuda to‘g‘ri chiziq va aylananing o‘zaro joylashuvining uchta holatini o‘rganamiz, <b>urinma</b> nima ekanini va uning asosiy xossalarini isbotlaymiz. Shuningdek, buyuk vatandoshimiz Abu Rayhon Beruniy urinma yordamida Yer radiusini qanday o‘lchaganini bilib olamiz. Bu — tarixdagi eng aqlli o‘lchovlardan biri.', 'В этой теме изучим три случая взаимного расположения прямой и окружности, узнаем, что такое <b>касательная</b>, и докажем её основные свойства. А ещё узнаем, как наш великий соотечественник Абу Райхан Беруни с помощью касательной измерил радиус Земли. Это одно из самых остроумных измерений в истории.', 'In this topic we study the three ways a line and a circle can be placed, learn what a <b>tangent</b> is and prove its main properties. We will also see how the great scholar Abu Rayhan Biruni used a tangent to measure the radius of the Earth — one of the cleverest measurements in history.')
    ] },
    { kind: 'def', h: L('Uchta holat', 'Три случая', 'Three cases'), p: [
      L('O markazli, r radiusli aylana va ℓ to‘g‘ri chiziq berilgan bo‘lsin. Markazdan to‘g‘ri chiziqqacha bo‘lgan masofani (ya’ni perpendikulyar uzunligini) d bilan belgilaymiz. d ni r bilan taqqoslab, umumiy nuqtalar sonini bilib olamiz:', 'Пусть даны окружность с центром O и радиусом r и прямая ℓ. Расстояние от центра до прямой (длину перпендикуляра) обозначим d. Сравнивая d и r, узнаём число общих точек:', 'Let a circle have centre O and radius r, and let ℓ be a line. Call the distance from the centre to the line (the length of the perpendicular) d. Comparing d with r tells us the number of common points:')
    ], list: [
      L('<b>d &gt; r</b> — to‘g‘ri chiziq aylanadan tashqarida o‘tadi, umumiy nuqta yo‘q.', '<b>d &gt; r</b> — прямая проходит вне окружности, общих точек нет.', '<b>d &gt; r</b> — the line passes outside the circle; no common points.'),
      L('<b>d = r</b> — bitta umumiy nuqta bor. Bunday to‘g‘ri chiziq <b>urinma</b>, umumiy nuqta esa <b>urinish nuqtasi</b> deyiladi.', '<b>d = r</b> — одна общая точка. Такая прямая называется <b>касательной</b>, а общая точка — <b>точкой касания</b>.', '<b>d = r</b> — exactly one common point. Such a line is a <b>tangent</b>, and the point is the <b>point of tangency</b>.'),
      L('<b>d &lt; r</b> — ikkita umumiy nuqta. Bunday to‘g‘ri chiziq <b>kesuvchi</b> deyiladi; ikki nuqta orasidagi kesma vatar bo‘ladi.', '<b>d &lt; r</b> — две общие точки. Такая прямая называется <b>секущей</b>; отрезок между точками — хорда.', '<b>d &lt; r</b> — two common points. Such a line is a <b>secant</b>; the segment between the points is a chord.')
    ], after: [
      L('Nega uchtadan ortiq holat yo‘q? Chunki to‘g‘ri chiziq aylanani ikkitadan ortiq nuqtada kesa olmaydi: agar uchta umumiy nuqta bo‘lsa, ular markazdan teng uzoqlikda yotgan bo‘lardi, bu esa bir to‘g‘ri chiziqda yotgan uch nuqta uchun mumkin emas.', 'Почему других случаев нет? Прямая не может пересечь окружность более чем в двух точках: три общие точки были бы равноудалены от центра, а для трёх точек одной прямой это невозможно.', 'Why are there no other cases? A line cannot meet a circle in more than two points: three common points would all be equally far from the centre, which is impossible for three points on one line.')
    ] },
    { kind: 'history', h: L('Beruniy Yer radiusini qanday o‘lchagan', 'Как Беруни измерил радиус Земли', 'How Biruni measured the Earth'), p: [
      L('XI asr boshida <b>Abu Rayhon Beruniy</b> (973–1048) hozirgi Pokiston hududidagi Nandana qal’asi yaqinidagi tog‘ga chiqqan. U tog‘ cho‘qqisidan tekislik ufqini kuzatgan. Ufq chizig‘iga qaragan nigoh Yer sirtiga <b>urinma</b> bo‘lib o‘tadi. Urinma esa urinish nuqtasiga o‘tkazilgan radiusga perpendikulyar. Natijada Yer markazi, urinish nuqtasi va kuzatuvchi to‘g‘ri burchakli uchburchak hosil qiladi.', 'В начале XI века <b>Абу Райхан Беруни</b> (973–1048) поднялся на гору возле крепости Нандана на территории нынешнего Пакистана. С вершины он наблюдал горизонт над равниной. Луч зрения, направленный на линию горизонта, — это <b>касательная</b> к поверхности Земли. А касательная перпендикулярна радиусу в точке касания. Поэтому центр Земли, точка касания и наблюдатель образуют прямоугольный треугольник.', 'Early in the 11th century <b>Abu Rayhan Biruni</b> (973–1048) climbed a mountain near the fort of Nandana, in today’s Pakistan. From the top he looked at the horizon over the plain. The line of sight to the horizon is a <b>tangent</b> to the Earth’s surface, and a tangent is perpendicular to the radius at the point of contact. So the Earth’s centre, the point of contact and the observer form a right triangle.'),
      L('Beruniy avval tog‘ balandligini o‘lchagan, so‘ng astrolyabiya yordamida ufq chizig‘ining gorizontaldan qancha pastga «cho‘kishini», ya’ni kichik burchakni o‘lchagan. Shu ikki son va to‘g‘ri burchakli uchburchak xossalaridan u Yer radiusini hisoblab chiqqan — taxminan 6340 km. Hozirgi qiymat taxminan 6371 km! Bunday aniqlik o‘sha davrda ajoyib natija edi. Usulning afzalligi shundaki, cho‘l bo‘ylab yuzlab chaqirim yurish shart emas edi — bitta tog‘ va aniq o‘lchov yetarli bo‘lgan.', 'Беруни сначала измерил высоту горы, затем с помощью астролябии — малый угол, на который линия горизонта «опускается» ниже горизонтали. По этим двум числам и свойствам прямоугольного треугольника он вычислил радиус Земли — около 6340 км. Современное значение — около 6371 км! Для того времени это была поразительная точность. Преимущество метода в том, что не нужно было идти сотни вёрст по пустыне — хватило одной горы и точного измерения.', 'Biruni first measured the mountain’s height, then used an astrolabe to measure the small angle by which the horizon “dips” below the horizontal. From these two numbers and the properties of a right triangle he computed the Earth’s radius — about 6340 km. The modern value is about 6371 km! That was astonishing precision for the time. The beauty of the method is that no one had to walk hundreds of miles across a desert — one mountain and a careful measurement were enough.')
    ] },
    { kind: 'rule', h: L('Urinmaning xossalari', 'Свойства касательной', 'Properties of a tangent'), list: [
      L('<b>1-teorema.</b> Urinma urinish nuqtasiga o‘tkazilgan radiusga perpendikulyar.', '<b>Теорема 1.</b> Касательная перпендикулярна радиусу, проведённому в точку касания.', '<b>Theorem 1.</b> A tangent is perpendicular to the radius drawn to the point of tangency.'),
      L('<b>2-teorema (alomat).</b> Agar to‘g‘ri chiziq aylana nuqtasidan o‘tsa va shu nuqtaga o‘tkazilgan radiusga perpendikulyar bo‘lsa, u urinma bo‘ladi.', '<b>Теорема 2 (признак).</b> Если прямая проходит через точку окружности и перпендикулярна радиусу, проведённому в эту точку, то она касательная.', '<b>Theorem 2 (test).</b> If a line passes through a point of the circle and is perpendicular to the radius at that point, it is a tangent.'),
      L('<b>3-teorema.</b> Aylanadan tashqaridagi P nuqtadan ikkita urinma o‘tkazish mumkin; P dan urinish nuqtalarigacha bo‘lgan kesmalar teng: PA = PB. Ular orasidagi burchakni PO nur teng ikkiga bo‘ladi.', '<b>Теорема 3.</b> Из точки P вне окружности можно провести две касательные; отрезки от P до точек касания равны: PA = PB. Луч PO делит угол между ними пополам.', '<b>Theorem 3.</b> From a point P outside the circle two tangents can be drawn; the segments from P to the points of tangency are equal: PA = PB. The ray PO bisects the angle between them.')
    ], after: [
      L('<b>1-teorema isboti.</b> Faraz qilaylik, urinma OA radiusga perpendikulyar emas. U holda O dan urinmaga tushirilgan perpendikulyar OH boshqa nuqtaga tushadi va og‘ma OA dan qisqa bo‘ladi: OH &lt; OA = r. Demak, d &lt; r va to‘g‘ri chiziq aylanani ikki nuqtada kesishi kerak edi. Bu urinma ta’rifiga zid. Demak, OA ⊥ urinma.', '<b>Доказательство теоремы 1.</b> Допустим, касательная не перпендикулярна радиусу OA. Тогда перпендикуляр OH из O на касательную падает в другую точку и короче наклонной OA: OH &lt; OA = r. Значит, d &lt; r, и прямая должна пересекать окружность в двух точках. Это противоречит определению касательной. Значит, OA ⊥ касательной.', '<b>Proof of Theorem 1.</b> Suppose the tangent is not perpendicular to OA. Then the perpendicular OH from O lands at another point and is shorter than the oblique OA: OH &lt; OA = r. So d &lt; r and the line would cut the circle twice, contradicting the definition of a tangent. Hence OA ⊥ tangent.'),
      L('<b>3-teorema isboti.</b> OAP va OBP uchburchaklar to‘g‘ri burchakli (1-teorema), gipotenuza OP umumiy, katetlar OA = OB = r. Ular gipotenuza va katet bo‘yicha teng, shuning uchun PA = PB. Uzunlik formulasi: <b>PA = √(OP<sup>2</sup> − r<sup>2</sup>)</b>.', '<b>Доказательство теоремы 3.</b> Треугольники OAP и OBP прямоугольные (теорема 1), гипотенуза OP общая, катеты OA = OB = r. Они равны по гипотенузе и катету, поэтому PA = PB. Формула длины: <b>PA = √(OP<sup>2</sup> − r<sup>2</sup>)</b>.', '<b>Proof of Theorem 3.</b> Triangles OAP and OBP are right-angled (Theorem 1), share the hypotenuse OP and have legs OA = OB = r. They are congruent by hypotenuse and leg, so PA = PB. The length formula is <b>PA = √(OP<sup>2</sup> − r<sup>2</sup>)</b>.')
    ] },
    { kind: 'steps', h: L('Urinma yasash', 'Построение касательной', 'Constructing a tangent'), p: [
      L('Aylananing A nuqtasi orqali urinma yasash uchun OA radiusni chizib, A nuqtadan unga perpendikulyar o‘tkazish kifoya (2-teorema). Tashqi P nuqtadan urinma yasash biroz qiyinroq, lekin chiroyli:', 'Чтобы построить касательную через точку A окружности, достаточно провести радиус OA и перпендикуляр к нему в точке A (теорема 2). Построение касательной из внешней точки P чуть сложнее, но красиво:', 'To draw a tangent at a point A on the circle, draw the radius OA and the perpendicular to it at A (Theorem 2). Drawing a tangent from an outside point P is a little harder but elegant:')
    ], list: [
      L('1-qadam. O va P nuqtalarni tutashtiring va OP kesmaning o‘rtasi M ni toping.', 'Шаг 1. Соедините O и P и найдите середину M отрезка OP.', 'Step 1. Join O and P and find the midpoint M of OP.'),
      L('2-qadam. M markazli, MO radiusli yordamchi aylana chizing.', 'Шаг 2. Проведите вспомогательную окружность с центром M и радиусом MO.', 'Step 2. Draw a helper circle with centre M and radius MO.'),
      L('3-qadam. Yordamchi aylana berilgan aylanani A va B nuqtalarda kesadi.', 'Шаг 3. Вспомогательная окружность пересекает данную в точках A и B.', 'Step 3. The helper circle meets the given circle at A and B.'),
      L('4-qadam. PA va PB to‘g‘ri chiziqlar — izlangan urinmalar. Nega? OAP burchak OP diametrga tiralgan, shuning uchun 90° (bu faktni keyingi mavzuda isbotlaymiz).', 'Шаг 4. Прямые PA и PB — искомые касательные. Почему? Угол OAP опирается на диаметр OP, значит он 90° (этот факт докажем в следующей теме).', 'Step 4. Lines PA and PB are the tangents. Why? Angle OAP stands on the diameter OP, so it is 90° (we prove this fact in the next topic).')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('r = 6, markazdan to‘g‘ri chiziqqacha masofa d = 8. Ular nechta umumiy nuqtaga ega?', 'r = 6, расстояние от центра до прямой d = 8. Сколько у них общих точек?', 'r = 6 and the distance from the centre to a line is d = 8. How many common points?'), s: L('d &gt; r, shuning uchun <b>umumiy nuqta yo‘q</b> — to‘g‘ri chiziq aylanadan tashqarida.', 'd &gt; r, поэтому <b>общих точек нет</b> — прямая проходит вне окружности.', 'd &gt; r, so there are <b>no common points</b> — the line misses the circle.') },
      { q: L('O markazdan P nuqtagacha 10 sm, aylana radiusi 6 sm. P dan o‘tkazilgan urinma kesmasi uzunligini toping.', 'Расстояние от центра O до точки P 10 см, радиус 6 см. Найдите длину отрезка касательной из P.', 'The distance from centre O to point P is 10 cm and the radius is 6 cm. Find the tangent length from P.'), s: L('OAP uchburchakda A da to‘g‘ri burchak. PA = √(10<sup>2</sup> − 6<sup>2</sup>) = √64 = <b>8 sm</b>. Ikkinchi urinma ham 8 sm.', 'В треугольнике OAP угол A прямой. PA = √(10<sup>2</sup> − 6<sup>2</sup>) = √64 = <b>8 см</b>. Вторая касательная тоже 8 см.', 'Triangle OAP has a right angle at A. PA = √(10<sup>2</sup> − 6<sup>2</sup>) = √64 = <b>8 cm</b>. The other tangent is also 8 cm.') },
      { q: L('P nuqtadan o‘tkazilgan ikki urinma orasidagi burchak 60°, r = 5. OP ni toping.', 'Угол между двумя касательными из точки P равен 60°, r = 5. Найдите OP.', 'Two tangents from P meet at 60°, r = 5. Find OP.'), s: L('PO burchakni teng ikkiga bo‘ladi: ∠APO = 30°. OAP to‘g‘ri burchakli uchburchakda 30° qarshisidagi katet OA = 5 gipotenuzaning yarmiga teng, demak OP = <b>10</b>.', 'PO делит угол пополам: ∠APO = 30°. В прямоугольном треугольнике OAP катет OA = 5 лежит против угла 30° и равен половине гипотенузы, значит OP = <b>10</b>.', 'PO bisects the angle: ∠APO = 30°. In right triangle OAP the leg OA = 5 is opposite 30°, so it is half the hypotenuse: OP = <b>10</b>.') },
      { q: L('Aylanaga tashqi chizilgan to‘rtburchakning uch tomoni ketma-ket 5, 7, 9. To‘rtinchi tomonini toping.', 'Три стороны описанного около окружности четырёхугольника по порядку равны 5, 7, 9. Найдите четвёртую.', 'Three consecutive sides of a quadrilateral drawn around a circle are 5, 7, 9. Find the fourth.'), s: L('Har bir uchdan chiqqan urinma kesmalari teng, shuning uchun qarama-qarshi tomonlar yig‘indisi teng: 5 + 9 = 7 + x, x = <b>7</b>.', 'Отрезки касательных из каждой вершины равны, поэтому суммы противоположных сторон равны: 5 + 9 = 7 + x, x = <b>7</b>.', 'Tangent lengths from each vertex are equal, so opposite sides have equal sums: 5 + 9 = 7 + x, x = <b>7</b>.') }
    ] },
    { kind: 'table', h: L('Holatlar jadvali', 'Таблица случаев', 'Table of cases'), p: [
      L('Masala shartida r va d berilganda javobni jadvaldan tez topish mumkin. Ikki aylana uchun ham shunga o‘xshash qoida bor: markazlar orasidagi masofani radiuslar yig‘indisi bilan taqqoslaymiz.', 'Если в условии даны r и d, ответ быстро находится по таблице. Для двух окружностей есть похожее правило: расстояние между центрами сравнивают с суммой радиусов.', 'When a problem gives r and d, the table gives the answer quickly. Two circles follow a similar rule: compare the distance between centres with the sum of the radii.')
    ], table: { head: [L('Shart', 'Условие', 'Condition'), L('Umumiy nuqtalar', 'Общие точки', 'Common points'), L('Nomi', 'Название', 'Name'), L('Misol', 'Пример', 'Example')], rows: [
      [L('d &gt; r', 'd &gt; r', 'd &gt; r'), '0', L('kesishmaydi', 'не пересекает', 'misses'), L('r = 4, d = 7', 'r = 4, d = 7', 'r = 4, d = 7')],
      [L('d = r', 'd = r', 'd = r'), '1', L('urinma', 'касательная', 'tangent'), L('r = 4, d = 4', 'r = 4, d = 4', 'r = 4, d = 4')],
      [L('d &lt; r', 'd &lt; r', 'd &lt; r'), '2', L('kesuvchi', 'секущая', 'secant'), L('r = 4, d = 2', 'r = 4, d = 2', 'r = 4, d = 2')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>d ni markazdan istalgan nuqtagacha o‘lchash.</b> d — bu aynan perpendikulyar uzunligi, ya’ni eng qisqa masofa.', '<b>Измеряют d до любой точки прямой.</b> d — именно длина перпендикуляра, кратчайшее расстояние.', '<b>Measuring d to any point of the line.</b> d is the length of the perpendicular — the shortest distance.'),
      L('<b>Urinma uzunligida kvadratlarni qo‘shish.</b> OP — gipotenuza, shuning uchun PA = √(OP<sup>2</sup> − r<sup>2</sup>), qo‘shish emas.', '<b>Складывают квадраты в длине касательной.</b> OP — гипотенуза, поэтому PA = √(OP<sup>2</sup> − r<sup>2</sup>), а не сумма.', '<b>Adding squares for the tangent length.</b> OP is the hypotenuse, so PA = √(OP<sup>2</sup> − r<sup>2</sup>), not a sum.'),
      L('<b>Aylanaga bir nuqtada tegadigan har qanday chiziqni urinma deb hisoblash.</b> Masalan, diametr davomidagi nur aylanaga bitta nuqtada tegishi mumkin, lekin u urinma emas — urinma radiusga perpendikulyar bo‘lishi shart.', '<b>Считают касательной любую линию с одной общей точкой.</b> Например, луч на продолжении диаметра может иметь одну общую точку, но касательной не является — касательная перпендикулярна радиусу.', '<b>Calling anything with one common point a tangent.</b> A ray along a diameter’s extension may meet the circle once but is not a tangent — a tangent must be perpendicular to the radius.'),
      L('<b>Aylana ichidagi nuqtadan urinma o‘tkazishga urinish.</b> Ichki nuqtadan urinma o‘tkazib bo‘lmaydi; aylana ustidagi nuqtadan — bitta, tashqi nuqtadan — ikkita.', '<b>Пытаются провести касательную из внутренней точки.</b> Из внутренней точки касательную провести нельзя; из точки на окружности — одну, из внешней — две.', '<b>Trying to draw a tangent from inside.</b> None exists from an inside point; there is one from a point on the circle and two from an outside point.')
    ] },
    { kind: 'life', h: L('Hayotda urinmalar', 'Касательные в жизни', 'Tangents in everyday life'), p: [
      L('<b>Ufqqacha masofa.</b> Beruniy usulini teskari qo‘llab, ufq qanchalik uzoqligini hisoblash mumkin. Balandligi h bo‘lgan joydan ufqqacha masofa √((R + h)<sup>2</sup> − R<sup>2</sup>) ≈ √(2Rh). Dengiz bo‘yida bo‘yi 1,7 m odam taxminan 4,7 km uzoqlikni ko‘radi, 100 m minoradan esa ufq 36 km uzoqlikda.', '<b>Расстояние до горизонта.</b> Применив метод Беруни наоборот, можно найти, насколько далеко горизонт. С высоты h расстояние до горизонта √((R + h)<sup>2</sup> − R<sup>2</sup>) ≈ √(2Rh). Человек ростом 1,7 м на берегу моря видит примерно на 4,7 км, а с башни 100 м — на 36 км.', '<b>Distance to the horizon.</b> Running Biruni’s method backwards tells you how far the horizon is. From height h the distance is √((R + h)<sup>2</sup> − R<sup>2</sup>) ≈ √(2Rh). A 1.7 m person on the seashore sees about 4.7 km; from a 100 m tower the horizon is 36 km away.'),
      L('<b>Tasma uzatmalar va velosiped zanjiri.</b> Ikki shkiv yoki yulduzcha orasidagi tasmaning tekis qismlari ikkala aylanaga umumiy urinma bo‘ylab yo‘nalgan. Muhandislar zanjir uzunligini shu urinmalar va yoylar yig‘indisi sifatida hisoblashadi.', '<b>Ременные передачи и велосипедная цепь.</b> Прямые участки ремня между двумя шкивами или звёздочками идут по общим касательным к обеим окружностям. Инженеры считают длину цепи как сумму этих касательных и дуг.', '<b>Belt drives and bicycle chains.</b> The straight runs of a belt between two pulleys or sprockets lie along common tangents to both circles. Engineers compute chain length as the sum of these tangents and arcs.'),
      L('<b>Sport.</b> Bolg‘achi otuvchi sportchi bolg‘ani aylana bo‘ylab aylantirib, qo‘yib yuboradi — bolg‘a urinma bo‘ylab uchib ketadi. Avtomobil sirpanchiq burilishda ham urinma bo‘ylab «chiqib ketadi».', '<b>Спорт.</b> Метатель молота раскручивает снаряд по окружности и отпускает — молот летит по касательной. Машина на скользком повороте тоже «уходит» по касательной.', '<b>Sport.</b> A hammer thrower spins the hammer around a circle and lets go — it flies off along the tangent. A car on an icy bend also slides away along a tangent.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('«Urinma» lotincha «tangens» — «tegib turuvchi» so‘zidan. Trigonometriyadagi tangens funksiyasi ham shu so‘zdan nom olgan.', '«Касательная» по-латыни «tangens» — «касающаяся». Тригонометрическая функция тангенс названа от того же слова.', '“Tangent” comes from Latin “tangens”, meaning “touching”. The trigonometric tangent function takes its name from the same word.'),
      L('Beruniy Yer o‘z o‘qi atrofida aylanishi mumkinligini ham jiddiy muhokama qilgan va bu fikrni geometrik jihatdan inkor etib bo‘lmasligini ta’kidlagan.', 'Беруни серьёзно обсуждал и возможность вращения Земли вокруг своей оси, отмечая, что геометрически опровергнуть эту мысль нельзя.', 'Biruni also seriously discussed the possibility that the Earth spins on its axis, noting that geometry alone could not refute the idea.'),
      L('Quyosh tutilishida Oy soyasining chegaralari Quyosh va Oyga umumiy urinmalar bo‘ylab o‘tadi.', 'При солнечном затмении границы лунной тени проходят по общим касательным к Солнцу и Луне.', 'During a solar eclipse, the edges of the Moon’s shadow run along the common tangents to the Sun and the Moon.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('r = 5, d = 5. To‘g‘ri chiziq qanday?', 'r = 5, d = 5. Какая это прямая?', 'r = 5, d = 5. What kind of line?'), s: L('d = r — <b>urinma</b>, bitta umumiy nuqta.', 'd = r — <b>касательная</b>, одна общая точка.', 'd = r — a <b>tangent</b>, one common point.') },
      { q: L('OP = 13, r = 5. PA = ?', 'OP = 13, r = 5. PA = ?', 'OP = 13, r = 5. PA = ?'), s: L('√(169 − 25) = √144 = <b>12</b>.', '√(169 − 25) = √144 = <b>12</b>.', '√(169 − 25) = √144 = <b>12</b>.') },
      { q: L('PA urinma, ∠AOP = 50°. ∠APO = ?', 'PA — касательная, ∠AOP = 50°. ∠APO = ?', 'PA is a tangent, ∠AOP = 50°. ∠APO = ?'), s: L('∠OAP = 90°, shuning uchun ∠APO = 180° − 90° − 50° = <b>40°</b>.', '∠OAP = 90°, поэтому ∠APO = 180° − 90° − 50° = <b>40°</b>.', '∠OAP = 90°, so ∠APO = 180° − 90° − 50° = <b>40°</b>.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('d &gt; r — umumiy nuqta yo‘q, d = r — urinma, d &lt; r — kesuvchi.', 'd &gt; r — нет общих точек, d = r — касательная, d &lt; r — секущая.', 'd &gt; r — no common points; d = r — tangent; d &lt; r — secant.'),
      L('Urinma urinish nuqtasidagi radiusga perpendikulyar; teskarisi ham to‘g‘ri.', 'Касательная перпендикулярна радиусу в точке касания; верно и обратное.', 'A tangent is perpendicular to the radius at the point of tangency, and conversely.'),
      L('Bir nuqtadan o‘tkazilgan urinma kesmalari teng: PA = PB = √(OP<sup>2</sup> − r<sup>2</sup>).', 'Отрезки касательных из одной точки равны: PA = PB = √(OP<sup>2</sup> − r<sup>2</sup>).', 'Tangent lengths from one point are equal: PA = PB = √(OP<sup>2</sup> − r<sup>2</sup>).'),
      L('Aylanaga tashqi chizilgan to‘rtburchakda qarama-qarshi tomonlar yig‘indilari teng.', 'В описанном около окружности четырёхугольнике суммы противоположных сторон равны.', 'In a quadrilateral drawn around a circle, opposite sides have equal sums.'),
      L('Beruniy tog‘ cho‘qqisidan ufqqa o‘tkazilgan urinma yordamida Yer radiusini ≈ 6340 km deb topgan.', 'Беруни по касательной с вершины горы к горизонту нашёл радиус Земли ≈ 6340 км.', 'Biruni used the tangent from a mountain top to the horizon to find the Earth’s radius ≈ 6340 km.')
    ] }
  ] });

  // ---------- t16. Aylanaga ichki chizilgan burchak ----------
  T.add(P, 't16', { sections: [
    { kind: 'intro', h: L('Teatrdagi eng yaxshi joy', 'Лучшее место в театре', 'The best seat in the theatre'), p: [
      L('Tasavvur qiling: siz amfiteatrda o‘tiribsiz, sahna esa sizdan pastda. Siz qayerda o‘tirsangiz, sahnaning chap va o‘ng chekkalariga qaragan nigohlaringiz orasidagi burchak qancha bo‘ladi? Ajablanarli, lekin agar o‘rindiqlar ma’lum aylana bo‘ylab joylashgan bo‘lsa, bu burchak hamma tomoshabin uchun bir xil chiqadi! Bu sirni <b>ichki chizilgan burchak</b> haqidagi teorema tushuntiradi.', 'Представьте: вы сидите в амфитеатре, сцена внизу. Каков угол между лучами зрения на левый и правый края сцены? Удивительно, но если кресла стоят по определённой окружности, этот угол одинаков для всех зрителей! Эту тайну объясняет теорема о <b>вписанном угле</b>.', 'Imagine you are sitting in an amphitheatre with the stage below. What is the angle between your lines of sight to the left and right edges of the stage? Surprisingly, if the seats lie on a certain circle, that angle is the same for every spectator! The theorem on the <b>inscribed angle</b> explains this secret.'),
      L('Bu mavzuda ichki chizilgan burchak nima ekanini, u tiralgan yoy bilan qanday bog‘langanini va bundan kelib chiqadigan ajoyib natijalarni o‘rganamiz. Masalan, nima uchun diametrga tiralgan har qanday burchak to‘g‘ri burchak bo‘lishini isbotlaymiz. Bu natija Yevklid kitobida Falesga nisbat beriladi va geometriyadagi eng go‘zal faktlardan biri hisoblanadi.', 'В этой теме узнаем, что такое вписанный угол, как он связан с дугой, на которую опирается, и какие замечательные следствия отсюда вытекают. Например, докажем, почему любой угол, опирающийся на диаметр, — прямой. Этот результат приписывают Фалесу, и он считается одним из красивейших фактов геометрии.', 'In this topic we learn what an inscribed angle is, how it relates to the arc it stands on, and the wonderful consequences of that. For example, we prove why every angle standing on a diameter is a right angle — a result credited to Thales and one of the most beautiful facts in geometry.')
    ] },
    { kind: 'def', h: L('Ichki chizilgan burchak', 'Вписанный угол', 'The inscribed angle'), p: [
      L('Uchi aylanada yotgan, tomonlari esa aylanani kesib o‘tadigan burchak <b>aylanaga ichki chizilgan burchak</b> deyiladi. Masalan, A, B, C aylana nuqtalari bo‘lsa, ABC burchak ichki chizilgan; uning tomonlari BA va BC vatarlardir. Bu burchak AC yoyga (B nuqtani o‘z ichiga olmagan yoyga) <b>tiraladi</b>.', 'Угол, вершина которого лежит на окружности, а стороны пересекают окружность, называется <b>вписанным</b>. Если A, B, C — точки окружности, угол ABC вписанный; его стороны — хорды BA и BC. Он <b>опирается</b> на дугу AC (не содержащую B).', 'An angle whose vertex lies on the circle and whose sides cut the circle is called an <b>inscribed angle</b>. If A, B, C are points of the circle, angle ABC is inscribed; its sides are the chords BA and BC. It <b>stands on</b> the arc AC (the one not containing B).'),
      L('Markaziy burchak bilan farqini eslab qoling: markaziy burchakning uchi markazda, ichki chizilganning uchi esa aylananing o‘zida. Bitta yoyga bitta markaziy burchak, lekin cheksiz ko‘p ichki chizilgan burchak tiraladi — B nuqtani aylana bo‘ylab istalgancha siljitish mumkin.', 'Запомните отличие от центрального угла: у центрального вершина в центре, у вписанного — на самой окружности. На одну дугу опирается один центральный угол, но бесконечно много вписанных — точку B можно двигать по окружности.', 'Remember the difference from a central angle: a central angle has its vertex at the centre, an inscribed angle on the circle itself. Each arc has one central angle but infinitely many inscribed angles — B can slide anywhere along the circle.')
    ] },
    { kind: 'history', h: L('Fales va Yevklid', 'Фалес и Евклид', 'Thales and Euclid'), p: [
      L('<b>Miletlik Fales</b> (miloddan avvalgi VI asr) — yunon olimlari orasida birinchi bo‘lib geometrik faktlarni isbotlashga harakat qilgan kishi. Rivoyatga ko‘ra, u diametrga tiralgan burchak to‘g‘ri ekanini kashf qilganda, xuddi Pifagor singari qurbonlik keltirgan. Shu sababli bu natija hozir ham ko‘p mamlakatlarda «Fales teoremasi» deb ataladi. Fales Misrda bo‘lganida piramida balandligini uning soyasi orqali o‘lchagani bilan ham mashhur.', '<b>Фалес Милетский</b> (VI в. до н. э.) — первый из греческих учёных, кто стал доказывать геометрические факты. По преданию, открыв, что угол, опирающийся на диаметр, прямой, он, как и Пифагор, принёс жертву. Поэтому этот результат во многих странах называют «теоремой Фалеса». Фалес также знаменит тем, что в Египте измерил высоту пирамиды по её тени.', '<b>Thales of Miletus</b> (6th century BC) was the first Greek scholar to try to prove geometric facts. Legend says that when he discovered that an angle on a diameter is a right angle, he, like Pythagoras, offered a sacrifice. That is why in many countries the result is called “Thales’ theorem”. Thales is also famous for measuring the height of a pyramid in Egypt from its shadow.'),
      L('Umumiy teoremani — ichki chizilgan burchak markaziy burchakning yarmiga teng ekanini — <b>Yevklid</b> «Negizlar»ning uchinchi kitobida (20-taklif) isbotlagan. O‘rta asrlarda Sharq olimlari, jumladan Beruniy va Nasriddin Tusiy, bu teoremalardan astronomik asboblar va xaritalarni hisoblashda keng foydalanishgan.', 'Общую теорему — вписанный угол равен половине центрального — доказал <b>Евклид</b> в третьей книге «Начал» (предложение 20). В Средние века учёные Востока, в том числе Беруни и Насир ад-Дин Туси, широко использовали эти теоремы при расчёте астрономических приборов и карт.', 'The general theorem — an inscribed angle is half the central angle — was proved by <b>Euclid</b> in Book III of the “Elements” (Proposition 20). In the Middle Ages scholars of the East, including Biruni and Nasir al-Din al-Tusi, used these theorems widely to design astronomical instruments and maps.')
    ] },
    { kind: 'rule', h: L('Asosiy teorema', 'Основная теорема', 'The main theorem'), p: [
      L('<b>Teorema.</b> Ichki chizilgan burchak o‘zi tiralgan yoyning yarmiga, ya’ni shu yoyga tiralgan markaziy burchakning yarmiga teng: <b>∠ABC = ∠AOC / 2</b>.', '<b>Теорема.</b> Вписанный угол равен половине дуги, на которую опирается, т.е. половине центрального угла, опирающегося на ту же дугу: <b>∠ABC = ∠AOC / 2</b>.', '<b>Theorem.</b> An inscribed angle equals half the arc it stands on, that is, half the central angle on the same arc: <b>∠ABC = ∠AOC / 2</b>.'),
      L('<b>Isbot (eng oddiy hol).</b> Burchakning bir tomoni, masalan BC, diametr bo‘lsin, ya’ni O markaz BC ustida yotsin. OAB uchburchakda OA = OB (radiuslar), demak u teng yonli va ∠OAB = ∠OBA = x. AOC burchak shu uchburchakning tashqi burchagi, shuning uchun u ikki ichki burchak yig‘indisiga teng: ∠AOC = x + x = 2x. Demak, ∠ABC = x = ∠AOC/2.', '<b>Доказательство (простейший случай).</b> Пусть одна сторона угла, например BC, — диаметр, т.е. центр O лежит на BC. В треугольнике OAB OA = OB (радиусы), он равнобедренный, ∠OAB = ∠OBA = x. Угол AOC — внешний угол этого треугольника, он равен сумме двух внутренних: ∠AOC = x + x = 2x. Значит, ∠ABC = x = ∠AOC/2.', '<b>Proof (simplest case).</b> Let one side, say BC, be a diameter, so the centre O lies on BC. In triangle OAB, OA = OB (radii), so it is isosceles and ∠OAB = ∠OBA = x. Angle AOC is an exterior angle of this triangle, so it equals the sum of the two remote interior angles: ∠AOC = 2x. Hence ∠ABC = x = ∠AOC/2.'),
      L('Agar markaz burchak ichida yoki tashqarisida yotsa, B dan diametr o‘tkazib, burchakni ikkita «oddiy hol» burchaklarining yig‘indisi yoki ayirmasi ko‘rinishida yozamiz va har biriga isbotlangan natijani qo‘llaymiz.', 'Если центр лежит внутри или вне угла, проводим диаметр из B и записываем угол как сумму или разность двух углов «простейшего случая», к каждому из которых применяем доказанное.', 'If the centre lies inside or outside the angle, draw the diameter from B and write the angle as the sum or difference of two “simplest case” angles, applying the proved result to each.')
    ] },
    { kind: 'rule', h: L('Natijalar', 'Следствия', 'Consequences'), list: [
      L('<b>1-natija.</b> Bitta yoyga tiralgan barcha ichki chizilgan burchaklar teng. (Teatrdagi tomoshabinlar misoli!)', '<b>Следствие 1.</b> Все вписанные углы, опирающиеся на одну дугу, равны. (Пример со зрителями в театре!)', '<b>Consequence 1.</b> All inscribed angles standing on the same arc are equal. (The theatre example!)'),
      L('<b>2-natija (Fales teoremasi).</b> Diametrga (yarim aylanaga) tiralgan ichki chizilgan burchak to‘g‘ri burchak: 180°/2 = 90°.', '<b>Следствие 2 (теорема Фалеса).</b> Вписанный угол, опирающийся на диаметр (полуокружность), прямой: 180°/2 = 90°.', '<b>Consequence 2 (Thales’ theorem).</b> An inscribed angle standing on a diameter (a semicircle) is a right angle: 180°/2 = 90°.'),
      L('<b>3-natija.</b> Aylanaga ichki chizilgan to‘rtburchakning qarama-qarshi burchaklari yig‘indisi 180°, chunki ular birgalikda butun aylanaga (360°) tiraladi.', '<b>Следствие 3.</b> Сумма противоположных углов вписанного четырёхугольника равна 180°, так как вместе они опираются на всю окружность (360°).', '<b>Consequence 3.</b> Opposite angles of a quadrilateral inscribed in a circle add to 180°, because together they stand on the whole circle (360°).'),
      L('<b>4-natija.</b> To‘g‘ri burchakli uchburchakka tashqi chizilgan aylananing markazi gipotenuza o‘rtasida, radiusi esa gipotenuzaning yarmiga teng.', '<b>Следствие 4.</b> Центр окружности, описанной около прямоугольного треугольника, — середина гипотенузы, радиус равен половине гипотенузы.', '<b>Consequence 4.</b> The circle around a right triangle has its centre at the midpoint of the hypotenuse and radius equal to half the hypotenuse.')
    ] },
    { kind: 'steps', h: L('Burchak masalalarini yechish tartibi', 'Порядок решения задач на углы', 'How to solve angle problems'), p: [
      L('Aylanadagi burchaklarga oid masalalar ko‘pincha bir-biriga o‘xshaydi. Ularni chalkashmasdan yechish uchun quyidagi tartibga amal qiling. Har bir qadamda chizmaga yangi ma’lumotni yozib boring — shunda yechim o‘z-o‘zidan ko‘rinib qoladi.', 'Задачи на углы в окружности часто похожи друг на друга. Чтобы не запутаться, действуйте по порядку. На каждом шаге отмечайте новое на чертеже — тогда решение станет видно само.', 'Problems about angles in a circle often look alike. To avoid confusion, follow this order. Write each new fact on the diagram as you go — the solution then shows itself.')
    ], list: [
      L('1-qadam. Burchak turini aniqlang: uchi markazdami (markaziy) yoki aylanadami (ichki chizilgan)?', 'Шаг 1. Определите вид угла: вершина в центре (центральный) или на окружности (вписанный)?', 'Step 1. Identify the angle: is the vertex at the centre (central) or on the circle (inscribed)?'),
      L('2-qadam. Burchak qaysi yoyga tiralganini toping — uning uchini o‘z ichiga olmagan yoyga.', 'Шаг 2. Найдите дугу, на которую опирается угол, — ту, что не содержит его вершину.', 'Step 2. Find the arc the angle stands on — the one not containing its vertex.'),
      L('3-qadam. Markaziy burchak = yoy; ichki chizilgan burchak = yoy : 2. Yoydan burchakka o‘tishda bo‘ling, burchakdan yoyga o‘tishda ko‘paytiring.', 'Шаг 3. Центральный угол = дуга; вписанный = дуга : 2. От дуги к углу — делим, от угла к дуге — умножаем.', 'Step 3. Central angle = arc; inscribed angle = arc ÷ 2. Arc to angle: divide; angle to arc: multiply.'),
      L('4-qadam. Diametr bormi? Bo‘lsa, unga tiralgan burchak 90° — Pifagor teoremasini qo‘llash mumkin.', 'Шаг 4. Есть ли диаметр? Если да, угол на него — 90°, можно применить теорему Пифагора.', 'Step 4. Is there a diameter? If so, the angle on it is 90° and Pythagoras applies.'),
      L('5-qadam. Teng yonli uchburchaklarni qidiring: ikki radius doimo teng, shuning uchun markaz bilan ikki nuqta teng yonli uchburchak hosil qiladi.', 'Шаг 5. Ищите равнобедренные треугольники: два радиуса всегда равны, поэтому центр и две точки дают равнобедренный треугольник.', 'Step 5. Look for isosceles triangles: two radii are always equal, so the centre and two points form an isosceles triangle.')
    ], after: [
      L('Masalan: B burchak 50° va u AC yoyga tiralgan bo‘lsa, AC yoy 100°, AOC markaziy burchak ham 100°, OAC teng yonli uchburchakning asosdagi burchaklari esa (180° − 100°) : 2 = 40° dan.', 'Например: угол B равен 50° и опирается на дугу AC; тогда дуга AC — 100°, центральный угол AOC — 100°, а углы при основании равнобедренного треугольника OAC — по (180° − 100°) : 2 = 40°.', 'For example: if angle B is 50° on arc AC, then arc AC is 100°, central angle AOC is 100°, and the base angles of isosceles triangle OAC are (180° − 100°) ÷ 2 = 40° each.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('AOC markaziy burchak 130°. AC yoyga tiralgan ichki chizilgan ABC burchakni toping.', 'Центральный угол AOC равен 130°. Найдите вписанный угол ABC, опирающийся на дугу AC.', 'Central angle AOC is 130°. Find the inscribed angle ABC on arc AC.'), s: L('∠ABC = 130°/2 = <b>65°</b>.', '∠ABC = 130°/2 = <b>65°</b>.', '∠ABC = 130°/2 = <b>65°</b>.') },
      { q: L('AB — diametr, C aylana nuqtasi, AC = 6, BC = 8. Aylana radiusini toping.', 'AB — диаметр, C — точка окружности, AC = 6, BC = 8. Найдите радиус окружности.', 'AB is a diameter, C is on the circle, AC = 6, BC = 8. Find the radius.'), s: L('Fales teoremasiga ko‘ra ∠ACB = 90°. AB = √(36 + 64) = 10, r = <b>5</b>.', 'По теореме Фалеса ∠ACB = 90°. AB = √(36 + 64) = 10, r = <b>5</b>.', 'By Thales, ∠ACB = 90°. AB = √(36 + 64) = 10, so r = <b>5</b>.') },
      { q: L('ABCD aylanaga ichki chizilgan, ∠A = 75°, ∠B = 110°. ∠C va ∠D ni toping.', 'ABCD вписан в окружность, ∠A = 75°, ∠B = 110°. Найдите ∠C и ∠D.', 'ABCD is inscribed in a circle, ∠A = 75°, ∠B = 110°. Find ∠C and ∠D.'), s: L('∠C = 180° − 75° = <b>105°</b>, ∠D = 180° − 110° = <b>70°</b>.', '∠C = 180° − 75° = <b>105°</b>, ∠D = 180° − 110° = <b>70°</b>.', '∠C = 180° − 75° = <b>105°</b>, ∠D = 180° − 110° = <b>70°</b>.') },
      { q: L('Aylana A, B, C nuqtalar bilan 3 : 4 : 5 nisbatdagi yoylarga bo‘lingan. ABC uchburchak burchaklarini toping.', 'Точки A, B, C делят окружность на дуги в отношении 3 : 4 : 5. Найдите углы треугольника ABC.', 'Points A, B, C split a circle into arcs in the ratio 3 : 4 : 5. Find the angles of triangle ABC.'), s: L('Yoylar: 360° : 12 = 30°, demak 90°, 120°, 150°. Har bir burchak qarshisidagi yoyning yarmi: <b>45°, 60°, 75°</b>. Tekshiruv: yig‘indi 180°.', 'Дуги: 360° : 12 = 30°, т.е. 90°, 120°, 150°. Каждый угол — половина противолежащей дуги: <b>45°, 60°, 75°</b>. Проверка: сумма 180°.', 'Arcs: 360° ÷ 12 = 30°, so 90°, 120°, 150°. Each angle is half the opposite arc: <b>45°, 60°, 75°</b>. Check: they add to 180°.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Ichki chizilgan burchakni yoyga teng deb olish.</b> Yoyga markaziy burchak teng; ichki chizilgan — yarmiga.', '<b>Считают вписанный угол равным дуге.</b> Дуге равен центральный угол, вписанный — её половине.', '<b>Taking the inscribed angle equal to the arc.</b> The central angle equals the arc; the inscribed angle is half of it.'),
      L('<b>Teskarisiga bo‘lish.</b> Ichki burchakdan yoyni topishda 2 ga <i>ko‘paytirish</i> kerak: 40° li burchak 80° li yoyga tiraladi.', '<b>Делят вместо умножения.</b> Чтобы по вписанному углу найти дугу, нужно <i>умножить</i> на 2: угол 40° опирается на дугу 80°.', '<b>Dividing instead of multiplying.</b> To get the arc from the inscribed angle, <i>multiply</i> by 2: a 40° angle stands on an 80° arc.'),
      L('<b>Noto‘g‘ri yoyni tanlash.</b> Burchak uchini o‘z ichiga <i>olmagan</i> yoy hisoblanadi. Agar yoy 360° − x bo‘lsa, burchak 180° − x/2 bo‘ladi.', '<b>Выбирают не ту дугу.</b> Берётся дуга, <i>не содержащая</i> вершину угла. Если она 360° − x, угол равен 180° − x/2.', '<b>Picking the wrong arc.</b> Use the arc that does <i>not</i> contain the vertex. If that arc is 360° − x, the angle is 180° − x/2.'),
      L('<b>Har qanday to‘rtburchakda qarama-qarshi burchaklar yig‘indisini 180° deb olish.</b> Bu faqat aylanaga ichki chizilgan to‘rtburchak uchun to‘g‘ri.', '<b>Считают, что в любом четырёхугольнике противоположные углы дают 180°.</b> Это верно только для вписанного.', '<b>Assuming opposite angles add to 180° in every quadrilateral.</b> That only holds for one inscribed in a circle.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Futbolda zarba burchagi.</b> Darvozaga zarba berilgan burchak darvoza ustunlari va to‘p orqali o‘tadigan aylanaga bog‘liq. Bir aylanadagi barcha nuqtalardan darvoza bir xil burchak ostida ko‘rinadi, kichikroq aylanada esa burchak kattaroq. Murabbiylar hujumchilarga «eng qulay nuqta»ni shunday tushuntirishadi.', '<b>Угол удара в футболе.</b> Угол, под которым видны ворота, зависит от окружности, проходящей через штанги и мяч. Из всех точек одной окружности ворота видны под одним углом, а на меньшей окружности угол больше. Так тренеры объясняют нападающим «лучшую точку».', '<b>Shooting angle in football.</b> The angle at which the goal is seen depends on the circle through the two posts and the ball. From every point on one circle the goal is seen at the same angle, and a smaller circle gives a larger angle. Coaches use this to explain the “best spot” to strikers.'),
      L('<b>Duradgorlik.</b> Usta yog‘ochdagi yarim doira o‘yiq aniq yarim aylana ekanini tekshirish uchun to‘g‘ri burchakli chizg‘ichni ichkariga qo‘yadi: agar burchak uchi o‘yiq chetiga, tomonlari esa diametr uchlariga tegsa — o‘yiq to‘g‘ri. Bu Fales teoremasining teskarisi.', '<b>Столярное дело.</b> Чтобы проверить, что полукруглый вырез — точная полуокружность, мастер вставляет внутрь угольник: если вершина касается края, а стороны — концов диаметра, вырез правильный. Это обратная теорема Фалеса.', '<b>Woodwork.</b> To check that a semicircular groove is a true semicircle, a carpenter sets a set square inside it: if the corner touches the edge and the sides reach the ends of the diameter, the groove is correct. This is the converse of Thales’ theorem.'),
      L('<b>Aylana markazini topish.</b> Qog‘oz varag‘ining to‘g‘ri burchagini aylanaga qo‘ying: tomonlar aylanani kesgan ikki nuqta diametr uchlari bo‘ladi. Buni ikki marta takrorlasangiz, diametrlar kesishgan nuqta — markaz.', '<b>Как найти центр круга.</b> Приложите прямой угол листа бумаги вершиной к окружности: точки, где стороны пересекают окружность, — концы диаметра. Повторив дважды, найдёте центр на пересечении диаметров.', '<b>Finding the centre of a circle.</b> Put the corner of a sheet of paper on the circle: where its edges cross the circle are the ends of a diameter. Do it twice — the diameters cross at the centre.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Fotograflar «ko‘rish burchagi» tushunchasidan foydalanishadi: bir aylana ustidagi istalgan nuqtadan ob’ekt bir xil burchakda ko‘rinadi, shuning uchun kadrdagi o‘lchami ham bir xil bo‘ladi.', 'Фотографы пользуются понятием «угла обзора»: из любой точки одной окружности объект виден под одним углом, поэтому в кадре он одного размера.', 'Photographers rely on the “angle of view”: from any point of one circle an object is seen at the same angle, so it looks the same size in the frame.'),
      L('Dengizchilar qirg‘oqdagi ikki mayoq orasidagi burchakni o‘lchab, kema qaysi aylanada turganini bilishgan; ikkinchi juft mayoq bilan aniq joy topilgan.', 'Моряки, измерив угол между двумя маяками на берегу, узнавали, на какой окружности находится корабль; вторая пара маяков давала точное место.', 'Sailors measured the angle between two lighthouses to know which circle their ship was on; a second pair of lighthouses fixed the exact position.'),
      L('Ichki chizilgan burchak teoremasi Ptolemeyning vatarlar jadvaliga asos bo‘lgan — bu dunyodagi birinchi «trigonometrik jadval» edi.', 'Теорема о вписанном угле легла в основу таблицы хорд Птолемея — первой в мире «тригонометрической таблицы».', 'The inscribed-angle theorem underlies Ptolemy’s table of chords — the world’s first “trigonometric table”.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('Yoy 140°. Ichki chizilgan burchak?', 'Дуга 140°. Вписанный угол?', 'Arc 140°. Inscribed angle?'), s: L('140° : 2 = <b>70°</b>.', '140° : 2 = <b>70°</b>.', '140° ÷ 2 = <b>70°</b>.') },
      { q: L('Ichki chizilgan burchak 35°. U tiralgan yoy?', 'Вписанный угол 35°. Дуга?', 'Inscribed angle 35°. Its arc?'), s: L('35° · 2 = <b>70°</b>.', '35° · 2 = <b>70°</b>.', '35° · 2 = <b>70°</b>.') },
      { q: L('To‘g‘ri burchakli uchburchak gipotenuzasi 26. Tashqi aylana radiusi?', 'Гипотенуза прямоугольного треугольника 26. Радиус описанной окружности?', 'A right triangle’s hypotenuse is 26. Circumradius?'), s: L('R = 26 : 2 = <b>13</b>.', 'R = 26 : 2 = <b>13</b>.', 'R = 26 ÷ 2 = <b>13</b>.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Ichki chizilgan burchak — uchi aylanada, tomonlari vatar bo‘lgan burchak.', 'Вписанный угол — угол с вершиной на окружности, стороны которого — хорды.', 'An inscribed angle has its vertex on the circle and chords as sides.'),
      L('U tiralgan yoyning yarmiga teng: ∠ABC = ∠AOC/2.', 'Он равен половине дуги, на которую опирается: ∠ABC = ∠AOC/2.', 'It equals half its arc: ∠ABC = ∠AOC/2.'),
      L('Bir yoyga tiralgan ichki chizilgan burchaklar teng.', 'Вписанные углы на одну дугу равны.', 'Inscribed angles on the same arc are equal.'),
      L('Diametrga tiralgan burchak 90° (Fales teoremasi).', 'Угол, опирающийся на диаметр, — 90° (теорема Фалеса).', 'An angle on a diameter is 90° (Thales’ theorem).'),
      L('Ichki chizilgan to‘rtburchakda qarama-qarshi burchaklar yig‘indisi 180°.', 'Во вписанном четырёхугольнике противоположные углы в сумме 180°.', 'In an inscribed quadrilateral opposite angles add to 180°.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-2';

  // ---------- t17. Ichki va tashqi chizilgan aylanalar ----------
  T.add(P, 't17', { sections: [
    { kind: 'intro', h: L('Uchburchak va aylana do‘stligi', 'Дружба треугольника и окружности', 'Triangles and circles together'), p: [
      L('Uchburchak shaklidagi bog‘ maydonchasi o‘rtasiga iloji boricha katta dumaloq favvora qurmoqchimiz, lekin favvora maydoncha chegarasidan chiqmasligi kerak. Favvora markazini qayerga qo‘yish kerak va uning radiusi qancha bo‘ladi? Endi boshqa masala: uchta qishloq uchun umumiy quduq qazish kerak, quduq esa har bir qishloqdan bir xil uzoqlikda bo‘lishi lozim. Uni qayerda qazish kerak?', 'Мы хотим построить в треугольном сквере как можно большой круглый фонтан, не выходящий за границы сквера. Где поставить его центр и каков будет радиус? Другая задача: для трёх сёл нужно выкопать общий колодец, равноудалённый от каждого села. Где его копать?', 'We want to build the largest possible round fountain inside a triangular park without crossing its edges. Where should its centre go, and what is its radius? Another problem: three villages need a shared well that is equally far from each village. Where should it be dug?'),
      L('Ikkala savolning javobi bu mavzuda. Birinchisida biz uchburchakka <b>ichki chizilgan aylanani</b>, ikkinchisida esa <b>tashqi chizilgan aylanani</b> izlaymiz. Har qanday uchburchakda ikkalasi ham mavjud va yagona ekanini isbotlaymiz, markazlarini yasashni va radiuslarini hisoblashni o‘rganamiz. To‘rtburchaklar uchun esa bu har doim ham mumkin emas — qanday shartda mumkinligini ham bilib olamiz.', 'Ответы на оба вопроса — в этой теме. В первом случае ищем <b>вписанную</b> в треугольник окружность, во втором — <b>описанную</b>. Докажем, что у любого треугольника обе существуют и единственны, научимся строить их центры и вычислять радиусы. Для четырёхугольников это возможно не всегда — узнаем, при каком условии.', 'Both answers are in this topic. In the first we look for the <b>inscribed circle</b> (incircle) of the triangle, in the second for the <b>circumscribed circle</b> (circumcircle). We prove that every triangle has exactly one of each, learn to construct their centres and compute their radii. For quadrilaterals this is not always possible — we will find out when it is.')
    ] },
    { kind: 'def', h: L('Ta’riflar', 'Определения', 'Definitions'), list: [
      L('<b>Ichki chizilgan aylana</b> — ko‘pburchakning barcha tomonlariga urinadigan aylana. Bunda ko‘pburchak aylanaga <i>tashqi chizilgan</i> deyiladi. Radiusi r bilan belgilanadi.', '<b>Вписанная окружность</b> — окружность, касающаяся всех сторон многоугольника. Многоугольник при этом называется <i>описанным</i>. Её радиус обозначают r.', 'An <b>inscribed circle</b> touches every side of a polygon; the polygon is then <i>circumscribed</i> about the circle. Its radius is r.'),
      L('<b>Tashqi chizilgan aylana</b> — ko‘pburchakning barcha uchlaridan o‘tadigan aylana. Bunda ko‘pburchak aylanaga <i>ichki chizilgan</i> deyiladi. Radiusi R bilan belgilanadi.', '<b>Описанная окружность</b> — окружность, проходящая через все вершины многоугольника. Многоугольник при этом называется <i>вписанным</i>. Её радиус обозначают R.', 'A <b>circumscribed circle</b> passes through every vertex of a polygon; the polygon is then <i>inscribed</i> in the circle. Its radius is R.'),
      L('<b>Bissektrisa</b> — burchakni teng ikkiga bo‘luvchi nur. Uning har bir nuqtasi burchak tomonlaridan teng uzoqlikda.', '<b>Биссектриса</b> — луч, делящий угол пополам. Каждая её точка равноудалена от сторон угла.', 'An <b>angle bisector</b> splits an angle in half. Each of its points is equally far from the two sides.'),
      L('<b>O‘rta perpendikulyar</b> — kesma o‘rtasidan unga perpendikulyar o‘tgan to‘g‘ri chiziq. Uning har bir nuqtasi kesma uchlaridan teng uzoqlikda.', '<b>Серединный перпендикуляр</b> — прямая, проходящая через середину отрезка перпендикулярно ему. Каждая её точка равноудалена от концов отрезка.', 'A <b>perpendicular bisector</b> passes through a segment’s midpoint at right angles. Each of its points is equally far from the segment’s ends.')
    ], after: [
      L('Yodlab olish uchun qoida: «ichki — tomonlarga tegadi, tashqi — uchlardan o‘tadi».', 'Правило для запоминания: «вписанная касается сторон, описанная проходит через вершины».', 'A memory hook: “the incircle touches the sides, the circumcircle passes through the corners”.')
    ] },
    { kind: 'history', h: L('Yevklid va «ajoyib nuqtalar»', 'Евклид и «замечательные точки»', 'Euclid and the “remarkable points”'), p: [
      L('<b>Yevklid</b> «Negizlar»ning to‘rtinchi kitobida uchburchakka ichki va tashqi aylana chizish usullarini sirkul va chizg‘ich yordamida bayon qilgan. U uchala bissektrisa bitta nuqtada kesishishini va uchala o‘rta perpendikulyar ham bitta nuqtada kesishishini isbotlagan. Bu nuqtalar keyinchalik uchburchakning «ajoyib nuqtalari» deb atala boshladi: ichki aylana markazi (intsentr), tashqi aylana markazi (sirkumtsentr), medianalar kesishmasi va balandliklar kesishmasi.', '<b>Евклид</b> в четвёртой книге «Начал» описал, как циркулем и линейкой вписать окружность в треугольник и описать около него. Он доказал, что три биссектрисы пересекаются в одной точке, и три серединных перпендикуляра — тоже. Позже эти точки назвали «замечательными точками» треугольника: центр вписанной окружности (инцентр), центр описанной (циркумцентр), точка пересечения медиан и точка пересечения высот.', 'In Book IV of the “Elements”, <b>Euclid</b> showed how to inscribe a circle in a triangle and circumscribe one around it with compass and straightedge. He proved that the three angle bisectors meet at one point, and so do the three perpendicular bisectors. Later these became the triangle’s “remarkable points”: the incentre, the circumcentre, the centroid and the orthocentre.'),
      L('1765-yilda shveytsariyalik buyuk matematik <b>Leonard Eyler</b> hayratlanarli kashfiyot qildi: tashqi aylana markazi, medianalar kesishmasi va balandliklar kesishmasi har doim bitta to‘g‘ri chiziqda yotadi. Bu chiziq hozir «Eyler to‘g‘ri chizig‘i» deb ataladi. Sharq olimlari ham bu nuqtalardan foydalanishgan: masalan, muntazam ko‘pburchaklarni aylanaga ichki chizish masalalari Abul Vafo Buzjoniy asarlarida batafsil yechilgan.', 'В 1765 году великий швейцарский математик <b>Леонард Эйлер</b> сделал удивительное открытие: центр описанной окружности, точка пересечения медиан и точка пересечения высот всегда лежат на одной прямой — «прямой Эйлера». Учёные Востока тоже использовали эти точки: например, задачи о вписывании правильных многоугольников в окружность подробно решены в трудах Абу-ль-Вафы аль-Бузджани.', 'In 1765 the great Swiss mathematician <b>Leonhard Euler</b> made an amazing discovery: the circumcentre, the centroid and the orthocentre always lie on one straight line, now called the “Euler line”. Eastern scholars used these points too: for example, Abu al-Wafa al-Buzjani solved in detail how to inscribe regular polygons in a circle.')
    ] },
    { kind: 'rule', h: L('Uchburchak uchun teoremalar', 'Теоремы для треугольника', 'Theorems for triangles'), list: [
      L('<b>1-teorema.</b> Har qanday uchburchakka bitta va faqat bitta aylana ichki chizish mumkin. Uning markazi — bissektrisalar kesishgan nuqta.', '<b>Теорема 1.</b> В любой треугольник можно вписать окружность, и притом только одну. Её центр — точка пересечения биссектрис.', '<b>Theorem 1.</b> Every triangle has exactly one inscribed circle. Its centre is where the angle bisectors meet.'),
      L('<b>2-teorema.</b> Har qanday uchburchakka bitta va faqat bitta aylana tashqi chizish mumkin. Uning markazi — tomonlarga o‘tkazilgan o‘rta perpendikulyarlar kesishgan nuqta.', '<b>Теорема 2.</b> Около любого треугольника можно описать окружность, и притом только одну. Её центр — точка пересечения серединных перпендикуляров к сторонам.', '<b>Theorem 2.</b> Every triangle has exactly one circumscribed circle. Its centre is where the perpendicular bisectors of the sides meet.'),
      L('<b>Radius formulalari:</b> r = S/p (p — yarim perimetr); to‘g‘ri burchakli uchburchakda R = c/2 va r = (a + b − c)/2.', '<b>Формулы радиусов:</b> r = S/p (p — полупериметр); в прямоугольном треугольнике R = c/2 и r = (a + b − c)/2.', '<b>Radius formulas:</b> r = S/p (p is the semi-perimeter); in a right triangle R = c/2 and r = (a + b − c)/2.')
    ], after: [
      L('<b>1-teorema isboti g‘oyasi.</b> A va B burchaklar bissektrisalari biror I nuqtada kesishadi. I nuqta A bissektrisasida yotgani uchun AB va AC tomonlardan teng uzoqlikda; B bissektrisasida yotgani uchun AB va BC dan teng uzoqlikda. Demak, I uchala tomondan teng uzoqlikda — bu masofa r. Shu sababli C burchak bissektrisasi ham I dan o‘tadi va I markazli r radiusli aylana uchala tomonga urinadi.', '<b>Идея доказательства теоремы 1.</b> Биссектрисы углов A и B пересекаются в точке I. Так как I на биссектрисе A, она равноудалена от AB и AC; так как на биссектрисе B — от AB и BC. Значит, I равноудалена от всех трёх сторон — это расстояние r. Поэтому биссектриса угла C тоже проходит через I, а окружность с центром I и радиусом r касается всех сторон.', '<b>Proof idea for Theorem 1.</b> The bisectors of angles A and B meet at a point I. Being on A’s bisector, I is equally far from AB and AC; being on B’s bisector, it is equally far from AB and BC. So I is equally far from all three sides — that distance is r. Hence C’s bisector also passes through I, and the circle with centre I and radius r touches all three sides.'),
      L('<b>r = S/p formulasi.</b> Uchburchakni I markaz orqali uchta uchburchakka bo‘lamiz: ularning balandliklari r, asoslari a, b, c. S = ar/2 + br/2 + cr/2 = r · p, demak r = S/p.', '<b>Формула r = S/p.</b> Разобьём треугольник через центр I на три треугольника с высотами r и основаниями a, b, c. S = ar/2 + br/2 + cr/2 = r · p, откуда r = S/p.', '<b>The formula r = S/p.</b> Split the triangle through I into three triangles with heights r and bases a, b, c. S = ar/2 + br/2 + cr/2 = r · p, so r = S/p.')
    ] },
    { kind: 'rule', h: L('To‘rtburchaklar uchun shartlar', 'Условия для четырёхугольников', 'Conditions for quadrilaterals'), p: [
      L('To‘rtburchakda vaziyat boshqacha: har qanday to‘rtburchakka aylana ichki yoki tashqi chizib bo‘lmaydi. Masalan, kvadratga ikkalasini ham chizish mumkin, rombga — faqat ichki, to‘g‘ri to‘rtburchakka — faqat tashqi aylana.', 'С четырёхугольниками иначе: не в каждый можно вписать и не около каждого можно описать окружность. Например, у квадрата есть обе, у ромба — только вписанная, у прямоугольника — только описанная.', 'Quadrilaterals are different: not every one has an incircle or a circumcircle. A square has both, a rhombus only an incircle, a rectangle only a circumcircle.')
    ], list: [
      L('<b>Tashqi aylana sharti:</b> to‘rtburchakka aylana tashqi chizish mumkin ⇔ uning qarama-qarshi burchaklari yig‘indisi 180°. (Bu ichki chizilgan burchak teoremasidan kelib chiqadi.)', '<b>Условие описанной окружности:</b> около четырёхугольника можно описать окружность ⇔ сумма его противоположных углов 180°. (Следует из теоремы о вписанном угле.)', '<b>Circumcircle condition:</b> a quadrilateral has a circumcircle ⇔ its opposite angles add to 180°. (This follows from the inscribed-angle theorem.)'),
      L('<b>Ichki aylana sharti:</b> to‘rtburchakka aylana ichki chizish mumkin ⇔ uning qarama-qarshi tomonlari yig‘indilari teng: a + c = b + d. (Bu urinma kesmalari tengligidan kelib chiqadi.)', '<b>Условие вписанной окружности:</b> в четырёхугольник можно вписать окружность ⇔ суммы его противоположных сторон равны: a + c = b + d. (Следует из равенства отрезков касательных.)', '<b>Incircle condition:</b> a quadrilateral has an incircle ⇔ its opposite sides have equal sums: a + c = b + d. (This follows from equal tangent lengths.)')
    ], after: [
      L('Shuning uchun teng yonli trapetsiyaga doimo tashqi aylana chizish mumkin, oddiy parallelogrammga esa (agar u to‘g‘ri to‘rtburchak bo‘lmasa) — mumkin emas.', 'Поэтому около равнобедренной трапеции всегда можно описать окружность, а около обычного параллелограмма (не прямоугольника) — нельзя.', 'That is why an isosceles trapezium always has a circumcircle, while an ordinary parallelogram (not a rectangle) does not.')
    ] },
    { kind: 'steps', h: L('Sirkul va chizg‘ich bilan yasash', 'Построение циркулем и линейкой', 'Constructing with compass and ruler'), list: [
      L('<b>Tashqi aylana.</b> 1) Ikki tomonning o‘rta perpendikulyarlarini yasang (har biri uchun kesma uchlaridan bir xil radiusli ikki yoy chizib, kesishish nuqtalarini tutashtiring). 2) Ular kesishgan O nuqta — markaz. 3) Sirkul ignasini O ga, qalamini istalgan uchga qo‘yib, aylana chizing — u qolgan ikki uchdan ham o‘tadi.', '<b>Описанная окружность.</b> 1) Постройте серединные перпендикуляры к двум сторонам (из концов отрезка проведите две дуги одного радиуса и соедините точки их пересечения). 2) Точка O их пересечения — центр. 3) Поставьте иглу циркуля в O, грифель — в любую вершину и проведите окружность: она пройдёт и через две другие.', '<b>Circumcircle.</b> 1) Construct the perpendicular bisectors of two sides (draw two equal arcs from each end of the segment and join their crossings). 2) Their meeting point O is the centre. 3) Put the compass point on O and the pencil on any vertex and draw — the circle passes through the other two vertices as well.'),
      L('<b>Ichki aylana.</b> 1) Ikki burchakning bissektrisalarini yasang. 2) Ular kesishgan I nuqta — markaz. 3) I dan istalgan tomonga perpendikulyar tushiring — uning uzunligi r. 4) I markazli, r radiusli aylana chizing.', '<b>Вписанная окружность.</b> 1) Постройте биссектрисы двух углов. 2) Точка I их пересечения — центр. 3) Опустите из I перпендикуляр на любую сторону — его длина r. 4) Проведите окружность с центром I и радиусом r.', '<b>Incircle.</b> 1) Construct the bisectors of two angles. 2) Their meeting point I is the centre. 3) Drop a perpendicular from I to any side — its length is r. 4) Draw the circle with centre I and radius r.')
    ], after: [
      L('Uchinchi bissektrisa yoki uchinchi o‘rta perpendikulyarni yasash shart emas — ular avtomatik ravishda topilgan nuqtadan o‘tadi. Ammo uni chizib, chizmangiz aniqligini tekshirish foydali.', 'Третью биссектрису или третий серединный перпендикуляр строить не обязательно — они сами пройдут через найденную точку. Но построить их полезно для проверки точности чертежа.', 'You do not need the third bisector or perpendicular bisector — it automatically passes through the point you found. Drawing it is a good check of your accuracy, though.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Katetlari 6 va 8 bo‘lgan to‘g‘ri burchakli uchburchakka ichki va tashqi chizilgan aylanalar radiuslarini toping.', 'Найдите радиусы вписанной и описанной окружностей прямоугольного треугольника с катетами 6 и 8.', 'Find the inradius and circumradius of a right triangle with legs 6 and 8.'), s: L('Gipotenuza c = 10. R = c/2 = <b>5</b>. r = (6 + 8 − 10)/2 = <b>2</b>. Tekshiruv: S = 24, p = 12, r = 24/12 = 2.', 'Гипотенуза c = 10. R = c/2 = <b>5</b>. r = (6 + 8 − 10)/2 = <b>2</b>. Проверка: S = 24, p = 12, r = 24/12 = 2.', 'Hypotenuse c = 10. R = c/2 = <b>5</b>. r = (6 + 8 − 10)/2 = <b>2</b>. Check: S = 24, p = 12, r = 24/12 = 2.') },
      { q: L('Tomonlari 13, 14, 15 bo‘lgan uchburchakka ichki chizilgan aylana radiusini toping.', 'Найдите радиус вписанной окружности треугольника 13, 14, 15.', 'Find the inradius of the 13, 14, 15 triangle.'), s: L('Geron formulasidan S = 84, p = 21. r = 84/21 = <b>4</b>.', 'По формуле Герона S = 84, p = 21. r = 84/21 = <b>4</b>.', 'Heron’s formula gives S = 84, p = 21. r = 84/21 = <b>4</b>.') },
      { q: L('Tomoni 6 bo‘lgan teng tomonli uchburchakda r va R ni toping.', 'Найдите r и R для равностороннего треугольника со стороной 6.', 'Find r and R for an equilateral triangle with side 6.'), s: L('Teng tomonli uchburchakda ikkala markaz ustma-ust tushadi va balandlikni 2 : 1 nisbatda bo‘ladi. h = 3√3. R = 2h/3 = <b>2√3 ≈ 3,46</b>, r = h/3 = <b>√3 ≈ 1,73</b>. R = 2r.', 'В равностороннем треугольнике оба центра совпадают и делят высоту в отношении 2 : 1. h = 3√3. R = 2h/3 = <b>2√3 ≈ 3,46</b>, r = h/3 = <b>√3 ≈ 1,73</b>. R = 2r.', 'In an equilateral triangle both centres coincide and divide the height 2 : 1. h = 3√3. R = 2h/3 = <b>2√3 ≈ 3.46</b>, r = h/3 = <b>√3 ≈ 1.73</b>. R = 2r.') },
      { q: L('To‘rtburchak burchaklari 70°, 95°, 110°, 85° (ketma-ket). Unga tashqi aylana chizish mumkinmi?', 'Углы четырёхугольника по порядку 70°, 95°, 110°, 85°. Можно ли описать около него окружность?', 'A quadrilateral has angles 70°, 95°, 110°, 85° in order. Does it have a circumcircle?'), s: L('Qarama-qarshi burchaklar: 70° + 110° = 180°, 95° + 85° = 180°. <b>Ha, mumkin.</b>', 'Противоположные углы: 70° + 110° = 180°, 95° + 85° = 180°. <b>Да, можно.</b>', 'Opposite angles: 70° + 110° = 180° and 95° + 85° = 180°. <b>Yes, it does.</b>') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Markazlarni chalkashtirish.</b> Ichki aylana markazi — <i>bissektrisalar</i>, tashqi aylana markazi — <i>o‘rta perpendikulyarlar</i> kesishmasi. Medianalar kesishmasi ikkalasi ham emas (teng tomonli uchburchakdan tashqari).', '<b>Путают центры.</b> Центр вписанной — пересечение <i>биссектрис</i>, описанной — <i>серединных перпендикуляров</i>. Точка пересечения медиан — ни то, ни другое (кроме равностороннего треугольника).', '<b>Mixing up the centres.</b> The incentre is where the <i>bisectors</i> meet; the circumcentre is where the <i>perpendicular bisectors</i> meet. The centroid is neither (except in an equilateral triangle).'),
      L('<b>r = S/p da perimetrni ishlatish.</b> Maxrajda yarim perimetr turadi; perimetr bilan javob ikki marta kichik chiqadi.', '<b>Берут периметр в r = S/p.</b> В знаменателе полупериметр; с периметром ответ выйдет вдвое меньше.', '<b>Using the perimeter in r = S/p.</b> The denominator is the semi-perimeter; with the perimeter the answer is halved.'),
      L('<b>Tashqi aylana markazi har doim ichkarida deb o‘ylash.</b> O‘tmas burchakli uchburchakda u tashqarida, to‘g‘ri burchaklida — gipotenuza o‘rtasida yotadi. Ichki aylana markazi esa doimo ichkarida.', '<b>Думают, что центр описанной всегда внутри.</b> У тупоугольного он снаружи, у прямоугольного — на середине гипотенузы. Центр вписанной — всегда внутри.', '<b>Thinking the circumcentre is always inside.</b> For an obtuse triangle it is outside; for a right triangle it is the midpoint of the hypotenuse. The incentre is always inside.'),
      L('<b>Har qanday to‘rtburchakka aylana chizish mumkin deb hisoblash.</b> Avval shartni tekshiring: burchaklar (tashqi uchun) yoki tomonlar (ichki uchun).', '<b>Считают, что окружность есть у любого четырёхугольника.</b> Сначала проверьте условие: углы (для описанной) или стороны (для вписанной).', '<b>Assuming every quadrilateral has such circles.</b> Check the condition first: angles (circumcircle) or sides (incircle).')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Quduq, minora, maktab.</b> Uch qishloq uchun umumiy quduq, uchta shahar uchun aloqa minorasi yoki uch mahalla uchun umumiy maktab qurishda ulardan teng uzoqlikdagi nuqta — tashqi aylana markazi izlanadi. Agar uchburchak o‘tmas burchakli bo‘lsa, bu nuqta uchburchakdan tashqarida chiqadi va muhandislar boshqa yechim izlashadi.', '<b>Колодец, вышка, школа.</b> Строя общий колодец для трёх сёл, вышку связи для трёх городов или школу для трёх махаллей, ищут точку, равноудалённую от них, — центр описанной окружности. Если треугольник тупоугольный, эта точка оказывается снаружи, и инженеры ищут другое решение.', '<b>Wells, towers, schools.</b> When placing a shared well for three villages, a phone mast for three towns or a school for three neighbourhoods, planners look for the point equally far from all three — the circumcentre. If the triangle is obtuse, that point lies outside it and engineers look for another solution.'),
      L('<b>Eng katta doira.</b> Uchburchak shaklidagi tunuka yoki fanera bo‘lagidan eng katta dumaloq detal kesib olish uchun ichki chizilgan aylanani topish kerak. Xuddi shunday, uchburchak maydonchadagi eng katta favvora yoki gulzor ham ichki aylana bo‘ladi.', '<b>Самый большой круг.</b> Чтобы вырезать из треугольного листа жести или фанеры самую большую круглую деталь, нужно найти вписанную окружность. Так же и самый большой фонтан или клумба на треугольной площадке — это вписанная окружность.', '<b>The largest disc.</b> To cut the biggest round piece from a triangular sheet of metal or plywood, find the inscribed circle. Likewise the largest fountain or flower bed on a triangular plot is the incircle.'),
      L('<b>GPS va zilzilalar.</b> Seysmologlar uchta stansiyadagi signallar vaqtidan zilzila markazini aniqlashadi: har bir stansiya atrofida aylana chiziladi va ular kesishgan joy — markaz. GPS ham shunga o‘xshash g‘oyaga asoslangan.', '<b>GPS и землетрясения.</b> Сейсмологи по времени сигналов на трёх станциях находят эпицентр: вокруг каждой станции рисуют окружность, и точка их пересечения — эпицентр. GPS основан на похожей идее.', '<b>GPS and earthquakes.</b> Seismologists locate an epicentre from signal times at three stations: a circle is drawn around each station and their meeting point is the epicentre. GPS uses a similar idea.')
    ] },
    { kind: 'table', h: L('Taqqoslash jadvali', 'Сравнительная таблица', 'Comparison table'), table: { head: [L('Xossa', 'Свойство', 'Property'), L('Ichki aylana', 'Вписанная', 'Incircle'), L('Tashqi aylana', 'Описанная', 'Circumcircle')], rows: [
      [L('Nimaga tegadi', 'Чего касается', 'Touches / passes'), L('uchala tomonga urinadi', 'касается всех сторон', 'touches all sides'), L('uchala uchdan o‘tadi', 'проходит через все вершины', 'passes through all vertices')],
      [L('Markazi', 'Центр', 'Centre'), L('bissektrisalar kesishmasi', 'пересечение биссектрис', 'angle bisectors meet'), L('o‘rta perpendikulyarlar kesishmasi', 'пересечение серединных перпендикуляров', 'perpendicular bisectors meet')],
      [L('Markaz joyi', 'Положение центра', 'Where the centre is'), L('doimo ichkarida', 'всегда внутри', 'always inside'), L('ichkarida, gipotenuzada yoki tashqarida', 'внутри, на гипотенузе или снаружи', 'inside, on the hypotenuse or outside')],
      [L('Radius', 'Радиус', 'Radius'), L('r = S/p', 'r = S/p', 'r = S/p'), L('to‘g‘ri burchaklida R = c/2', 'в прямоугольном R = c/2', 'right triangle: R = c/2')],
      [L('To‘rtburchak sharti', 'Условие для четырёхугольника', 'Quadrilateral condition'), L('a + c = b + d', 'a + c = b + d', 'a + c = b + d'), L('∠A + ∠C = 180°', '∠A + ∠C = 180°', '∠A + ∠C = 180°')]
    ] } },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('To‘g‘ri burchakli uchburchak: 5, 12, 13. R va r?', 'Прямоугольный треугольник 5, 12, 13. R и r?', 'Right triangle 5, 12, 13. R and r?'), s: L('R = 13/2 = <b>6,5</b>; r = (5 + 12 − 13)/2 = <b>2</b>.', 'R = 13/2 = <b>6,5</b>; r = (5 + 12 − 13)/2 = <b>2</b>.', 'R = 13/2 = <b>6.5</b>; r = (5 + 12 − 13)/2 = <b>2</b>.') },
      { q: L('Tomonlari 5, 7, 9, 7 (ketma-ket) bo‘lgan to‘rtburchakka aylana ichki chizish mumkinmi?', 'Можно ли вписать окружность в четырёхугольник со сторонами 5, 7, 9, 7 (по порядку)?', 'Can a circle be inscribed in a quadrilateral with sides 5, 7, 9, 7 in order?'), s: L('5 + 9 = 14 = 7 + 7. <b>Ha.</b>', '5 + 9 = 14 = 7 + 7. <b>Да.</b>', '5 + 9 = 14 = 7 + 7. <b>Yes.</b>') },
      { q: L('S = 60, p = 15. r = ?', 'S = 60, p = 15. r = ?', 'S = 60, p = 15. r = ?'), s: L('r = 60/15 = <b>4</b>.', 'r = 60/15 = <b>4</b>.', 'r = 60/15 = <b>4</b>.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Ichki aylana tomonlarga urinadi, markazi — bissektrisalar kesishmasi, r = S/p.', 'Вписанная окружность касается сторон, центр — пересечение биссектрис, r = S/p.', 'The incircle touches the sides; its centre is where the bisectors meet; r = S/p.'),
      L('Tashqi aylana uchlardan o‘tadi, markazi — o‘rta perpendikulyarlar kesishmasi.', 'Описанная окружность проходит через вершины, центр — пересечение серединных перпендикуляров.', 'The circumcircle passes through the vertices; its centre is where the perpendicular bisectors meet.'),
      L('Har qanday uchburchakda ikkala aylana mavjud va yagona.', 'У любого треугольника обе окружности существуют и единственны.', 'Every triangle has exactly one of each.'),
      L('To‘g‘ri burchakli uchburchakda R = c/2, r = (a + b − c)/2.', 'В прямоугольном треугольнике R = c/2, r = (a + b − c)/2.', 'In a right triangle R = c/2 and r = (a + b − c)/2.'),
      L('To‘rtburchak: tashqi aylana — qarama-qarshi burchaklar yig‘indisi 180°; ichki aylana — qarama-qarshi tomonlar yig‘indilari teng.', 'Четырёхугольник: описанная — сумма противоположных углов 180°; вписанная — суммы противоположных сторон равны.', 'Quadrilaterals: circumcircle — opposite angles add to 180°; incircle — opposite sides have equal sums.')
    ] }
  ] });

  // ---------- t18. Vektor tushunchasi. Qo‘shish, ayirish, songa ko‘paytirish ----------
  T.add(P, 't18', { sections: [
    { kind: 'intro', h: L('Qayerga va qancha?', 'Куда и сколько?', 'Where to and how far?'), p: [
      L('Do‘stingiz telefonda: «Maktabdan 300 metr yur», — dedi. Siz uni topa olasizmi? Yo‘q! Qaysi tomonga yurish kerakligi aytilmadi. Agar «maktabdan 300 metr shimolga yur» desa — boshqa gap. Demak, ba’zi kattaliklar uchun faqat son yetarli emas, <b>yo‘nalish</b> ham kerak. Bunday kattaliklar <b>vektorlar</b> bilan ifodalanadi.', 'Друг говорит по телефону: «Пройди 300 метров от школы». Найдёте ли вы его? Нет! Не сказано, в какую сторону. А если «300 метров от школы на север» — другое дело. Значит, для некоторых величин одного числа мало, нужно ещё и <b>направление</b>. Такие величины описываются <b>векторами</b>.', 'A friend on the phone says: “Walk 300 metres from the school.” Can you find them? No! You were not told which way. “Walk 300 metres north from the school” is different. So for some quantities a number is not enough — you also need a <b>direction</b>. Such quantities are described by <b>vectors</b>.'),
      L('Tezlik, kuch, siljish, shamol — bularning barchasi vektor kattaliklar. Massa, harorat, vaqt esa faqat son bilan beriladi, ular <b>skalyar</b> kattaliklar. Bu mavzuda vektor nima ekanini, vektorlarni qanday qo‘shish, ayirish va songa ko‘paytirish mumkinligini o‘rganamiz. Vektorlar fizika, kompyuter grafikasi, robototexnika va navigatsiyaning asosiy tilidir.', 'Скорость, сила, перемещение, ветер — всё это векторные величины. Масса, температура, время задаются только числом — это <b>скалярные</b> величины. В этой теме узнаем, что такое вектор и как векторы складывать, вычитать и умножать на число. Векторы — основной язык физики, компьютерной графики, робототехники и навигации.', 'Velocity, force, displacement and wind are all vector quantities. Mass, temperature and time are given by a number alone — they are <b>scalars</b>. In this topic we learn what a vector is and how to add, subtract and scale vectors. Vectors are the basic language of physics, computer graphics, robotics and navigation.')
    ] },
    { kind: 'def', h: L('Vektor va unga oid tushunchalar', 'Вектор и связанные понятия', 'Vectors and related ideas'), list: [
      L('<b>Vektor</b> — yo‘nalgan kesma, ya’ni qaysi uchi boshi, qaysi biri oxiri ekani ko‘rsatilgan kesma. Boshi A, oxiri B bo‘lsa, AB→ deb yoziladi; bitta harf bilan a→ ham belgilanadi. Chizmada oxiriga strelka qo‘yiladi.', '<b>Вектор</b> — направленный отрезок, т.е. отрезок, у которого указано, какой конец начало, а какой конец. С началом A и концом B пишут AB→; также обозначают одной буквой a→. На чертеже на конце ставят стрелку.', 'A <b>vector</b> is a directed segment — one end is marked as the start and the other as the end. With start A and end B we write AB→; a single letter a→ is also used. In drawings an arrowhead marks the end.'),
      L('<b>Vektor uzunligi (moduli)</b> — kesma uzunligi: |AB→| yoki |a→|.', '<b>Длина (модуль) вектора</b> — длина отрезка: |AB→| или |a→|.', 'The <b>length (magnitude)</b> of a vector is the segment’s length: |AB→| or |a→|.'),
      L('<b>Nol vektor</b> 0→ — boshi va oxiri ustma-ust tushgan vektor; uzunligi 0, yo‘nalishi aniqlanmagan.', '<b>Нулевой вектор</b> 0→ — вектор, у которого начало и конец совпадают; длина 0, направление не определено.', 'The <b>zero vector</b> 0→ has the same start and end; its length is 0 and it has no definite direction.'),
      L('<b>Kollinear vektorlar</b> — bir to‘g‘ri chiziqda yoki parallel to‘g‘ri chiziqlarda yotuvchi vektorlar. Ular bir xil yo‘nalgan (↑↑) yoki qarama-qarshi yo‘nalgan (↑↓) bo‘lishi mumkin.', '<b>Коллинеарные векторы</b> — лежащие на одной прямой или на параллельных прямых. Они могут быть сонаправленными (↑↑) или противоположно направленными (↑↓).', '<b>Collinear vectors</b> lie on one line or on parallel lines. They can point the same way (↑↑) or opposite ways (↑↓).'),
      L('<b>Teng vektorlar</b> — bir xil yo‘nalgan va uzunliklari teng vektorlar. Vektorni parallel ko‘chirsak, u o‘ziga teng qoladi — shuning uchun vektorni istalgan nuqtadan boshlab chizish mumkin.', '<b>Равные векторы</b> — сонаправленные векторы одинаковой длины. При параллельном переносе вектор остаётся равным себе, поэтому его можно откладывать от любой точки.', '<b>Equal vectors</b> point the same way and have the same length. Sliding a vector parallel to itself does not change it, so a vector can be drawn starting from any point.'),
      L('<b>Qarama-qarshi vektor</b> −a→ — uzunligi a→ ga teng, lekin teskari yo‘nalgan vektor. Masalan, BA→ = −AB→.', '<b>Противоположный вектор</b> −a→ — вектор той же длины, но противоположного направления. Например, BA→ = −AB→.', 'The <b>opposite vector</b> −a→ has the same length as a→ but points the other way. For example, BA→ = −AB→.')
    ] },
    { kind: 'history', h: L('Stevindan Gamiltongacha', 'От Стевина до Гамильтона', 'From Stevin to Hamilton'), p: [
      L('Kuchlarni qo‘shish g‘oyasi juda qadimiy, lekin uni aniq qoidaga aylantirgan kishi gollandiyalik muhandis <b>Simon Stevin</b> (1548–1620) bo‘ldi. U qiya tekislikdagi yuklar muvozanatini o‘rganib, ikki kuch ta’sirini bitta kuch bilan almashtirish mumkinligini va bu kuch ikki kuchga qurilgan parallelogramm diagonali bo‘ylab yo‘nalganini ko‘rsatdi. Bu <b>«kuchlar parallelogrammi»</b> qoidasi edi. Stevin o‘nli kasrlarni Yevropada ommalashtirgan olim sifatida ham mashhur.', 'Идея сложения сил очень древняя, но превратил её в точное правило голландский инженер <b>Симон Стевин</b> (1548–1620). Изучая равновесие грузов на наклонной плоскости, он показал, что действие двух сил можно заменить одной силой, направленной по диагонали параллелограмма, построенного на этих силах. Это было правило <b>«параллелограмма сил»</b>. Стевин известен и тем, что ввёл в Европе десятичные дроби.', 'The idea of adding forces is ancient, but the Dutch engineer <b>Simon Stevin</b> (1548–1620) turned it into a precise rule. Studying the balance of loads on an inclined plane, he showed that two forces can be replaced by a single force along the diagonal of the parallelogram built on them — the <b>“parallelogram of forces”</b>. Stevin is also famous for popularising decimal fractions in Europe.'),
      L('«Vektor» so‘zini esa 1840-yillarda irlandiyalik matematik <b>Uilyam Gamilton</b> kiritgan; lotinchada «vector» — «tashuvchi» degani. Deyarli bir vaqtda nemis maktab o‘qituvchisi <b>German Grassman</b> vektorlar ustida amallarning umumiy nazariyasini yaratdi, lekin uning kitobi o‘z davrida tushunilmay qoldi. XIX asr oxirida amerikalik Gibbs va ingliz Xevisayd vektorlarni hozirgi qulay ko‘rinishga keltirishdi va ular fizikaning asosiy quroliga aylandi.', 'Слово «вектор» ввёл в 1840-х годах ирландский математик <b>Уильям Гамильтон</b>; по-латыни «vector» — «несущий». Почти одновременно немецкий школьный учитель <b>Герман Грассман</b> создал общую теорию действий над векторами, но его книгу в то время не поняли. В конце XIX века американец Гиббс и англичанин Хевисайд придали векторам нынешний удобный вид, и они стали главным инструментом физики.', 'The word “vector” was introduced in the 1840s by the Irish mathematician <b>William Hamilton</b>; in Latin “vector” means “carrier”. At almost the same time the German schoolteacher <b>Hermann Grassmann</b> built a general theory of operations on vectors, but his book was not understood in his day. Late in the 19th century the American Gibbs and the Englishman Heaviside gave vectors their convenient modern form, and they became a central tool of physics.')
    ] },
    { kind: 'rule', h: L('Vektorlarni qo‘shish', 'Сложение векторов', 'Adding vectors'), list: [
      L('<b>Uchburchak qoidasi.</b> a→ vektor oxiridan b→ vektorni qo‘yamiz. Birinchi vektor boshidan ikkinchisining oxirigacha bo‘lgan vektor — yig‘indi: <b>AB→ + BC→ = AC→</b>.', '<b>Правило треугольника.</b> От конца вектора a→ откладываем вектор b→. Вектор от начала первого до конца второго — сумма: <b>AB→ + BC→ = AC→</b>.', '<b>Triangle rule.</b> Place b→ starting at the end of a→. The vector from the start of the first to the end of the second is the sum: <b>AB→ + BC→ = AC→</b>.'),
      L('<b>Parallelogramm qoidasi.</b> a→ va b→ ni bitta A nuqtadan qo‘yamiz va ularga parallelogramm quramiz. A dan chiquvchi diagonal — yig‘indi. Bu Stevinning kuchlar qoidasi.', '<b>Правило параллелограмма.</b> Откладываем a→ и b→ от одной точки A и строим на них параллелограмм. Диагональ из A — сумма. Это правило сил Стевина.', '<b>Parallelogram rule.</b> Draw a→ and b→ from the same point A and complete the parallelogram. The diagonal from A is the sum. This is Stevin’s rule of forces.'),
      L('<b>Ko‘pburchak qoidasi.</b> Bir nechta vektorni ketma-ket «zanjir» qilib qo‘ysak, yig‘indi birinchisining boshidan oxirgisining oxirigacha: AB→ + BC→ + CD→ = AD→.', '<b>Правило многоугольника.</b> Если откладывать векторы один за другим «цепочкой», сумма идёт от начала первого до конца последнего: AB→ + BC→ + CD→ = AD→.', '<b>Polygon rule.</b> Chain several vectors end to start; the sum runs from the start of the first to the end of the last: AB→ + BC→ + CD→ = AD→.')
    ], after: [
      L('Qo‘shish xossalari sonlardagi kabi: a→ + b→ = b→ + a→ (o‘rin almashtirish), (a→ + b→) + c→ = a→ + (b→ + c→) (guruhlash), a→ + 0→ = a→, a→ + (−a→) = 0→. Agar zanjir yopilsa (oxiri boshiga qaytsa), yig‘indi nol vektor bo‘ladi.', 'Свойства сложения такие же, как у чисел: a→ + b→ = b→ + a→ (переместительное), (a→ + b→) + c→ = a→ + (b→ + c→) (сочетательное), a→ + 0→ = a→, a→ + (−a→) = 0→. Если цепочка замкнулась (конец вернулся в начало), сумма — нулевой вектор.', 'Addition behaves like numbers: a→ + b→ = b→ + a→ (commutative), (a→ + b→) + c→ = a→ + (b→ + c→) (associative), a→ + 0→ = a→, a→ + (−a→) = 0→. If the chain closes up (the end returns to the start), the sum is the zero vector.')
    ] },
    { kind: 'rule', h: L('Ayirish va songa ko‘paytirish', 'Вычитание и умножение на число', 'Subtracting and scaling'), list: [
      L('<b>Ayirish.</b> a→ − b→ — shunday vektorki, unga b→ ni qo‘shsak, a→ hosil bo‘ladi. Amalda: a→ − b→ = a→ + (−b→). Ikkala vektorni bitta nuqtadan qo‘ysak, ayirma b→ ning oxiridan a→ ning oxiriga yo‘nalgan: <b>OA→ − OB→ = BA→</b>.', '<b>Вычитание.</b> a→ − b→ — вектор, который в сумме с b→ даёт a→. На практике: a→ − b→ = a→ + (−b→). Если отложить оба вектора от одной точки, разность направлена от конца b→ к концу a→: <b>OA→ − OB→ = BA→</b>.', '<b>Subtraction.</b> a→ − b→ is the vector that gives a→ when added to b→. In practice a→ − b→ = a→ + (−b→). Drawn from one point, the difference runs from the end of b→ to the end of a→: <b>OA→ − OB→ = BA→</b>.'),
      L('<b>Songa ko‘paytirish.</b> k · a→ vektor a→ ga kollinear, uzunligi |k| · |a→|. k &gt; 0 bo‘lsa yo‘nalishi a→ bilan bir xil, k &lt; 0 bo‘lsa — teskari. k = 0 da nol vektor hosil bo‘ladi.', '<b>Умножение на число.</b> Вектор k · a→ коллинеарен a→, его длина |k| · |a→|. При k &gt; 0 он сонаправлен с a→, при k &lt; 0 — противоположно направлен. При k = 0 получается нулевой вектор.', '<b>Scaling.</b> k · a→ is collinear with a→ and has length |k| · |a→|. For k &gt; 0 it points the same way as a→; for k &lt; 0 the opposite way. k = 0 gives the zero vector.'),
      L('<b>Xossalar:</b> k(a→ + b→) = ka→ + kb→; (k + m)a→ = ka→ + ma→; k(ma→) = (km)a→.', '<b>Свойства:</b> k(a→ + b→) = ka→ + kb→; (k + m)a→ = ka→ + ma→; k(ma→) = (km)a→.', '<b>Properties:</b> k(a→ + b→) = ka→ + kb→; (k + m)a→ = ka→ + ma→; k(ma→) = (km)a→.')
    ], after: [
      L('Muhim natija: ikki nol bo‘lmagan vektor kollinear bo‘lishi uchun ulardan biri ikkinchisining biror songa ko‘paytmasi bo‘lishi zarur va yetarli: b→ = k · a→.', 'Важное следствие: два ненулевых вектора коллинеарны тогда и только тогда, когда один равен другому, умноженному на число: b→ = k · a→.', 'Key fact: two non-zero vectors are collinear exactly when one is a number times the other: b→ = k · a→.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Soddalashtiring: AB→ + BC→ + CD→ + DA→.', 'Упростите: AB→ + BC→ + CD→ + DA→.', 'Simplify: AB→ + BC→ + CD→ + DA→.'), s: L('Zanjir A dan boshlanib yana A da tugaydi: yig‘indi AA→ = <b>0→</b>.', 'Цепочка начинается в A и заканчивается в A: сумма AA→ = <b>0→</b>.', 'The chain starts at A and ends at A: the sum is AA→ = <b>0→</b>.') },
      { q: L('ABCD parallelogramm. AB→ + AD→ va AB→ − AD→ ni toping.', 'ABCD — параллелограмм. Найдите AB→ + AD→ и AB→ − AD→.', 'ABCD is a parallelogram. Find AB→ + AD→ and AB→ − AD→.'), s: L('Parallelogramm qoidasi: AB→ + AD→ = <b>AC→</b>. Ayirma: bitta A nuqtadan chiqqan vektorlar, ayirma D dan B ga yo‘nalgan: AB→ − AD→ = <b>DB→</b>. Ya’ni yig‘indi va ayirma — parallelogramm diagonallari.', 'Правило параллелограмма: AB→ + AD→ = <b>AC→</b>. Разность векторов из одной точки A направлена от D к B: AB→ − AD→ = <b>DB→</b>. То есть сумма и разность — диагонали параллелограмма.', 'Parallelogram rule: AB→ + AD→ = <b>AC→</b>. For vectors from A, the difference runs from D to B: AB→ − AD→ = <b>DB→</b>. So the sum and the difference are the diagonals.') },
      { q: L('|a→| = 5. −3a→ vektorning uzunligi va yo‘nalishi qanday?', '|a→| = 5. Какова длина и направление вектора −3a→?', '|a→| = 5. What are the length and direction of −3a→?'), s: L('|−3a→| = 3 · 5 = <b>15</b>; k = −3 &lt; 0, shuning uchun yo‘nalishi a→ ga <b>teskari</b>.', '|−3a→| = 3 · 5 = <b>15</b>; k = −3 &lt; 0, поэтому направление <b>противоположно</b> a→.', '|−3a→| = 3 · 5 = <b>15</b>; since k = −3 &lt; 0 it points <b>opposite</b> to a→.') },
      { q: L('Qayiq daryoni 4 m/s tezlik bilan oqimga perpendikulyar kesib o‘tmoqda, oqim tezligi 3 m/s. Qayiqning qirg‘oqqa nisbatan tezligi qancha?', 'Лодка пересекает реку со скоростью 4 м/с перпендикулярно течению, скорость течения 3 м/с. Какова скорость лодки относительно берега?', 'A boat crosses a river at 4 m/s perpendicular to the current, which flows at 3 m/s. What is the boat’s speed relative to the bank?'), s: L('Tezlik vektorlari qo‘shiladi; ular perpendikulyar, shuning uchun yig‘indi uzunligi √(4<sup>2</sup> + 3<sup>2</sup>) = <b>5 m/s</b>. Qayiq qiya yo‘nalishda harakatlanadi.', 'Векторы скоростей складываются; они перпендикулярны, поэтому длина суммы √(4<sup>2</sup> + 3<sup>2</sup>) = <b>5 м/с</b>. Лодка движется наискосок.', 'The velocity vectors add; they are perpendicular, so the sum has length √(4<sup>2</sup> + 3<sup>2</sup>) = <b>5 m/s</b>. The boat moves diagonally.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Uzunliklarni qo‘shish.</b> |a→ + b→| odatda |a→| + |b→| ga teng emas! 3 va 4 uzunlikdagi perpendikulyar vektorlar yig‘indisi uzunligi 5, 7 emas. Tenglik faqat vektorlar bir xil yo‘nalganda bo‘ladi.', '<b>Складывают длины.</b> |a→ + b→| обычно не равно |a→| + |b→|! Сумма перпендикулярных векторов длиной 3 и 4 имеет длину 5, а не 7. Равенство — только для сонаправленных векторов.', '<b>Adding lengths.</b> |a→ + b→| is usually not |a→| + |b→|! Perpendicular vectors of length 3 and 4 add to length 5, not 7. Equality holds only when they point the same way.'),
      L('<b>Harflar tartibini e’tiborsiz qoldirish.</b> AB→ va BA→ — turli vektorlar: BA→ = −AB→.', '<b>Не следят за порядком букв.</b> AB→ и BA→ — разные векторы: BA→ = −AB→.', '<b>Ignoring letter order.</b> AB→ and BA→ are different vectors: BA→ = −AB→.'),
      L('<b>Uchburchak qoidasini noto‘g‘ri qo‘llash.</b> AB→ + CD→ ni darhol AD→ deb yozib bo‘lmaydi — avval ikkinchi vektor birinchisining oxiridan boshlanishi kerak.', '<b>Неверно применяют правило треугольника.</b> AB→ + CD→ нельзя сразу записать как AD→ — второй вектор должен начинаться в конце первого.', '<b>Misusing the triangle rule.</b> AB→ + CD→ is not simply AD→ — the second vector must start where the first ends.'),
      L('<b>Ayirma yo‘nalishini adashtirish.</b> OA→ − OB→ = BA→ (B dan A ga), AB→ emas. Eslab qoling: «kamayuvchining oxiriga qarab».', '<b>Путают направление разности.</b> OA→ − OB→ = BA→ (от B к A), а не AB→. Запомните: «к концу уменьшаемого».', '<b>Getting the difference backwards.</b> OA→ − OB→ = BA→ (from B to A), not AB→. Remember: “towards the end of the first vector”.')
    ] },
    { kind: 'life', h: L('Hayotda vektorlar', 'Векторы в жизни', 'Vectors in real life'), p: [
      L('<b>Samolyot va shamol.</b> Uchuvchi samolyot tezligi vektoriga shamol tezligi vektorini qo‘shadi. Agar shamol yon tomondan essa, samolyot burnini biroz shamolga qarab burish kerak, aks holda u mo‘ljaldan chetga chiqib ketadi. Bu — vektorlarni qo‘shishning eng aniq misoli.', '<b>Самолёт и ветер.</b> Пилот складывает вектор скорости самолёта с вектором ветра. Если ветер боковой, нос самолёта приходится немного разворачивать навстречу ветру, иначе он отклонится от курса. Это нагляднейший пример сложения векторов.', '<b>Planes and wind.</b> A pilot adds the wind’s velocity vector to the plane’s. With a crosswind the nose has to be turned slightly into the wind, or the plane drifts off course. This is the clearest example of adding vectors.'),
      L('<b>Kuchlar.</b> Ikki kishi qayiqni qirg‘oqqa ikki arqon bilan tortsa, natijaviy kuch Stevin parallelogrammi diagonali bo‘ylab yo‘naladi. Ko‘prik va minoralarni loyihalashda muhandislar har bir tirgakka ta’sir qiluvchi kuchlar vektorlarini qo‘shib, ular muvozanatda (yig‘indi nol) ekanini tekshirishadi.', '<b>Силы.</b> Если двое тянут лодку к берегу двумя верёвками, равнодействующая направлена по диагонали параллелограмма Стевина. Проектируя мосты и башни, инженеры складывают векторы сил на каждую опору и проверяют равновесие (сумма равна нулю).', '<b>Forces.</b> When two people pull a boat ashore with two ropes, the resultant force runs along the diagonal of Stevin’s parallelogram. Designing bridges and towers, engineers add the force vectors on each support and check that they balance (sum to zero).'),
      L('<b>O‘yinlar va animatsiya.</b> Kompyuter o‘yinida qahramonning har bir qadami — siljish vektori. Tezlikni 2 ga ko‘paytirsak, qahramon ikki barobar tez yuguradi; −1 ga ko‘paytirsak — orqaga qaytadi.', '<b>Игры и анимация.</b> В компьютерной игре каждый шаг героя — вектор перемещения. Умножив скорость на 2, герой побежит вдвое быстрее; на −1 — повернёт назад.', '<b>Games and animation.</b> In a video game each step of a character is a displacement vector. Multiply the velocity by 2 and the hero runs twice as fast; by −1 and they turn back.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Stevin o‘z kashfiyotini qiya tekislikdagi yopiq marjon zanjiri tasviri bilan isbotlagan va bu rasmni shunchalik yaxshi ko‘rganki, uni kitobining muqovasiga qo‘ygan.', 'Стевин доказал своё открытие рисунком замкнутой цепочки бус на наклонной плоскости и так им гордился, что поместил его на обложку своей книги.', 'Stevin proved his discovery with a picture of a closed chain of beads on an inclined plane, and was so proud of it that he put it on the cover of his book.'),
      L('Gamilton 1843-yilda Dublindagi ko‘prik ustida yangi sonlar — kvaternionlar formulasini topganida, uni ko‘prik toshiga o‘yib yozgan. Bugun u yerda yodgorlik lavhasi bor.', 'В 1843 году Гамильтон, найдя на мосту в Дублине формулу новых чисел — кватернионов, вырезал её на камне моста. Сегодня там висит памятная доска.', 'In 1843, when Hamilton found the formula for a new kind of number — quaternions — on a Dublin bridge, he carved it into the stone. A plaque marks the spot today.'),
      L('Telefoningizdagi akselerometr har soniyada yuzlab marta tezlanish vektorini o‘lchaydi — ekran shuning uchun burilganda aylanadi.', 'Акселерометр в телефоне сотни раз в секунду измеряет вектор ускорения — поэтому экран поворачивается вслед за телефоном.', 'The accelerometer in your phone measures the acceleration vector hundreds of times a second — that is how the screen knows to rotate.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('AB→ + BC→ − AC→ = ?', 'AB→ + BC→ − AC→ = ?', 'AB→ + BC→ − AC→ = ?'), s: L('AB→ + BC→ = AC→, AC→ − AC→ = <b>0→</b>.', 'AB→ + BC→ = AC→, AC→ − AC→ = <b>0→</b>.', 'AB→ + BC→ = AC→, and AC→ − AC→ = <b>0→</b>.') },
      { q: L('|a→| = 2. |4a→| = ?', '|a→| = 2. |4a→| = ?', '|a→| = 2. |4a→| = ?'), s: L('4 · 2 = <b>8</b>.', '4 · 2 = <b>8</b>.', '4 · 2 = <b>8</b>.') },
      { q: L('Odam 6 km sharqqa, so‘ng 8 km shimolga yurdi. Siljish vektori uzunligi?', 'Человек прошёл 6 км на восток, затем 8 км на север. Длина вектора перемещения?', 'A person walks 6 km east, then 8 km north. Length of the displacement?'), s: L('√(36 + 64) = <b>10 km</b> (yo‘l 14 km bo‘lsa ham).', '√(36 + 64) = <b>10 км</b> (хотя путь 14 км).', '√(36 + 64) = <b>10 km</b> (even though the path was 14 km).') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Vektor — yo‘nalgan kesma; uning uzunligi va yo‘nalishi bor.', 'Вектор — направленный отрезок с длиной и направлением.', 'A vector is a directed segment with a length and a direction.'),
      L('Teng vektorlar: bir xil yo‘nalish va uzunlik; −a→ — teskari vektor.', 'Равные векторы: одинаковые направление и длина; −a→ — противоположный вектор.', 'Equal vectors share direction and length; −a→ is the opposite vector.'),
      L('Qo‘shish: uchburchak qoidasi AB→ + BC→ = AC→ yoki parallelogramm qoidasi.', 'Сложение: правило треугольника AB→ + BC→ = AC→ или параллелограмма.', 'Addition: triangle rule AB→ + BC→ = AC→ or the parallelogram rule.'),
      L('Ayirish: a→ − b→ = a→ + (−b→); OA→ − OB→ = BA→.', 'Вычитание: a→ − b→ = a→ + (−b→); OA→ − OB→ = BA→.', 'Subtraction: a→ − b→ = a→ + (−b→); OA→ − OB→ = BA→.'),
      L('k · a→: uzunlik |k| marta o‘zgaradi, k &lt; 0 da yo‘nalish teskari.', 'k · a→: длина меняется в |k| раз, при k &lt; 0 направление противоположное.', 'k · a→: the length is multiplied by |k|; for k &lt; 0 the direction flips.'),
      L('Stevin kuchlar parallelogrammini, Gamilton «vektor» so‘zini, Grassman vektor amallari nazariyasini berdi.', 'Стевин дал параллелограмм сил, Гамильтон — слово «вектор», Грассман — теорию действий над векторами.', 'Stevin gave the parallelogram of forces, Hamilton the word “vector”, Grassmann the theory of vector operations.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-2';

  // ---------- t19. Vektorning koordinatalari va ular ustida amallar ----------
  T.add(P, 't19', { sections: [
    { kind: 'intro', h: L('Rasm o‘rniga sonlar', 'Числа вместо рисунков', 'Numbers instead of pictures'), p: [
      L('Oldingi mavzuda vektorlarni chizma yordamida qo‘shdik: strelkalarni ketma-ket qo‘yib, parallelogramm chizdik. Bu usul ko‘rgazmali, lekin aniq emas — chizg‘ich bilan millimetrlarni o‘lchash xatoga olib keladi. Kompyuter esa umuman rasm chiza olmaydi, u faqat sonlar bilan ishlaydi. Qanday qilib vektorni sonlar bilan yozish mumkin?', 'В прошлой теме мы складывали векторы на чертеже: ставили стрелки друг за другом, строили параллелограмм. Это наглядно, но неточно — измерение миллиметров линейкой даёт ошибки. А компьютер вообще не умеет рисовать, он работает только с числами. Как же записать вектор числами?', 'In the last topic we added vectors by drawing: placing arrows end to end and building parallelograms. It is visual but not precise — measuring millimetres with a ruler leads to errors. A computer cannot draw at all; it works only with numbers. So how can a vector be written as numbers?'),
      L('Javob — <b>koordinatalar</b>. Koordinata tekisligida har bir vektorni ikki son bilan ifodalash mumkin: u o‘ngga (yoki chapga) qancha va yuqoriga (yoki pastga) qancha siljiydi. Shundan keyin vektorlar ustidagi barcha amallar oddiy arifmetikaga aylanadi. Bu mavzuda koordinatalarni topishni, ular orqali uzunlikni hisoblashni va qo‘shish, ayirish, songa ko‘paytirishni bajarishni o‘rganamiz.', 'Ответ — <b>координаты</b>. На координатной плоскости каждый вектор можно задать двумя числами: насколько он смещается вправо (или влево) и насколько вверх (или вниз). Тогда все действия над векторами превращаются в простую арифметику. В этой теме научимся находить координаты, вычислять по ним длину и выполнять сложение, вычитание и умножение на число.', 'The answer is <b>coordinates</b>. On the coordinate plane every vector can be given by two numbers: how far it moves right (or left) and how far up (or down). Then all vector operations become simple arithmetic. In this topic we learn to find coordinates, compute lengths from them, and add, subtract and scale vectors.')
    ] },
    { kind: 'def', h: L('Vektor koordinatalari', 'Координаты вектора', 'Vector coordinates'), p: [
      L('Koordinata tekisligida Ox o‘qi bo‘ylab yo‘nalgan, uzunligi 1 bo‘lgan i→ vektorni va Oy o‘qi bo‘ylab yo‘nalgan, uzunligi 1 bo‘lgan j→ vektorni olamiz. Ular <b>birlik (koordinata) vektorlari</b> deyiladi. Har qanday a→ vektorni yagona usulda a→ = x · i→ + y · j→ ko‘rinishda yozish mumkin. x va y sonlari a→ vektorning <b>koordinatalari</b> deyiladi va a→(x; y) yoki a→ = (x; y) deb yoziladi.', 'На координатной плоскости возьмём вектор i→ длины 1 вдоль оси Ox и вектор j→ длины 1 вдоль оси Oy. Они называются <b>единичными (координатными) векторами</b>. Любой вектор a→ единственным образом записывается как a→ = x · i→ + y · j→. Числа x и y называются <b>координатами</b> вектора и пишутся так: a→(x; y) или a→ = (x; y).', 'On the coordinate plane take the vector i→ of length 1 along the Ox axis and j→ of length 1 along Oy. These are the <b>unit (coordinate) vectors</b>. Every vector a→ can be written in exactly one way as a→ = x · i→ + y · j→. The numbers x and y are the vector’s <b>coordinates</b>, written a→(x; y) or a→ = (x; y).'),
      L('Oddiy so‘z bilan: x — vektor gorizontal yo‘nalishda necha birlik siljishi (o‘ngga musbat, chapga manfiy), y — vertikal yo‘nalishda necha birlik siljishi (yuqoriga musbat, pastga manfiy). Masalan, (3; −2) vektor 3 birlik o‘ngga va 2 birlik pastga «yuradi».', 'Простыми словами: x — на сколько единиц вектор смещается по горизонтали (вправо — плюс, влево — минус), y — по вертикали (вверх — плюс, вниз — минус). Например, вектор (3; −2) «идёт» на 3 вправо и на 2 вниз.', 'Put simply: x is how many units the vector moves horizontally (right is positive, left negative), and y how many units vertically (up positive, down negative). The vector (3; −2) “walks” 3 right and 2 down.'),
      L('Teng vektorlarning koordinatalari teng va aksincha. Nol vektor 0→ = (0; 0). O nuqtadan A nuqtaga o‘tkazilgan OA→ vektor <b>radius-vektor</b> deyiladi, uning koordinatalari A nuqtaning koordinatalariga teng.', 'У равных векторов равные координаты, и наоборот. Нулевой вектор 0→ = (0; 0). Вектор OA→ из начала координат в точку A называется <b>радиус-вектором</b>; его координаты совпадают с координатами точки A.', 'Equal vectors have equal coordinates and vice versa. The zero vector is 0→ = (0; 0). The vector OA→ from the origin to a point A is the <b>position vector</b> of A; its coordinates are the coordinates of A.')
    ] },
    { kind: 'history', h: L('Dekart va koordinatalar g‘oyasi', 'Декарт и идея координат', 'Descartes and the idea of coordinates'), p: [
      L('Nuqtani sonlar bilan belgilash g‘oyasini 1637-yilda fransuz faylasufi va matematigi <b>Rene Dekart</b> «Geometriya» asarida tizimli bayon qilgan; deyarli bir vaqtda <b>Per Ferma</b> ham shu fikrga kelgan. Rivoyatga ko‘ra, Dekart kasal bo‘lib yotganida shiftda o‘rmalayotgan pashshani kuzatib, uning o‘rnini ikki devorgacha bo‘lgan masofalar bilan aniqlash mumkinligini tushungan. Shu sababli to‘g‘ri burchakli koordinatalar «Dekart koordinatalari» deyiladi.', 'Идею задавать точку числами систематически изложил в 1637 году французский философ и математик <b>Рене Декарт</b> в трактате «Геометрия»; почти одновременно к ней пришёл и <b>Пьер Ферма</b>. По легенде, Декарт, лёжа больным, наблюдал за мухой на потолке и понял, что её положение можно задать расстояниями до двух стен. Поэтому прямоугольные координаты называют «декартовыми».', 'The idea of labelling points with numbers was set out systematically in 1637 by the French philosopher and mathematician <b>René Descartes</b> in his “Geometry”; <b>Pierre de Fermat</b> reached it at almost the same time. Legend says Descartes, lying ill in bed, watched a fly on the ceiling and realised its position could be given by its distances to two walls. That is why rectangular coordinates are called “Cartesian”.'),
      L('Koordinatalar g‘oyasining ildizlari esa ancha qadimiy. <b>Beruniy</b> va <b>Ulug‘bek</b> yulduz jadvallarida har bir yulduzning o‘rnini ikki son — uzunlik va kenglik bilan bergan; Ulug‘bekning «Ziji jadidi Ko‘ragoniy» katalogida mingdan ortiq yulduz shunday yozilgan. Vektorlarni koordinatalar orqali yozish esa XIX asrda Gamilton va Grassman ishlaridan keyin keng tarqaldi.', 'Корни идеи координат гораздо древнее. <b>Беруни</b> и <b>Улугбек</b> в звёздных таблицах задавали положение каждой звезды двумя числами — долготой и широтой; в каталоге Улугбека «Зидж-и джадид-и Гурагани» так записано более тысячи звёзд. А запись векторов в координатах распространилась в XIX веке после работ Гамильтона и Грассмана.', 'The roots of the idea are much older. <b>Biruni</b> and <b>Ulugh Beg</b> gave each star’s position in their star tables by two numbers — longitude and latitude; Ulugh Beg’s catalogue “Zij-i Jadid-i Gurgani” lists over a thousand stars this way. Writing vectors in coordinates spread in the 19th century after the work of Hamilton and Grassmann.')
    ] },
    { kind: 'rule', h: L('Asosiy formulalar', 'Основные формулы', 'Key formulas'), list: [
      L('<b>Uchlari bo‘yicha koordinatalar.</b> A(x<sub>1</sub>; y<sub>1</sub>), B(x<sub>2</sub>; y<sub>2</sub>) bo‘lsa, AB→ = (x<sub>2</sub> − x<sub>1</sub>; y<sub>2</sub> − y<sub>1</sub>) — «oxiridan boshini ayiramiz».', '<b>Координаты по концам.</b> Если A(x<sub>1</sub>; y<sub>1</sub>), B(x<sub>2</sub>; y<sub>2</sub>), то AB→ = (x<sub>2</sub> − x<sub>1</sub>; y<sub>2</sub> − y<sub>1</sub>) — «из конца вычитаем начало».', '<b>From the endpoints.</b> If A(x<sub>1</sub>; y<sub>1</sub>) and B(x<sub>2</sub>; y<sub>2</sub>), then AB→ = (x<sub>2</sub> − x<sub>1</sub>; y<sub>2</sub> − y<sub>1</sub>) — “end minus start”.'),
      L('<b>Uzunlik.</b> a→ = (x; y) bo‘lsa, |a→| = √(x<sup>2</sup> + y<sup>2</sup>). Bu Pifagor teoremasi: x va y — katetlar, vektor — gipotenuza.', '<b>Длина.</b> Если a→ = (x; y), то |a→| = √(x<sup>2</sup> + y<sup>2</sup>). Это теорема Пифагора: x и y — катеты, вектор — гипотенуза.', '<b>Length.</b> If a→ = (x; y), then |a→| = √(x<sup>2</sup> + y<sup>2</sup>). This is Pythagoras: x and y are the legs, the vector is the hypotenuse.'),
      L('<b>Ikki nuqta orasidagi masofa:</b> AB = √((x<sub>2</sub> − x<sub>1</sub>)<sup>2</sup> + (y<sub>2</sub> − y<sub>1</sub>)<sup>2</sup>).', '<b>Расстояние между точками:</b> AB = √((x<sub>2</sub> − x<sub>1</sub>)<sup>2</sup> + (y<sub>2</sub> − y<sub>1</sub>)<sup>2</sup>).', '<b>Distance between points:</b> AB = √((x<sub>2</sub> − x<sub>1</sub>)<sup>2</sup> + (y<sub>2</sub> − y<sub>1</sub>)<sup>2</sup>).'),
      L('<b>Amallar koordinatalar bo‘yicha:</b> (a<sub>1</sub>; a<sub>2</sub>) + (b<sub>1</sub>; b<sub>2</sub>) = (a<sub>1</sub> + b<sub>1</sub>; a<sub>2</sub> + b<sub>2</sub>); (a<sub>1</sub>; a<sub>2</sub>) − (b<sub>1</sub>; b<sub>2</sub>) = (a<sub>1</sub> − b<sub>1</sub>; a<sub>2</sub> − b<sub>2</sub>); k · (a<sub>1</sub>; a<sub>2</sub>) = (ka<sub>1</sub>; ka<sub>2</sub>).', '<b>Действия покоординатно:</b> (a<sub>1</sub>; a<sub>2</sub>) + (b<sub>1</sub>; b<sub>2</sub>) = (a<sub>1</sub> + b<sub>1</sub>; a<sub>2</sub> + b<sub>2</sub>); (a<sub>1</sub>; a<sub>2</sub>) − (b<sub>1</sub>; b<sub>2</sub>) = (a<sub>1</sub> − b<sub>1</sub>; a<sub>2</sub> − b<sub>2</sub>); k · (a<sub>1</sub>; a<sub>2</sub>) = (ka<sub>1</sub>; ka<sub>2</sub>).', '<b>Operations coordinate-wise:</b> (a<sub>1</sub>; a<sub>2</sub>) + (b<sub>1</sub>; b<sub>2</sub>) = (a<sub>1</sub> + b<sub>1</sub>; a<sub>2</sub> + b<sub>2</sub>); (a<sub>1</sub>; a<sub>2</sub>) − (b<sub>1</sub>; b<sub>2</sub>) = (a<sub>1</sub> − b<sub>1</sub>; a<sub>2</sub> − b<sub>2</sub>); k · (a<sub>1</sub>; a<sub>2</sub>) = (ka<sub>1</sub>; ka<sub>2</sub>).'),
      L('<b>Kesma o‘rtasi:</b> M((x<sub>1</sub> + x<sub>2</sub>)/2; (y<sub>1</sub> + y<sub>2</sub>)/2).', '<b>Середина отрезка:</b> M((x<sub>1</sub> + x<sub>2</sub>)/2; (y<sub>1</sub> + y<sub>2</sub>)/2).', '<b>Midpoint:</b> M((x<sub>1</sub> + x<sub>2</sub>)/2; (y<sub>1</sub> + y<sub>2</sub>)/2).')
    ], after: [
      L('<b>Kollinearlik sharti:</b> (a<sub>1</sub>; a<sub>2</sub>) va (b<sub>1</sub>; b<sub>2</sub>) vektorlar kollinear bo‘lishi uchun koordinatalari proporsional bo‘lishi kerak: a<sub>1</sub>b<sub>2</sub> = a<sub>2</sub>b<sub>1</sub>. Masalan, (2; 3) va (6; 9) kollinear, chunki 2 · 9 = 3 · 6.', '<b>Условие коллинеарности:</b> векторы (a<sub>1</sub>; a<sub>2</sub>) и (b<sub>1</sub>; b<sub>2</sub>) коллинеарны, если координаты пропорциональны: a<sub>1</sub>b<sub>2</sub> = a<sub>2</sub>b<sub>1</sub>. Например, (2; 3) и (6; 9) коллинеарны, так как 2 · 9 = 3 · 6.', '<b>Collinearity test:</b> (a<sub>1</sub>; a<sub>2</sub>) and (b<sub>1</sub>; b<sub>2</sub>) are collinear when their coordinates are proportional: a<sub>1</sub>b<sub>2</sub> = a<sub>2</sub>b<sub>1</sub>. For example (2; 3) and (6; 9) are collinear since 2 · 9 = 3 · 6.')
    ] },
    { kind: 'steps', h: L('Vektor masalasini yechish tartibi', 'Порядок решения задачи с векторами', 'Solving a vector problem'), p: [
      L('Koordinatali masalalar deyarli har doim bir xil sxema bo‘yicha yechiladi. Bu sxemani yodlab olsangiz, eng qiyin ko‘ringan masala ham bir necha qatorda yechiladi.', 'Задачи с координатами почти всегда решаются по одной схеме. Запомните её — и даже трудная на вид задача решится в несколько строк.', 'Coordinate problems almost always follow one pattern. Learn it and even a hard-looking problem takes a few lines.')
    ], list: [
      L('1-qadam. Kerakli vektorlarni nuqtalar koordinatalari orqali yozing: «oxiri minus boshi».', 'Шаг 1. Запишите нужные векторы через координаты точек: «конец минус начало».', 'Step 1. Write the needed vectors from the point coordinates: “end minus start”.'),
      L('2-qadam. Shartdagi amallarni (qo‘shish, ayirish, songa ko‘paytirish) har bir koordinata uchun alohida bajaring.', 'Шаг 2. Выполните действия из условия (сложение, вычитание, умножение на число) для каждой координаты отдельно.', 'Step 2. Do the operations in the problem (add, subtract, scale) separately for each coordinate.'),
      L('3-qadam. Uzunlik so‘ralsa, √(x<sup>2</sup> + y<sup>2</sup>) formulasini qo‘llang.', 'Шаг 3. Если спрашивают длину, примените формулу √(x<sup>2</sup> + y<sup>2</sup>).', 'Step 3. If a length is asked, use √(x<sup>2</sup> + y<sup>2</sup>).'),
      L('4-qadam. Javobni chizmada tekshiring: vektor taxminan to‘g‘ri tomonga qarab turibdimi?', 'Шаг 4. Проверьте ответ на рисунке: смотрит ли вектор примерно туда, куда нужно?', 'Step 4. Check the answer on a sketch: does the vector point roughly the right way?')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('A(1; 2), B(4; 6). AB→ koordinatalari va uzunligini toping.', 'A(1; 2), B(4; 6). Найдите координаты и длину AB→.', 'A(1; 2), B(4; 6). Find the coordinates and length of AB→.'), s: L('AB→ = (4 − 1; 6 − 2) = <b>(3; 4)</b>. |AB→| = √(9 + 16) = <b>5</b>.', 'AB→ = (4 − 1; 6 − 2) = <b>(3; 4)</b>. |AB→| = √(9 + 16) = <b>5</b>.', 'AB→ = (4 − 1; 6 − 2) = <b>(3; 4)</b>. |AB→| = √(9 + 16) = <b>5</b>.') },
      { q: L('a→ = (2; −1), b→ = (−3; 4). 2a→ − b→ ni toping.', 'a→ = (2; −1), b→ = (−3; 4). Найдите 2a→ − b→.', 'a→ = (2; −1), b→ = (−3; 4). Find 2a→ − b→.'), s: L('2a→ = (4; −2). 2a→ − b→ = (4 − (−3); −2 − 4) = <b>(7; −6)</b>.', '2a→ = (4; −2). 2a→ − b→ = (4 − (−3); −2 − 4) = <b>(7; −6)</b>.', '2a→ = (4; −2). 2a→ − b→ = (4 − (−3); −2 − 4) = <b>(7; −6)</b>.') },
      { q: L('ABCD parallelogrammda A(1; 1), B(5; 2), C(7; 6). D uchini toping.', 'В параллелограмме ABCD A(1; 1), B(5; 2), C(7; 6). Найдите вершину D.', 'In parallelogram ABCD, A(1; 1), B(5; 2), C(7; 6). Find vertex D.'), s: L('Parallelogrammda AD→ = BC→ = (7 − 5; 6 − 2) = (2; 4). D = A + (2; 4) = <b>(3; 5)</b>. Tekshiruv: AC va BD o‘rtalari bir xil — (4; 3,5).', 'В параллелограмме AD→ = BC→ = (7 − 5; 6 − 2) = (2; 4). D = A + (2; 4) = <b>(3; 5)</b>. Проверка: середины AC и BD совпадают — (4; 3,5).', 'In a parallelogram AD→ = BC→ = (7 − 5; 6 − 2) = (2; 4). D = A + (2; 4) = <b>(3; 5)</b>. Check: the midpoints of AC and BD coincide at (4; 3.5).') },
      { q: L('a→ = (3; k) va b→ = (6; 10) kollinear bo‘lishi uchun k qanday bo‘lishi kerak?', 'При каком k векторы a→ = (3; k) и b→ = (6; 10) коллинеарны?', 'For which k are a→ = (3; k) and b→ = (6; 10) collinear?'), s: L('3 · 10 = k · 6, demak k = <b>5</b>. Haqiqatan, b→ = 2a→.', '3 · 10 = k · 6, значит k = <b>5</b>. Действительно, b→ = 2a→.', '3 · 10 = k · 6, so k = <b>5</b>. Indeed b→ = 2a→.') }
    ] },
    { kind: 'table', h: L('Amallar jadvali', 'Таблица действий', 'Table of operations'), p: [
      L('a→ = (2; 3) va b→ = (4; −1) vektorlar uchun barcha asosiy amallar natijasi. Har bir qatorni o‘zingiz hisoblab, natija bilan solishtiring.', 'Результаты основных действий для векторов a→ = (2; 3) и b→ = (4; −1). Посчитайте каждую строку сами и сравните.', 'Results of the main operations for a→ = (2; 3) and b→ = (4; −1). Work out each row yourself and compare.')
    ], table: { head: [L('Amal', 'Действие', 'Operation'), L('Hisob', 'Вычисление', 'Working'), L('Natija', 'Результат', 'Result')], rows: [
      [L('a→ + b→', 'a→ + b→', 'a→ + b→'), L('(2 + 4; 3 − 1)', '(2 + 4; 3 − 1)', '(2 + 4; 3 − 1)'), L('(6; 2)', '(6; 2)', '(6; 2)')],
      [L('a→ − b→', 'a→ − b→', 'a→ − b→'), L('(2 − 4; 3 + 1)', '(2 − 4; 3 + 1)', '(2 − 4; 3 + 1)'), L('(−2; 4)', '(−2; 4)', '(−2; 4)')],
      [L('3a→', '3a→', '3a→'), L('(3 · 2; 3 · 3)', '(3 · 2; 3 · 3)', '(3 · 2; 3 · 3)'), L('(6; 9)', '(6; 9)', '(6; 9)')],
      [L('−b→', '−b→', '−b→'), L('(−4; 1)', '(−4; 1)', '(−4; 1)'), L('(−4; 1)', '(−4; 1)', '(−4; 1)')],
      [L('|b→|', '|b→|', '|b→|'), L('√(16 + 1)', '√(16 + 1)', '√(16 + 1)'), L('√17 ≈ 4,12', '√17 ≈ 4,12', '√17 ≈ 4.12')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Boshidan oxirini ayirish.</b> AB→ = B − A, aksincha emas. A(1; 2), B(4; 6) uchun AB→ = (3; 4), (−3; −4) esa BA→.', '<b>Вычитают конец из начала.</b> AB→ = B − A, а не наоборот. Для A(1; 2), B(4; 6) AB→ = (3; 4), а (−3; −4) — это BA→.', '<b>Subtracting end from start.</b> AB→ = B − A, not the other way. For A(1; 2), B(4; 6), AB→ = (3; 4); (−3; −4) is BA→.'),
      L('<b>Uzunlikda kvadratdan oldin manfiy ishorani yo‘qotish.</b> (−3)<sup>2</sup> = 9, −9 emas. |(−3; 4)| = 5.', '<b>Теряют знак при возведении в квадрат.</b> (−3)<sup>2</sup> = 9, а не −9. |(−3; 4)| = 5.', '<b>Sign slips when squaring.</b> (−3)<sup>2</sup> = 9, not −9. |(−3; 4)| = 5.'),
      L('<b>Uzunlikni x + y deb hisoblash.</b> |(3; 4)| = 5, 7 emas — ildiz ostida kvadratlar yig‘indisi.', '<b>Считают длину как x + y.</b> |(3; 4)| = 5, а не 7 — под корнем сумма квадратов.', '<b>Taking the length as x + y.</b> |(3; 4)| = 5, not 7 — it is the root of the sum of squares.'),
      L('<b>Songa ko‘paytirishda faqat bitta koordinatani ko‘paytirish.</b> 3 · (2; 5) = (6; 15), (6; 5) emas.', '<b>Умножают на число только одну координату.</b> 3 · (2; 5) = (6; 15), а не (6; 5).', '<b>Scaling only one coordinate.</b> 3 · (2; 5) = (6; 15), not (6; 5).'),
      L('<b>Nuqta va vektorni chalkashtirish.</b> A(4; 6) — joy, AB→ = (3; 4) — siljish. Vektor koordinatalari boshi qayerda ekaniga bog‘liq emas.', '<b>Путают точку и вектор.</b> A(4; 6) — место, AB→ = (3; 4) — смещение. Координаты вектора не зависят от того, где его начало.', '<b>Mixing up points and vectors.</b> A(4; 6) is a place; AB→ = (3; 4) is a shift. A vector’s coordinates do not depend on where it starts.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Kompyuter o‘yinlari.</b> Ekrandagi har bir qahramonning o‘rni — nuqta, tezligi — vektor. Har bir kadrda dastur o‘rniga tezlik vektorini qo‘shadi: (x; y) + (v<sub>x</sub>; v<sub>y</sub>). Sekundiga 60 marta shunday qo‘shish — va qahramon silliq harakatlanadi. Ikki qahramon to‘qnashganini bilish uchun ular orasidagi masofa √(Δx<sup>2</sup> + Δy<sup>2</sup>) hisoblanadi.', '<b>Компьютерные игры.</b> Положение каждого героя на экране — точка, скорость — вектор. В каждом кадре программа прибавляет к положению вектор скорости: (x; y) + (v<sub>x</sub>; v<sub>y</sub>). 60 таких сложений в секунду — и герой движется плавно. Чтобы понять, столкнулись ли два героя, считают расстояние √(Δx<sup>2</sup> + Δy<sup>2</sup>).', '<b>Video games.</b> Each character’s position on screen is a point and its velocity a vector. Every frame the program adds the velocity to the position: (x; y) + (v<sub>x</sub>; v<sub>y</sub>). Do that 60 times a second and the character moves smoothly. To check if two characters collide, the game computes the distance √(Δx<sup>2</sup> + Δy<sup>2</sup>).'),
      L('<b>Xaritalar va navigatsiya.</b> Taksi ilovasi haydovchi va yo‘lovchi koordinatalaridan ular orasidagi vektorni topadi. Robot-changyutgich xona xaritasini koordinatalarda saqlaydi va har bir harakatini vektor sifatida rejalashtiradi.', '<b>Карты и навигация.</b> Приложение такси по координатам водителя и пассажира находит вектор между ними. Робот-пылесос хранит карту комнаты в координатах и планирует каждое движение как вектор.', '<b>Maps and navigation.</b> A taxi app finds the vector between driver and passenger from their coordinates. A robot vacuum stores a map of the room in coordinates and plans each move as a vector.'),
      L('<b>Rassomlik va dizayn.</b> Vektorli grafika (SVG, logotiplar) rasmni piksellar emas, koordinatalar va vektorlar bilan saqlaydi, shuning uchun uni sifatini yo‘qotmasdan istalgancha kattalashtirish mumkin.', '<b>Дизайн.</b> Векторная графика (SVG, логотипы) хранит рисунок не пикселями, а координатами и векторами, поэтому его можно увеличивать без потери качества.', '<b>Design.</b> Vector graphics (SVG, logos) store a picture as coordinates and vectors rather than pixels, so it can be enlarged without losing quality.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Shaxmat taxtasidagi «e4» yozuvi ham koordinatalar: harf — ustun, raqam — qator. Ot yurishi (2; 1) yoki (1; 2) kabi vektorlar bilan ifodalanadi.', 'Запись «e4» на шахматной доске — тоже координаты: буква — столбец, цифра — строка. Ход коня описывается векторами вроде (2; 1) или (1; 2).', 'Chess notation like “e4” is coordinates too: the letter is the column, the digit the row. A knight’s move is a vector such as (2; 1) or (1; 2).'),
      L('Fazoda vektorlar uchta koordinataga ega: (x; y; z). Uch o‘lchamli o‘yinlar va kosmik kemalar trayektoriyalari aynan shunday hisoblanadi.', 'В пространстве у векторов три координаты: (x; y; z). Так считаются 3D-игры и траектории космических кораблей.', 'In space vectors have three coordinates: (x; y; z). That is how 3D games and spacecraft trajectories are computed.'),
      L('Ulug‘bek katalogidagi yulduz koordinatalari shunchalik aniq ediki, ular XVII asrda Oksfordda lotin tiliga tarjima qilinib nashr etilgan.', 'Координаты звёзд из каталога Улугбека были так точны, что в XVII веке их перевели на латынь и издали в Оксфорде.', 'The star coordinates in Ulugh Beg’s catalogue were so accurate that they were translated into Latin and published in Oxford in the 17th century.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('A(−2; 3), B(4; −5). |AB→| = ?', 'A(−2; 3), B(4; −5). |AB→| = ?', 'A(−2; 3), B(4; −5). |AB→| = ?'), s: L('AB→ = (6; −8), uzunligi √(36 + 64) = <b>10</b>.', 'AB→ = (6; −8), длина √(36 + 64) = <b>10</b>.', 'AB→ = (6; −8), length √(36 + 64) = <b>10</b>.') },
      { q: L('(1; −2) + 3 · (2; 1) = ?', '(1; −2) + 3 · (2; 1) = ?', '(1; −2) + 3 · (2; 1) = ?'), s: L('(1; −2) + (6; 3) = <b>(7; 1)</b>.', '(1; −2) + (6; 3) = <b>(7; 1)</b>.', '(1; −2) + (6; 3) = <b>(7; 1)</b>.') },
      { q: L('A(2; 8), B(6; 2) kesma o‘rtasi?', 'Середина отрезка A(2; 8), B(6; 2)?', 'Midpoint of A(2; 8) and B(6; 2)?'), s: L('((2 + 6)/2; (8 + 2)/2) = <b>(4; 5)</b>.', '((2 + 6)/2; (8 + 2)/2) = <b>(4; 5)</b>.', '((2 + 6)/2; (8 + 2)/2) = <b>(4; 5)</b>.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Vektor koordinatalari: a→ = x · i→ + y · j→ = (x; y).', 'Координаты вектора: a→ = x · i→ + y · j→ = (x; y).', 'Vector coordinates: a→ = x · i→ + y · j→ = (x; y).'),
      L('AB→ = (x<sub>2</sub> − x<sub>1</sub>; y<sub>2</sub> − y<sub>1</sub>) — oxiri minus boshi.', 'AB→ = (x<sub>2</sub> − x<sub>1</sub>; y<sub>2</sub> − y<sub>1</sub>) — конец минус начало.', 'AB→ = (x<sub>2</sub> − x<sub>1</sub>; y<sub>2</sub> − y<sub>1</sub>) — end minus start.'),
      L('Uzunlik |a→| = √(x<sup>2</sup> + y<sup>2</sup>) — Pifagor teoremasi.', 'Длина |a→| = √(x<sup>2</sup> + y<sup>2</sup>) — теорема Пифагора.', 'Length |a→| = √(x<sup>2</sup> + y<sup>2</sup>) — Pythagoras again.'),
      L('Qo‘shish, ayirish va songa ko‘paytirish har bir koordinata uchun alohida bajariladi.', 'Сложение, вычитание и умножение на число выполняются покоординатно.', 'Addition, subtraction and scaling are done coordinate by coordinate.'),
      L('Kollinearlik: a<sub>1</sub>b<sub>2</sub> = a<sub>2</sub>b<sub>1</sub>; kesma o‘rtasi — koordinatalar o‘rta arifmetigi.', 'Коллинеарность: a<sub>1</sub>b<sub>2</sub> = a<sub>2</sub>b<sub>1</sub>; середина отрезка — среднее арифметическое координат.', 'Collinear: a<sub>1</sub>b<sub>2</sub> = a<sub>2</sub>b<sub>1</sub>; the midpoint is the average of the coordinates.')
    ] }
  ] });

  // ---------- t20. Vektorlarning skalyar ko‘paytmasi. Tatbiqlar ----------
  T.add(P, 't20', { sections: [
    { kind: 'intro', h: L('Ikki vektorni ko‘paytirish mumkinmi?', 'Можно ли перемножить два вектора?', 'Can two vectors be multiplied?'), p: [
      L('Vektorlarni qo‘shishni va songa ko‘paytirishni bilamiz. Endi tabiiy savol tug‘iladi: ikki vektorni bir-biriga ko‘paytirsa bo‘ladimi? Fizikadan misol: aravachani arqon bilan tortyapsiz. Agar arqon yo‘l bo‘ylab tortilsa, butun kuch foydali ishga sarflanadi. Agar arqon qiya, masalan yuqoriga tortilsa, kuchning bir qismi aravachani faqat «ko‘tarishga» ketadi. Ish kuch va siljishga hamda ular orasidagi burchakka bog‘liq.', 'Мы умеем складывать векторы и умножать их на число. Возникает естественный вопрос: можно ли перемножить два вектора? Пример из физики: вы тянете тележку за верёвку. Если тянуть вдоль дороги, вся сила идёт в полезную работу. Если тянуть наискосок, вверх, часть силы лишь «приподнимает» тележку. Работа зависит от силы, перемещения и угла между ними.', 'We know how to add vectors and multiply them by numbers. A natural question follows: can two vectors be multiplied together? An example from physics: you pull a cart with a rope. Pull along the road and all the force does useful work. Pull at a slant, upwards, and part of the force only “lifts” the cart. The work depends on the force, the displacement and the angle between them.'),
      L('Bu g‘oya <b>skalyar ko‘paytma</b> tushunchasiga olib keladi. Uning natijasi vektor emas, oddiy son (skalyar) bo‘ladi — nomi ham shundan. Skalyar ko‘paytma yordamida vektorlar orasidagi burchakni topish, perpendikulyarlikni tekshirish va ko‘plab geometrik masalalarni faqat hisoblash bilan yechish mumkin. Bu mavzu bilan 8-sinf geometriya kursi yakunlanadi.', 'Эта идея приводит к понятию <b>скалярного произведения</b>. Его результат — не вектор, а обычное число (скаляр), отсюда и название. С его помощью можно находить угол между векторами, проверять перпендикулярность и решать множество геометрических задач одними вычислениями. Этой темой завершается курс геометрии 8 класса.', 'This idea leads to the <b>dot product</b> (scalar product). Its result is not a vector but an ordinary number — a scalar — hence the name. With it we can find the angle between vectors, test for perpendicularity and solve many geometry problems purely by calculation. This topic completes the grade 8 geometry course.')
    ] },
    { kind: 'def', h: L('Ta’rif', 'Определение', 'Definition'), p: [
      L('Ikki nol bo‘lmagan vektorni bitta nuqtadan qo‘yamiz. Ular orasidagi burchak φ (0° dan 180° gacha) <b>vektorlar orasidagi burchak</b> deyiladi. Bir xil yo‘nalgan vektorlar orasidagi burchak 0°, qarama-qarshi yo‘nalganlar orasidagi esa 180°.', 'Отложим два ненулевых вектора от одной точки. Угол φ между ними (от 0° до 180°) называется <b>углом между векторами</b>. У сонаправленных векторов он равен 0°, у противоположно направленных — 180°.', 'Draw two non-zero vectors from the same point. The angle φ between them (from 0° to 180°) is the <b>angle between the vectors</b>. It is 0° for vectors pointing the same way and 180° for opposite ones.'),
      L('<b>Skalyar ko‘paytma</b> — vektorlar uzunliklari va ular orasidagi burchak kosinusining ko‘paytmasi: <b>a→ · b→ = |a→| · |b→| · cos φ</b>. Agar vektorlardan biri nol vektor bo‘lsa, skalyar ko‘paytma 0 deb olinadi.', '<b>Скалярное произведение</b> — произведение длин векторов на косинус угла между ними: <b>a→ · b→ = |a→| · |b→| · cos φ</b>. Если один из векторов нулевой, скалярное произведение считается равным 0.', 'The <b>dot product</b> is the product of the lengths and the cosine of the angle between them: <b>a→ · b→ = |a→| · |b→| · cos φ</b>. If either vector is zero, the dot product is 0.'),
      L('Eslatma: cos 0° = 1, cos 60° = 1/2, cos 90° = 0, cos 120° = −1/2, cos 180° = −1. O‘tkir burchakda kosinus musbat, o‘tmas burchakda manfiy.', 'Напомним: cos 0° = 1, cos 60° = 1/2, cos 90° = 0, cos 120° = −1/2, cos 180° = −1. Для острого угла косинус положителен, для тупого — отрицателен.', 'Reminder: cos 0° = 1, cos 60° = 1/2, cos 90° = 0, cos 120° = −1/2, cos 180° = −1. The cosine is positive for acute angles and negative for obtuse ones.')
    ] },
    { kind: 'history', h: L('Gamilton, Grassman va Gibbs', 'Гамильтон, Грассман и Гиббс', 'Hamilton, Grassmann and Gibbs'), p: [
      L('Skalyar ko‘paytma tarixi vektorlar tarixi bilan chambarchas bog‘liq. Irlandiyalik <b>Uilyam Gamilton</b> 1843-yilda kvaternionlarni kashf qilganda, ikki vektor ko‘paytmasi ikki qismdan iborat ekanini ko‘rdi: biri son (u «skalyar qism» deb atadi), ikkinchisi vektor. «Skalyar» so‘zi lotincha «scala» — «narvon, shkala» so‘zidan olingan: son shkalada joylashgan kattalik.', 'История скалярного произведения тесно связана с историей векторов. Ирландец <b>Уильям Гамильтон</b>, открыв в 1843 году кватернионы, увидел, что произведение двух векторов состоит из двух частей: числа (он назвал его «скалярной частью») и вектора. Слово «скаляр» происходит от латинского «scala» — «лестница, шкала»: число — величина, расположенная на шкале.', 'The history of the dot product is bound up with the history of vectors. When the Irishman <b>William Hamilton</b> discovered quaternions in 1843, he saw that the product of two vectors has two parts: a number (which he called the “scalar part”) and a vector. “Scalar” comes from Latin “scala” — “ladder, scale”: a number is a quantity that sits on a scale.'),
      L('Nemis o‘qituvchisi <b>German Grassman</b> 1844-yilda «ichki ko‘paytma» g‘oyasini mustaqil ravishda ishlab chiqdi. Nihoyat, 1880-yillarda amerikalik fizik <b>Jozaya Gibbs</b> va ingliz muhandisi <b>Oliver Xevisayd</b> kvaternionlarni soddalashtirib, skalyar ko‘paytmani hozirgi «a→ · b→» ko‘rinishida yozishdi. Shundan beri u mexanika, elektr va magnetizm, kompyuter grafikasi hamda sun’iy intellektning asosiy formulalaridan biriga aylandi.', 'Немецкий учитель <b>Герман Грассман</b> в 1844 году независимо разработал идею «внутреннего произведения». Наконец, в 1880-х американский физик <b>Джозайя Гиббс</b> и английский инженер <b>Оливер Хевисайд</b>, упростив кватернионы, записали скалярное произведение в нынешнем виде «a→ · b→». С тех пор оно стало одной из главных формул механики, электромагнетизма, компьютерной графики и искусственного интеллекта.', 'The German teacher <b>Hermann Grassmann</b> independently developed the idea of an “inner product” in 1844. Finally, in the 1880s the American physicist <b>Josiah Gibbs</b> and the English engineer <b>Oliver Heaviside</b> simplified quaternions and wrote the dot product in today’s form “a→ · b→”. Since then it has become one of the key formulas of mechanics, electromagnetism, computer graphics and artificial intelligence.')
    ] },
    { kind: 'rule', h: L('Koordinatalardagi formula va xossalar', 'Формула в координатах и свойства', 'The coordinate formula and properties'), p: [
      L('<b>Teorema.</b> a→ = (x<sub>1</sub>; y<sub>1</sub>), b→ = (x<sub>2</sub>; y<sub>2</sub>) bo‘lsa, <b>a→ · b→ = x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub></b>.', '<b>Теорема.</b> Если a→ = (x<sub>1</sub>; y<sub>1</sub>), b→ = (x<sub>2</sub>; y<sub>2</sub>), то <b>a→ · b→ = x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub></b>.', '<b>Theorem.</b> If a→ = (x<sub>1</sub>; y<sub>1</sub>) and b→ = (x<sub>2</sub>; y<sub>2</sub>), then <b>a→ · b→ = x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub></b>.'),
      L('<b>Isbot g‘oyasi.</b> a→, b→ va a→ − b→ vektorlardan uchburchak hosil bo‘ladi. Kosinuslar teoremasiga ko‘ra |a→ − b→|<sup>2</sup> = |a→|<sup>2</sup> + |b→|<sup>2</sup> − 2|a→||b→| cos φ. Uzunliklarni koordinatalarda yozib, qavslarni ochsak, qisqartirishlardan keyin |a→||b→| cos φ = x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub> qoladi.', '<b>Идея доказательства.</b> Векторы a→, b→ и a→ − b→ образуют треугольник. По теореме косинусов |a→ − b→|<sup>2</sup> = |a→|<sup>2</sup> + |b→|<sup>2</sup> − 2|a→||b→| cos φ. Записав длины в координатах и раскрыв скобки, после сокращений получим |a→||b→| cos φ = x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub>.', '<b>Proof idea.</b> The vectors a→, b→ and a→ − b→ form a triangle. By the law of cosines |a→ − b→|<sup>2</sup> = |a→|<sup>2</sup> + |b→|<sup>2</sup> − 2|a→||b→| cos φ. Writing the lengths in coordinates and expanding, everything cancels except |a→||b→| cos φ = x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub>.')
    ], list: [
      L('<b>Perpendikulyarlik sharti:</b> a→ ⊥ b→ ⇔ a→ · b→ = 0, ya’ni x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub> = 0.', '<b>Условие перпендикулярности:</b> a→ ⊥ b→ ⇔ a→ · b→ = 0, т.е. x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub> = 0.', '<b>Perpendicularity:</b> a→ ⊥ b→ ⇔ a→ · b→ = 0, i.e. x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub> = 0.'),
      L('<b>Skalyar kvadrat:</b> a→ · a→ = |a→|<sup>2</sup> = x<sup>2</sup> + y<sup>2</sup>.', '<b>Скалярный квадрат:</b> a→ · a→ = |a→|<sup>2</sup> = x<sup>2</sup> + y<sup>2</sup>.', '<b>Dot square:</b> a→ · a→ = |a→|<sup>2</sup> = x<sup>2</sup> + y<sup>2</sup>.'),
      L('<b>Burchak kosinusi:</b> cos φ = (x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub>) / (|a→| · |b→|).', '<b>Косинус угла:</b> cos φ = (x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub>) / (|a→| · |b→|).', '<b>Cosine of the angle:</b> cos φ = (x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub>) / (|a→| · |b→|).'),
      L('<b>Ishora:</b> a→ · b→ &gt; 0 — burchak o‘tkir; a→ · b→ &lt; 0 — burchak o‘tmas.', '<b>Знак:</b> a→ · b→ &gt; 0 — угол острый; a→ · b→ &lt; 0 — тупой.', '<b>Sign:</b> a→ · b→ &gt; 0 — acute angle; a→ · b→ &lt; 0 — obtuse.'),
      L('<b>Algebraik xossalar:</b> a→ · b→ = b→ · a→; (ka→) · b→ = k(a→ · b→); (a→ + b→) · c→ = a→ · c→ + b→ · c→.', '<b>Алгебраические свойства:</b> a→ · b→ = b→ · a→; (ka→) · b→ = k(a→ · b→); (a→ + b→) · c→ = a→ · c→ + b→ · c→.', '<b>Algebra rules:</b> a→ · b→ = b→ · a→; (ka→) · b→ = k(a→ · b→); (a→ + b→) · c→ = a→ · c→ + b→ · c→.')
    ] },
    { kind: 'steps', h: L('Vektorlar orasidagi burchakni topish', 'Как найти угол между векторами', 'Finding the angle between vectors'), list: [
      L('1-qadam. Vektorlar koordinatalarini toping (kerak bo‘lsa, «oxiri minus boshi» qoidasi bilan).', 'Шаг 1. Найдите координаты векторов (при необходимости — «конец минус начало»).', 'Step 1. Find the vectors’ coordinates (using “end minus start” if needed).'),
      L('2-qadam. Skalyar ko‘paytmani hisoblang: x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub>. Agar u 0 bo‘lsa — burchak 90°, ish tugadi.', 'Шаг 2. Вычислите скалярное произведение x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub>. Если оно 0 — угол 90°, готово.', 'Step 2. Compute the dot product x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub>. If it is 0, the angle is 90° — done.'),
      L('3-qadam. Ikkala vektor uzunligini toping.', 'Шаг 3. Найдите длины обоих векторов.', 'Step 3. Find both lengths.'),
      L('4-qadam. cos φ = (skalyar ko‘paytma) / (uzunliklar ko‘paytmasi) ni hisoblang va jadvaldan burchakni aniqlang.', 'Шаг 4. Вычислите cos φ = (скалярное произведение) / (произведение длин) и найдите угол по таблице.', 'Step 4. Compute cos φ = (dot product) / (product of lengths) and read off the angle.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('a→ = (2; 3), b→ = (4; −1). a→ · b→ ni toping.', 'a→ = (2; 3), b→ = (4; −1). Найдите a→ · b→.', 'a→ = (2; 3), b→ = (4; −1). Find a→ · b→.'), s: L('2 · 4 + 3 · (−1) = 8 − 3 = <b>5</b>. Musbat, demak burchak o‘tkir.', '2 · 4 + 3 · (−1) = 8 − 3 = <b>5</b>. Положительно, значит угол острый.', '2 · 4 + 3 · (−1) = 8 − 3 = <b>5</b>. Positive, so the angle is acute.') },
      { q: L('(3; 4) va (−4; 3) vektorlar perpendikulyarmi?', 'Перпендикулярны ли векторы (3; 4) и (−4; 3)?', 'Are (3; 4) and (−4; 3) perpendicular?'), s: L('3 · (−4) + 4 · 3 = −12 + 12 = 0. <b>Ha, perpendikulyar.</b> Umuman, (x; y) ga (−y; x) doimo perpendikulyar — bu vektorni 90° ga burish.', '3 · (−4) + 4 · 3 = −12 + 12 = 0. <b>Да, перпендикулярны.</b> Вообще (−y; x) всегда перпендикулярен (x; y) — это поворот на 90°.', '3 · (−4) + 4 · 3 = −12 + 12 = 0. <b>Yes.</b> In general (−y; x) is always perpendicular to (x; y) — it is a 90° turn.') },
      { q: L('a→ = (1; 1), b→ = (0; 2). Ular orasidagi burchakni toping.', 'a→ = (1; 1), b→ = (0; 2). Найдите угол между ними.', 'a→ = (1; 1), b→ = (0; 2). Find the angle between them.'), s: L('a→ · b→ = 0 + 2 = 2; |a→| = √2, |b→| = 2. cos φ = 2/(2√2) = 1/√2 = √2/2, demak φ = <b>45°</b>.', 'a→ · b→ = 0 + 2 = 2; |a→| = √2, |b→| = 2. cos φ = 2/(2√2) = √2/2, значит φ = <b>45°</b>.', 'a→ · b→ = 0 + 2 = 2; |a→| = √2, |b→| = 2. cos φ = 2/(2√2) = √2/2, so φ = <b>45°</b>.') },
      { q: L('A(1; 1), B(4; 2), C(2; 4) uchburchakda A burchak to‘g‘rimi?', 'В треугольнике A(1; 1), B(4; 2), C(2; 4) прямой ли угол A?', 'In triangle A(1; 1), B(4; 2), C(2; 4), is angle A a right angle?'), s: L('AB→ = (3; 1), AC→ = (1; 3). AB→ · AC→ = 3 + 3 = 6 ≠ 0 — <b>yo‘q</b>, A burchak o‘tkir (cos A = 6/10 = 0,6).', 'AB→ = (3; 1), AC→ = (1; 3). AB→ · AC→ = 3 + 3 = 6 ≠ 0 — <b>нет</b>, угол A острый (cos A = 6/10 = 0,6).', 'AB→ = (3; 1), AC→ = (1; 3). AB→ · AC→ = 3 + 3 = 6 ≠ 0 — <b>no</b>; angle A is acute (cos A = 6/10 = 0.6).') }
    ] },
    { kind: 'table', h: L('Burchak va skalyar ko‘paytma ishorasi', 'Угол и знак скалярного произведения', 'Angle and the sign of the dot product'), p: [
      L('Skalyar ko‘paytmaning ishorasi burchak haqida darhol ma’lumot beradi — uni hatto burchakni hisoblamasdan bilish mumkin.', 'Знак скалярного произведения сразу говорит об угле — его можно узнать, даже не вычисляя угол.', 'The sign of the dot product tells you about the angle at once — even without computing it.')
    ], table: { head: [L('Burchak φ', 'Угол φ', 'Angle φ'), L('cos φ', 'cos φ', 'cos φ'), L('a→ · b→', 'a→ · b→', 'a→ · b→'), L('Ma’nosi', 'Смысл', 'Meaning')], rows: [
      ['0°', '1', L('|a→| · |b→|', '|a→| · |b→|', '|a→| · |b→|'), L('bir xil yo‘nalgan', 'сонаправлены', 'same direction')],
      [L('0° … 90°', '0° … 90°', '0° … 90°'), L('&gt; 0', '&gt; 0', '&gt; 0'), L('&gt; 0', '&gt; 0', '&gt; 0'), L('o‘tkir burchak', 'острый угол', 'acute angle')],
      ['90°', '0', '0', L('perpendikulyar', 'перпендикулярны', 'perpendicular')],
      [L('90° … 180°', '90° … 180°', '90° … 180°'), L('&lt; 0', '&lt; 0', '&lt; 0'), L('&lt; 0', '&lt; 0', '&lt; 0'), L('o‘tmas burchak', 'тупой угол', 'obtuse angle')],
      ['180°', '−1', L('−|a→| · |b→|', '−|a→| · |b→|', '−|a→| · |b→|'), L('qarama-qarshi yo‘nalgan', 'противоположно направлены', 'opposite directions')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Natijani vektor deb yozish.</b> Skalyar ko‘paytma — son! (2; 3) · (4; −1) = 5, (8; −3) emas.', '<b>Записывают результат как вектор.</b> Скалярное произведение — число! (2; 3) · (4; −1) = 5, а не (8; −3).', '<b>Writing the result as a vector.</b> The dot product is a number! (2; 3) · (4; −1) = 5, not (8; −3).'),
      L('<b>Koordinatalarni «xoch» ko‘paytirish.</b> x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub>: x lar x larga, y lar y larga ko‘paytiriladi, x<sub>1</sub>y<sub>2</sub> emas.', '<b>Перемножают «крест-накрест».</b> x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub>: x на x, y на y, а не x<sub>1</sub>y<sub>2</sub>.', '<b>Cross-multiplying.</b> x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub>: x with x and y with y — not x<sub>1</sub>y<sub>2</sub>.'),
      L('<b>Manfiy ishorani yo‘qotish.</b> 3 · (−4) = −12. Bitta ishora xatosi perpendikulyar vektorlarni «perpendikulyar emas» qilib qo‘yadi.', '<b>Теряют минус.</b> 3 · (−4) = −12. Одна ошибка в знаке делает перпендикулярные векторы «неперпендикулярными».', '<b>Dropping a minus sign.</b> 3 · (−4) = −12. One sign slip turns perpendicular vectors into “not perpendicular”.'),
      L('<b>Burchakni vektorlarni bir nuqtadan qo‘ymasdan o‘lchash.</b> Uchburchakda B burchak uchun BA→ va BC→ olinadi, AB→ va BC→ emas — aks holda tashqi burchak chiqadi.', '<b>Измеряют угол, не отложив векторы от одной точки.</b> Для угла B треугольника берут BA→ и BC→, а не AB→ и BC→ — иначе получится внешний угол.', '<b>Measuring the angle without a common start.</b> For angle B of a triangle use BA→ and BC→, not AB→ and BC→ — otherwise you get the exterior angle.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Fizikada ish.</b> Kuchning bajargan ishi A = F→ · s→ = |F→| · |s→| · cos φ. Masalan, 50 N kuch bilan chanani 60° burchak ostida 10 m tortsangiz, ish 50 · 10 · 1/2 = 250 J bo‘ladi. Agar kuch harakatga perpendikulyar bo‘lsa (masalan, sumkani gorizontal ko‘tarib yurganda), ish nolga teng!', '<b>Работа в физике.</b> Работа силы A = F→ · s→ = |F→| · |s→| · cos φ. Если тянуть санки силой 50 Н под углом 60° на 10 м, работа 50 · 10 · 1/2 = 250 Дж. Если сила перпендикулярна движению (например, несёте сумку горизонтально), работа равна нулю!', '<b>Work in physics.</b> The work done by a force is A = F→ · s→ = |F→| · |s→| · cos φ. Pull a sled with 50 N at 60° for 10 m and the work is 50 · 10 · 1/2 = 250 J. If the force is perpendicular to the motion (carrying a bag along level ground), the work is zero!'),
      L('<b>Kompyuter grafikasi.</b> 3D o‘yinlarda sirtning qanchalik yorug‘ ko‘rinishi yorug‘lik yo‘nalishi va sirt normali vektorlarining skalyar ko‘paytmasi bilan hisoblanadi: nur tik tushsa — yorug‘, qiya tushsa — xira, orqadan tushsa — soya.', '<b>Компьютерная графика.</b> В 3D-играх яркость поверхности считается через скалярное произведение направления света и нормали к поверхности: луч падает прямо — светло, наискосок — тускло, сзади — тень.', '<b>Computer graphics.</b> In 3D games a surface’s brightness comes from the dot product of the light direction and the surface normal: light hitting straight on is bright, at a slant dim, from behind — shadow.'),
      L('<b>Sun’iy intellekt.</b> Qidiruv tizimlari va tavsiya xizmatlari matn yoki qo‘shiqlarni uzun vektorlar ko‘rinishida saqlaydi. Ikki matn qanchalik o‘xshashligini ular orasidagi burchak kosinusi — ya’ni skalyar ko‘paytma bilan o‘lchashadi.', '<b>Искусственный интеллект.</b> Поисковики и рекомендательные сервисы хранят тексты и песни в виде длинных векторов. Насколько похожи два текста, измеряют косинусом угла между ними — т.е. скалярным произведением.', '<b>Artificial intelligence.</b> Search engines and recommendation services store texts and songs as long vectors. How similar two texts are is measured by the cosine of the angle between them — that is, by the dot product.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Skalyar ko‘paytma tufayli Pifagor teoremasi bir qatorda isbotlanadi: a→ ⊥ b→ bo‘lsa, |a→ + b→|<sup>2</sup> = a→ · a→ + 2a→ · b→ + b→ · b→ = |a→|<sup>2</sup> + |b→|<sup>2</sup>.', 'Благодаря скалярному произведению теорема Пифагора доказывается в одну строку: если a→ ⊥ b→, то |a→ + b→|<sup>2</sup> = a→ · a→ + 2a→ · b→ + b→ · b→ = |a→|<sup>2</sup> + |b→|<sup>2</sup>.', 'With the dot product Pythagoras’ theorem takes one line: if a→ ⊥ b→, then |a→ + b→|<sup>2</sup> = a→ · a→ + 2a→ · b→ + b→ · b→ = |a→|<sup>2</sup> + |b→|<sup>2</sup>.'),
      L('Zamonaviy videokartalar sekundiga trillionlab skalyar ko‘paytmani hisoblaydi — sun’iy intellekt modellarining asosiy ishi aynan shu.', 'Современные видеокарты вычисляют триллионы скалярных произведений в секунду — это и есть основная работа моделей искусственного интеллекта.', 'Modern graphics cards compute trillions of dot products per second — that is the core work of artificial intelligence models.'),
      L('Quyosh panellari Quyoshga qarab buriladi, chunki olinadigan energiya nur yo‘nalishi va panel normali skalyar ko‘paytmasiga proporsional.', 'Солнечные панели поворачивают к Солнцу, потому что получаемая энергия пропорциональна скалярному произведению направления луча и нормали панели.', 'Solar panels are turned towards the Sun because the energy collected is proportional to the dot product of the sunlight direction and the panel’s normal.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('(5; −2) · (1; 3) = ?', '(5; −2) · (1; 3) = ?', '(5; −2) · (1; 3) = ?'), s: L('5 − 6 = <b>−1</b> (burchak o‘tmas).', '5 − 6 = <b>−1</b> (угол тупой).', '5 − 6 = <b>−1</b> (obtuse angle).') },
      { q: L('k ning qanday qiymatida (2; k) ⊥ (3; −6)?', 'При каком k (2; k) ⊥ (3; −6)?', 'For which k is (2; k) ⊥ (3; −6)?'), s: L('6 − 6k = 0, k = <b>1</b>.', '6 − 6k = 0, k = <b>1</b>.', '6 − 6k = 0, so k = <b>1</b>.') },
      { q: L('|a→| = 4, |b→| = 3, φ = 60°. a→ · b→ = ?', '|a→| = 4, |b→| = 3, φ = 60°. a→ · b→ = ?', '|a→| = 4, |b→| = 3, φ = 60°. a→ · b→ = ?'), s: L('4 · 3 · 1/2 = <b>6</b>.', '4 · 3 · 1/2 = <b>6</b>.', '4 · 3 · 1/2 = <b>6</b>.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Skalyar ko‘paytma: a→ · b→ = |a→| · |b→| · cos φ — natija son.', 'Скалярное произведение: a→ · b→ = |a→| · |b→| · cos φ — результат число.', 'Dot product: a→ · b→ = |a→| · |b→| · cos φ — the result is a number.'),
      L('Koordinatalarda: a→ · b→ = x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub>.', 'В координатах: a→ · b→ = x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub>.', 'In coordinates: a→ · b→ = x<sub>1</sub>x<sub>2</sub> + y<sub>1</sub>y<sub>2</sub>.'),
      L('a→ ⊥ b→ ⇔ a→ · b→ = 0; ishora burchak o‘tkir yoki o‘tmasligini ko‘rsatadi.', 'a→ ⊥ b→ ⇔ a→ · b→ = 0; знак показывает, острый угол или тупой.', 'a→ ⊥ b→ ⇔ a→ · b→ = 0; the sign tells acute from obtuse.'),
      L('cos φ = (a→ · b→) / (|a→| · |b→|) — burchakni hisoblash formulasi.', 'cos φ = (a→ · b→) / (|a→| · |b→|) — формула для угла.', 'cos φ = (a→ · b→) / (|a→| · |b→|) gives the angle.'),
      L('Tatbiqlar: fizikada ish A = F→ · s→, grafikada yoritish, sun’iy intellektda o‘xshashlik.', 'Применения: работа A = F→ · s→ в физике, освещение в графике, сходство в ИИ.', 'Uses: work A = F→ · s→ in physics, lighting in graphics, similarity in AI.'),
      L('Gamilton «skalyar» atamasini kiritgan, Gibbs va Xevisayd hozirgi yozuvni berishgan.', 'Гамильтон ввёл термин «скаляр», Гиббс и Хевисайд — современную запись.', 'Hamilton coined “scalar”; Gibbs and Heaviside gave the modern notation.')
    ] }
  ] });
})(this);
